export enum AssistantState {
  IDLE = 'IDLE',
  CONNECTING = 'CONNECTING',
  LISTENING = 'LISTENING',
  SPEAKING = 'SPEAKING',
  ERROR = 'ERROR'
}

export interface TranscriptionEntry {
  id: string;
  sender: 'user' | 'assistant';
  text: string;
  timestamp: Date;
}

export interface VoiceOption {
  id: string;
  name: string;
}

import { Blob as GeminiBlob } from '@google/genai';

export function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export function encode(bytes: Uint8Array): string {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export function createPcmBlob(data: Float32Array): GeminiBlob {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) {
    int16[i] = data[i] * 32768;
  }
  return {
    data: encode(new Uint8Array(int16.buffer)),
    mimeType: 'audio/pcm;rate=16000',
  };
}

export async function blobToBase64(blob: Blob): Promise<string> {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => {
            const base64String = (reader.result as string).split(',')[1];
            resolve(base64String);
        };
        reader.onerror = reject;
        reader.readAsDataURL(blob);
    });
}

import React, { useRef, useEffect } from 'react';
import { AssistantState } from '../types';

interface VoiceVisualizerProps {
  state: AssistantState;
  analyser?: AnalyserNode;
}

const VoiceVisualizer: React.FC<VoiceVisualizerProps> = ({ state, analyser }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (!canvasRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationId: number;
    const bufferLength = analyser?.frequencyBinCount || 128;
    const dataArray = new Uint8Array(bufferLength);

    const render = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const width = canvas.width;
      const height = canvas.height;
      const centerY = height / 2;

      if (analyser) {
        analyser.getByteFrequencyData(dataArray);
      }

      const barCount = 40;
      const barWidth = width / barCount;
      const gap = 4;

      for (let i = 0; i < barCount; i++) {
        let barHeight = 4;

        if (state === AssistantState.LISTENING || state === AssistantState.SPEAKING) {
           const dataIndex = Math.floor((i / barCount) * bufferLength);
           barHeight = (dataArray[dataIndex] / 255) * (height / 1.5) + 4;
        } else if (state === AssistantState.CONNECTING) {
           barHeight = Math.sin(Date.now() / 200 + i * 0.5) * 15 + 20;
        }

        const x = i * (barWidth + gap);
        const y = centerY - barHeight / 2;

        // Gradient color based on state
        const gradient = ctx.createLinearGradient(x, y, x, y + barHeight);
        if (state === AssistantState.SPEAKING) {
          gradient.addColorStop(0, '#60a5fa');
          gradient.addColorStop(1, '#a855f7');
        } else if (state === AssistantState.LISTENING) {
          gradient.addColorStop(0, '#34d399');
          gradient.addColorStop(1, '#60a5fa');
        } else {
          gradient.addColorStop(0, '#94a3b8');
          gradient.addColorStop(1, '#cbd5e1');
        }

        ctx.fillStyle = gradient;
        ctx.beginPath();
        ctx.roundRect(x, y, barWidth, barHeight, 4);
        ctx.fill();
      }

      animationId = requestAnimationFrame(render);
    };

    render();
    return () => cancelAnimationFrame(animationId);
  }, [state, analyser]);

  return (
    <div className="w-full h-32 flex items-center justify-center">
      <canvas 
        ref={canvasRef} 
        width={400} 
        height={100} 
        className="w-full max-w-md h-full"
      />
    </div>
  );
};

export default VoiceVisualizer;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage } from '@google/genai';
import { AssistantState, TranscriptionEntry } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const App: React.FC = () => {
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [selectedVoice, setSelectedVoice] = useState(VOICES[0].id);
  const [error, setError] = useState<string | null>(null);

  // Refs for audio handling
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);

  // Refs for transcript accumulation
  const currentInputTranscript = useRef('');
  const currentOutputTranscript = useRef('');
  const scrollRef = useRef<HTMLDivElement>(null);

  // Auto-scroll transcription
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [transcriptions]);

  const addTranscription = (sender: 'user' | 'assistant', text: string) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      {
        id: Math.random().toString(36).substr(2, 9),
        sender,
        text,
        timestamp: new Date()
      }
    ]);
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) {
      // sessionRef.current.close(); // Not always available in all client SDK versions
      sessionRef.current = null;
    }
    if (micStreamRef.current) {
      micStreamRef.current.getTracks().forEach(track => track.stop());
      micStreamRef.current = null;
    }
    activeSourcesRef.current.forEach(source => source.stop());
    activeSourcesRef.current.clear();
    setState(AssistantState.IDLE);
  }, []);

  const startSession = async () => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);

      const apiKey = process.env.API_KEY;
      if (!apiKey) {
        throw new Error("API Key is missing. Please ensure process.env.API_KEY is configured.");
      }

      // 1. Initialize Audio Contexts
      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      await inputCtx.resume();
      await outputCtx.resume();

      // 2. Setup Analyser for Visualization
      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      // 3. Get Microphone Stream
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      // 4. Initialize Gemini
      const ai = new GoogleGenAI({ apiKey });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: selectedVoice } },
          },
          systemInstruction: 'You are a highly capable, friendly, and proactive virtual assistant named Nova. You respond naturally and concisely. You have access to real-time audio and should act like a real person in a conversation.',
          inputAudioTranscription: {},
          outputAudioTranscription: {}
        },
        callbacks: {
          onopen: () => {
            console.log('Gemini Live session opened');
            setState(AssistantState.LISTENING);

            // Stream microphone data to the session
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = audioUtils.createPcmBlob(inputData);
              sessionPromise.then(session => {
                if (sessionRef.current) {
                  session.sendRealtimeInput({ media: pcmBlob });
                }
              });
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            // Handle Audio Output
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);

              const audioData = audioUtils.decode(base64Audio);
              const audioBuffer = await audioUtils.decodeAudioData(audioData, outputCtx, 24000, 1);

              const sourceNode = outputCtx.createBufferSource();
              sourceNode.buffer = audioBuffer;
              sourceNode.connect(outputCtx.destination);
              sourceNode.addEventListener('ended', () => {
                activeSourcesRef.current.delete(sourceNode);
                if (activeSourcesRef.current.size === 0) {
                  setState(AssistantState.LISTENING);
                }
              });

              sourceNode.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              activeSourcesRef.current.add(sourceNode);
            }

            // Handle Transcriptions
            if (message.serverContent?.inputTranscription) {
              currentInputTranscript.current += message.serverContent.inputTranscription.text;
            }
            if (message.serverContent?.outputTranscription) {
              currentOutputTranscript.current += message.serverContent.outputTranscription.text;
            }

            if (message.serverContent?.turnComplete) {
              if (currentInputTranscript.current) {
                addTranscription('user', currentInputTranscript.current);
                currentInputTranscript.current = '';
              }
              if (currentOutputTranscript.current) {
                addTranscription('assistant', currentOutputTranscript.current);
                currentOutputTranscript.current = '';
              }
            }

            // Handle Interruptions
            if (message.serverContent?.interrupted) {
              activeSourcesRef.current.forEach(s => s.stop());
              activeSourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setState(AssistantState.LISTENING);
            }
          },
          onerror: (err) => {
            console.error('Session error:', err);
            setError('An error occurred during the session. Please try again.');
            stopSession();
          },
          onclose: () => {
            console.log('Session closed');
            stopSession();
          }
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (err: any) {
      console.error('Startup error:', err);
      setError(err.message || 'Could not start assistant session.');
      setState(AssistantState.IDLE);
    }
  };

  return (
    <div className="flex flex-col h-screen max-w-4xl mx-auto p-4 md:p-8">
      {/* Header */}
      <header className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg shadow-blue-500/50">
            <i className="fas fa-robot text-xl"></i>
          </div>
          <div>
            <h1 className="text-2xl font-bold tracking-tight">Nova Assistant</h1>
            <p className="text-xs text-blue-400 font-medium">REAL-TIME VOICE AI</p>
          </div>
        </div>

        <div className="flex gap-2">
           <select 
             value={selectedVoice}
             onChange={(e) => setSelectedVoice(e.target.value)}
             disabled={state !== AssistantState.IDLE}
             className="bg-white/10 border border-white/20 rounded-lg px-3 py-1 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:opacity-50"
           >
             {VOICES.map(v => (
               <option key={v.id} value={v.id} className="bg-slate-900">{v.name}</option>
             ))}
           </select>
        </div>
      </header>

      {/* Visualizer Area */}
      <div className="flex-1 flex flex-col items-center justify-center relative bg-white/5 rounded-3xl border border-white/10 backdrop-blur-sm overflow-hidden mb-6 group">
        <div className="absolute inset-0 bg-gradient-to-b from-blue-500/5 to-purple-500/5 opacity-50"></div>

        {state === AssistantState.IDLE && (
          <div className="text-center z-10 px-6 animate-fade-in">
            <div className="w-24 h-24 rounded-full bg-blue-600/20 border border-blue-500/30 flex items-center justify-center mx-auto mb-6 animate-pulse-slow">
              <i className="fas fa-microphone text-4xl text-blue-400"></i>
            </div>
            <h2 className="text-2xl font-semibold mb-2">Ready to talk?</h2>
            <p className="text-gray-400 mb-8 max-w-sm">Tap the button below to start a natural, real-time conversation with Nova.</p>
          </div>
        )}

        {(state !== AssistantState.IDLE) && (
          <div className="z-10 w-full px-6 flex flex-col items-center">
             <div className="text-sm font-medium tracking-widest text-blue-400 uppercase mb-4 animate-pulse">
                {state === AssistantState.CONNECTING && 'Connecting...'}
                {state === AssistantState.LISTENING && 'Listening...'}
                {state === AssistantState.SPEAKING && 'Speaking...'}
             </div>
             <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
          </div>
        )}

        {error && (
          <div className="absolute bottom-4 left-4 right-4 bg-red-500/20 border border-red-500/50 rounded-xl p-3 flex items-center gap-3 text-red-200 text-sm animate-bounce">
            <i className="fas fa-exclamation-circle text-lg"></i>
            <p>{error}</p>
            <button onClick={() => setError(null)} className="ml-auto text-red-400 hover:text-white">
              <i className="fas fa-times"></i>
            </button>
          </div>
        )}
      </div>

      {/* Transcription Area */}
      <div className="h-1/3 bg-black/40 rounded-2xl border border-white/10 p-4 mb-6 flex flex-col overflow-hidden">
        <div className="flex items-center gap-2 mb-3 text-xs font-semibold text-gray-500 uppercase tracking-widest">
           <i className="fas fa-quote-left"></i>
           Live Transcript
        </div>
        <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-4 pr-2 scrollbar-thin scrollbar-thumb-white/10">
          {transcriptions.length === 0 && (
            <div className="h-full flex items-center justify-center text-gray-600 italic text-sm">
              Your conversation history will appear here...
            </div>
          )}
          {transcriptions.map((entry) => (
            <div 
              key={entry.id} 
              className={`flex flex-col ${entry.sender === 'user' ? 'items-end' : 'items-start'}`}
            >
              <div className={`max-w-[85%] rounded-2xl px-4 py-2.5 text-sm leading-relaxed ${
                entry.sender === 'user' 
                  ? 'bg-blue-600 text-white rounded-tr-none' 
                  : 'bg-white/10 text-gray-200 border border-white/10 rounded-tl-none'
              }`}>
                {entry.text}
              </div>
              <span className="text-[10px] text-gray-500 mt-1 uppercase">
                {entry.sender === 'user' ? 'You' : 'Nova'} • {entry.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </span>
            </div>
          ))}
        </div>
      </div>

      {/* Controls */}
      <div className="flex items-center justify-center gap-6 pb-4">
        {state === AssistantState.IDLE ? (
          <button
            onClick={startSession}
            className="group relative flex items-center gap-3 bg-blue-600 hover:bg-blue-500 text-white font-bold py-4 px-10 rounded-full transition-all duration-300 shadow-xl shadow-blue-500/25 active:scale-95"
          >
            <span className="absolute inset-0 rounded-full bg-blue-400 animate-ping opacity-20 group-hover:opacity-40 transition-opacity"></span>
            <i className="fas fa-microphone text-xl"></i>
            <span>START CONVERSATION</span>
          </button>
        ) : (
          <button
            onClick={stopSession}
            className="flex items-center gap-3 bg-red-600/20 hover:bg-red-600 text-white font-bold py-4 px-10 rounded-full border border-red-500/50 transition-all duration-300 active:scale-95"
          >
            <i className="fas fa-stop text-xl"></i>
            <span>STOP ASSISTANT</span>
          </button>
        )}
      </div>

      {/* Footer Meta */}
      <footer className="text-center text-gray-600 text-[10px] uppercase tracking-widest mt-4">
        Powered by Gemini 2.5 Flash Native Audio • Low Latency Duplex
      </footer>
    </div>
  );
};

export default App;

