                  <i className="fas fa-microphone text-5xl text-blue-400"></i>
                </div>
                <h2 className="text-2xl font-bold mb-3">Talk to Nova</h2>
                <p className="text-gray-400 text-sm leading-relaxed">A high-fidelity virtual assistant that learns from you in real-time. Start a conversation to begin.</p>
              </div>
            ) : (
              <div className="w-full max-w-lg flex flex-col items-center">
                 <div className="text-[10px] font-bold tracking-[0.2em] text-blue-400 uppercase mb-6 animate-pulse">
