            >
              <i className="fas fa-power-off text-xl"></i>
              <span className="tracking-tighter uppercase">Terminate</span>
            </button>
          )}
        </div>

        {error && (
          <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-red-900/80 border border-red-500/50 text-white px-6 py-3 rounded-2xl text-xs backdrop-blur-xl z-50 flex items-center gap-3 animate-fade-in">
            <i className="fas fa-circle-exclamation text-red-400"></i>
            {error}
          </div>
        )}
      </div>

      {/* Persistent Memory Side Panel */}
      <aside className={`fixed right-0 top-0 bottom-0 w-[320px] z-40 transition-transform duration-500 ease-in-out transform bg-[#0d0d1f] shadow-2xl border-l border-white/5 ${isMemoryOpen ? 'translate-x-0' : 'translate-x-full'}`}>
         <div className="flex flex-col h-full pt-8">
            <button 
              onClick={() => setIsMemoryOpen(false)}
              className="absolute top-8 right-6 text-gray-500 hover:text-white transition-colors"
            >
              <i className="fas fa-times text-xl"></i>
            </button>
            <MemoryBank memories={memories} onRemove={removeMemory} />
         </div>
      </aside>

      {/* Mobile Memory Overlay */}
      {isMemoryOpen && (
        <div 
          className="fixed inset-0 bg-black/60 backdrop-blur-sm z-30 md:hidden animate-fade-in"
          onClick={() => setIsMemoryOpen(false)}
        ></div>
      )}
    </div>
  );
};

