import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, AuthUser } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or piece of information provided by the user for long-term memory.',
    properties: {
      fact: {
        type: Type.STRING,
        description: 'The specific fact or piece of information to remember (e.g., "The user loves spicy food").',
      },
    },
    required: ['fact'],
  },
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [assistantName, setAssistantName] = useState('Nova');
  const [isEditingName, setIsEditingName] = useState(false);
  const [selectedVoice, setSelectedVoice] = useState(VOICES[0].id);
  const [error, setError] = useState<string | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [isLearning, setIsLearning] = useState(false);
  const [isNoisy, setIsNoisy] = useState(false);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);

  const currentInputTranscript = useRef('');
  const currentOutputTranscript = useRef('');
  const scrollRef = useRef<HTMLDivElement>(null);

  // Load User from session on boot
  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_active_user');
    if (sessionUser) {
      handleLogin(sessionUser);
    }
  }, []);

  // Load User Data when logged in
  useEffect(() => {
    if (user) {
      const storageKeyMemories = `user_${user.username}_memories`;
      const storageKeyName = `user_${user.username}_name`;

      const savedMemories = localStorage.getItem(storageKeyMemories);
      if (savedMemories) {
        try { setMemories(JSON.parse(savedMemories)); } catch (e) { console.error("Memory parse error"); }
      } else {
        setMemories([]); // Reset for new user
      }

      const savedName = localStorage.getItem(storageKeyName);
      setAssistantName(savedName || 'Nova');
    }
  }, [user]);

  // Persist User Data
  useEffect(() => {
    if (user) {
      localStorage.setItem(`user_${user.username}_memories`, JSON.stringify(memories));
    }
  }, [memories, user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`user_${user.username}_name`, assistantName);
    }
  }, [assistantName, user]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [transcriptions]);

  const handleLogin = (username: string) => {
    setUser({ username });
    sessionStorage.setItem('nova_active_user', username);
  };

  const handleLogout = () => {
    stopSession();
    setUser(null);
    setTranscriptions([]);
    sessionStorage.removeItem('nova_active_user');
  };

  const addTranscription = (sender: 'user' | 'assistant', text: string) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      {
        id: Math.random().toString(36).substr(2, 9),
        sender,
        text,
        timestamp: new Date()
      }
    ]);
  };

  const removeMemory = (id: string) => {
    setMemories(prev => prev.filter(m => m.id !== id));
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) {
      sessionRef.current.close?.();
      sessionRef.current = null;
    }
    if (micStreamRef.current) {
      micStreamRef.current.getTracks().forEach(track => track.stop());
      micStreamRef.current = null;
    }
    activeSourcesRef.current.forEach(source => source.stop());
    activeSourcesRef.current.clear();
    setState(AssistantState.IDLE);
    setIsLearning(false);
    setIsNoisy(false);
  }, []);

  const startSession = async () => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);

      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key is missing.");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      await inputCtx.resume();
      await outputCtx.resume();

      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true,
          channelCount: 1,
          sampleRate: 16000
        } 
      });

      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });

      const knownFacts = memories.length > 0 
        ? `Known facts about user: ${memories.map(m => m.fact).join('; ')}.`
        : '';

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools: [{ functionDeclarations: [saveKnowledgeTool] }],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: selectedVoice } },
          },
          systemInstruction: `Your name is ${assistantName}. You are a secure and private assistant for ${user?.username}. ${knownFacts} 
          - PRIVACY: This is a secure conversation. Respect the user's isolated environment.
          - ROBUSTNESS: Handle noise or interruptions gracefully.
          - MEMORY: Always use 'save_knowledge' when the user provides specific preferences or information they want you to remember.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {}
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            const dataArray = new Uint8Array(analyser.frequencyBinCount);

            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              analyser.getByteFrequencyData(dataArray);
              const average = dataArray.reduce((a, b) => a + b) / dataArray.length;
              setIsNoisy(average > 50);

              const pcmBlob = audioUtils.createPcmBlob(inputData);
              sessionPromise.then(session => {
                if (sessionRef.current) session.sendRealtimeInput({ media: pcmBlob });
              });
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const fact = (fc.args as any).fact;
                  setIsLearning(true);
                  setMemories(prev => [
                    ...prev, 
                    { id: Math.random().toString(36).substr(2, 9), fact, timestamp: new Date() }
                  ]);
                  setIsMemoryOpen(true);
                  sessionPromise.then(session => {
                    session.sendToolResponse({
                      functionResponses: { id: fc.id, name: fc.name, response: { result: "Memory synchronized with encrypted storage." } }
                    });
                  });
                  setTimeout(() => setIsLearning(false), 2000);
                }
              }
            }

            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const audioBuffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const sourceNode = outputCtx.createBufferSource();
              sourceNode.buffer = audioBuffer;
              sourceNode.connect(outputCtx.destination);
              sourceNode.addEventListener('ended', () => {
                activeSourcesRef.current.delete(sourceNode);
                if (activeSourcesRef.current.size === 0) setState(AssistantState.LISTENING);
              });
              sourceNode.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              activeSourcesRef.current.add(sourceNode);
            }

            if (message.serverContent?.inputTranscription) currentInputTranscript.current += message.serverContent.inputTranscription.text;
            if (message.serverContent?.outputTranscription) currentOutputTranscript.current += message.serverContent.outputTranscription.text;

            if (message.serverContent?.turnComplete) {
              if (currentInputTranscript.current) { addTranscription('user', currentInputTranscript.current); currentInputTranscript.current = ''; }
              if (currentOutputTranscript.current) { addTranscription('assistant', currentOutputTranscript.current); currentOutputTranscript.current = ''; }
            }

            if (message.serverContent?.interrupted) {
              activeSourcesRef.current.forEach(s => s.stop());
              activeSourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setState(AssistantState.LISTENING);
            }
          },
          onerror: (err) => { setError('Sync error. Resetting...'); stopSession(); },
          onclose: () => stopSession()
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (err: any) {
      setError(err.message || 'Could not start assistant.');
      setState(AssistantState.IDLE);
    }
  };

  // If not logged in, show LoginPage
  if (!user) {
    return <LoginPage onLogin={handleLogin} />;
  }

  return (
    <div className="flex flex-col md:flex-row h-screen w-full bg-[#0a0a1a] text-white overflow-hidden font-sans animate-fade-in">
      {/* Main Content */}
      <div className={`flex-1 flex flex-col p-4 md:p-8 transition-all duration-500 ${isMemoryOpen ? 'md:mr-[320px]' : ''}`}>

        <header className="flex items-center justify-between mb-8">
          <div className="flex items-center gap-4">
            <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-lg transition-all duration-300 ${state !== AssistantState.IDLE ? 'bg-blue-600 shadow-blue-500/50' : 'bg-white/10'}`}>
              <i className={`fas fa-fingerprint text-xl ${state !== AssistantState.IDLE ? 'text-white' : 'text-blue-400'}`}></i>
            </div>
            <div className="flex flex-col">
              <div className="flex items-center gap-2 group">
                {isEditingName ? (
                  <input
                    autoFocus
                    className="bg-white/5 border border-white/20 rounded px-2 py-0.5 text-xl font-bold focus:outline-none focus:ring-1 focus:ring-blue-500"
                    value={assistantName}
                    onChange={(e) => setAssistantName(e.target.value)}
                    onBlur={() => setIsEditingName(false)}
                    onKeyDown={(e) => e.key === 'Enter' && setIsEditingName(false)}
                  />
                ) : (
                  <>
                    <h1 className="text-xl md:text-2xl font-bold tracking-tight bg-gradient-to-r from-blue-400 to-cyan-400 bg-clip-text text-transparent">
                      {assistantName}
                    </h1>
                    <button 
                      onClick={() => setIsEditingName(true)}
                      className="opacity-0 group-hover:opacity-100 transition-opacity text-gray-500 hover:text-blue-400 text-xs"
                    >
                      <i className="fas fa-edit"></i>
                    </button>
                  </>
                )}
              </div>
              <div className="flex items-center gap-2">
                <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest flex items-center gap-2">
                  <span className="text-blue-500">@{user.username}</span> • {state === AssistantState.IDLE ? 'Secure Context' : 'Adaptive Sync Active'}
                </p>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3">
             <button 
               onClick={() => setIsMemoryOpen(!isMemoryOpen)}
               className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isMemoryOpen ? 'bg-blue-600 text-white' : 'bg-white/5 text-gray-400 hover:bg-white/10'}`}
               title="Open Memory Bank"
             >
               <i className="fas fa-brain"></i>
             </button>
             <button 
               onClick={handleLogout}
               className="w-10 h-10 rounded-xl flex items-center justify-center bg-red-500/10 text-red-400 hover:bg-red-500 hover:text-white transition-all border border-red-500/20"
               title="Sign Out"
             >
               <i className="fas fa-sign-out-alt"></i>
             </button>
             <select 
               value={selectedVoice}
               onChange={(e) => setSelectedVoice(e.target.value)}
               disabled={state !== AssistantState.IDLE}
               className="bg-white/5 border border-white/10 rounded-xl px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 appearance-none cursor-pointer"
             >
               {VOICES.map(v => (
                 <option key={v.id} value={v.id} className="bg-[#0a0a1a]">{v.name}</option>
               ))}
             </select>
          </div>
        </header>

        <div className="flex-1 flex flex-col min-h-0 bg-white/5 rounded-[2.5rem] border border-white/10 backdrop-blur-md overflow-hidden relative shadow-inner">
          <div className="absolute inset-0 bg-gradient-to-br from-blue-500/5 via-transparent to-cyan-500/5 pointer-events-none"></div>

          <div className="absolute top-6 left-1/2 -translate-x-1/2 z-20 space-y-2 flex flex-col items-center">
            {isLearning && (
              <div className="bg-yellow-500/20 border border-yellow-500/50 text-yellow-200 text-[10px] px-4 py-1.5 rounded-full uppercase tracking-tighter flex items-center gap-2 animate-bounce">
                <i className="fas fa-shield-alt"></i> Knowledge Isolated & Saved
              </div>
            )}
            {isNoisy && state !== AssistantState.IDLE && (
              <div className="bg-orange-500/20 border border-orange-500/50 text-orange-200 text-[10px] px-4 py-1.5 rounded-full uppercase tracking-tighter flex items-center gap-2">
                <i className="fas fa-filter"></i> Noise Mitigation Active
              </div>
            )}
          </div>

          <div className="flex-1 flex flex-col items-center justify-center z-10 p-6">
            {state === AssistantState.IDLE ? (
              <div className="text-center animate-fade-in max-w-sm">
                <div className="w-32 h-32 rounded-full bg-blue-600/10 border border-blue-500/20 flex items-center justify-center mx-auto mb-8 relative group">
                  <div className="absolute inset-0 rounded-full bg-blue-500/20 animate-pulse group-hover:bg-blue-500/30 transition-all"></div>
                  <i className="fas fa-microphone-lines text-5xl text-blue-400"></i>
                </div>
                <h2 className="text-2xl font-bold mb-3">Welcome back, {user.username}</h2>
                <p className="text-gray-400 text-sm leading-relaxed">Your isolated environment is ready. Start a session to talk to {assistantName}.</p>
              </div>
            ) : (
              <div className="w-full max-w-lg flex flex-col items-center">
                 <div className="text-[10px] font-bold tracking-[0.2em] text-blue-400 uppercase mb-6 animate-pulse">
                    {state === AssistantState.CONNECTING ? 'Handshake...' : state === AssistantState.LISTENING ? `${assistantName} Listening` : `${assistantName} Speaking`}
                 </div>
                 <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
              </div>
            )}
          </div>

          <div className="h-48 md:h-64 bg-black/40 border-t border-white/10 p-6 flex flex-col">
            <div className="flex items-center gap-2 mb-4 text-[10px] font-bold text-gray-500 uppercase tracking-widest">
               <i className="fas fa-align-left"></i>
               Private Voice Stream
            </div>
            <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-4 pr-4 scrollbar-thin scrollbar-thumb-white/10">
              {transcriptions.length === 0 && (
                <div className="h-full flex items-center justify-center text-gray-600 italic text-xs">
                  Awaiting vocal input...
                </div>
              )}
              {transcriptions.map((entry) => (
                <div 
                  key={entry.id} 
                  className={`flex flex-col ${entry.sender === 'user' ? 'items-end' : 'items-start'} animate-slide-up`}
                >
                  <div className={`max-w-[80%] rounded-2xl px-5 py-3 text-sm leading-relaxed shadow-sm transition-all ${
                    entry.sender === 'user' 
                      ? 'bg-blue-600 text-white rounded-tr-none' 
                      : 'bg-white/10 text-gray-200 border border-white/10 rounded-tl-none'
                  }`}>
                    {entry.text}
                  </div>
                  <span className="text-[9px] text-gray-600 mt-1 uppercase tracking-widest">
                    {entry.sender === 'user' ? user.username : assistantName}
                  </span>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="flex items-center justify-center mt-8 gap-6">
          {state === AssistantState.IDLE ? (
            <button
              onClick={startSession}
              className="group relative flex items-center gap-4 bg-white text-[#0a0a1a] font-black py-5 px-14 rounded-full transition-all duration-300 shadow-2xl hover:scale-105 active:scale-95"
            >
              <i className="fas fa-play text-xl"></i>
              <span className="tracking-tighter uppercase">Initiate Stream</span>
            </button>
          ) : (
            <button
              onClick={stopSession}
              className="flex items-center gap-4 bg-red-500/10 hover:bg-red-500 text-white font-black py-5 px-14 rounded-full border border-red-500/50 transition-all duration-300 hover:shadow-2xl hover:shadow-red-500/40 active:scale-95"
            >
              <i className="fas fa-power-off text-xl"></i>
              <span className="tracking-tighter uppercase">Terminate</span>
            </button>
          )}
        </div>

        {error && (
          <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-red-900/80 border border-red-500/50 text-white px-6 py-3 rounded-2xl text-xs backdrop-blur-xl z-50 flex items-center gap-3 animate-fade-in">
            <i className="fas fa-circle-exclamation text-red-400"></i>
            {error}
          </div>
        )}
      </div>

      <aside className={`fixed right-0 top-0 bottom-0 w-[320px] z-40 transition-transform duration-500 ease-in-out transform bg-[#0d0d1f] shadow-2xl border-l border-white/5 ${isMemoryOpen ? 'translate-x-0' : 'translate-x-full'}`}>
         <div className="flex flex-col h-full pt-8">
            <button 
              onClick={() => setIsMemoryOpen(false)}
              className="absolute top-8 right-6 text-gray-500 hover:text-white transition-colors"
            >
              <i className="fas fa-times text-xl"></i>
            </button>
            <MemoryBank memories={memories} onRemove={removeMemory} assistantName={assistantName} />
         </div>
      </aside>

      {isMemoryOpen && (
        <div 
          className="fixed inset-0 bg-black/60 backdrop-blur-sm z-30 md:hidden animate-fade-in"
          onClick={() => setIsMemoryOpen(false)}
        ></div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const STORAGE_KEY = 'nova_assistant_memories';
const NAME_STORAGE_KEY = 'nova_assistant_name';

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or piece of information provided by the user for long-term memory.',
    properties: {
      fact: {
        type: Type.STRING,
        description: 'The specific fact or piece of information to remember (e.g., "The user loves spicy food").',
      },
    },
    required: ['fact'],
  },
};

const updateIdentityTool: FunctionDeclaration = {
  name: 'update_identity',
  parameters: {
    type: Type.OBJECT,
    description: 'Update your own identity/name based on the user’s request.',
    properties: {
      newName: {
        type: Type.STRING,
        description: 'The new name the user wants to call you.',
      },
    },
    required: ['newName'],
  },
};

const App: React.FC = () => {
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [assistantName, setAssistantName] = useState('Nova');
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [selectedVoice, setSelectedVoice] = useState(VOICES[0].id);
  const [error, setError] = useState<string | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [isLearning, setIsLearning] = useState(false);
  const [isNoisy, setIsNoisy] = useState(false);
  const [isRebranding, setIsRebranding] = useState(false);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);

  const currentInputTranscript = useRef('');
  const currentOutputTranscript = useRef('');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const savedMemories = localStorage.getItem(STORAGE_KEY);
    if (savedMemories) {
      try {
        setMemories(JSON.parse(savedMemories));
      } catch (e) {
        console.error("Failed to parse saved memories");
      }
    }
    const savedName = localStorage.getItem(NAME_STORAGE_KEY);
    if (savedName) {
      setAssistantName(savedName);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(memories));
  }, [memories]);

  useEffect(() => {
    localStorage.setItem(NAME_STORAGE_KEY, assistantName);
  }, [assistantName]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [transcriptions]);

  const addTranscription = (sender: 'user' | 'assistant', text: string) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      {
        id: Math.random().toString(36).substr(2, 9),
        sender,
        text,
        timestamp: new Date()
      }
    ]);
  };

  const removeMemory = (id: string) => {
    setMemories(prev => prev.filter(m => m.id !== id));
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) {
      sessionRef.current.close?.();
      sessionRef.current = null;
    }
    if (micStreamRef.current) {
      micStreamRef.current.getTracks().forEach(track => track.stop());
      micStreamRef.current = null;
    }
    activeSourcesRef.current.forEach(source => source.stop());
    activeSourcesRef.current.clear();
    setState(AssistantState.IDLE);
    setIsLearning(false);
    setIsNoisy(false);
  }, []);

  const startSession = async () => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);

      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key is missing.");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      await inputCtx.resume();
      await outputCtx.resume();

      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true,
          channelCount: 1,
          sampleRate: 16000
        } 
      });

      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });

      const knownFacts = memories.length > 0 
        ? `Knowledge: ${memories.map(m => m.fact).join('; ')}.`
        : '';

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools: [{ functionDeclarations: [saveKnowledgeTool, updateIdentityTool] }],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: selectedVoice } },
          },
          systemInstruction: `You are ${assistantName}, a highly adaptive and personal assistant. ${knownFacts} 
          - ROBUSTNESS: You may experience background noise. Ask for clarification if needed.
          - IDENTITY: Your name is currently ${assistantName}. If the user asks to change your name or call you something else, use the 'update_identity' tool.
          - MEMORY: Use 'save_knowledge' to store user preferences. 
          - STYLE: Be concise and professional.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {}
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            const dataArray = new Uint8Array(analyser.frequencyBinCount);

            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              analyser.getByteFrequencyData(dataArray);
              const average = dataArray.reduce((a, b) => a + b) / dataArray.length;
              setIsNoisy(average > 50);

              const pcmBlob = audioUtils.createPcmBlob(inputData);
              sessionPromise.then(session => {
                if (sessionRef.current) session.sendRealtimeInput({ media: pcmBlob });
              });
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const fact = (fc.args as any).fact;
                  setIsLearning(true);
                  setMemories(prev => [
                    ...prev, 
                    { id: Math.random().toString(36).substr(2, 9), fact, timestamp: new Date() }
                  ]);
                  setIsMemoryOpen(true);
                  sessionPromise.then(session => {
                    session.sendToolResponse({
                      functionResponses: { id: fc.id, name: fc.name, response: { result: "Fact saved." } }
                    });
                  });
                  setTimeout(() => setIsLearning(false), 2000);
                }

                if (fc.name === 'update_identity') {
                  const newName = (fc.args as any).newName;
                  setIsRebranding(true);
                  setAssistantName(newName);
                  sessionPromise.then(session => {
                    session.sendToolResponse({
                      functionResponses: { id: fc.id, name: fc.name, response: { result: `My name has been updated to ${newName}. I will now identify as ${newName}.` } }
                    });
                  });
                  setTimeout(() => setIsRebranding(false), 3000);
                }
              }
            }

            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const audioBuffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const sourceNode = outputCtx.createBufferSource();
              sourceNode.buffer = audioBuffer;
              sourceNode.connect(outputCtx.destination);
              sourceNode.addEventListener('ended', () => {
                activeSourcesRef.current.delete(sourceNode);
                if (activeSourcesRef.current.size === 0) setState(AssistantState.LISTENING);
              });
              sourceNode.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              activeSourcesRef.current.add(sourceNode);
            }

            if (message.serverContent?.inputTranscription) currentInputTranscript.current += message.serverContent.inputTranscription.text;
            if (message.serverContent?.outputTranscription) currentOutputTranscript.current += message.serverContent.outputTranscription.text;

            if (message.serverContent?.turnComplete) {
              if (currentInputTranscript.current) { addTranscription('user', currentInputTranscript.current); currentInputTranscript.current = ''; }
              if (currentOutputTranscript.current) { addTranscription('assistant', currentOutputTranscript.current); currentOutputTranscript.current = ''; }
            }

            if (message.serverContent?.interrupted) {
              activeSourcesRef.current.forEach(s => s.stop());
              activeSourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setState(AssistantState.LISTENING);
            }
          },
          onerror: (err) => { setError('Sync error. Resetting...'); stopSession(); },
          onclose: () => stopSession()
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (err: any) {
      setError(err.message || 'Could not start assistant.');
      setState(AssistantState.IDLE);
    }
  };

  return (
    <div className="flex flex-col md:flex-row h-screen w-full bg-[#0a0a1a] text-white overflow-hidden font-sans">
      <div className={`flex-1 flex flex-col p-4 md:p-8 transition-all duration-500 ${isMemoryOpen ? 'md:mr-[320px]' : ''}`}>

        <header className="flex items-center justify-between mb-8">
          <div className="flex items-center gap-4">
            <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-lg transition-all duration-300 ${state !== AssistantState.IDLE ? 'bg-blue-600 shadow-blue-500/50' : 'bg-white/10'}`}>
              <i className={`fas ${isRebranding ? 'fa-sync fa-spin' : 'fa-wave-square'} text-xl ${state !== AssistantState.IDLE ? 'text-white' : 'text-gray-500'}`}></i>
            </div>
            <div className="flex flex-col">
              <h1 className={`text-xl md:text-2xl font-bold tracking-tight bg-gradient-to-r from-blue-400 to-cyan-400 bg-clip-text text-transparent transition-all duration-500 ${isRebranding ? 'blur-sm scale-95' : 'blur-0 scale-100'}`}>
                {assistantName} Assistant
              </h1>
              <div className="flex items-center gap-2">
                <span className={`w-2 h-2 rounded-full ${state === AssistantState.IDLE ? 'bg-gray-600' : 'bg-green-500 animate-pulse'}`}></span>
                <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest flex items-center gap-2">
                  {state === AssistantState.IDLE ? 'Offline' : 'Live Sync'}
                  {isRebranding && <span className="text-cyan-400 animate-pulse">• Updating Identity</span>}
                </p>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3">
             <button 
               onClick={() => setIsMemoryOpen(!isMemoryOpen)}
               className={`w-10 h-10 rounded-full flex items-center justify-center transition-all ${isMemoryOpen ? 'bg-blue-600 text-white' : 'bg-white/5 text-gray-400 hover:bg-white/10'}`}
             >
               <i className="fas fa-brain"></i>
             </button>
             <button 
               onClick={() => setIsSettingsOpen(true)}
               className="w-10 h-10 rounded-full flex items-center justify-center bg-white/5 text-gray-400 hover:bg-white/10 transition-all"
             >
               <i className="fas fa-cog"></i>
             </button>
          </div>
        </header>

        <div className="flex-1 flex flex-col min-h-0 bg-white/5 rounded-[2rem] border border-white/10 backdrop-blur-md overflow-hidden relative">
          <div className="absolute inset-0 bg-gradient-to-br from-blue-500/5 via-transparent to-cyan-500/5"></div>

          <div className="absolute top-6 left-1/2 -translate-x-1/2 z-20 space-y-2 flex flex-col items-center">
            {isLearning && (
              <div className="bg-yellow-500/20 border border-yellow-500/50 text-yellow-200 text-[10px] px-4 py-1.5 rounded-full uppercase tracking-tighter flex items-center gap-2 animate-bounce">
                <i className="fas fa-lightbulb"></i> Learning facts...
              </div>
            )}
            {isNoisy && state !== AssistantState.IDLE && (
              <div className="bg-orange-500/20 border border-orange-500/50 text-orange-200 text-[10px] px-4 py-1.5 rounded-full uppercase tracking-tighter flex items-center gap-2">
                <i className="fas fa-wind"></i> Noise Filtering
              </div>
            )}
          </div>

          <div className="flex-1 flex flex-col items-center justify-center z-10 p-6">
            {state === AssistantState.IDLE ? (
              <div className="text-center animate-fade-in max-w-sm">
                <div className="w-32 h-32 rounded-full bg-blue-600/10 border border-blue-500/20 flex items-center justify-center mx-auto mb-8 relative group">
                  <div className="absolute inset-0 rounded-full bg-blue-500/20 animate-pulse group-hover:bg-blue-500/30 transition-all"></div>
                  <i className="fas fa-microphone-lines text-5xl text-blue-400"></i>
                </div>
                <h2 className="text-2xl font-bold mb-3">Initialize {assistantName}</h2>
                <p className="text-gray-400 text-sm leading-relaxed">Your personal AI, capable of learning your preferences and adapting its identity to your liking.</p>
              </div>
            ) : (
              <div className="w-full max-w-lg flex flex-col items-center">
                 <div className="text-[10px] font-bold tracking-[0.2em] text-blue-400 uppercase mb-6 animate-pulse">
                    {state === AssistantState.CONNECTING ? 'Syncing...' : state === AssistantState.LISTENING ? 'Listening' : 'Speaking'}
                 </div>
                 <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
              </div>
            )}
          </div>

          <div className="h-48 md:h-64 bg-black/40 border-t border-white/10 p-6 flex flex-col">
            <div className="flex items-center gap-2 mb-4 text-[10px] font-bold text-gray-500 uppercase tracking-widest">
               <i className="fas fa-align-left"></i>
               Synchronized Transcript
            </div>
            <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-4 pr-4 scrollbar-thin scrollbar-thumb-white/10">
              {transcriptions.length === 0 && (
                <div className="h-full flex items-center justify-center text-gray-600 italic text-xs">
                  Ready for communication...
                </div>
              )}
              {transcriptions.map((entry) => (
                <div 
                  key={entry.id} 
                  className={`flex flex-col ${entry.sender === 'user' ? 'items-end' : 'items-start'} animate-slide-up`}
                >
                  <div className={`max-w-[80%] rounded-2xl px-5 py-3 text-sm leading-relaxed shadow-sm transition-all ${
                    entry.sender === 'user' 
                      ? 'bg-blue-600 text-white rounded-tr-none' 
                      : 'bg-white/10 text-gray-200 border border-white/10 rounded-tl-none'
                  }`}>
                    {entry.text}
                  </div>
                  <span className="text-[9px] text-gray-600 mt-1 uppercase tracking-widest">
                    {entry.sender === 'user' ? 'You' : assistantName}
                  </span>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="flex items-center justify-center mt-8 gap-6">
          {state === AssistantState.IDLE ? (
            <button
              onClick={startSession}
              className="group relative flex items-center gap-4 bg-white text-[#0a0a1a] font-black py-5 px-14 rounded-full transition-all duration-300 shadow-2xl hover:scale-105 active:scale-95"
            >
              <i className="fas fa-play text-xl"></i>
              <span className="tracking-tighter uppercase">Activate {assistantName}</span>
            </button>
          ) : (
            <button
              onClick={stopSession}
              className="flex items-center gap-4 bg-red-500/10 hover:bg-red-500 text-white font-black py-5 px-14 rounded-full border border-red-500/50 transition-all duration-300 hover:shadow-2xl hover:shadow-red-500/40 active:scale-95"
            >
              <i className="fas fa-power-off text-xl"></i>
              <span className="tracking-tighter uppercase">Deactivate</span>
            </button>
          )}
        </div>
      </div>

      <aside className={`fixed right-0 top-0 bottom-0 w-[320px] z-40 transition-transform duration-500 ease-in-out transform bg-[#0d0d1f] shadow-2xl border-l border-white/5 ${isMemoryOpen ? 'translate-x-0' : 'translate-x-full'}`}>
         <div className="flex flex-col h-full pt-8">
            <button onClick={() => setIsMemoryOpen(false)} className="absolute top-8 right-6 text-gray-500 hover:text-white"><i className="fas fa-times text-xl"></i></button>
            <MemoryBank memories={memories} onRemove={removeMemory} assistantName={assistantName} />
         </div>
      </aside>

      {/* Settings Modal */}
      {isSettingsOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/60 backdrop-blur-sm animate-fade-in">
          <div className="bg-[#0f0f25] border border-white/10 rounded-[2.5rem] w-full max-w-md p-8 shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 to-purple-500"></div>
            <button onClick={() => setIsSettingsOpen(false)} className="absolute top-6 right-6 text-gray-500 hover:text-white transition-colors"><i className="fas fa-times text-xl"></i></button>

            <h2 className="text-2xl font-black mb-8 tracking-tighter">Assistant Settings</h2>

            <div className="space-y-8">
              <div className="space-y-3">
                <label className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Assistant Name</label>
                <div className="relative">
                  <i className="fas fa-id-card absolute left-4 top-1/2 -translate-y-1/2 text-gray-600"></i>
                  <input 
                    type="text" 
                    value={assistantName}
                    onChange={(e) => setAssistantName(e.target.value)}
                    className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 pl-12 pr-4 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all"
                  />
                </div>
                <p className="text-[9px] text-gray-600 italic">Tip: You can also say "Your name is now Jarvis" to change it via voice.</p>
              </div>

              <div className="space-y-3">
                <label className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Voice Synthesis</label>
                <div className="grid grid-cols-1 gap-2">
                  {VOICES.map(voice => (
                    <button
                      key={voice.id}
                      onClick={() => setSelectedVoice(voice.id)}
                      disabled={state !== AssistantState.IDLE}
                      className={`flex items-center justify-between px-5 py-3 rounded-2xl border transition-all ${selectedVoice === voice.id ? 'bg-blue-600/10 border-blue-500 text-blue-400' : 'bg-white/5 border-white/10 text-gray-400 hover:bg-white/10'}`}
                    >
                      <span className="text-sm font-medium">{voice.name}</span>
                      {selectedVoice === voice.id && <i className="fas fa-check-circle"></i>}
                    </button>
                  ))}
                </div>
              </div>

              <button 
                onClick={() => setIsSettingsOpen(false)}
                className="w-full bg-white text-black font-black py-4 rounded-2xl shadow-xl hover:scale-[1.02] active:scale-95 transition-all mt-4"
              >
                SAVE CONFIGURATION
              </button>
            </div>
          </div>
        </div>
      )}

      {isMemoryOpen && <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-30 md:hidden animate-fade-in" onClick={() => setIsMemoryOpen(false)}></div>}
    </div>
  );
};

export default App;

export enum AssistantState {
  IDLE = 'IDLE',
  CONNECTING = 'CONNECTING',
  LISTENING = 'LISTENING',
  SPEAKING = 'SPEAKING',
  THINKING = 'THINKING',
  ERROR = 'ERROR'
}

export interface GroundingSource {
  title: string;
  uri: string;
}

export interface TranscriptionEntry {
  id: string;
  sender: 'user' | 'assistant';
  text: string;
  timestamp: Date;
  isThinking?: boolean;
  sources?: GroundingSource[];
}

export interface MemoryEntry {
  id: string;
  fact: string;
  timestamp: Date;
}

export interface VoiceOption {
  id: string;
  name: string;
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const STORAGE_KEY = 'nova_assistant_memories';
const NAME_STORAGE_KEY = 'nova_assistant_name';

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or piece of information provided by the user for long-term memory.',
    properties: {
      fact: {
        type: Type.STRING,
        description: 'The specific fact or piece of information to remember (e.g., "The user loves spicy food").',
      },
    },
    required: ['fact'],
  },
};

const updateIdentityTool: FunctionDeclaration = {
  name: 'update_identity',
  parameters: {
    type: Type.OBJECT,
    description: 'Update your own identity/name based on the user’s request.',
    properties: {
      newName: {
        type: Type.STRING,
        description: 'The new name the user wants to call you.',
      },
    },
    required: ['newName'],
  },
};

const App: React.FC = () => {
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [assistantName, setAssistantName] = useState('Nova');
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [selectedVoice, setSelectedVoice] = useState(VOICES[0].id);
  const [isHighPrecision, setIsHighPrecision] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [isLearning, setIsLearning] = useState(false);
  const [isRebranding, setIsRebranding] = useState(false);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);

  const currentInputTranscript = useRef('');
  const currentOutputTranscript = useRef('');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const savedMemories = localStorage.getItem(STORAGE_KEY);
    if (savedMemories) {
      try { setMemories(JSON.parse(savedMemories)); } catch (e) { console.error("Memory error"); }
    }
    const savedName = localStorage.getItem(NAME_STORAGE_KEY);
    if (savedName) setAssistantName(savedName);
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(memories));
  }, [memories]);

  useEffect(() => {
    localStorage.setItem(NAME_STORAGE_KEY, assistantName);
  }, [assistantName]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [transcriptions]);

  const addTranscription = (sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      {
        id: Math.random().toString(36).substr(2, 9),
        sender,
        text,
        timestamp: new Date(),
        sources
      }
    ]);
  };

  const performDeepThinking = async (query: string) => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) return;

    setState(AssistantState.THINKING);
    const ai = new GoogleGenAI({ apiKey });

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: query,
        config: {
          thinkingConfig: { thinkingBudget: 32768 },
          tools: [{ googleSearch: {} }]
        }
      });

      const text = response.text || "I processed that request but couldn't generate a text response.";
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const sources: GroundingSource[] = chunks
        .filter(c => c.web)
        .map(c => ({ title: c.web!.title, uri: c.web!.uri }));

      addTranscription('assistant', text, sources);

      // Optionally TTS the result
      const ttsResponse = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `High precision results are ready. ${text.slice(0, 200)}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: selectedVoice } } },
        },
      });

      const audioData = ttsResponse.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (audioData && audioContextRef.current) {
        const audioBuffer = await audioUtils.decodeAudioData(audioUtils.decode(audioData), audioContextRef.current.output, 24000, 1);
        const sourceNode = audioContextRef.current.output.createBufferSource();
        sourceNode.buffer = audioBuffer;
        sourceNode.connect(audioContextRef.current.output.destination);
        sourceNode.start();
      }
    } catch (err) {
      console.error("Deep thinking failed", err);
    } finally {
      setState(AssistantState.LISTENING);
    }
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close?.(); sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(track => track.stop()); micStreamRef.current = null; }
    activeSourcesRef.current.forEach(source => source.stop());
    activeSourcesRef.current.clear();
    setState(AssistantState.IDLE);
    setIsLearning(false);
  }, []);

  const startSession = async () => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);

      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key is missing.");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      await inputCtx.resume(); await outputCtx.resume();

      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true, sampleRate: 16000 } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const knownFacts = memories.length > 0 ? `Facts: ${memories.map(m => m.fact).join('; ')}.` : '';

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools: [{ functionDeclarations: [saveKnowledgeTool, updateIdentityTool] }],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: selectedVoice } } },
          systemInstruction: `You are ${assistantName}, an Elite Intelligence Unit. Accuracy is your primary directive. ${knownFacts}
          - LOGIC: Be mathematically precise and logically consistent.
          - IDENTITY: Your name is ${assistantName}.
          - ADAPTATION: Use tools to update memory or identity when requested.
          - QUALITY: If a question is complex, provide a high-level summary.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {}
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(session => {
                if (sessionRef.current) session.sendRealtimeInput({ media: audioUtils.createPcmBlob(inputData) });
              });
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  setMemories(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), fact: (fc.args as any).fact, timestamp: new Date() }]);
                  setIsLearning(true);
                  setTimeout(() => setIsLearning(false), 2000);
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Memory unsealed." } } }));
                }
                if (fc.name === 'update_identity') {
                  setAssistantName((fc.args as any).newName);
                  setIsRebranding(true);
                  setTimeout(() => setIsRebranding(false), 2000);
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Identity localized." } } }));
                }
              }
            }

            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const audioBuffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const sourceNode = outputCtx.createBufferSource();
              sourceNode.buffer = audioBuffer;
              sourceNode.connect(outputCtx.destination);
              sourceNode.addEventListener('ended', () => {
                activeSourcesRef.current.delete(sourceNode);
                if (activeSourcesRef.current.size === 0) setState(AssistantState.LISTENING);
              });
              sourceNode.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              activeSourcesRef.current.add(sourceNode);
            }

            if (message.serverContent?.inputTranscription) currentInputTranscript.current += message.serverContent.inputTranscription.text;
            if (message.serverContent?.outputTranscription) currentOutputTranscript.current += message.serverContent.outputTranscription.text;

            if (message.serverContent?.turnComplete) {
              const userInput = currentInputTranscript.current;
              if (userInput) {
                addTranscription('user', userInput);
                if (isHighPrecision && userInput.length > 5) {
                   performDeepThinking(userInput);
                }
                currentInputTranscript.current = '';
              }
              if (currentOutputTranscript.current) { addTranscription('assistant', currentOutputTranscript.current); currentOutputTranscript.current = ''; }
            }
          },
          onerror: () => stopSession(),
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) {
      setError(err.message);
      setState(AssistantState.IDLE);
    }
  };

  return (
    <div className="flex flex-col md:flex-row h-screen w-full bg-[#050510] text-white overflow-hidden font-sans">
      <div className={`flex-1 flex flex-col p-4 md:p-8 transition-all duration-500 ${isMemoryOpen ? 'md:mr-[320px]' : ''}`}>

        <header className="flex items-center justify-between mb-8">
          <div className="flex items-center gap-6">
            <div className={`w-14 h-14 rounded-3xl flex items-center justify-center shadow-2xl transition-all duration-500 ${state !== AssistantState.IDLE ? 'bg-blue-600 shadow-blue-500/50 scale-110' : 'bg-white/5 border border-white/10'}`}>
              <i className={`fas ${state === AssistantState.THINKING ? 'fa-microchip animate-pulse' : 'fa-atom'} text-2xl`}></i>
            </div>
            <div>
              <div className="flex items-center gap-3">
                <h1 className="text-2xl font-black tracking-tighter bg-gradient-to-r from-blue-400 via-cyan-300 to-indigo-400 bg-clip-text text-transparent">
                  {assistantName} <span className="text-gray-600 font-light">OS</span>
                </h1>
                {isHighPrecision && (
                  <span className="bg-blue-500/20 text-blue-400 text-[9px] px-2 py-0.5 rounded-full border border-blue-500/30 font-bold tracking-widest animate-pulse">
                    MAX PRECISION
                  </span>
                )}
              </div>
              <div className="flex items-center gap-2 mt-1">
                <div className={`w-1.5 h-1.5 rounded-full ${state === AssistantState.IDLE ? 'bg-gray-700' : 'bg-blue-400 animate-pulse'}`}></div>
                <p className="text-[9px] text-gray-500 font-bold uppercase tracking-[0.2em]">
                  {state === AssistantState.IDLE ? 'Standby Mode' : state === AssistantState.THINKING ? 'Deep Reasoning Active' : 'Neural Link Active'}
                </p>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-4">
             <div className="hidden lg:flex flex-col items-end mr-4">
                <span className="text-[9px] text-gray-600 font-bold uppercase tracking-widest mb-1">Cognitive Accuracy</span>
                <div className="w-32 h-1 bg-white/5 rounded-full overflow-hidden">
                   <div className={`h-full transition-all duration-1000 ${isHighPrecision ? 'w-full bg-blue-500' : 'w-2/3 bg-cyan-500/50'}`}></div>
                </div>
             </div>
             <button 
               onClick={() => setIsHighPrecision(!isHighPrecision)}
               className={`px-4 py-2 rounded-xl text-[10px] font-black tracking-widest border transition-all ${isHighPrecision ? 'bg-blue-600 border-blue-400 text-white shadow-lg shadow-blue-500/40' : 'bg-white/5 border-white/10 text-gray-500 hover:text-white'}`}
             >
               {isHighPrecision ? 'ACCURACY: MAX' : 'ACCURACY: STANDARD'}
             </button>
             <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-11 h-11 rounded-2xl flex items-center justify-center transition-all ${isMemoryOpen ? 'bg-blue-600' : 'bg-white/5 hover:bg-white/10 border border-white/10'}`}>
               <i className="fas fa-brain text-sm"></i>
             </button>
             <button onClick={() => setIsSettingsOpen(true)} className="w-11 h-11 rounded-2xl flex items-center justify-center bg-white/5 border border-white/10 hover:bg-white/10"><i className="fas fa-sliders text-sm"></i></button>
          </div>
        </header>

        <main className="flex-1 flex flex-col min-h-0 bg-white/[0.02] rounded-[3rem] border border-white/5 backdrop-blur-3xl overflow-hidden relative shadow-2xl">
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_0%,_rgba(59,130,246,0.05)_0%,_transparent_50%)]"></div>

          <div className="flex-1 flex flex-col items-center justify-center z-10 p-8">
            {state === AssistantState.IDLE ? (
              <div className="text-center animate-fade-in space-y-8">
                <div className="relative inline-block">
                  <div className="w-40 h-40 rounded-[3rem] bg-blue-600/5 border border-blue-500/20 flex items-center justify-center mx-auto shadow-inner">
                    <i className="fas fa-fingerprint text-6xl text-blue-500/40"></i>
                  </div>
                  <div className="absolute -bottom-2 -right-2 w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center shadow-xl">
                    <i className="fas fa-bolt text-white text-sm"></i>
                  </div>
                </div>
                <div className="max-w-xs mx-auto">
                  <h2 className="text-3xl font-black mb-4 tracking-tighter">System Ready.</h2>
                  <p className="text-gray-500 text-sm leading-relaxed font-medium">Initialize {assistantName} to begin an elite precision-focused cognitive session.</p>
                </div>
              </div>
            ) : (
              <div className="w-full max-w-2xl flex flex-col items-center">
                 <div className="text-[10px] font-bold tracking-[0.4em] text-blue-400 uppercase mb-12 animate-pulse">
                    {state === AssistantState.THINKING ? 'Navigating Logical Vectors' : 'Neural Synchronization'}
                 </div>
                 <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
                 {state === AssistantState.THINKING && (
                    <div className="mt-8 flex items-center gap-3 bg-blue-500/10 border border-blue-500/30 px-6 py-3 rounded-2xl animate-bounce">
                       <i className="fas fa-spinner fa-spin text-blue-400 text-xs"></i>
                       <span className="text-[10px] font-bold uppercase tracking-widest text-blue-200">Processing 32k Thinking Tokens...</span>
                    </div>
                 )}
              </div>
            )}
          </div>

          <div className="h-64 md:h-80 bg-black/60 border-t border-white/5 p-8 flex flex-col backdrop-blur-xl">
            <div className="flex items-center justify-between mb-6">
              <div className="flex items-center gap-3 text-[10px] font-black text-gray-500 uppercase tracking-[0.3em]">
                 <i className="fas fa-list-ul text-blue-500"></i>
                 Verified Stream
              </div>
              <div className="flex gap-1">
                 <div className="w-1.5 h-1.5 rounded-full bg-blue-500"></div>
                 <div className="w-1.5 h-1.5 rounded-full bg-blue-500/30"></div>
                 <div className="w-1.5 h-1.5 rounded-full bg-blue-500/10"></div>
              </div>
            </div>

            <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-6 pr-6 scrollbar-thin scrollbar-thumb-white/10">
              {transcriptions.map((entry) => (
                <div key={entry.id} className={`flex flex-col ${entry.sender === 'user' ? 'items-end' : 'items-start'} animate-slide-up`}>
                  <div className={`max-w-[85%] rounded-[1.5rem] px-6 py-4 text-sm leading-relaxed shadow-sm transition-all ${
                    entry.sender === 'user' ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white/5 text-gray-200 border border-white/10 rounded-tl-none'
                  }`}>
                    {entry.text}
                    {entry.sources && entry.sources.length > 0 && (
                      <div className="mt-4 pt-4 border-t border-white/10 space-y-2">
                        <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest">Verified Sources:</p>
                        <div className="flex flex-wrap gap-2">
                          {entry.sources.map((s, idx) => (
                            <a key={idx} href={s.uri} target="_blank" rel="noreferrer" className="text-[10px] bg-white/5 hover:bg-white/10 border border-white/10 px-3 py-1 rounded-full text-gray-400 flex items-center gap-2 transition-all">
                              <i className="fas fa-link text-[8px]"></i> {s.title.slice(0, 20)}...
                            </a>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                  <span className="text-[8px] text-gray-600 mt-2 font-black uppercase tracking-[0.2em]">
                    {entry.sender === 'user' ? 'Direct Input' : `${assistantName} Unit`}
                  </span>
                </div>
              ))}
            </div>
          </div>
        </main>

        <div className="flex items-center justify-center mt-10 gap-8">
          {state === AssistantState.IDLE ? (
            <button onClick={startSession} className="group relative flex items-center gap-6 bg-white text-black font-black py-6 px-16 rounded-[2rem] transition-all duration-500 shadow-[0_0_50px_rgba(255,255,255,0.1)] hover:scale-105 active:scale-95">
              <i className="fas fa-power-off text-xl"></i>
              <span className="tracking-[0.2em] uppercase text-sm">Engage System</span>
            </button>
          ) : (
            <button onClick={stopSession} className="flex items-center gap-6 bg-red-500/5 hover:bg-red-600 text-white font-black py-6 px-16 rounded-[2rem] border border-red-500/20 transition-all duration-500 hover:shadow-2xl hover:shadow-red-500/40 active:scale-95">
              <i className="fas fa-stop text-xl"></i>
              <span className="tracking-[0.2em] uppercase text-sm">Terminate Link</span>
            </button>
          )}
        </div>
      </div>

      <aside className={`fixed right-0 top-0 bottom-0 w-[320px] z-40 transition-transform duration-700 cubic-bezier(0.4, 0, 0.2, 1) transform bg-[#070715] shadow-[0_0_100px_rgba(0,0,0,0.5)] border-l border-white/5 ${isMemoryOpen ? 'translate-x-0' : 'translate-x-full'}`}>
         <div className="flex flex-col h-full pt-10">
            <button onClick={() => setIsMemoryOpen(false)} className="absolute top-10 right-8 text-gray-600 hover:text-white transition-colors"><i className="fas fa-times text-2xl"></i></button>
            <MemoryBank memories={memories} onRemove={(id) => setMemories(prev => prev.filter(m => m.id !== id))} assistantName={assistantName} />
         </div>
      </aside>

      {isSettingsOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/80 backdrop-blur-md animate-fade-in">
          <div className="bg-[#0a0a1f] border border-white/10 rounded-[3rem] w-full max-w-lg p-10 shadow-3xl relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-blue-600 via-cyan-400 to-indigo-600"></div>
            <button onClick={() => setIsSettingsOpen(false)} className="absolute top-8 right-8 text-gray-600 hover:text-white"><i className="fas fa-times text-2xl"></i></button>
            <h2 className="text-3xl font-black mb-10 tracking-tighter">System Configuration</h2>
            <div className="space-y-10">
              <div className="space-y-4">
                <label className="text-[10px] font-black text-gray-500 uppercase tracking-[0.3em]">Designation</label>
                <input type="text" value={assistantName} onChange={(e) => setAssistantName(e.target.value)} className="w-full bg-white/5 border border-white/10 rounded-2xl py-5 px-6 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all font-bold text-lg" />
              </div>
              <div className="space-y-4">
                <label className="text-[10px] font-black text-gray-500 uppercase tracking-[0.3em]">Vocal Profile</label>
                <div className="grid grid-cols-1 gap-3">
                  {VOICES.map(voice => (
                    <button key={voice.id} onClick={() => setSelectedVoice(voice.id)} className={`flex items-center justify-between px-6 py-4 rounded-2xl border transition-all ${selectedVoice === voice.id ? 'bg-blue-600/10 border-blue-500 text-blue-400' : 'bg-white/5 border-white/10 text-gray-500 hover:bg-white/10'}`}>
                      <span className="font-bold">{voice.name}</span>
                      {selectedVoice === voice.id && <i className="fas fa-check-circle"></i>}
                    </button>
                  ))}
                </div>
              </div>
              <button onClick={() => setIsSettingsOpen(false)} className="w-full bg-white text-black font-black py-5 rounded-2xl shadow-2xl hover:scale-[1.02] active:scale-95 transition-all text-sm tracking-widest">COMMIT CHANGES</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

{
  "name": "Nova Virtual Assistant - Ultimate Edition",
  "description": "A high-fidelity AI companion featuring real-time voice, vision, deep reasoning, and secure biometric access.",
  "requestFramePermissions": [
    "microphone",
    "camera"
  ]
}

export enum AssistantState {
  IDLE = 'IDLE',
  CONNECTING = 'CONNECTING',
  LISTENING = 'LISTENING',
  SPEAKING = 'SPEAKING',
  THINKING = 'THINKING',
  OBSERVING = 'OBSERVING',
  ERROR = 'ERROR'
}

export interface GroundingSource {
  title: string;
  uri: string;
}

export interface TranscriptionEntry {
  id: string;
  sender: 'user' | 'assistant';
  text: string;
  timestamp: Date;
  isThinking?: boolean;
  sources?: GroundingSource[];
}

export interface MemoryEntry {
  id: string;
  fact: string;
  timestamp: Date;
}

export interface AuthUser {
  username: string;
}

import React, { useState } from 'react';

interface LoginPageProps {
  onLogin: (username: string) => void;
}

const LoginPage: React.FC<LoginPageProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (username.trim()) {
      setIsLoading(true);
      setTimeout(() => onLogin(username.trim()), 1500);
    }
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center p-6 bg-[#02020a] relative overflow-hidden">
      {/* Neural Background Elements */}
      <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-blue-600/10 rounded-full blur-[120px] animate-pulse"></div>
      <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-indigo-600/10 rounded-full blur-[120px] animate-pulse"></div>

      <div className="w-full max-w-md z-10">
        <div className="bg-white/5 backdrop-blur-3xl border border-white/10 rounded-[3rem] p-10 shadow-[0_0_80px_rgba(0,0,0,0.5)] relative overflow-hidden group">
          <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-blue-500 to-transparent opacity-20 group-hover:animate-[scan_3s_linear_infinite]"></div>

          <div className="text-center mb-10">
            <div className="w-24 h-24 rounded-[2rem] bg-gradient-to-br from-blue-600 to-indigo-600 flex items-center justify-center mx-auto mb-6 shadow-2xl shadow-blue-500/20">
              <i className={`fas ${isLoading ? 'fa-spinner fa-spin' : 'fa-fingerprint'} text-4xl text-white`}></i>
            </div>
            <h2 className="text-3xl font-black tracking-tighter mb-2">Access Portal</h2>
            <p className="text-gray-500 text-[10px] font-bold uppercase tracking-[0.3em]">Neural Interface v4.0</p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
