import React, { useRef, useEffect } from 'react';

interface ObservationModeProps {
  isActive: boolean;
  onFrame: (base64: string) => void;
}

const ObservationMode: React.FC<ObservationModeProps> = ({ isActive, onFrame }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    let stream: MediaStream | null = null;
    let interval: number | null = null;

    const startCamera = async () => {
      try {
        stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }

        interval = window.setInterval(() => {
          if (videoRef.current && canvasRef.current) {
            const video = videoRef.current;
            const canvas = canvasRef.current;
            const ctx = canvas.getContext('2d');
            if (ctx) {
              canvas.width = video.videoWidth;
              canvas.height = video.videoHeight;
              ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
              const base64 = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];
              onFrame(base64);
            }
          }
        }, 1000); // 1 FPS for efficiency
      } catch (err) {
        console.error("Camera access failed", err);
      }
    };

    if (isActive) {
      startCamera();
    }

    return () => {
      if (stream) {
        stream.getTracks().forEach(t => t.stop());
      }
      if (interval) {
        clearInterval(interval);
      }
    };
  }, [isActive, onFrame]);

  if (!isActive) return null;

  return (
    <div className="relative rounded-[2rem] overflow-hidden border border-white/20 shadow-2xl bg-black animate-fade-in group">
      <video ref={videoRef} autoPlay playsInline muted className="w-full aspect-video object-cover" />
      <canvas ref={canvasRef} className="hidden" />
      <div className="absolute inset-0 pointer-events-none border-[20px] border-blue-500/10"></div>
      <div className="absolute top-4 left-4 bg-red-500 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest flex items-center gap-2 animate-pulse">
        <div className="w-2 h-2 rounded-full bg-white"></div>
        Live Optics
      </div>
      <div className="absolute bottom-4 right-4 text-[10px] text-white/50 font-mono">
        VISION FEED 01 // GROUNDING ACTIVE
      </div>
    </div>
  );
};

export default ObservationMode;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const updateIdentityTool: FunctionDeclaration = {
  name: 'update_identity',
  parameters: {
    type: Type.OBJECT,
    description: 'Update the assistant name.',
    properties: {
      newName: { type: Type.STRING, description: 'The new name requested.' },
    },
    required: ['newName'],
  },
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [assistantName, setAssistantName] = useState('Nova');
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [selectedVoice, setSelectedVoice] = useState(VOICES[0].id);
  const [isHighPrecision, setIsHighPrecision] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [isLearning, setIsLearning] = useState(false);
  const [isRebranding, setIsRebranding] = useState(false);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);

  const currentInputTranscript = useRef('');
  const currentOutputTranscript = useRef('');
  const scrollRef = useRef<HTMLDivElement>(null);

  // Persistence logic
  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) setUser({ username: sessionUser });
  }, []);

  useEffect(() => {
    if (user) {
      const savedMemories = localStorage.getItem(`nova_${user.username}_memories`);
      if (savedMemories) setMemories(JSON.parse(savedMemories));
      const savedName = localStorage.getItem(`nova_${user.username}_name`);
      if (savedName) setAssistantName(savedName);
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_name`, assistantName);
    }
  }, [memories, assistantName, user]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [transcriptions]);

  const addTranscription = (sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  };

  const handleDeepThink = async (query: string) => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) return;
    setState(AssistantState.THINKING);
    const ai = new GoogleGenAI({ apiKey });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: query,
        config: {
          thinkingConfig: { thinkingBudget: 32768 },
          tools: [{ googleSearch: {} }]
        }
      });
      const text = response.text || "";
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const sources: GroundingSource[] = chunks.filter(c => c.web).map(c => ({ title: c.web!.title, uri: c.web!.uri }));
      addTranscription('assistant', text, sources);
    } catch (err) {
      console.error("Deep thinking error", err);
    } finally {
      setState(AssistantState.LISTENING);
    }
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close?.(); sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    activeSourcesRef.current.forEach(s => s.stop());
    activeSourcesRef.current.clear();
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
  }, []);

  const startSession = async () => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      await inputCtx.resume(); await outputCtx.resume();

      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools: [{ functionDeclarations: [saveKnowledgeTool, updateIdentityTool] }],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: selectedVoice } } },
          systemInstruction: `Identity: ${assistantName}. Context: User is ${user?.username}. Memories: ${facts}. 
          Objective: Be the ultimate assistant. If vision is active, describe what you see. For deep logic, use precision mode.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {}
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(s => s.sendRealtimeInput({ media: audioUtils.createPcmBlob(inputData) }));
              // Send camera frame if active
              if (currentFrameRef.current && sessionRef.current) {
                sessionPromise.then(s => s.sendRealtimeInput({ media: { data: currentFrameRef.current!, mimeType: 'image/jpeg' } }));
                currentFrameRef.current = null;
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: (fc.args as any).fact, timestamp: new Date() }]);
                  setIsLearning(true); setTimeout(() => setIsLearning(false), 2000);
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Learned." } } }));
                }
                if (fc.name === 'update_identity') {
                  setAssistantName((fc.args as any).newName);
                  setIsRebranding(true); setTimeout(() => setIsRebranding(false), 2000);
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Updated." } } }));
                }
              }
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); s.buffer = buffer; s.connect(outputCtx.destination);
              s.onended = () => { activeSourcesRef.current.delete(s); if (activeSourcesRef.current.size === 0) setState(AssistantState.LISTENING); };
              s.start(nextStartTimeRef.current); nextStartTimeRef.current += buffer.duration;
              activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) currentInputTranscript.current += message.serverContent.inputTranscription.text;
            if (message.serverContent?.outputTranscription) currentOutputTranscript.current += message.serverContent.outputTranscription.text;
            if (message.serverContent?.turnComplete) {
              const uInput = currentInputTranscript.current;
              if (uInput) {
                addTranscription('user', uInput);
                if (isHighPrecision) handleDeepThink(uInput);
                currentInputTranscript.current = '';
              }
              if (currentOutputTranscript.current) { addTranscription('assistant', currentOutputTranscript.current); currentOutputTranscript.current = ''; }
            }
            if (message.serverContent?.interrupted) { activeSourcesRef.current.forEach(s => s.stop()); activeSourcesRef.current.clear(); nextStartTimeRef.current = 0; setState(AssistantState.LISTENING); }
          },
          onerror: () => stopSession(),
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(err.message); setState(AssistantState.IDLE); }
  };

  const handleLogout = () => {
    stopSession();
    setUser(null);
    sessionStorage.removeItem('nova_session_user');
  };

  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u })} />;

  return (
    <div className="flex flex-col md:flex-row h-screen w-full bg-[#02020a] text-white overflow-hidden font-sans selection:bg-blue-500/30">
      <div className={`flex-1 flex flex-col p-4 md:p-8 transition-all duration-700 ${isMemoryOpen ? 'md:mr-[340px]' : ''}`}>

        <header className="flex items-center justify-between mb-8 animate-fade-in">
          <div className="flex items-center gap-6">
            <div className={`w-16 h-16 rounded-[2rem] flex items-center justify-center shadow-2xl transition-all duration-500 border border-white/10 ${state !== AssistantState.IDLE ? 'bg-blue-600 shadow-blue-500/40 rotate-12 scale-110' : 'bg-white/5'}`}>
              <i className={`fas ${state === AssistantState.THINKING ? 'fa-microchip animate-pulse' : isVisionActive ? 'fa-eye' : 'fa-atom'} text-3xl text-white`}></i>
            </div>
            <div>
              <div className="flex items-center gap-4">
                <h1 className="text-3xl font-black tracking-tighter bg-gradient-to-r from-blue-400 via-indigo-400 to-purple-400 bg-clip-text text-transparent">
                  {assistantName}
                </h1>
                <div className="flex gap-2">
                  {isHighPrecision && <span className="bg-blue-500/20 text-blue-400 text-[8px] font-black uppercase px-2 py-0.5 rounded-full border border-blue-500/30 tracking-[0.2em] animate-pulse">Precision: Max</span>}
                  {isVisionActive && <span className="bg-red-500/20 text-red-400 text-[8px] font-black uppercase px-2 py-0.5 rounded-full border border-red-500/30 tracking-[0.2em] animate-pulse">Vision: On</span>}
                </div>
              </div>
              <p className="text-[10px] text-gray-500 font-bold uppercase tracking-[0.4em] mt-1 flex items-center gap-2">
                <i className="fas fa-user-circle text-blue-500/50"></i> {user.username} // {state === AssistantState.IDLE ? 'Standby' : 'Neural Core Engaged'}
              </p>
            </div>
          </div>

          <div className="flex items-center gap-4">
             <button onClick={() => setIsVisionActive(!isVisionActive)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isVisionActive ? 'bg-red-500 text-white' : 'bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5'}`} title="Toggle Vision">
               <i className="fas fa-camera text-sm"></i>
             </button>
             <button onClick={() => setIsHighPrecision(!isHighPrecision)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isHighPrecision ? 'bg-blue-600 text-white' : 'bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5'}`} title="High Precision Mode">
               <i className="fas fa-brain text-sm"></i>
             </button>
             <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isMemoryOpen ? 'bg-indigo-600 text-white' : 'bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5'}`} title="Memory Bank">
