               {isLearning && <div className="bg-yellow-500/20 border border-yellow-500/50 text-yellow-200 text-[10px] px-6 py-2 rounded-full uppercase tracking-[0.2em] animate-bounce">Neural Map Updated</div>}
               {isRebranding && <div className="bg-cyan-500/20 border border-cyan-500/50 text-cyan-200 text-[10px] px-6 py-2 rounded-full uppercase tracking-[0.2em] animate-pulse">Persona Re-aligned</div>}
             </div>

             <div className="flex-1 flex flex-col items-center justify-center p-8 z-10">
               {state === AssistantState.IDLE ? (
                 <div className="text-center space-y-10 group">
                   <div className="w-48 h-48 rounded-[4rem] bg-blue-600/5 border border-blue-500/10 flex items-center justify-center mx-auto shadow-inner relative">
