                       {state === AssistantState.THINKING ? 'Divergent Reasoning' : isVisionActive ? 'Scanning Physical Plane' : 'Audio Sync Active'}
                    </div>
                    <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
                    {state === AssistantState.THINKING && (
                      <div className="mt-12 bg-white/5 border border-white/10 px-8 py-4 rounded-3xl flex items-center gap-4 backdrop-blur-md">
