                 <div className="flex gap-2 h-1.5">
                    <div className={`w-8 rounded-full ${state === AssistantState.SPEAKING ? 'bg-blue-500' : 'bg-white/10'}`}></div>
                    <div className={`w-8 rounded-full ${state === AssistantState.LISTENING ? 'bg-green-500' : 'bg-white/10'}`}></div>
                 </div>
               </div>
               <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-6 pr-6 scrollbar-thin scrollbar-thumb-white/10">
                 {transcriptions.map(e => (
                   <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'} animate-slide-up`}>
