                       )}
                     </div>
                     <span className="text-[8px] text-gray-700 mt-2 font-black uppercase tracking-[0.3em]">{e.sender === 'user' ? 'User Signature' : `${assistantName} Unit`}</span>
                   </div>
                 ))}
               </div>
             </div>
          </div>

          {isVisionActive && (
            <div className="w-full md:w-80 flex flex-col">
              <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />
              <div className="mt-6 p-6 bg-white/5 border border-white/10 rounded-[2rem] flex-1">
