                       <span className="text-gray-600">FRAME RATE</span>
                       <span className="text-blue-400">1.0 FPS</span>
                    </div>
                    <div className="w-full h-1 bg-white/5 rounded-full mt-4 overflow-hidden">
                       <div className="w-full h-full bg-blue-500 animate-[loading_2s_infinite]"></div>
                    </div>
                 </div>
              </div>
            </div>
          )}
        </main>

        <div className="flex items-center justify-center mt-10 gap-8">
           {state === AssistantState.IDLE ? (
             <button onClick={startSession} className="bg-white text-black font-black py-7 px-20 rounded-[2.5rem] shadow-[0_0_60px_rgba(255,255,255,0.1)] hover:scale-105 active:scale-95 transition-all flex items-center gap-6 group">
