import React, { useState, useEffect } from 'react';

interface LoginPageProps {
  onLogin: (username: string) => void;
}

type AuthMode = 'SIGN_IN' | 'SIGN_UP' | 'INITIAL';

const LoginPage: React.FC<LoginPageProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [mode, setMode] = useState<AuthMode>('INITIAL');
  const [identities, setIdentities] = useState<string[]>([]);
  const [loadingId, setLoadingId] = useState<string | null>(null);

  useEffect(() => {
    const stored = localStorage.getItem('nova_identities');
    if (stored) {
      const parsed = JSON.parse(stored);
      setIdentities(parsed);
      setMode(parsed.length > 0 ? 'SIGN_IN' : 'SIGN_UP');
    } else {
      setMode('SIGN_UP');
    }
  }, []);

  const handleAuth = (name: string) => {
    setLoadingId(name);
    // Persist identity
    const updated = Array.from(new Set([name, ...identities]));
    localStorage.setItem('nova_identities', JSON.stringify(updated));

    // Aesthetic delay for "Neural Sync"
    setTimeout(() => {
      onLogin(name);
    }, 1200);
  };

  const purgeIdentity = (e: React.MouseEvent, name: string) => {
    e.stopPropagation();
    const updated = identities.filter(i => i !== name);
    setIdentities(updated);
    localStorage.setItem('nova_identities', JSON.stringify(updated));
    if (updated.length === 0) setMode('SIGN_UP');
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center p-6 bg-[#02020a] relative overflow-hidden font-sans">
      {/* Background Ambience */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute top-[-15%] left-[-10%] w-[60%] h-[60%] bg-blue-600/10 rounded-full blur-[140px] animate-pulse-slow"></div>
        <div className="absolute bottom-[-15%] right-[-10%] w-[60%] h-[60%] bg-indigo-600/10 rounded-full blur-[140px] animate-pulse-slow"></div>
        <div className="w-full h-full bg-[radial-gradient(#ffffff05_1px,transparent_1px)] [background-size:40px_40px]"></div>
      </div>

      <div className="w-full max-w-2xl z-10 animate-fade-in">
        {mode === 'SIGN_IN' ? (
          <div className="space-y-10">
            <header className="text-center space-y-4">
              <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-full bg-blue-500/10 border border-blue-500/20 text-blue-400 text-[9px] font-black uppercase tracking-[0.4em] mb-4 mx-auto">
                <i className="fas fa-fingerprint"></i> Authorized Access Only
              </div>
              <h1 className="text-6xl font-black tracking-tighter text-white">Neural Profiles</h1>
              <p className="text-gray-500 text-sm font-medium tracking-widest uppercase">Select your identity to synchronize</p>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {identities.map((name) => (
                <button
                  key={name}
                  onClick={() => handleAuth(name)}
                  disabled={!!loadingId}
                  className={`group relative bg-white/[0.02] hover:bg-white/[0.06] border border-white/5 rounded-[2.5rem] p-8 transition-all duration-500 hover:scale-[1.02] text-left disabled:opacity-50 ${loadingId === name ? 'ring-2 ring-blue-500 bg-blue-500/10' : ''}`}
                >
                  <div className="flex items-start justify-between">
                    <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-blue-500 to-indigo-600 flex items-center justify-center text-xl font-black shadow-lg group-hover:rotate-3 transition-transform">
                      {loadingId === name ? <i className="fas fa-circle-notch fa-spin"></i> : name[0].toUpperCase()}
                    </div>
                    <button
                      onClick={(e) => purgeIdentity(e, name)}
                      className="text-gray-700 hover:text-red-400 p-2 transition-colors"
                      title="Purge Profile"
                    >
                      <i className="fas fa-times"></i>
                    </button>
                  </div>
