                  </div>
                </button>
              ))}

              <button
                onClick={() => setMode('SIGN_UP')}
                className="flex flex-col items-center justify-center gap-4 bg-white/[0.01] border-2 border-dashed border-white/5 rounded-[2.5rem] p-8 hover:bg-white/[0.03] hover:border-white/20 transition-all group"
              >
                <div className="w-14 h-14 rounded-2xl border-2 border-dashed border-white/10 flex items-center justify-center text-gray-600 group-hover:text-white group-hover:border-white/30 transition-all">
                  <i className="fas fa-user-plus"></i>
                </div>
                <div className="text-center">
                  <p className="font-black text-gray-500 group-hover:text-white transition-colors">Register New Recruit</p>
                </div>
              </button>
            </div>
          </div>
        ) : (
