                        value={username}
                        onChange={(e) => setUsername(e.target.value)}
                      />
                    </div>
                  </div>
                )}

                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest ml-2">Access Key</label>
                  <div className="relative group/input">
                    <i className="fas fa-key absolute left-6 top-1/2 -translate-y-1/2 text-gray-600 group-focus-within/input:text-blue-500 transition-colors"></i>
                    <input
                      type={showPassword ? 'text' : 'password'}
                      required
                      placeholder="••••••••"
                      className="w-full bg-white/5 border border-white/10 rounded-2xl py-5 pl-14 pr-14 focus:outline-none focus:border-blue-500/50 transition-all font-bold text-lg placeholder:text-gray-800"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                    />
                    <button 
                      type="button"
                      onClick={() => setShowPassword(!showPassword)}
                      className="absolute right-6 top-1/2 -translate-y-1/2 text-gray-600 hover:text-white transition-colors"
                    >
                      <i className={`fas ${showPassword ? 'fa-eye-slash' : 'fa-eye'}`}></i>
                    </button>
                  </div>
                </div>

                {error && (
                  <div className="bg-red-500/10 border border-red-500/20 rounded-xl p-4 text-red-400 text-[10px] font-bold uppercase tracking-widest text-center animate-pulse">
                    <i className="fas fa-triangle-exclamation mr-2"></i> {error}
                  </div>
                )}

                <button
                  type="submit"
                  disabled={isSyncing}
                  className="w-full bg-white text-black font-black py-6 rounded-2xl transition-all duration-500 hover:bg-blue-50 hover:scale-[1.02] active:scale-95 shadow-2xl flex items-center justify-center gap-4 disabled:opacity-50"
                >
                  <span className="tracking-widest">{isSyncing ? 'SYNCHRONIZING...' : mode === 'VERIFY' ? 'VERIFY KEY' : 'INITIATE LINK'}</span>
                  {!isSyncing && <i className="fas fa-bolt-lightning text-xs"></i>}
                </button>
              </form>

              <button
                onClick={() => { setMode('VAULT'); setError(null); setPassword(''); setUsername(''); }}
                className="mt-8 w-full text-[10px] text-gray-600 hover:text-white font-black uppercase tracking-[0.4em] transition-colors py-2 flex items-center justify-center gap-3"
              >
                <i className="fas fa-chevron-left text-[8px]"></i> Back to Vault
              </button>
            </div>

            <div className="mt-12 text-center">
              <p className="text-gray-700 text-[9px] font-black uppercase tracking-[0.8em]">
                Secure Segment Protocol // Local Access Only
              </p>
            </div>
          </div>
        )}
      </div>

      <style>{`
        @keyframes scan {
          0% { top: 0%; opacity: 0; }
          20% { opacity: 0.5; }
          80% { opacity: 0.5; }
          100% { top: 100%; opacity: 0; }
        }
        .animate-shake {
          animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both;
        }
        @keyframes shake {
          10%, 90% { transform: translate3d(-1px, 0, 0); }
          20%, 80% { transform: translate3d(2px, 0, 0); }
          30%, 50%, 70% { transform: translate3d(-4px, 0, 0); }
          40%, 60% { transform: translate3d(4px, 0, 0); }
        }
      `}</style>
    </div>
  );
};

