                  className="w-full bg-white text-black font-black py-6 rounded-2xl transition-all duration-500 hover:bg-blue-50 hover:scale-[1.02] active:scale-95 shadow-2xl flex items-center justify-center gap-4 disabled:opacity-50"
                >
                  <span className="tracking-widest">{isSyncing ? 'SYNCHRONIZING...' : mode === 'VERIFY' ? 'VERIFY PASSWORD' : 'INITIATE LINK'}</span>
                  {!isSyncing && <i className="fas fa-bolt-lightning text-xs"></i>}
                </button>
              </form>

              <button
                onClick={() => { setMode('VAULT'); setError(null); setPassword(''); setUsername(''); }}
                className="mt-8 w-full text-[10px] text-gray-600 hover:text-white font-black uppercase tracking-[0.4em] transition-colors py-2 flex items-center justify-center gap-3"
              >
                <i className="fas fa-chevron-left text-[8px]"></i> Back to Vault
              </button>
            </div>

            <div className="mt-12 text-center">
              <p className="text-gray-700 text-[9px] font-black uppercase tracking-[0.8em]">
                Secure Segment Protocol // Local Access Only
              </p>
            </div>
          </div>
        )}
      </div>

      <style>{`
        @keyframes scan {
          0% { top: 0%; opacity: 0; }
          20% { opacity: 0.5; }
          80% { opacity: 0.5; }
          100% { top: 100%; opacity: 0; }
        }
        .animate-shake {
          animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both;
        }
        @keyframes shake {
          10%, 90% { transform: translate3d(-1px, 0, 0); }
          20%, 80% { transform: translate3d(2px, 0, 0); }
          30%, 50%, 70% { transform: translate3d(-4px, 0, 0); }
          40%, 60% { transform: translate3d(4px, 0, 0); }
        }
      `}</style>
    </div>
  );
};

export default LoginPage;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser, UITheme, PersonalityType, UserPreferences } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const THEMES: Record<UITheme, { primary: string; secondary: string; glow: string; bg: string }> = {
  cosmic: { primary: 'blue-500', secondary: 'indigo-500', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: 'emerald-500', secondary: 'teal-500', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: 'rose-500', secondary: 'orange-500', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: 'slate-400', secondary: 'zinc-500', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: VOICES[0].id,
  assistantName: 'Nova'
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isHighPrecision, setIsHighPrecision] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [isLearning, setIsLearning] = useState(false);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Persistence: Initial User Load
  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
      setUser({ 
        username: sessionUser, 
        preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS 
      });
    }
  }, []);

  // Identity Synchronization: Load data for the current user
  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);

      const savedMemories = localStorage.getItem(`nova_${user.username}_memories`);
      if (savedMemories) setMemories(JSON.parse(savedMemories));

      // LOAD PRIVATE TRANSCRIPTIONS
      const savedLogs = localStorage.getItem(`nova_${user.username}_logs`);
      if (savedLogs) {
        setTranscriptions(JSON.parse(savedLogs));
      } else {
        setTranscriptions([]);
      }

      sessionStorage.setItem('nova_session_user', user.username);
    } else {
      setTranscriptions([]);
      setMemories([]);
    }
  }, [user]);

  // Persistent Storage: Save data for the current user
  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme], [prefs.theme]);

  const addTranscription = (sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close?.(); sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
  }, []);

  const handleDeepThink = async (query: string) => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) return;
    setState(AssistantState.THINKING);
    const ai = new GoogleGenAI({ apiKey });
    try {
      const personalityPrompt = prefs.personality === 'custom' ? prefs.customPersonality : PERSONALITIES[prefs.personality];
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: query,
        config: {
          systemInstruction: `Personality: ${personalityPrompt}`,
          thinkingConfig: { thinkingBudget: 32768 },
          tools: [{ googleSearch: {} }]
        }
      });
      const text = response.text || "";
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const sources: GroundingSource[] = chunks.filter(c => c.web).map(c => ({ title: c.web!.title, uri: c.web!.uri }));
      addTranscription('assistant', text, sources);
    } catch (err) {
      console.error("Deep thinking error", err);
    } finally {
      setState(AssistantState.LISTENING);
    }
  };

  const startSession = async () => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      await inputCtx.resume(); await outputCtx.resume();

      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? prefs.customPersonality : PERSONALITIES[prefs.personality];

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools: [{ functionDeclarations: [saveKnowledgeTool] }],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. Context: User is ${user?.username}. Memories: ${facts}. 
          Personality Directive: ${personalityPrompt} 
          Maintain a natural, real-time conversation. If vision is active, talk about what you see in the present tense.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {}
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: audioUtils.createPcmBlob(inputData) }); });
              if (currentFrameRef.current && sessionRef.current) {
                sessionPromise.then(s => s.sendRealtimeInput({ media: { data: currentFrameRef.current!, mimeType: 'image/jpeg' } }));
                currentFrameRef.current = null;
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: (fc.args as any).fact, timestamp: new Date() }]);
                  setIsLearning(true); setTimeout(() => setIsLearning(false), 2000);
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Memory saved." } } }));
                }
              }
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); s.buffer = buffer; s.connect(outputCtx.destination);
              s.onended = () => { activeSourcesRef.current.delete(s); if (activeSourcesRef.current.size === 0) setState(AssistantState.LISTENING); };
              s.start(nextStartTimeRef.current); nextStartTimeRef.current += buffer.duration; activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            if (message.serverContent?.turnComplete) {
              setStreamingUserText(u => { if (u) { addTranscription('user', u); if (isHighPrecision && u.length > 10) handleDeepThink(u); } return ''; });
              setStreamingAssistantText(a => { if (a) addTranscription('assistant', a); return ''; });
            }
            if (message.serverContent?.interrupted) {
              activeSourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
              activeSourcesRef.current.clear(); nextStartTimeRef.current = 0; setState(AssistantState.LISTENING);
              setStreamingAssistantText(a => { if (a) addTranscription('assistant', a + "... [interrupted]"); return ''; });
            }
          },
          onerror: (err) => { console.error(err); setError("Link disrupted."); stopSession(); },
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(err.message); setState(AssistantState.IDLE); }
  };

  const handleLogout = () => { 
    stopSession(); 
    setUser(null); 
    setTranscriptions([]); 
    setMemories([]);
    sessionStorage.removeItem('nova_session_user'); 
  };

  const clearHistory = () => {
    if (confirm("Permanently wipe all neural logs for this segment?")) {
      setTranscriptions([]);
    }
  };

  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;

  return (
    <div 
      className={`flex flex-col h-screen w-full text-white overflow-hidden font-sans selection:bg-${themeData.primary}/30 transition-colors duration-1000`}
      style={{ backgroundColor: themeData.bg }}
    >
      <div className={`flex-1 flex flex-col md:flex-row transition-all duration-700 ${isMemoryOpen ? 'p-0' : 'p-4 md:p-8'}`}>

        {/* Main Interface */}
        <div className={`flex-1 flex flex-col transition-all duration-700 ${isMemoryOpen && prefs.layout === 'right' ? 'md:mr-[340px]' : ''} ${isMemoryOpen && prefs.layout === 'left' ? 'md:ml-[340px]' : ''}`}>

          <header className="flex items-center justify-between mb-8 animate-fade-in relative z-50">
            <div className="flex items-center gap-6">
              <div 
                className={`w-16 h-16 rounded-[2rem] flex items-center justify-center shadow-2xl transition-all duration-500 border border-white/10 ${state !== AssistantState.IDLE ? `bg-${themeData.primary} rotate-12 scale-110` : 'bg-white/5'}`}
                style={state !== AssistantState.IDLE ? { boxShadow: `0 0 40px ${themeData.glow}` } : {}}
              >
                <i className={`fas ${state === AssistantState.THINKING ? 'fa-microchip animate-pulse' : isVisionActive ? 'fa-eye' : 'fa-atom'} text-3xl text-white`}></i>
              </div>
              <div>
                <h1 className={`text-3xl font-black tracking-tighter bg-gradient-to-r from-${themeData.primary} via-${themeData.secondary} to-white bg-clip-text text-transparent`}>
                  {prefs.assistantName}
                </h1>
                <p className="text-[10px] text-gray-500 font-bold uppercase tracking-[0.4em] mt-1 flex items-center gap-2">
                  <i className={`fas fa-shield-halved text-[6px] text-${themeData.primary} animate-pulse`}></i> {user.username} // Secure Segment
                </p>
              </div>
            </div>

            <div className="flex items-center gap-4">
               <button onClick={() => setIsVisionActive(!isVisionActive)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isVisionActive ? 'bg-red-500' : 'bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5'}`}>
                 <i className="fas fa-camera text-sm"></i>
               </button>
               <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isMemoryOpen ? `bg-${themeData.primary} text-white` : 'bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5'}`}>
                 <i className="fas fa-database text-sm"></i>
               </button>
               <button onClick={() => setIsSettingsOpen(true)} className="w-12 h-12 rounded-2xl flex items-center justify-center bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5">
                 <i className="fas fa-cog text-sm"></i>
               </button>
               <div className="w-px h-8 bg-white/10 mx-2"></div>
               <button onClick={handleLogout} className="text-gray-600 hover:text-red-400 transition-colors"><i className="fas fa-sign-out-alt"></i></button>
            </div>
          </header>

          <main className="flex-1 flex flex-col md:flex-row gap-6 min-h-0">
            <div className="flex-1 flex flex-col min-h-0 bg-white/[0.01] rounded-[3rem] border border-white/5 backdrop-blur-3xl overflow-hidden relative shadow-inner animate-fade-in">
               <div className="flex-1 flex flex-col items-center justify-center p-8 z-10">
                 {state === AssistantState.IDLE ? (
                   <div className="text-center space-y-10 group">
                     <div className="w-48 h-48 rounded-[4rem] bg-white/5 border border-white/10 flex items-center justify-center mx-auto shadow-inner relative">
                        <i className={`fas fa-microphone-lines text-7xl text-${themeData.primary}/30`}></i>
                     </div>
                     <h2 className="text-4xl font-black mb-4 tracking-tighter uppercase opacity-30">Standby</h2>
                   </div>
                 ) : (
                   <div className="w-full max-w-2xl flex flex-col items-center">
                      <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
                   </div>
                 )}
               </div>

               <div className="h-80 bg-black/40 border-t border-white/5 p-8 flex flex-col backdrop-blur-2xl">
                 <div className="flex items-center justify-between mb-4">
                    <span className="text-[10px] text-gray-600 font-black tracking-widest uppercase">Neural Logs // {transcriptions.length} Entries</span>
                    <button onClick={clearHistory} className="text-[10px] text-gray-700 hover:text-red-400 font-black tracking-widest uppercase transition-colors">Wipe History</button>
                 </div>
                 <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-6 pr-6 scrollbar-thin scrollbar-thumb-white/10">
                   {transcriptions.map(e => (
                     <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'} animate-slide-up`}>
                       <div className={`max-w-[85%] rounded-[2rem] px-8 py-5 text-sm ${e.sender === 'user' ? `bg-${themeData.primary} text-white rounded-tr-none` : 'bg-white/5 border border-white/10 text-gray-300 rounded-tl-none'}`}>
                         {e.text}
                       </div>
                       {e.sources && e.sources.length > 0 && (
                         <div className="mt-2 flex flex-wrap gap-2">
                            {e.sources.map((s, idx) => (
                              <a key={idx} href={s.uri} target="_blank" rel="noopener noreferrer" className="text-[9px] bg-white/5 hover:bg-white/10 border border-white/10 px-2 py-1 rounded text-blue-400 transition-colors">
                                <i className="fas fa-link mr-1"></i> {s.title}
                              </a>
                            ))}
                         </div>
                       )}
                     </div>
                   ))}
                   {streamingUserText && <div className="flex flex-col items-end"><div className={`max-w-[85%] rounded-[2rem] px-8 py-5 text-sm bg-${themeData.primary} text-white rounded-tr-none animate-pulse`}>{streamingUserText}</div></div>}
                   {streamingAssistantText && <div className="flex flex-col items-start"><div className="max-w-[85%] rounded-[2rem] px-8 py-5 text-sm bg-white/10 border border-white/20 text-blue-200 rounded-tl-none animate-pulse">{streamingAssistantText}</div></div>}
                 </div>
               </div>
            </div>

            {isVisionActive && (
              <div className="w-full md:w-80 flex flex-col gap-6 animate-slide-in-right">
                <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />
                <div className="p-6 bg-white/5 border border-white/10 rounded-[2rem] flex-1">
                   <h4 className="text-[10px] font-black uppercase tracking-[0.5em] text-gray-500 mb-6 flex items-center gap-2"><i className="fas fa-microscope"></i> Optics Active</h4>
                </div>
              </div>
            )}
          </main>

          <div className="flex items-center justify-center mt-10">
             {state === AssistantState.IDLE ? (
               <button onClick={startSession} className="bg-white text-black font-black py-7 px-20 rounded-[2.5rem] hover:scale-105 active:scale-95 transition-all flex items-center gap-6 shadow-2xl">
                  <i className="fas fa-play"></i>
                  <span className="tracking-[0.3em] uppercase text-sm">Initialize {prefs.assistantName}</span>
               </button>
             ) : (
               <button onClick={stopSession} className="bg-red-500/10 hover:bg-red-600 text-white font-black py-7 px-20 rounded-[2.5rem] border border-red-500/20 transition-all flex items-center gap-6 shadow-2xl">
                  <i className="fas fa-stop"></i>
                  <span className="tracking-[0.3em] uppercase text-sm">Terminate Link</span>
               </button>
             )}
          </div>
        </div>
      </div>

      {/* Memory Sidebar */}
      <aside className={`fixed top-0 bottom-0 w-[340px] z-[60] transition-transform duration-700 transform bg-black/90 border-white/5 shadow-2xl backdrop-blur-2xl ${prefs.layout === 'right' ? 'right-0 border-l' : 'left-0 border-r'} ${isMemoryOpen ? 'translate-x-0' : prefs.layout === 'right' ? 'translate-x-full' : '-translate-x-full'}`}>
         <div className="flex flex-col h-full pt-12">
            <button onClick={() => setIsMemoryOpen(false)} className={`absolute top-12 ${prefs.layout === 'right' ? 'right-10' : 'left-10'} text-gray-600 hover:text-white transition-colors`}><i className="fas fa-times text-2xl"></i></button>
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
         </div>
      </aside>

      {/* Settings Modal */}
      {isSettingsOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/80 backdrop-blur-lg animate-fade-in">
          <div className="bg-[#0a0a1f] border border-white/10 rounded-[3rem] w-full max-w-2xl p-10 shadow-3xl relative max-h-[90vh] overflow-y-auto scrollbar-thin">
            <button onClick={() => setIsSettingsOpen(false)} className="absolute top-8 right-8 text-gray-600 hover:text-white"><i className="fas fa-times text-2xl"></i></button>
            <h2 className="text-3xl font-black mb-10 tracking-tighter">System Persona & UI</h2>

            <div className="space-y-10">
              {/* Identity */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Assistant Designation</label>
                  <input type="text" value={prefs.assistantName} onChange={(e) => setPrefs(p => ({ ...p, assistantName: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 focus:ring-2 focus:ring-blue-500 focus:outline-none font-bold" />
                </div>
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Voice Synthesis</label>
                  <select value={prefs.voiceId} onChange={(e) => setPrefs(p => ({ ...p, voiceId: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 focus:ring-2 focus:ring-blue-500 focus:outline-none font-bold appearance-none">
                    {VOICES.map(v => <option key={v.id} value={v.id} className="bg-black">{v.name}</option>)}
                  </select>
                </div>
              </div>

              {/* Theme Selector */}
              <div className="space-y-3">
                <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Visual Core Theme</label>
                <div className="grid grid-cols-4 gap-4">
                  {(Object.keys(THEMES) as UITheme[]).map(t => (
                    <button key={t} onClick={() => setPrefs(p => ({ ...p, theme: t }))} className={`h-16 rounded-2xl border-2 transition-all flex items-center justify-center ${prefs.theme === t ? 'border-white scale-105 shadow-lg' : 'border-white/5'}`} style={{ backgroundColor: THEMES[t].bg }}>
                      <div className={`w-4 h-4 rounded-full bg-${THEMES[t].primary}`}></div>
                    </button>
                  ))}
                </div>
              </div>

              {/* Personality Selector */}
              <div className="space-y-3">
                <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Cognitive Personality</label>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                  {(Object.keys(PERSONALITIES) as PersonalityType[]).map(p => (
                    <button key={p} onClick={() => setPrefs(prev => ({ ...prev, personality: p }))} className={`px-6 py-4 rounded-2xl border-2 transition-all font-bold text-xs capitalize ${prefs.personality === p ? `bg-${themeData.primary}/20 border-${themeData.primary} text-white` : 'bg-white/5 border-white/5 text-gray-500 hover:bg-white/10'}`}>
                      {p}
                    </button>
                  ))}
                </div>
                {prefs.personality === 'custom' && (
                  <textarea value={prefs.customPersonality} onChange={(e) => setPrefs(p => ({ ...p, customPersonality: e.target.value }))} placeholder="Describe how the assistant should behave..." className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 focus:ring-2 focus:ring-blue-500 focus:outline-none font-medium text-sm h-24 mt-4" />
                )}
              </div>

              {/* Layout Selector */}
              <div className="space-y-3">
                <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Interface Layout</label>
                <div className="flex gap-4">
                  <button onClick={() => setPrefs(p => ({ ...p, layout: 'left' }))} className={`flex-1 py-4 rounded-2xl border-2 transition-all font-bold text-xs ${prefs.layout === 'left' ? `border-${themeData.primary} text-white` : 'border-white/5 text-gray-500'}`}>SIDEBAR LEFT</button>
                  <button onClick={() => setPrefs(p => ({ ...p, layout: 'right' }))} className={`flex-1 py-4 rounded-2xl border-2 transition-all font-bold text-xs ${prefs.layout === 'right' ? `border-${themeData.primary} text-white` : 'border-white/5 text-gray-500'}`}>SIDEBAR RIGHT</button>
                </div>
              </div>

              <button onClick={() => setIsSettingsOpen(false)} className="w-full bg-white text-black font-black py-5 rounded-[2rem] shadow-2xl hover:scale-[1.02] active:scale-95 transition-all text-sm tracking-widest mt-10">APPLY & RE-CALIBRATE</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export enum AssistantState {
  IDLE = 'IDLE',
  CONNECTING = 'CONNECTING',
  LISTENING = 'LISTENING',
  SPEAKING = 'SPEAKING',
  THINKING = 'THINKING',
  OBSERVING = 'OBSERVING',
  ERROR = 'ERROR'
}

export type UITheme = 'cosmic' | 'emerald' | 'ruby' | 'obsidian';
export type PersonalityType = 'professional' | 'friendly' | 'witty' | 'minimalist' | 'alluring' | 'custom';

export interface GroundingSource {
  title: string;
  uri: string;
}

export interface CustomVoiceProfile {
  name: string;
  analysis: string;
  timestamp: Date;
}

export interface TranscriptionEntry {
  id: string;
  sender: 'user' | 'assistant';
  text: string;
  timestamp: Date;
  isThinking?: boolean;
  isStreaming?: boolean;
  sources?: GroundingSource[];
}

export interface MemoryEntry {
  id: string;
  fact: string;
  timestamp: Date;
}

export interface UserPreferences {
  theme: UITheme;
  personality: PersonalityType;
  customPersonality?: string;
  layout: 'left' | 'right';
  voiceId: string;
  assistantName: string;
  customVoiceProfile?: CustomVoiceProfile;
}

export interface AuthUser {
  username: string;
  preferences: UserPreferences;
}

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser, UITheme, PersonalityType, UserPreferences, CustomVoiceProfile } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const THEMES: Record<UITheme, { primary: string; secondary: string; glow: string; bg: string }> = {
  cosmic: { primary: 'blue-500', secondary: 'indigo-500', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: 'emerald-500', secondary: 'teal-500', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: 'rose-500', secondary: 'orange-500', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: 'slate-400', secondary: 'zinc-500', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: VOICES[0].id,
  assistantName: 'Nova'
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isHighPrecision, setIsHighPrecision] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [isAnalyzingVoice, setIsAnalyzingVoice] = useState(false);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
      setUser({ 
        username: sessionUser, 
        preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS 
      });
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      const savedMemories = localStorage.getItem(`nova_${user.username}_memories`);
      if (savedMemories) setMemories(JSON.parse(savedMemories));
      const savedLogs = localStorage.getItem(`nova_${user.username}_logs`);
      setTranscriptions(savedLogs ? JSON.parse(savedLogs) : []);
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme], [prefs.theme]);

  const addTranscription = (sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  };

  const handleVoiceImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !process.env.API_KEY) return;

    setIsAnalyzingVoice(true);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const base64 = await audioUtils.blobToBase64(file);
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            parts: [
              { inlineData: { data: base64, mimeType: file.type } },
              { text: "Analyze the vocal characteristics of this audio. Describe its pitch, tone, cadence, and emotional qualities in 3 specific sentences. Focus on traits that a voice actor could mimic." }
            ]
          }
        ]
      });

      const analysis = response.text || "Standard neural profile.";
      const profile: CustomVoiceProfile = {
        name: file.name,
        analysis,
        timestamp: new Date()
      };

      setPrefs(p => ({ ...p, customVoiceProfile: profile }));
    } catch (err) {
      console.error("Voice analysis failed", err);
      setError("Neural analysis failed. Check audio format.");
    } finally {
      setIsAnalyzingVoice(false);
    }
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close?.(); sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
  }, []);

  const handleDeepThink = async (query: string) => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) return;
    setState(AssistantState.THINKING);
    const ai = new GoogleGenAI({ apiKey });
    try {
      const personalityPrompt = prefs.personality === 'custom' ? prefs.customPersonality : PERSONALITIES[prefs.personality];
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: query,
        config: {
          systemInstruction: `Personality: ${personalityPrompt}`,
          thinkingConfig: { thinkingBudget: 32768 },
          tools: [{ googleSearch: {} }]
        }
      });
      const text = response.text || "";
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const sources: GroundingSource[] = chunks.filter(c => c.web).map(c => ({ title: c.web!.title, uri: c.web!.uri }));
      addTranscription('assistant', text, sources);
    } catch (err) {
      console.error("Deep thinking error", err);
    } finally {
      setState(AssistantState.LISTENING);
    }
  };

  const startSession = async () => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      await inputCtx.resume(); await outputCtx.resume();

      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? prefs.customPersonality : PERSONALITIES[prefs.personality];

      // Inject Voice DNA into system instructions
      const voiceDNA = prefs.customVoiceProfile 
        ? `VOCAL STYLE DIRECTIVE: Mimic these traits in your speech: ${prefs.customVoiceProfile.analysis}. Use prosody and rhythm that reflects this profile.` 
        : "";

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools: [{ functionDeclarations: [saveKnowledgeTool] }],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. Context: User is ${user?.username}. Memories: ${facts}. 
          Personality Directive: ${personalityPrompt} 
          ${voiceDNA}
          Maintain a natural, real-time conversation. If vision is active, talk about what you see in the present tense.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {}
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: audioUtils.createPcmBlob(inputData) }); });
              if (currentFrameRef.current && sessionRef.current) {
                sessionPromise.then(s => s.sendRealtimeInput({ media: { data: currentFrameRef.current!, mimeType: 'image/jpeg' } }));
                currentFrameRef.current = null;
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: (fc.args as any).fact, timestamp: new Date() }]);
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Memory saved." } } }));
                }
              }
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); s.buffer = buffer; s.connect(outputCtx.destination);
              s.onended = () => { activeSourcesRef.current.delete(s); if (activeSourcesRef.current.size === 0) setState(AssistantState.LISTENING); };
              s.start(nextStartTimeRef.current); nextStartTimeRef.current += buffer.duration; activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            if (message.serverContent?.turnComplete) {
              setStreamingUserText(u => { if (u) { addTranscription('user', u); } return ''; });
              setStreamingAssistantText(a => { if (a) addTranscription('assistant', a); return ''; });
            }
            if (message.serverContent?.interrupted) {
              activeSourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
              activeSourcesRef.current.clear(); nextStartTimeRef.current = 0; setState(AssistantState.LISTENING);
            }
          },
          onerror: (err) => { console.error(err); setError("Link disrupted."); stopSession(); },
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(err.message); setState(AssistantState.IDLE); }
  };

  const handleLogout = () => { 
    stopSession(); 
    setUser(null); 
    setTranscriptions([]); 
    setMemories([]);
    sessionStorage.removeItem('nova_session_user'); 
  };

  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;

  return (
    <div 
      className={`flex flex-col h-screen w-full text-white overflow-hidden font-sans selection:bg-${themeData.primary}/30 transition-colors duration-1000`}
      style={{ backgroundColor: themeData.bg }}
    >
      <div className={`flex-1 flex flex-col md:flex-row transition-all duration-700 ${isMemoryOpen ? 'p-0' : 'p-4 md:p-8'}`}>
        <div className={`flex-1 flex flex-col transition-all duration-700 ${isMemoryOpen && prefs.layout === 'right' ? 'md:mr-[340px]' : ''} ${isMemoryOpen && prefs.layout === 'left' ? 'md:ml-[340px]' : ''}`}>

          <header className="flex items-center justify-between mb-8 animate-fade-in relative z-50">
            <div className="flex items-center gap-6">
              <div 
                className={`w-16 h-16 rounded-[2rem] flex items-center justify-center shadow-2xl transition-all duration-500 border border-white/10 ${state !== AssistantState.IDLE ? `bg-${themeData.primary} rotate-12 scale-110` : 'bg-white/5'}`}
                style={state !== AssistantState.IDLE ? { boxShadow: `0 0 40px ${themeData.glow}` } : {}}
              >
                <i className={`fas ${state === AssistantState.THINKING ? 'fa-microchip animate-pulse' : isVisionActive ? 'fa-eye' : 'fa-atom'} text-3xl text-white`}></i>
              </div>
              <div>
                <h1 className={`text-3xl font-black tracking-tighter bg-gradient-to-r from-${themeData.primary} via-${themeData.secondary} to-white bg-clip-text text-transparent`}>
                  {prefs.assistantName}
                </h1>
                <p className="text-[10px] text-gray-500 font-bold uppercase tracking-[0.4em] mt-1 flex items-center gap-2">
                  <i className={`fas fa-shield-halved text-[6px] text-${themeData.primary} animate-pulse`}></i> {user.username} // Secure Segment
                </p>
              </div>
            </div>

            <div className="flex items-center gap-4">
               <button onClick={() => setIsVisionActive(!isVisionActive)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isVisionActive ? 'bg-red-500' : 'bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5'}`}>
                 <i className="fas fa-camera text-sm"></i>
               </button>
               <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isMemoryOpen ? `bg-${themeData.primary} text-white` : 'bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5'}`}>
                 <i className="fas fa-database text-sm"></i>
               </button>
               <button onClick={() => setIsSettingsOpen(true)} className="w-12 h-12 rounded-2xl flex items-center justify-center bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5">
                 <i className="fas fa-cog text-sm"></i>
               </button>
               <div className="w-px h-8 bg-white/10 mx-2"></div>
               <button onClick={handleLogout} className="text-gray-600 hover:text-red-400 transition-colors"><i className="fas fa-sign-out-alt"></i></button>
            </div>
          </header>

          <main className="flex-1 flex flex-col md:flex-row gap-6 min-h-0">
            <div className="flex-1 flex flex-col min-h-0 bg-white/[0.01] rounded-[3rem] border border-white/5 backdrop-blur-3xl overflow-hidden relative shadow-inner animate-fade-in">
               <div className="flex-1 flex flex-col items-center justify-center p-8 z-10">
                 {state === AssistantState.IDLE ? (
                   <div className="text-center space-y-10 group">
                     <div className="w-48 h-48 rounded-[4rem] bg-white/5 border border-white/10 flex items-center justify-center mx-auto shadow-inner relative">
                        <i className={`fas fa-microphone-lines text-7xl text-${themeData.primary}/30`}></i>
                     </div>
                     <h2 className="text-4xl font-black mb-4 tracking-tighter uppercase opacity-30">Standby</h2>
                   </div>
                 ) : (
                   <div className="w-full max-w-2xl flex flex-col items-center">
                      <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
                   </div>
                 )}
               </div>

               <div className="h-80 bg-black/40 border-t border-white/5 p-8 flex flex-col backdrop-blur-2xl">
                 <div className="flex items-center justify-between mb-4">
                    <span className="text-[10px] text-gray-600 font-black tracking-widest uppercase">Neural Logs // {transcriptions.length} Entries</span>
                 </div>
                 <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-6 pr-6 scrollbar-thin scrollbar-thumb-white/10">
                   {transcriptions.map(e => (
                     <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'} animate-slide-up`}>
                       <div className={`max-w-[85%] rounded-[2rem] px-8 py-5 text-sm ${e.sender === 'user' ? `bg-${themeData.primary} text-white rounded-tr-none` : 'bg-white/5 border border-white/10 text-gray-300 rounded-tl-none'}`}>
                         {e.text}
                       </div>
                     </div>
                   ))}
                   {streamingUserText && <div className="flex flex-col items-end"><div className={`max-w-[85%] rounded-[2rem] px-8 py-5 text-sm bg-${themeData.primary} text-white rounded-tr-none animate-pulse`}>{streamingUserText}</div></div>}
                   {streamingAssistantText && <div className="flex flex-col items-start"><div className="max-w-[85%] rounded-[2rem] px-8 py-5 text-sm bg-white/10 border border-white/20 text-blue-200 rounded-tl-none animate-pulse">{streamingAssistantText}</div></div>}
                 </div>
               </div>
            </div>

            {isVisionActive && (
              <div className="w-full md:w-80 flex flex-col gap-6 animate-slide-in-right">
                <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />
              </div>
            )}
          </main>

          <div className="flex items-center justify-center mt-10">
             {state === AssistantState.IDLE ? (
               <button onClick={startSession} className="bg-white text-black font-black py-7 px-20 rounded-[2.5rem] hover:scale-105 active:scale-95 transition-all flex items-center gap-6 shadow-2xl">
                  <i className="fas fa-play"></i>
                  <span className="tracking-[0.3em] uppercase text-sm">Initialize {prefs.assistantName}</span>
               </button>
             ) : (
               <button onClick={stopSession} className="bg-red-500/10 hover:bg-red-600 text-white font-black py-7 px-20 rounded-[2.5rem] border border-red-500/20 transition-all flex items-center gap-6 shadow-2xl">
                  <i className="fas fa-stop"></i>
                  <span className="tracking-[0.3em] uppercase text-sm">Terminate Link</span>
               </button>
             )}
          </div>
        </div>
      </div>

      <aside className={`fixed top-0 bottom-0 w-[340px] z-[60] transition-transform duration-700 transform bg-black/90 border-white/5 shadow-2xl backdrop-blur-2xl ${prefs.layout === 'right' ? 'right-0 border-l' : 'left-0 border-r'} ${isMemoryOpen ? 'translate-x-0' : prefs.layout === 'right' ? 'translate-x-full' : '-translate-x-full'}`}>
         <div className="flex flex-col h-full pt-12">
            <button onClick={() => setIsMemoryOpen(false)} className={`absolute top-12 ${prefs.layout === 'right' ? 'right-10' : 'left-10'} text-gray-600 hover:text-white transition-colors`}><i className="fas fa-times text-2xl"></i></button>
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
         </div>
      </aside>

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/80 backdrop-blur-lg animate-fade-in overflow-y-auto">
          <div className="bg-[#0a0a1f] border border-white/10 rounded-[3rem] w-full max-w-2xl p-10 shadow-3xl relative my-auto">
            <button onClick={() => setIsSettingsOpen(false)} className="absolute top-8 right-8 text-gray-600 hover:text-white"><i className="fas fa-times text-2xl"></i></button>
            <h2 className="text-3xl font-black mb-10 tracking-tighter uppercase">System Config</h2>

            <div className="space-y-12">
              {/* Voice Synthesis & Neural Import */}
              <section className="space-y-6">
                <div className="flex items-center justify-between">
                   <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Neural Voice Synthesis</label>
                   {isAnalyzingVoice && <span className="text-[9px] text-blue-400 animate-pulse font-black uppercase tracking-widest"><i className="fas fa-dna mr-2"></i> Analyzing Waveform...</span>}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-3">
                    <select value={prefs.voiceId} onChange={(e) => setPrefs(p => ({ ...p, voiceId: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-2xl py-5 px-6 font-bold appearance-none">
                      {VOICES.map(v => <option key={v.id} value={v.id} className="bg-black">{v.name}</option>)}
                    </select>
                  </div>

                  <div className="relative group">
                    <input 
                      type="file" 
                      accept="audio/*" 
                      onChange={handleVoiceImport} 
                      className="absolute inset-0 opacity-0 cursor-pointer z-10" 
                      disabled={isAnalyzingVoice}
                    />
                    <div className={`h-full border-2 border-dashed border-white/10 rounded-2xl p-4 flex items-center justify-center gap-3 transition-all ${isAnalyzingVoice ? 'opacity-50' : 'group-hover:border-blue-500/50 group-hover:bg-blue-500/5'}`}>
                       <i className="fas fa-upload text-gray-600 group-hover:text-blue-400"></i>
                       <span className="text-xs font-black text-gray-500 group-hover:text-white uppercase tracking-widest">Import Voice Print</span>
                    </div>
                  </div>
                </div>

                {prefs.customVoiceProfile && (
                  <div className="bg-blue-500/5 border border-blue-500/10 rounded-2xl p-6 animate-slide-up">
                    <div className="flex items-center justify-between mb-4">
                       <span className="text-[9px] font-black text-blue-400 uppercase tracking-widest">Active Neural Profile</span>
                       <button onClick={() => setPrefs(p => ({ ...p, customVoiceProfile: undefined }))} className="text-[9px] text-gray-600 hover:text-red-400 font-black uppercase tracking-widest">Purge Print</button>
                    </div>
                    <p className="text-xs text-blue-200/70 leading-relaxed font-medium italic">"{prefs.customVoiceProfile.analysis}"</p>
                  </div>
                )}
              </section>

              {/* Theme & Layout */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="space-y-4">
                  <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Visual Core</label>
                  <div className="grid grid-cols-4 gap-3">
                    {(Object.keys(THEMES) as UITheme[]).map(t => (
                      <button key={t} onClick={() => setPrefs(p => ({ ...p, theme: t }))} className={`h-12 rounded-xl border-2 transition-all flex items-center justify-center ${prefs.theme === t ? 'border-white scale-110' : 'border-white/5'}`} style={{ backgroundColor: THEMES[t].bg }}>
                        <div className={`w-3 h-3 rounded-full bg-${THEMES[t].primary}`}></div>
                      </button>
                    ))}
                  </div>
                </div>
                <div className="space-y-4">
                  <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Interface Layout</label>
                  <div className="flex gap-3">
                    <button onClick={() => setPrefs(p => ({ ...p, layout: 'left' }))} className={`flex-1 py-4 rounded-xl border-2 transition-all font-bold text-[10px] uppercase tracking-widest ${prefs.layout === 'left' ? `border-${themeData.primary} text-white` : 'border-white/5 text-gray-600'}`}>Left</button>
                    <button onClick={() => setPrefs(p => ({ ...p, layout: 'right' }))} className={`flex-1 py-4 rounded-xl border-2 transition-all font-bold text-[10px] uppercase tracking-widest ${prefs.layout === 'right' ? `border-${themeData.primary} text-white` : 'border-white/5 text-gray-600'}`}>Right</button>
                  </div>
                </div>
              </div>

              <button onClick={() => setIsSettingsOpen(false)} className="w-full bg-white text-black font-black py-6 rounded-[2rem] shadow-2xl hover:scale-[1.02] active:scale-95 transition-all text-xs tracking-[0.3em] uppercase">Apply Sequence</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export enum AssistantState {
  IDLE = 'IDLE',
  CONNECTING = 'CONNECTING',
  LISTENING = 'LISTENING',
  SPEAKING = 'SPEAKING',
  THINKING = 'THINKING',
  OBSERVING = 'OBSERVING',
  ERROR = 'ERROR'
}

export type UITheme = 'cosmic' | 'emerald' | 'ruby' | 'obsidian';
export type PersonalityType = 'professional' | 'friendly' | 'witty' | 'minimalist' | 'alluring' | 'custom';

export interface GroundingSource {
  title: string;
  uri: string;
}

export interface CustomVoiceProfile {
  id: string;
  name: string;
  analysis: string;
  timestamp: Date;
}

export interface TranscriptionEntry {
  id: string;
  sender: 'user' | 'assistant';
  text: string;
  timestamp: Date;
  isThinking?: boolean;
  isStreaming?: boolean;
  sources?: GroundingSource[];
}

export interface MemoryEntry {
  id: string;
  fact: string;
  timestamp: Date;
}

export interface UserPreferences {
  theme: UITheme;
  personality: PersonalityType;
  customPersonality?: string;
  layout: 'left' | 'right';
  voiceId: string;
  assistantName: string;
  customVoiceProfiles?: CustomVoiceProfile[];
  activeCustomVoiceId?: string;
}

export interface AuthUser {
  username: string;
  preferences: UserPreferences;
}

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser, UITheme, PersonalityType, UserPreferences, CustomVoiceProfile } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const THEMES: Record<UITheme, { primary: string; secondary: string; glow: string; bg: string }> = {
  cosmic: { primary: 'blue-500', secondary: 'indigo-500', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: 'emerald-500', secondary: 'teal-500', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: 'rose-500', secondary: 'orange-500', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: 'slate-400', secondary: 'zinc-500', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: VOICES[0].id,
  assistantName: 'Nova',
  customVoiceProfiles: []
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [isAnalyzingVoice, setIsAnalyzingVoice] = useState(false);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
      setUser({ 
        username: sessionUser, 
        preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS 
      });
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      const savedMemories = localStorage.getItem(`nova_${user.username}_memories`);
      if (savedMemories) setMemories(JSON.parse(savedMemories));
      const savedLogs = localStorage.getItem(`nova_${user.username}_logs`);
      setTranscriptions(savedLogs ? JSON.parse(savedLogs) : []);
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme], [prefs.theme]);

  const addTranscription = (sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  };

  const handleVoiceImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !process.env.API_KEY) return;

    setIsAnalyzingVoice(true);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const base64 = await audioUtils.blobToBase64(file);
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            parts: [
              { inlineData: { data: base64, mimeType: file.type } },
              { text: "Analyze the vocal characteristics of this audio. Describe its pitch (high/low), tone (raspy, smooth, robotic, warm), cadence (fast, slow, rhythmic), and emotional weight in 3 concise technical sentences." }
            ]
          }
        ]
      });

      const analysis = response.text || "Standard neural profile.";
      const profile: CustomVoiceProfile = {
        id: Math.random().toString(36).substr(2, 9),
        name: file.name.split('.')[0],
        analysis,
        timestamp: new Date()
      };

      setPrefs(p => ({ 
        ...p, 
        customVoiceProfiles: [...(p.customVoiceProfiles || []), profile],
        activeCustomVoiceId: profile.id
      }));
    } catch (err) {
      console.error("Voice analysis failed", err);
      setError("Neural analysis failed. Check audio format.");
    } finally {
      setIsAnalyzingVoice(false);
    }
  };

  const removeVoiceProfile = (id: string) => {
    setPrefs(p => ({
      ...p,
      customVoiceProfiles: p.customVoiceProfiles?.filter(v => v.id !== id),
      activeCustomVoiceId: p.activeCustomVoiceId === id ? undefined : p.activeCustomVoiceId
    }));
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close?.(); sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
  }, []);

  const startSession = async () => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      await inputCtx.resume(); await outputCtx.resume();

      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? prefs.customPersonality : PERSONALITIES[prefs.personality];

      const activeCustomProfile = prefs.customVoiceProfiles?.find(v => v.id === prefs.activeCustomVoiceId);
      const voiceDNA = activeCustomProfile 
        ? `VOCAL MODULATION: You must speak using these characteristics: ${activeCustomProfile.analysis}. Adjust your prosody and cadence to match this neural profile exactly.` 
        : "";

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalalities: [Modality.AUDIO],
          tools: [{ functionDeclarations: [saveKnowledgeTool] }],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. User: ${user?.username}. Memories: ${facts}. Personality: ${personalityPrompt}. ${voiceDNA}. Real-time communication protocol active.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {}
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: audioUtils.createPcmBlob(inputData) }); });
              if (currentFrameRef.current && sessionRef.current) {
                sessionPromise.then(s => s.sendRealtimeInput({ media: { data: currentFrameRef.current!, mimeType: 'image/jpeg' } }));
                currentFrameRef.current = null;
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: (fc.args as any).fact, timestamp: new Date() }]);
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Fact assimilated." } } }));
                }
              }
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); s.buffer = buffer; s.connect(outputCtx.destination);
              s.onended = () => { activeSourcesRef.current.delete(s); if (activeSourcesRef.current.size === 0) setState(AssistantState.LISTENING); };
              s.start(nextStartTimeRef.current); nextStartTimeRef.current += buffer.duration; activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            if (message.serverContent?.turnComplete) {
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) addTranscription('assistant', a); return ''; });
            }
            if (message.serverContent?.interrupted) {
              activeSourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
              activeSourcesRef.current.clear(); nextStartTimeRef.current = 0; setState(AssistantState.LISTENING);
            }
          },
          onerror: (err) => { console.error(err); setError("Signal lost."); stopSession(); },
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(err.message); setState(AssistantState.IDLE); }
  };

  const handleLogout = () => { 
    stopSession(); 
    setUser(null); 
    setTranscriptions([]); 
    setMemories([]);
    sessionStorage.removeItem('nova_session_user'); 
  };

  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;

  return (
    <div className={`flex flex-col h-screen w-full text-white overflow-hidden font-sans transition-colors duration-1000`} style={{ backgroundColor: themeData.bg }}>
      <div className={`flex-1 flex flex-col md:flex-row transition-all duration-700 ${isMemoryOpen ? 'p-0' : 'p-4 md:p-8'}`}>
        <div className={`flex-1 flex flex-col transition-all duration-700 ${isMemoryOpen && prefs.layout === 'right' ? 'md:mr-[340px]' : ''} ${isMemoryOpen && prefs.layout === 'left' ? 'md:ml-[340px]' : ''}`}>

          <header className="flex items-center justify-between mb-8 animate-fade-in relative z-50">
            <div className="flex items-center gap-6">
              <div 
                className={`w-16 h-16 rounded-[2rem] flex items-center justify-center shadow-2xl transition-all duration-500 border border-white/10 ${state !== AssistantState.IDLE ? `bg-${themeData.primary} rotate-12 scale-110` : 'bg-white/5'}`}
                style={state !== AssistantState.IDLE ? { boxShadow: `0 0 40px ${themeData.glow}` } : {}}
              >
                <i className={`fas ${state === AssistantState.THINKING ? 'fa-microchip animate-pulse' : isVisionActive ? 'fa-eye' : 'fa-atom'} text-3xl text-white`}></i>
              </div>
              <div>
                <h1 className={`text-3xl font-black tracking-tighter bg-gradient-to-r from-${themeData.primary} via-${themeData.secondary} to-white bg-clip-text text-transparent`}>{prefs.assistantName}</h1>
                <p className="text-[10px] text-gray-500 font-bold uppercase tracking-[0.4em] mt-1 flex items-center gap-2">
                  <i className={`fas fa-shield-halved text-[6px] text-${themeData.primary} animate-pulse`}></i> {user.username} // Neural Hub
                </p>
              </div>
            </div>

            <div className="flex items-center gap-4">
               <button onClick={() => setIsVisionActive(!isVisionActive)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isVisionActive ? 'bg-red-500 shadow-[0_0_20px_rgba(239,68,68,0.5)]' : 'bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5'}`}>
                 <i className="fas fa-camera text-sm"></i>
               </button>
               <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isMemoryOpen ? `bg-${themeData.primary} text-white` : 'bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5'}`}>
                 <i className="fas fa-database text-sm"></i>
               </button>
               <button onClick={() => setIsSettingsOpen(true)} className="w-12 h-12 rounded-2xl flex items-center justify-center bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5">
                 <i className="fas fa-cog text-sm"></i>
               </button>
               <div className="w-px h-8 bg-white/10 mx-2"></div>
               <button onClick={handleLogout} className="text-gray-600 hover:text-red-400 transition-colors"><i className="fas fa-sign-out-alt"></i></button>
            </div>
          </header>

          <main className="flex-1 flex flex-col md:flex-row gap-6 min-h-0">
            <div className="flex-1 flex flex-col min-h-0 bg-white/[0.01] rounded-[3rem] border border-white/5 backdrop-blur-3xl overflow-hidden relative shadow-inner animate-fade-in">
               <div className="flex-1 flex flex-col items-center justify-center p-8 z-10">
                 {state === AssistantState.IDLE ? (
                   <div className="text-center space-y-10 group">
                     <div className="w-48 h-48 rounded-[4rem] bg-white/5 border border-white/10 flex items-center justify-center mx-auto shadow-inner relative transition-transform duration-500 group-hover:scale-105 group-hover:bg-white/[0.08]">
                        <i className={`fas fa-microphone-lines text-7xl text-${themeData.primary}/30`}></i>
                     </div>
                     <h2 className="text-4xl font-black mb-4 tracking-tighter uppercase opacity-30">Standby</h2>
                   </div>
                 ) : (
                   <div className="w-full max-w-2xl flex flex-col items-center">
                      <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
                   </div>
                 )}
               </div>

               <div className="h-80 bg-black/40 border-t border-white/5 p-8 flex flex-col backdrop-blur-2xl">
                 <div className="flex items-center justify-between mb-4">
                    <span className="text-[10px] text-gray-600 font-black tracking-widest uppercase">Encryption Log // Scoped Entry</span>
                 </div>
                 <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-6 pr-6 scrollbar-thin scrollbar-thumb-white/10">
                   {transcriptions.map(e => (
                     <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'} animate-slide-up`}>
                       <div className={`max-w-[85%] rounded-[2rem] px-8 py-5 text-sm ${e.sender === 'user' ? `bg-${themeData.primary} text-white rounded-tr-none shadow-xl` : 'bg-white/5 border border-white/10 text-gray-300 rounded-tl-none'}`}>
                         {e.text}
                       </div>
                     </div>
                   ))}
                   {streamingUserText && <div className="flex flex-col items-end"><div className={`max-w-[85%] rounded-[2rem] px-8 py-5 text-sm bg-${themeData.primary} text-white rounded-tr-none animate-pulse`}>{streamingUserText}</div></div>}
                   {streamingAssistantText && <div className="flex flex-col items-start"><div className="max-w-[85%] rounded-[2rem] px-8 py-5 text-sm bg-white/10 border border-white/20 text-blue-200 rounded-tl-none animate-pulse">{streamingAssistantText}</div></div>}
                 </div>
               </div>
            </div>

            {isVisionActive && (
              <div className="w-full md:w-80 flex flex-col gap-6 animate-slide-in-right">
                <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />
              </div>
            )}
          </main>

          <div className="flex items-center justify-center mt-10">
             {state === AssistantState.IDLE ? (
               <button onClick={startSession} className="bg-white text-black font-black py-7 px-20 rounded-[2.5rem] hover:scale-105 active:scale-95 transition-all flex items-center gap-6 shadow-2xl">
                  <i className="fas fa-play"></i>
                  <span className="tracking-[0.3em] uppercase text-sm italic">Initialize {prefs.assistantName}</span>
               </button>
             ) : (
               <button onClick={stopSession} className="bg-red-500/10 hover:bg-red-600 text-white font-black py-7 px-20 rounded-[2.5rem] border border-red-500/20 transition-all flex items-center gap-6 shadow-2xl">
                  <i className="fas fa-stop"></i>
                  <span className="tracking-[0.3em] uppercase text-sm">Terminate Link</span>
               </button>
             )}
          </div>
        </div>
      </div>

      <aside className={`fixed top-0 bottom-0 w-[340px] z-[60] transition-transform duration-700 transform bg-black/90 border-white/5 shadow-2xl backdrop-blur-2xl ${prefs.layout === 'right' ? 'right-0 border-l' : 'left-0 border-r'} ${isMemoryOpen ? 'translate-x-0' : prefs.layout === 'right' ? 'translate-x-full' : '-translate-x-full'}`}>
         <div className="flex flex-col h-full pt-12">
            <button onClick={() => setIsMemoryOpen(false)} className={`absolute top-12 ${prefs.layout === 'right' ? 'right-10' : 'left-10'} text-gray-600 hover:text-white transition-colors`}><i className="fas fa-times text-2xl"></i></button>
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
         </div>
      </aside>

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/90 backdrop-blur-2xl animate-fade-in overflow-y-auto">
          <div className="bg-[#02020a] border border-white/10 rounded-[4rem] w-full max-w-4xl p-12 shadow-3xl relative my-auto">
            <button onClick={() => setIsSettingsOpen(false)} className="absolute top-10 right-10 text-gray-600 hover:text-white"><i className="fas fa-times text-3xl"></i></button>

            <header className="mb-12">
              <h2 className="text-5xl font-black tracking-tighter uppercase mb-2">Neural Config</h2>
              <p className="text-gray-500 text-xs font-bold uppercase tracking-[0.5em]">Adjusting assistant cognitive parameters</p>
            </header>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
              <section className="space-y-10">
                <div className="space-y-6">
                   <div className="flex items-center justify-between">
                      <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Core Personality</label>
                      <span className={`text-[8px] font-black uppercase text-${themeData.primary}`}>Active Module</span>
                   </div>
                   <div className="grid grid-cols-2 gap-3">
                     {(Object.keys(PERSONALITIES) as PersonalityType[]).map(p => (
                       <button key={p} onClick={() => setPrefs(prev => ({ ...prev, personality: p }))} className={`px-4 py-3 rounded-2xl border-2 transition-all font-black text-[10px] uppercase tracking-widest ${prefs.personality === p ? `bg-${themeData.primary}/10 border-${themeData.primary} text-white` : 'bg-white/5 border-white/5 text-gray-600 hover:bg-white/10'}`}>{p}</button>
                     ))}
                   </div>
                </div>

                <div className="space-y-6">
                  <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Base Identity Label</label>
                  <input type="text" value={prefs.assistantName} onChange={(e) => setPrefs(p => ({ ...p, assistantName: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-2xl py-5 px-8 font-black text-xl focus:border-blue-500 focus:outline-none transition-all" />
                </div>

                <div className="space-y-6">
                  <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Base Frequency (Synthesizer)</label>
                  <select value={prefs.voiceId} onChange={(e) => setPrefs(p => ({ ...p, voiceId: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-2xl py-5 px-8 font-black appearance-none text-gray-300">
                    {VOICES.map(v => <option key={v.id} value={v.id} className="bg-black">{v.name}</option>)}
                  </select>
                </div>
              </section>

              <section className="bg-white/[0.03] border border-white/5 rounded-[3rem] p-8 space-y-8">
                <div className="flex items-center justify-between">
                   <h3 className="text-sm font-black text-blue-400 uppercase tracking-[0.3em]">Neural Voice Lab</h3>
                   {isAnalyzingVoice && <div className="flex items-center gap-2"><div className="w-1.5 h-1.5 rounded-full bg-blue-500 animate-ping"></div><span className="text-[9px] font-black text-blue-500 animate-pulse uppercase">Scanning...</span></div>}
                </div>

                <div className="relative group overflow-hidden rounded-[2rem] border-2 border-dashed border-white/10 p-10 flex flex-col items-center justify-center gap-4 transition-all hover:bg-blue-500/5 hover:border-blue-500/30">
                  <input type="file" accept="audio/*" onChange={handleVoiceImport} className="absolute inset-0 opacity-0 cursor-pointer z-10" disabled={isAnalyzingVoice} />
                  <i className="fas fa-fingerprint text-4xl text-gray-700 group-hover:text-blue-400 transition-colors"></i>
                  <span className="text-xs font-black text-gray-500 group-hover:text-white uppercase tracking-widest text-center">Import Voice Print<br/><span className="text-[8px] opacity-40 font-medium">MP3, WAV, M4A Accepted</span></span>
                </div>

                <div className="space-y-3 max-h-[300px] overflow-y-auto pr-2 scrollbar-thin">
                   {prefs.customVoiceProfiles?.map(v => (
                     <div key={v.id} onClick={() => setPrefs(p => ({ ...p, activeCustomVoiceId: v.id }))} className={`group relative p-5 rounded-2xl border transition-all cursor-pointer ${prefs.activeCustomVoiceId === v.id ? 'bg-blue-500/20 border-blue-500' : 'bg-white/5 border-white/10 hover:bg-white/10'}`}>
                        <div className="flex items-center justify-between mb-2">
                           <span className="text-[10px] font-black uppercase tracking-widest truncate max-w-[150px]">{v.name}</span>
                           <button onClick={(e) => { e.stopPropagation(); removeVoiceProfile(v.id); }} className="text-[9px] text-gray-600 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity">Purge</button>
                        </div>
                        <p className="text-[9px] text-gray-400 leading-tight italic truncate">"{v.analysis}"</p>
                        {prefs.activeCustomVoiceId === v.id && <div className="absolute -left-2 top-1/2 -translate-y-1/2 w-1 h-6 bg-blue-500 rounded-full shadow-[0_0_10px_rgba(59,130,246,1)]"></div>}
                     </div>
                   ))}
                   {!prefs.customVoiceProfiles?.length && (
                     <div className="py-10 text-center opacity-20"><i className="fas fa-wave-square text-2xl mb-2"></i><p className="text-[8px] font-black uppercase tracking-widest">No custom prints found</p></div>
                   )}
                </div>
              </section>
            </div>

            <footer className="mt-12 flex items-center justify-between gap-10">
              <div className="flex items-center gap-4">
                {(Object.keys(THEMES) as UITheme[]).map(t => (
                  <button key={t} onClick={() => setPrefs(p => ({ ...p, theme: t }))} className={`w-10 h-10 rounded-xl border-2 transition-all flex items-center justify-center ${prefs.theme === t ? 'border-white scale-110 shadow-lg' : 'border-white/5 hover:border-white/20'}`} style={{ backgroundColor: THEMES[t].bg }}>
                    <div className={`w-2 h-2 rounded-full bg-${THEMES[t].primary}`}></div>
                  </button>
                ))}
              </div>
              <button onClick={() => setIsSettingsOpen(false)} className="flex-1 bg-white text-black font-black py-6 rounded-[2rem] shadow-2xl hover:scale-[1.02] active:scale-95 transition-all text-xs tracking-[0.4em] uppercase">Commit Changes</button>
            </footer>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export enum AssistantState {
  IDLE = 'IDLE',
  CONNECTING = 'CONNECTING',
  LISTENING = 'LISTENING',
  SPEAKING = 'SPEAKING',
  THINKING = 'THINKING',
  OBSERVING = 'OBSERVING',
  ERROR = 'ERROR'
}

export type UITheme = 'cosmic' | 'emerald' | 'ruby' | 'obsidian';
export type PersonalityType = 'professional' | 'friendly' | 'witty' | 'minimalist' | 'alluring' | 'custom';

export interface GroundingSource {
  title: string;
  uri: string;
}

export interface TranscriptionEntry {
  id: string;
  sender: 'user' | 'assistant';
  text: string;
  timestamp: Date;
  isThinking?: boolean;
  isStreaming?: boolean;
  sources?: GroundingSource[];
}

export interface MemoryEntry {
  id: string;
  fact: string;
  timestamp: Date;
}

export interface UserPreferences {
  theme: UITheme;
  personality: PersonalityType;
  customPersonality?: string;
  layout: 'left' | 'right';
  voiceId: string;
  assistantName: string;
}

export interface AuthUser {
  username: string;
  preferences: UserPreferences;
}

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser, UITheme, PersonalityType, UserPreferences } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const THEMES: Record<UITheme, { primary: string; secondary: string; glow: string; bg: string }> = {
  cosmic: { primary: 'blue-500', secondary: 'indigo-500', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: 'emerald-500', secondary: 'teal-500', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: 'rose-500', secondary: 'orange-500', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: 'slate-400', secondary: 'zinc-500', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: VOICES[0].id,
  assistantName: 'Nova'
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
      setUser({ 
        username: sessionUser, 
        preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS 
      });
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      const savedMemories = localStorage.getItem(`nova_${user.username}_memories`);
      if (savedMemories) setMemories(JSON.parse(savedMemories));
      const savedLogs = localStorage.getItem(`nova_${user.username}_logs`);
      setTranscriptions(savedLogs ? JSON.parse(savedLogs) : []);
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme], [prefs.theme]);

  const addTranscription = (sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close?.(); sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
  }, []);

  const startSession = async () => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      await inputCtx.resume(); await outputCtx.resume();

      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? prefs.customPersonality : PERSONALITIES[prefs.personality];

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools: [{ functionDeclarations: [saveKnowledgeTool] }],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. User: ${user?.username}. Memories: ${facts}. Personality: ${personalityPrompt}. Real-time communication protocol active.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {}
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: audioUtils.createPcmBlob(inputData) }); });
              if (currentFrameRef.current && sessionRef.current) {
                sessionPromise.then(s => s.sendRealtimeInput({ media: { data: currentFrameRef.current!, mimeType: 'image/jpeg' } }));
                currentFrameRef.current = null;
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: (fc.args as any).fact, timestamp: new Date() }]);
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Fact assimilated." } } }));
                }
              }
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); s.buffer = buffer; s.connect(outputCtx.destination);
              s.onended = () => { activeSourcesRef.current.delete(s); if (activeSourcesRef.current.size === 0) setState(AssistantState.LISTENING); };
              s.start(nextStartTimeRef.current); nextStartTimeRef.current += buffer.duration; activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            if (message.serverContent?.turnComplete) {
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) addTranscription('assistant', a); return ''; });
            }
            if (message.serverContent?.interrupted) {
              activeSourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
              activeSourcesRef.current.clear(); nextStartTimeRef.current = 0; setState(AssistantState.LISTENING);
            }
          },
          onerror: (err) => { console.error(err); setError("Signal lost."); stopSession(); },
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(err.message); setState(AssistantState.IDLE); }
  };

  const handleLogout = () => { 
    stopSession(); 
    setUser(null); 
    setTranscriptions([]); 
    setMemories([]);
    sessionStorage.removeItem('nova_session_user'); 
  };

  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;

  return (
    <div className={`flex flex-col h-screen w-full text-white overflow-hidden font-sans transition-colors duration-1000`} style={{ backgroundColor: themeData.bg }}>
      <div className={`flex-1 flex flex-col md:flex-row transition-all duration-700 ${isMemoryOpen ? 'p-0' : 'p-4 md:p-8'}`}>
        <div className={`flex-1 flex flex-col transition-all duration-700 ${isMemoryOpen && prefs.layout === 'right' ? 'md:mr-[340px]' : ''} ${isMemoryOpen && prefs.layout === 'left' ? 'md:ml-[340px]' : ''}`}>

          <header className="flex items-center justify-between mb-8 animate-fade-in relative z-50">
            <div className="flex items-center gap-6">
              <div 
                className={`w-16 h-16 rounded-[2rem] flex items-center justify-center shadow-2xl transition-all duration-500 border border-white/10 ${state !== AssistantState.IDLE ? `bg-${themeData.primary} rotate-12 scale-110` : 'bg-white/5'}`}
                style={state !== AssistantState.IDLE ? { boxShadow: `0 0 40px ${themeData.glow}` } : {}}
              >
                <i className={`fas ${state === AssistantState.THINKING ? 'fa-microchip animate-pulse' : isVisionActive ? 'fa-eye' : 'fa-atom'} text-3xl text-white`}></i>
              </div>
              <div>
                <h1 className={`text-3xl font-black tracking-tighter bg-gradient-to-r from-${themeData.primary} via-${themeData.secondary} to-white bg-clip-text text-transparent`}>{prefs.assistantName}</h1>
                <p className="text-[10px] text-gray-500 font-bold uppercase tracking-[0.4em] mt-1 flex items-center gap-2">
                  <i className={`fas fa-shield-halved text-[6px] text-${themeData.primary} animate-pulse`}></i> {user.username} // Neural Hub
                </p>
              </div>
            </div>

            <div className="flex items-center gap-4">
               <button onClick={() => setIsVisionActive(!isVisionActive)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isVisionActive ? 'bg-red-500 shadow-[0_0_20px_rgba(239,68,68,0.5)]' : 'bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5'}`}>
                 <i className="fas fa-camera text-sm"></i>
               </button>
               <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isMemoryOpen ? `bg-${themeData.primary} text-white` : 'bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5'}`}>
                 <i className="fas fa-database text-sm"></i>
               </button>
               <button onClick={() => setIsSettingsOpen(true)} className="w-12 h-12 rounded-2xl flex items-center justify-center bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5">
                 <i className="fas fa-cog text-sm"></i>
               </button>
               <div className="w-px h-8 bg-white/10 mx-2"></div>
               <button onClick={handleLogout} className="text-gray-600 hover:text-red-400 transition-colors"><i className="fas fa-sign-out-alt"></i></button>
            </div>
          </header>

          <main className="flex-1 flex flex-col md:flex-row gap-6 min-h-0">
