const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: VOICES[0].id,
  assistantName: 'Nova'
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
      setUser({ 
        username: sessionUser, 
        preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS 
      });
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      const savedMemories = localStorage.getItem(`nova_${user.username}_memories`);
      if (savedMemories) setMemories(JSON.parse(savedMemories));
      const savedLogs = localStorage.getItem(`nova_${user.username}_logs`);
      setTranscriptions(savedLogs ? JSON.parse(savedLogs) : []);
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme], [prefs.theme]);

  const addTranscription = (sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close?.(); sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
  }, []);

  const startSession = async () => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      await inputCtx.resume(); await outputCtx.resume();

      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? prefs.customPersonality : PERSONALITIES[prefs.personality];

      const visualMode = isScreenSharing ? "Screen Sharing / Neural Uplink" : "Camera / Live Optics";

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools: [{ functionDeclarations: [saveKnowledgeTool] }],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. User: ${user?.username}. Memories: ${facts}. Personality: ${personalityPrompt}. 
          VISUAL CONTEXT: You currently have a ${visualMode} feed active. 
          If screen sharing is on, you can see the user's desktop, applications, and documents. Assist with technical tasks or explain what's on screen.
          If camera is on, you can see the user and their surroundings. 
          Real-time communication protocol active. Thinking budget enabled for maximum intelligence.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              if (!sessionRef.current) return;
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(s => { 
                if (sessionRef.current) s.sendRealtimeInput({ media: audioUtils.createPcmBlob(inputData) }); 
              });
              if (currentFrameRef.current && sessionRef.current) {
                const frame = currentFrameRef.current;
                sessionPromise.then(s => {
                  if (sessionRef.current) s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } });
                });
                currentFrameRef.current = null;
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = (fc.args as any).fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => {
                    if (sessionRef.current) s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Fact assimilated into long-term storage." } } });
                  });
                }
              }
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); 
              s.buffer = buffer; 
              s.connect(outputCtx.destination);
              s.onended = () => { 
                activeSourcesRef.current.delete(s); 
                if (activeSourcesRef.current.size === 0 && sessionRef.current) setState(AssistantState.LISTENING); 
              };
              s.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration; 
              activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            if (message.serverContent?.turnComplete) {
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) addTranscription('assistant', a); return ''; });
            }
            if (message.serverContent?.interrupted) {
              activeSourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
              activeSourcesRef.current.clear(); 
              nextStartTimeRef.current = 0; 
              setState(AssistantState.LISTENING);
            }
          },
          onerror: (err) => { 
            console.error("Neural session error:", err); 
            setError("Signal degradation detected. Restarting link..."); 
            stopSession(); 
          },
          onclose: () => {
            console.warn("Neural session closed.");
            stopSession();
          }
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { 
      console.error("Initialization error:", err);
      setError(err.message || "Failed to establish neural link."); 
      setState(AssistantState.IDLE); 
    }
  };

  const handleLogout = () => { 
    stopSession(); 
    setUser(null); 
    setTranscriptions([]); 
    setMemories([]);
    sessionStorage.removeItem('nova_session_user'); 
  };

  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;

  return (
    <div className={`flex flex-col h-screen w-full text-white overflow-hidden font-sans transition-colors duration-1000`} style={{ backgroundColor: themeData.bg }}>
      <div className={`flex-1 flex flex-col md:flex-row transition-all duration-700 ${isMemoryOpen ? 'p-0' : 'p-4 md:p-8'}`}>
        <div className={`flex-1 flex flex-col transition-all duration-700 ${isMemoryOpen && prefs.layout === 'right' ? 'md:mr-[340px]' : ''} ${isMemoryOpen && prefs.layout === 'left' ? 'md:ml-[340px]' : ''}`}>

          <header className="flex items-center justify-between mb-8 animate-fade-in relative z-50">
            <div className="flex items-center gap-6">
              <div 
                className={`w-16 h-16 rounded-[2rem] flex items-center justify-center shadow-2xl transition-all duration-500 border border-white/10 ${state !== AssistantState.IDLE ? `bg-${themeData.primary} rotate-12 scale-110` : 'bg-white/5'}`}
                style={state !== AssistantState.IDLE ? { boxShadow: `0 0 40px ${themeData.glow}` } : {}}
              >
                <i className={`fas ${state === AssistantState.THINKING ? 'fa-microchip animate-pulse' : isVisionActive ? 'fa-eye' : isScreenSharing ? 'fa-desktop' : 'fa-atom'} text-3xl text-white`}></i>
              </div>
              <div>
                <h1 className={`text-3xl font-black tracking-tighter bg-gradient-to-r from-${themeData.primary} via-${themeData.secondary} to-white bg-clip-text text-transparent`}>{prefs.assistantName}</h1>
                <p className="text-[10px] text-gray-500 font-bold uppercase tracking-[0.4em] mt-1 flex items-center gap-2">
                  <i className={`fas fa-shield-halved text-[6px] text-${themeData.primary} animate-pulse`}></i> {user.username} // Neural Hub
                </p>
              </div>
            </div>

            <div className="flex items-center gap-4">
               <button 
                 onClick={() => { setIsScreenSharing(!isScreenSharing); setIsVisionActive(false); }} 
                 className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isScreenSharing ? 'bg-cyan-500 shadow-[0_0_20px_rgba(6,182,212,0.5)] text-white' : 'bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5'}`}
                 title="Screen Share"
               >
                 <i className="fas fa-desktop text-sm"></i>
               </button>
               <button 
                 onClick={() => { setIsVisionActive(!isVisionActive); setIsScreenSharing(false); }} 
                 className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isVisionActive ? 'bg-red-500 shadow-[0_0_20px_rgba(239,68,68,0.5)] text-white' : 'bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5'}`}
                 title="Camera View"
               >
                 <i className="fas fa-camera text-sm"></i>
               </button>
               <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isMemoryOpen ? `bg-${themeData.primary} text-white` : 'bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5'}`}>
                 <i className="fas fa-database text-sm"></i>
               </button>
               <button onClick={() => setIsSettingsOpen(true)} className="w-12 h-12 rounded-2xl flex items-center justify-center bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5">
                 <i className="fas fa-cog text-sm"></i>
               </button>
               <div className="w-px h-8 bg-white/10 mx-2"></div>
               <button onClick={handleLogout} className="text-gray-600 hover:text-red-400 transition-colors"><i className="fas fa-sign-out-alt"></i></button>
            </div>
          </header>

          <main className="flex-1 flex flex-col md:flex-row gap-6 min-h-0">
            <div className="flex-1 flex flex-col min-h-0 bg-white/[0.01] rounded-[3rem] border border-white/5 backdrop-blur-3xl overflow-hidden relative shadow-inner animate-fade-in">
               <div className="flex-1 flex flex-col items-center justify-center p-8 z-10">
                 {state === AssistantState.IDLE ? (
                   <div className="text-center space-y-10 group">
                     <div className="w-48 h-48 rounded-[4rem] bg-white/5 border border-white/10 flex items-center justify-center mx-auto shadow-inner relative transition-transform duration-500 group-hover:scale-105 group-hover:bg-white/[0.08]">
                        <i className={`fas fa-microphone-lines text-7xl text-${themeData.primary}/30`}></i>
                     </div>
                     <h2 className="text-4xl font-black mb-4 tracking-tighter uppercase opacity-30">Standby</h2>
                     {error && <p className="text-red-400 font-bold uppercase tracking-widest text-[10px] animate-pulse">{error}</p>}
                   </div>
                 ) : (
                   <div className="w-full max-w-2xl flex flex-col items-center">
                      <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
                      {error && <p className="mt-8 text-red-400 font-bold uppercase tracking-widest text-[10px] animate-pulse">{error}</p>}
                   </div>
                 )}
               </div>

               <div className="h-80 bg-black/40 border-t border-white/5 p-8 flex flex-col backdrop-blur-2xl">
                 <div className="flex items-center justify-between mb-4">
                    <span className="text-[10px] text-gray-600 font-black tracking-widest uppercase">Encryption Log // Scoped Entry</span>
                 </div>
                 <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-6 pr-6 scrollbar-thin scrollbar-thumb-white/10">
                   {transcriptions.map(e => (
                     <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'} animate-slide-up`}>
                       <div className={`max-w-[85%] rounded-[2rem] px-8 py-5 text-sm ${e.sender === 'user' ? `bg-${themeData.primary} text-white rounded-tr-none shadow-xl` : 'bg-white/5 border border-white/10 text-gray-300 rounded-tl-none'}`}>
                         {e.text}
                       </div>
                     </div>
                   ))}
                   {streamingUserText && <div className="flex flex-col items-end"><div className={`max-w-[85%] rounded-[2rem] px-8 py-5 text-sm bg-${themeData.primary} text-white rounded-tr-none animate-pulse`}>{streamingUserText}</div></div>}
                   {streamingAssistantText && <div className="flex flex-col items-start"><div className="max-w-[85%] rounded-[2rem] px-8 py-5 text-sm bg-white/10 border border-white/20 text-blue-200 rounded-tl-none animate-pulse">{streamingAssistantText}</div></div>}
                 </div>
               </div>
            </div>

            {(isVisionActive || isScreenSharing) && (
              <div className="w-full md:w-80 flex flex-col gap-6 animate-slide-in-right">
                {isVisionActive && <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />}
                {isScreenSharing && <ScreenShareMode isActive={isScreenSharing} onFrame={(b) => currentFrameRef.current = b} onStop={() => setIsScreenSharing(false)} />}
              </div>
            )}
          </main>

          <div className="flex items-center justify-center mt-10">
             {state === AssistantState.IDLE ? (
               <button onClick={startSession} className="bg-white text-black font-black py-7 px-20 rounded-[2.5rem] hover:scale-105 active:scale-95 transition-all flex items-center gap-6 shadow-2xl">
                  <i className="fas fa-play"></i>
                  <span className="tracking-[0.3em] uppercase text-sm italic">Initialize {prefs.assistantName}</span>
               </button>
             ) : (
               <button onClick={stopSession} className="bg-red-500/10 hover:bg-red-600 text-white font-black py-7 px-20 rounded-[2.5rem] border border-red-500/20 transition-all flex items-center gap-6 shadow-2xl">
                  <i className="fas fa-stop"></i>
                  <span className="tracking-[0.3em] uppercase text-sm">Terminate Link</span>
               </button>
             )}
          </div>
        </div>
      </div>

      <aside className={`fixed top-0 bottom-0 w-[340px] z-[60] transition-transform duration-700 transform bg-black/90 border-white/5 shadow-2xl backdrop-blur-2xl ${prefs.layout === 'right' ? 'right-0 border-l' : 'left-0 border-r'} ${isMemoryOpen ? 'translate-x-0' : prefs.layout === 'right' ? 'translate-x-full' : '-translate-x-full'}`}>
         <div className="flex flex-col h-full pt-12">
            <button onClick={() => setIsMemoryOpen(false)} className={`absolute top-12 ${prefs.layout === 'right' ? 'right-10' : 'left-10'} text-gray-600 hover:text-white transition-colors`}><i className="fas fa-times text-2xl"></i></button>
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
         </div>
      </aside>

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/90 backdrop-blur-2xl animate-fade-in overflow-y-auto">
          <div className="bg-[#02020a] border border-white/10 rounded-[4rem] w-full max-w-4xl p-12 shadow-3xl relative my-auto">
            <button onClick={() => setIsSettingsOpen(false)} className="absolute top-10 right-10 text-gray-600 hover:text-white"><i className="fas fa-times text-3xl"></i></button>

            <header className="mb-12">
              <h2 className="text-5xl font-black tracking-tighter uppercase mb-2">Neural Config</h2>
              <p className="text-gray-500 text-xs font-bold uppercase tracking-[0.5em]">Adjusting assistant cognitive parameters</p>
            </header>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
              <section className="space-y-10">
                <div className="space-y-6">
                   <div className="flex items-center justify-between">
                      <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Core Personality</label>
                      <span className={`text-[8px] font-black uppercase text-${themeData.primary}`}>Active Module</span>
                   </div>
                   <div className="grid grid-cols-2 gap-3">
                     {(Object.keys(PERSONALITIES) as PersonalityType[]).map(p => (
                       <button key={p} onClick={() => setPrefs(prev => ({ ...prev, personality: p }))} className={`px-4 py-3 rounded-2xl border-2 transition-all font-black text-[10px] uppercase tracking-widest ${prefs.personality === p ? `bg-${themeData.primary}/10 border-${themeData.primary} text-white` : 'bg-white/5 border-white/5 text-gray-600 hover:bg-white/10'}`}>{p}</button>
                     ))}
                   </div>
                </div>

                <div className="space-y-6">
                  <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Base Identity Label</label>
                  <input type="text" value={prefs.assistantName} onChange={(e) => setPrefs(p => ({ ...p, assistantName: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-2xl py-5 px-8 font-black text-xl focus:border-blue-500 focus:outline-none transition-all" />
                </div>

                <div className="space-y-6">
                  <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Base Frequency (Synthesizer)</label>
                  <select value={prefs.voiceId} onChange={(e) => setPrefs(p => ({ ...p, voiceId: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-2xl py-5 px-8 font-black appearance-none text-gray-300">
                    {VOICES.map(v => <option key={v.id} value={v.id} className="bg-black">{v.name}</option>)}
                  </select>
                </div>
              </section>

              <section className="bg-white/[0.03] border border-white/5 rounded-[3rem] p-8 space-y-8 flex flex-col justify-center">
                <div className="text-center opacity-30">
                  <i className="fas fa-wave-square text-6xl mb-6 text-blue-500"></i>
                  <h3 className="text-xl font-black uppercase tracking-widest">Synthesizer Core</h3>
                  <p className="text-[10px] mt-4 leading-relaxed font-bold uppercase tracking-[0.2em]">Neural voice modulation utilizing pre-calibrated frequency profiles.</p>
                </div>
              </section>
            </div>

            <footer className="mt-12 flex items-center justify-between gap-10">
              <div className="flex items-center gap-4">
                {(Object.keys(THEMES) as UITheme[]).map(t => (
                  <button key={t} onClick={() => setPrefs(p => ({ ...p, theme: t }))} className={`w-10 h-10 rounded-xl border-2 transition-all flex items-center justify-center ${prefs.theme === t ? 'border-white scale-110 shadow-lg' : 'border-white/5 hover:border-white/20'}`} style={{ backgroundColor: THEMES[t].bg }}>
                    <div className={`w-2 h-2 rounded-full bg-${THEMES[t].primary}`}></div>
                  </button>
                ))}
              </div>
              <button onClick={() => setIsSettingsOpen(false)} className="flex-1 bg-white text-black font-black py-6 rounded-[2rem] shadow-2xl hover:scale-[1.02] active:scale-95 transition-all text-xs tracking-[0.4em] uppercase">Commit Changes</button>
            </footer>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser, UITheme, PersonalityType, UserPreferences } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';
import ScreenShareMode from './components/ScreenShareMode';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const THEMES: Record<UITheme, { primary: string; secondary: string; glow: string; bg: string }> = {
  cosmic: { primary: 'blue-500', secondary: 'indigo-500', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: 'emerald-500', secondary: 'teal-500', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: 'rose-500', secondary: 'orange-500', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: 'slate-400', secondary: 'zinc-500', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: VOICES[0].id,
  assistantName: 'Nova'
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
      setUser({ 
        username: sessionUser, 
        preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS 
      });
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      const savedMemories = localStorage.getItem(`nova_${user.username}_memories`);
      if (savedMemories) setMemories(JSON.parse(savedMemories));
      const savedLogs = localStorage.getItem(`nova_${user.username}_logs`);
      setTranscriptions(savedLogs ? JSON.parse(savedLogs) : []);
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme], [prefs.theme]);

  const addTranscription = (sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
  }, [screenStream]);

  const handleScreenToggle = async () => {
    if (isScreenSharing) {
      if (screenStream) {
        screenStream.getTracks().forEach(t => t.stop());
        setScreenStream(null);
      }
      setIsScreenSharing(false);
    } else {
      try {
        setError(null);
        // getDisplayMedia MUST be called directly in the event handler to satisfy browser gesture requirements
        const stream = await navigator.mediaDevices.getDisplayMedia({
          video: { cursor: "always", displaySurface: "monitor" } as any,
          audio: false
        });
        setScreenStream(stream);
        setIsScreenSharing(true);
        setIsVisionActive(false);

        stream.getVideoTracks()[0].onended = () => {
          setIsScreenSharing(false);
          setScreenStream(null);
        };
      } catch (err: any) {
        console.error("Screen share access failed:", err);
        if (err.name === 'NotAllowedError' || err.message?.includes('denied')) {
          setError("Screen capture permission was denied by the user or browser.");
        } else {
          setError("Failed to initialize screen capture.");
        }
        setIsScreenSharing(false);
      }
    }
  };

  const startSession = async () => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? prefs.customPersonality : PERSONALITIES[prefs.personality];

      const visualMode = isScreenSharing ? "Screen Sharing / Neural Uplink" : "Camera / Live Optics";

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools: [{ functionDeclarations: [saveKnowledgeTool] }],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. User: ${user?.username}. Memories: ${facts}. Personality: ${personalityPrompt}. 
          VISUAL CONTEXT: You currently have a ${visualMode} feed active. 
          If screen sharing is on, you can see the user's desktop, applications, and documents. Assist with technical tasks or explain what's on screen.
          If camera is on, you can see the user and their surroundings. 
          Real-time communication protocol active. Thinking budget enabled for maximum intelligence.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              if (!sessionRef.current) return;
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(s => { 
                if (sessionRef.current) s.sendRealtimeInput({ media: audioUtils.createPcmBlob(inputData) }); 
              });
              if (currentFrameRef.current && sessionRef.current) {
                const frame = currentFrameRef.current;
                sessionPromise.then(s => {
                  if (sessionRef.current) s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } });
                });
                currentFrameRef.current = null;
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = (fc.args as any).fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => {
                    if (sessionRef.current) s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Fact assimilated into long-term storage." } } });
                  });
                }
              }
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); 
              s.buffer = buffer; 
              s.connect(outputCtx.destination);
              s.onended = () => { 
                activeSourcesRef.current.delete(s); 
                if (activeSourcesRef.current.size === 0 && sessionRef.current) setState(AssistantState.LISTENING); 
              };
              s.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration; 
              activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            if (message.serverContent?.turnComplete) {
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) addTranscription('assistant', a); return ''; });
            }
            if (message.serverContent?.interrupted) {
              activeSourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
              activeSourcesRef.current.clear(); 
              nextStartTimeRef.current = 0; 
              setState(AssistantState.LISTENING);
            }
          },
          onerror: (err) => { 
            console.error("Neural session error:", err); 
            setError("Link instability detected. Disconnecting..."); 
            stopSession(); 
          },
          onclose: () => {
            console.warn("Neural session closed.");
            stopSession();
          }
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { 
      console.error("Initialization error:", err);
      setError(err.message || "Failed to establish neural link."); 
      setState(AssistantState.IDLE); 
    }
  };

  const handleLogout = () => { 
    stopSession(); 
    setUser(null); 
    setTranscriptions([]); 
    setMemories([]);
    sessionStorage.removeItem('nova_session_user'); 
  };

  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;

  return (
    <div className={`flex flex-col h-screen w-full text-white overflow-hidden font-sans transition-colors duration-1000`} style={{ backgroundColor: themeData.bg }}>
