  personality: PersonalityType;
  customPersonality?: string;
  layout: 'left' | 'right';
  voiceId: string;
  assistantName: string;
}

export interface AuthUser {
  username: string;
  preferences: UserPreferences;
}

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser, UITheme, PersonalityType, UserPreferences, DeviceType } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';
import ScreenShareMode from './components/ScreenShareMode';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const THEMES: Record<UITheme, { primary: string; secondary: string; glow: string; bg: string }> = {
  cosmic: { primary: 'blue-500', secondary: 'indigo-500', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: 'emerald-500', secondary: 'teal-500', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: 'rose-500', secondary: 'orange-500', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: 'slate-400', secondary: 'zinc-500', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: VOICES[0].id,
  assistantName: 'Nova'
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [device, setDevice] = useState<DeviceType>('desktop');
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Device Detection Logic
  useEffect(() => {
    const detectDevice = () => {
      const w = window.innerWidth;
      const ua = navigator.userAgent.toLowerCase();
      if (w <= 300) setDevice('wear');
      else if (ua.includes('tv') || ua.includes('google-tv') || ua.includes('android-tv') || w >= 1920) setDevice('tv');
      else if (w < 1024) setDevice('mobile');
      else setDevice('desktop');
    };
    detectDevice();
    window.addEventListener('resize', detectDevice);
    return () => window.removeEventListener('resize', detectDevice);
  }, []);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
      setUser({ 
        username: sessionUser, 
        preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS 
      });
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      const savedMemories = localStorage.getItem(`nova_${user.username}_memories`);
      if (savedMemories) setMemories(JSON.parse(savedMemories));
      const savedLogs = localStorage.getItem(`nova_${user.username}_logs`);
      setTranscriptions(savedLogs ? JSON.parse(savedLogs) : []);
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme], [prefs.theme]);

  const addTranscription = (sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
  }, [screenStream]);

  const handleScreenToggle = async () => {
    if (isScreenSharing) {
      if (screenStream) {
        screenStream.getTracks().forEach(t => t.stop());
        setScreenStream(null);
      }
      setIsScreenSharing(false);
    } else {
      try {
        setError(null);
        const stream = await navigator.mediaDevices.getDisplayMedia({
          video: { cursor: "always", displaySurface: "monitor" } as any,
          audio: false
        });
        setScreenStream(stream);
        setIsScreenSharing(true);
        setIsVisionActive(false);
        stream.getVideoTracks()[0].onended = () => { setIsScreenSharing(false); setScreenStream(null); };
      } catch (err: any) {
        setError("Screen capture permission was denied.");
        setIsScreenSharing(false);
      }
    }
  };

  const startSession = async () => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? prefs.customPersonality : PERSONALITIES[prefs.personality];

      const visualMode = isScreenSharing ? "Screen Sharing / Neural Uplink" : "Camera / Live Optics";

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools: [{ functionDeclarations: [saveKnowledgeTool] }],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. User: ${user?.username}. Memories: ${facts}. Personality: ${personalityPrompt}. Device: ${device}. 
          Real-time communication protocol active. Thinking budget enabled. Assist the user via voice and vision.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              if (!sessionRef.current) return;
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(s => { 
                if (sessionRef.current) s.sendRealtimeInput({ media: audioUtils.createPcmBlob(inputData) }); 
              });
              if (currentFrameRef.current && sessionRef.current) {
                const frame = currentFrameRef.current;
                sessionPromise.then(s => {
                  if (sessionRef.current) s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } });
                });
                currentFrameRef.current = null;
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = (fc.args as any).fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => {
                    if (sessionRef.current) s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Memory saved." } } });
                  });
                }
              }
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); 
              s.buffer = buffer; 
              s.connect(outputCtx.destination);
              s.onended = () => { 
                activeSourcesRef.current.delete(s); 
                if (activeSourcesRef.current.size === 0 && sessionRef.current) setState(AssistantState.LISTENING); 
              };
              s.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration; 
              activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            if (message.serverContent?.turnComplete) {
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) addTranscription('assistant', a); return ''; });
            }
          },
          onerror: (err) => { stopSession(); },
          onclose: () => { stopSession(); }
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { 
      setError(err.message || "Link failed."); 
      setState(AssistantState.IDLE); 
    }
  };

  const handleLogout = () => { 
    stopSession(); 
    setUser(null); 
    sessionStorage.removeItem('nova_session_user'); 
  };

  // ---------------------------------------------------------------------------------
  // WEAROS RENDER PATH
  // ---------------------------------------------------------------------------------
  if (device === 'wear') {
    if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;
    return (
      <div className="wear-screen bg-black flex flex-col items-center justify-center p-4">
        <div className={`w-full h-full border-4 rounded-full flex flex-col items-center justify-center relative transition-colors duration-1000 border-${themeData.primary}/30`}>
          <div className="absolute top-6">
             <h2 className={`text-[10px] font-black tracking-widest uppercase text-${themeData.primary}`}>{prefs.assistantName}</h2>
          </div>

          <div className="flex-1 flex flex-col items-center justify-center w-full">
            <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
            <div className="h-10 overflow-hidden text-center mt-2 px-4">
              <p className="text-[9px] text-gray-400 line-clamp-2 italic">{streamingAssistantText || transcriptions[transcriptions.length-1]?.text || 'Standby...'}</p>
            </div>
          </div>

          <div className="absolute bottom-6">
            <button 
              onClick={state === AssistantState.IDLE ? startSession : stopSession}
              className={`w-12 h-12 rounded-full flex items-center justify-center transition-all shadow-lg ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500 text-white'}`}
            >
              <i className={`fas ${state === AssistantState.IDLE ? 'fa-play' : 'fa-stop'} text-xs`}></i>
            </button>
          </div>
        </div>
      </div>
    );
  }

  // ---------------------------------------------------------------------------------
  // MAIN RENDER PATH (Mobile, Desktop, TV)
  // ---------------------------------------------------------------------------------
  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;

  const isTv = device === 'tv';
  const isMobile = device === 'mobile';

  return (
    <div className={`flex flex-col h-screen w-full text-white overflow-hidden font-sans transition-colors duration-1000 ${isTv ? 'text-xl' : 'text-base'}`} style={{ backgroundColor: themeData.bg }}>
      <div className={`flex-1 flex flex-col ${isMobile ? 'overflow-y-auto' : 'md:flex-row'} transition-all duration-700 ${isMemoryOpen ? 'p-0' : 'p-4 md:p-8'}`}>
        <div className={`flex-1 flex flex-col transition-all duration-700 ${!isMobile && isMemoryOpen && prefs.layout === 'right' ? 'md:mr-[340px]' : ''} ${!isMobile && isMemoryOpen && prefs.layout === 'left' ? 'md:ml-[340px]' : ''}`}>

          <header className={`flex items-center justify-between animate-fade-in relative z-50 ${isMobile ? 'mb-4' : 'mb-8'}`}>
            <div className="flex items-center gap-4 md:gap-6">
              <div 
                className={`${isTv ? 'w-24 h-24' : isMobile ? 'w-12 h-12' : 'w-16 h-16'} rounded-[2rem] flex items-center justify-center shadow-2xl transition-all duration-500 border border-white/10 ${state !== AssistantState.IDLE ? `bg-${themeData.primary} rotate-12 scale-110` : 'bg-white/5'}`}
                style={state !== AssistantState.IDLE ? { boxShadow: `0 0 40px ${themeData.glow}` } : {}}
              >
                <i className={`fas ${state === AssistantState.THINKING ? 'fa-microchip animate-pulse' : isVisionActive ? 'fa-eye' : isScreenSharing ? 'fa-desktop' : 'fa-atom'} ${isTv ? 'text-5xl' : 'text-xl md:text-3xl'} text-white`}></i>
              </div>
              {!isMobile && (
                <div>
                  <h1 className={`${isTv ? 'text-5xl' : 'text-3xl'} font-black tracking-tighter bg-gradient-to-r from-${themeData.primary} via-${themeData.secondary} to-white bg-clip-text text-transparent`}>{prefs.assistantName}</h1>
                  <p className="text-[10px] text-gray-500 font-bold uppercase tracking-[0.4em] mt-1 flex items-center gap-2">
                    <i className={`fas fa-shield-halved text-[6px] text-${themeData.primary} animate-pulse`}></i> {user.username} // Hub
                  </p>
                </div>
              )}
            </div>

            <div className="flex items-center gap-2 md:gap-4">
               {!isMobile && (
                 <>
                  <button tabIndex={1} onClick={handleScreenToggle} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isScreenSharing ? 'bg-cyan-500' : 'bg-white/5 text-gray-400'}`} title="Screen Share"><i className="fas fa-desktop text-sm"></i></button>
                  <button tabIndex={2} onClick={() => { setIsVisionActive(!isVisionActive); setIsScreenSharing(false); }} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isVisionActive ? 'bg-red-500' : 'bg-white/5 text-gray-400'}`} title="Camera"><i className="fas fa-camera text-sm"></i></button>
                 </>
               )}
               <button tabIndex={3} onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isMemoryOpen ? `bg-${themeData.primary}` : 'bg-white/5 text-gray-400'}`}><i className="fas fa-database text-sm"></i></button>
               <button tabIndex={4} onClick={() => setIsSettingsOpen(true)} className="w-12 h-12 rounded-2xl flex items-center justify-center bg-white/5 text-gray-400"><i className="fas fa-cog text-sm"></i></button>
               <button tabIndex={5} onClick={handleLogout} className="text-gray-600 hover:text-red-400 px-2"><i className="fas fa-sign-out-alt"></i></button>
            </div>
          </header>

          <main className="flex-1 flex flex-col md:flex-row gap-6 min-h-0">
            <div className={`flex-1 flex flex-col min-h-0 bg-white/[0.01] ${isMobile ? 'rounded-[2rem]' : 'rounded-[3rem]'} border border-white/5 backdrop-blur-3xl overflow-hidden relative shadow-inner animate-fade-in`}>
               <div className={`flex-1 flex flex-col items-center justify-center z-10 ${isMobile ? 'p-4' : 'p-8'}`}>
                 {state === AssistantState.IDLE ? (
                   <div className="text-center space-y-6 md:space-y-10 group">
                     <div className={`${isTv ? 'w-64 h-64' : isMobile ? 'w-32 h-32' : 'w-48 h-48'} rounded-[4rem] bg-white/5 border border-white/10 flex items-center justify-center mx-auto shadow-inner relative transition-transform duration-500 group-hover:scale-105`}>
                        <i className={`fas fa-microphone-lines ${isTv ? 'text-8xl' : isMobile ? 'text-4xl' : 'text-7xl'} text-${themeData.primary}/30`}></i>
                     </div>
                     <h2 className={`${isTv ? 'text-6xl' : 'text-2xl md:text-4xl'} font-black mb-4 tracking-tighter uppercase opacity-30`}>Standby</h2>
                     {error && <p className="text-red-400 font-bold uppercase tracking-widest text-[10px] animate-pulse bg-red-500/10 px-6 py-3 rounded-2xl border border-red-500/20">{error}</p>}
                   </div>
                 ) : (
                   <div className="w-full max-w-2xl flex flex-col items-center">
                      <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
                   </div>
                 )}
               </div>

               <div className={`${isTv ? 'h-96' : isMobile ? 'h-48' : 'h-80'} bg-black/40 border-t border-white/5 p-4 md:p-8 flex flex-col backdrop-blur-2xl`}>
                 <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-4 pr-2 scrollbar-thin scrollbar-thumb-white/10">
                   {transcriptions.map(e => (
                     <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'}`}>
                       <div className={`max-w-[85%] rounded-[1.5rem] px-4 py-3 md:px-8 md:py-5 text-sm ${e.sender === 'user' ? `bg-${themeData.primary} text-white` : 'bg-white/5 text-gray-300'}`}>
                         {e.text}
                       </div>
                     </div>
                   ))}
                   {streamingAssistantText && <div className="flex flex-col items-start"><div className="max-w-[85%] rounded-[1.5rem] px-4 py-3 md:px-8 md:py-5 text-sm bg-white/10 text-blue-200 animate-pulse">{streamingAssistantText}</div></div>}
                 </div>
               </div>
            </div>

            {(!isMobile && (isVisionActive || isScreenSharing)) && (
              <div className="w-full md:w-80 flex flex-col gap-6 animate-slide-in-right">
                {isVisionActive && <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />}
                {isScreenSharing && screenStream && <ScreenShareMode isActive={isScreenSharing} stream={screenStream} onFrame={(b) => currentFrameRef.current = b} onStop={() => { setIsScreenSharing(false); setScreenStream(null); }} />}
              </div>
            )}
          </main>

          <div className={`flex items-center justify-center ${isMobile ? 'my-4' : 'mt-10'}`}>
             <button 
               tabIndex={6}
               onClick={state === AssistantState.IDLE ? startSession : stopSession} 
               className={`${isTv ? 'py-10 px-32 text-2xl' : isMobile ? 'py-4 px-10 text-xs' : 'py-7 px-20 text-sm'} ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500/10 border-red-500/20 text-white'} font-black rounded-[2.5rem] transition-all flex items-center gap-6 shadow-2xl`}
             >
                <i className={`fas ${state === AssistantState.IDLE ? 'fa-play' : 'fa-stop'}`}></i>
                <span className="tracking-[0.3em] uppercase italic">{state === AssistantState.IDLE ? `Initialize ${prefs.assistantName}` : 'Terminate'}</span>
             </button>
          </div>
        </div>
      </div>

      <aside className={`fixed top-0 bottom-0 ${isMobile ? 'w-full' : 'w-[340px]'} z-[60] transition-transform duration-700 transform bg-black/90 border-white/5 shadow-2xl backdrop-blur-2xl ${prefs.layout === 'right' || isMobile ? 'right-0 border-l' : 'left-0 border-r'} ${isMemoryOpen ? 'translate-x-0' : (prefs.layout === 'right' || isMobile) ? 'translate-x-full' : '-translate-x-full'}`}>
         <div className="flex flex-col h-full pt-12">
            <button onClick={() => setIsMemoryOpen(false)} className={`absolute top-12 ${isMobile || prefs.layout === 'right' ? 'right-10' : 'left-10'} text-gray-600 hover:text-white transition-colors`}><i className="fas fa-times text-2xl"></i></button>
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
         </div>
      </aside>

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 md:p-6 bg-black/90 backdrop-blur-2xl animate-fade-in overflow-y-auto">
          <div className={`bg-[#02020a] border border-white/10 ${isMobile ? 'rounded-[2rem]' : 'rounded-[4rem]'} w-full max-w-4xl p-6 md:p-12 shadow-3xl relative my-auto`}>
            <button onClick={() => setIsSettingsOpen(false)} className="absolute top-6 right-6 md:top-10 md:right-10 text-gray-600"><i className="fas fa-times text-3xl"></i></button>
            <header className="mb-6 md:mb-12">
              <h2 className={`${isTv ? 'text-6xl' : 'text-3xl md:text-5xl'} font-black tracking-tighter uppercase mb-2`}>Neural Config</h2>
            </header>
            <div className={`grid grid-cols-1 ${!isMobile ? 'lg:grid-cols-2' : ''} gap-6 md:gap-12`}>
              <section className="space-y-6 md:space-y-10">
                <div className="space-y-4">
                   <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Personality</label>
                   <div className="grid grid-cols-2 gap-2">
                     {(Object.keys(PERSONALITIES) as PersonalityType[]).map(p => (
                       <button key={p} onClick={() => setPrefs(prev => ({ ...prev, personality: p }))} className={`px-2 py-3 rounded-xl border-2 transition-all font-black text-[9px] uppercase tracking-widest ${prefs.personality === p ? `bg-${themeData.primary}/10 border-${themeData.primary}` : 'bg-white/5 border-white/5 text-gray-600'}`}>{p}</button>
                     ))}
                   </div>
                </div>
                <div className="space-y-4">
                  <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Base Identity</label>
                  <input type="text" value={prefs.assistantName} onChange={(e) => setPrefs(p => ({ ...p, assistantName: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-xl py-3 px-6 font-black focus:outline-none transition-all" />
                </div>
              </section>
              {!isMobile && (
                <section className="bg-white/[0.03] border border-white/5 rounded-[3rem] p-8 space-y-8 flex flex-col justify-center text-center opacity-30">
                  <i className="fas fa-wave-square text-6xl text-blue-500"></i>
                  <h3 className="text-xl font-black uppercase">Synthesizer Core</h3>
                </section>
              )}
            </div>
            <footer className="mt-8 md:mt-12 flex flex-col md:flex-row items-center justify-between gap-6">
              <div className="flex items-center gap-4">
                {(Object.keys(THEMES) as UITheme[]).map(t => (
                  <button key={t} onClick={() => setPrefs(p => ({ ...p, theme: t }))} className={`w-8 h-8 rounded-xl border-2 transition-all ${prefs.theme === t ? 'border-white scale-110' : 'border-white/5'}`} style={{ backgroundColor: THEMES[t].bg }} />
                ))}
              </div>
              <button onClick={() => setIsSettingsOpen(false)} className="w-full md:w-auto md:flex-1 bg-white text-black font-black py-4 px-12 rounded-[2rem] text-xs tracking-[0.4em] uppercase">Commit Changes</button>
            </footer>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export enum AssistantState {
  IDLE = 'IDLE',
  CONNECTING = 'CONNECTING',
  LISTENING = 'LISTENING',
  SPEAKING = 'SPEAKING',
  THINKING = 'THINKING',
  OBSERVING = 'OBSERVING',
  ERROR = 'ERROR'
}

export type DeviceType = 'wear' | 'mobile' | 'desktop' | 'tv' | 'auto';

export type UITheme = 'cosmic' | 'emerald' | 'ruby' | 'obsidian';
export type PersonalityType = 'professional' | 'friendly' | 'witty' | 'minimalist' | 'alluring' | 'custom';

export interface GroundingSource {
  title: string;
  uri: string;
}

export interface TranscriptionEntry {
  id: string;
  sender: 'user' | 'assistant';
  text: string;
  timestamp: Date;
  isThinking?: boolean;
  isStreaming?: boolean;
  sources?: GroundingSource[];
}

export interface MemoryEntry {
  id: string;
  fact: string;
  timestamp: Date;
}

export interface UserPreferences {
  theme: UITheme;
  personality: PersonalityType;
  customPersonality?: string;
  layout: 'left' | 'right';
  voiceId: string;
  assistantName: string;
}

export interface AuthUser {
  username: string;
  preferences: UserPreferences;
}

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser, UITheme, PersonalityType, UserPreferences, DeviceType } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';
import ScreenShareMode from './components/ScreenShareMode';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const THEMES: Record<UITheme, { primary: string; secondary: string; glow: string; bg: string }> = {
  cosmic: { primary: 'blue-500', secondary: 'indigo-500', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: 'emerald-500', secondary: 'teal-500', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: 'rose-500', secondary: 'orange-500', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: 'slate-400', secondary: 'zinc-500', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: VOICES[0].id,
  assistantName: 'Nova'
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [device, setDevice] = useState<DeviceType>('desktop');
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Device Detection Logic including Android Auto
  useEffect(() => {
    const detectDevice = () => {
      const w = window.innerWidth;
      const h = window.innerHeight;
      const ua = navigator.userAgent.toLowerCase();

      // Android Auto Detection (Commonly Android landscape mobile-ish aspect ratios)
      const isAndroid = ua.includes('android');
      const isLandscape = w > h;
      const isAutoDimensions = w >= 800 && w <= 1280 && h >= 400 && h <= 800;

      if (w <= 300) setDevice('wear');
      else if (isAndroid && isLandscape && isAutoDimensions) setDevice('auto');
      else if (ua.includes('tv') || ua.includes('google-tv') || ua.includes('android-tv') || w >= 1920) setDevice('tv');
      else if (w < 1024) setDevice('mobile');
      else setDevice('desktop');
    };
    detectDevice();
    window.addEventListener('resize', detectDevice);
    return () => window.removeEventListener('resize', detectDevice);
  }, []);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
      setUser({ 
        username: sessionUser, 
        preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS 
      });
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      const savedMemories = localStorage.getItem(`nova_${user.username}_memories`);
      if (savedMemories) setMemories(JSON.parse(savedMemories));
      const savedLogs = localStorage.getItem(`nova_${user.username}_logs`);
      setTranscriptions(savedLogs ? JSON.parse(savedLogs) : []);
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme], [prefs.theme]);

  const addTranscription = (sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
  }, [screenStream]);

  const handleScreenToggle = async () => {
    if (isScreenSharing) {
      if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
      setIsScreenSharing(false);
    } else {
      try {
        setError(null);
        const stream = await navigator.mediaDevices.getDisplayMedia({ video: { cursor: "always", displaySurface: "monitor" } as any, audio: false });
        setScreenStream(stream);
        setIsScreenSharing(true);
        setIsVisionActive(false);
        stream.getVideoTracks()[0].onended = () => { setIsScreenSharing(false); setScreenStream(null); };
      } catch (err: any) { setError("Screen capture denied."); setIsScreenSharing(false); }
    }
  };

  const startSession = async () => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? prefs.customPersonality : PERSONALITIES[prefs.personality];

      const contextHint = device === 'auto' ? "IMPORTANT: The user is currently driving a vehicle. Be extremely concise, use simple language, and do not expect them to look at the screen. Focus on verbal clarity." : "";

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools: [{ functionDeclarations: [saveKnowledgeTool] }],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. User: ${user?.username}. Memories: ${facts}. Personality: ${personalityPrompt}. Device: ${device}. ${contextHint} Real-time communication protocol active. Assist via voice.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              if (!sessionRef.current) return;
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: audioUtils.createPcmBlob(inputData) }); });
              if (currentFrameRef.current && sessionRef.current) {
                const frame = currentFrameRef.current;
                sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } }); });
                currentFrameRef.current = null;
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = (fc.args as any).fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => { if (sessionRef.current) s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Memory saved." } } }); });
                }
              }
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); 
              s.buffer = buffer; 
              s.connect(outputCtx.destination);
              s.onended = () => { 
                activeSourcesRef.current.delete(s); 
                if (activeSourcesRef.current.size === 0 && sessionRef.current) setState(AssistantState.LISTENING); 
              };
              s.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration; 
              activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            if (message.serverContent?.turnComplete) {
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) addTranscription('assistant', a); return ''; });
            }
          },
          onerror: (err) => { stopSession(); },
          onclose: () => { stopSession(); }
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(err.message || "Link failed."); setState(AssistantState.IDLE); }
  };

  const handleLogout = () => { stopSession(); setUser(null); sessionStorage.removeItem('nova_session_user'); };

  // ---------------------------------------------------------------------------------
  // ANDROID AUTO RENDER PATH
  // ---------------------------------------------------------------------------------
  if (device === 'auto') {
    if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;
    return (
      <div className="h-screen w-full bg-black text-white p-6 flex flex-col font-sans">
        <header className="flex items-center justify-between mb-4 border-b border-white/10 pb-4">
          <div className="flex items-center gap-4">
            <i className={`fas fa-car-side text-2xl text-${themeData.primary}`}></i>
            <h1 className="text-3xl font-black tracking-tighter uppercase">{prefs.assistantName} // Driving</h1>
          </div>
          <div className="bg-white/5 px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest text-gray-400">
            Link: {state === AssistantState.IDLE ? 'STBY' : 'ACTV'}
          </div>
        </header>

        <main className="flex-1 flex items-center gap-8">
          <div className="w-1/3 flex flex-col items-center justify-center">
             <div className={`w-64 h-64 rounded-full border-8 border-${themeData.primary}/20 flex items-center justify-center bg-black shadow-[0_0_60px_rgba(0,0,0,1)]`}>
                <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
             </div>
          </div>
          <div className="flex-1 flex flex-col justify-center gap-4">
            <div className="bg-white/[0.02] border border-white/10 rounded-[2rem] p-8 h-48 flex items-center shadow-inner overflow-hidden">
              <p className="text-3xl font-bold leading-tight text-blue-100">
                {streamingAssistantText || transcriptions[transcriptions.length-1]?.text || 'Neural link established. Awaiting voice input...'}
              </p>
            </div>
            {streamingUserText && <p className="text-sm uppercase tracking-[0.3em] text-gray-500 animate-pulse ml-4 italic">User: {streamingUserText}</p>}
          </div>
        </main>

        <footer className="mt-4">
          {state === AssistantState.IDLE ? (
            <button onClick={startSession} className="w-full bg-white text-black font-black py-8 rounded-[2rem] text-2xl uppercase tracking-[0.2em] shadow-2xl flex items-center justify-center gap-6">
              <i className="fas fa-play"></i> Initialize Link
            </button>
          ) : (
            <button onClick={stopSession} className="w-full bg-red-600 text-white font-black py-8 rounded-[2rem] text-2xl uppercase tracking-[0.2em] shadow-2xl flex items-center justify-center gap-6 animate-pulse">
              <i className="fas fa-stop-circle"></i> Terminate Link
            </button>
          )}
        </footer>
      </div>
    );
  }

  // ---------------------------------------------------------------------------------
  // WEAROS RENDER PATH
  // ---------------------------------------------------------------------------------
  if (device === 'wear') {
    if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;
    return (
      <div className="wear-screen bg-black flex flex-col items-center justify-center p-4">
        <div className={`w-full h-full border-4 rounded-full flex flex-col items-center justify-center relative transition-colors duration-1000 border-${themeData.primary}/30`}>
          <div className="absolute top-6">
             <h2 className={`text-[10px] font-black tracking-widest uppercase text-${themeData.primary}`}>{prefs.assistantName}</h2>
          </div>
          <div className="flex-1 flex flex-col items-center justify-center w-full">
            <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
            <div className="h-10 overflow-hidden text-center mt-2 px-4">
              <p className="text-[9px] text-gray-400 line-clamp-2 italic">{streamingAssistantText || transcriptions[transcriptions.length-1]?.text || 'Standby...'}</p>
            </div>
          </div>
          <div className="absolute bottom-6">
            <button onClick={state === AssistantState.IDLE ? startSession : stopSession} className={`w-12 h-12 rounded-full flex items-center justify-center transition-all shadow-lg ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500 text-white'}`}>
              <i className={`fas ${state === AssistantState.IDLE ? 'fa-play' : 'fa-stop'} text-xs`}></i>
            </button>
          </div>
        </div>
      </div>
    );
  }

  // ---------------------------------------------------------------------------------
  // MAIN RENDER PATH (Mobile, Desktop, TV)
  // ---------------------------------------------------------------------------------
  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;

  const isTv = device === 'tv';
  const isMobile = device === 'mobile';

  return (
    <div className={`flex flex-col h-screen w-full text-white overflow-hidden font-sans transition-colors duration-1000 ${isTv ? 'text-xl' : 'text-base'}`} style={{ backgroundColor: themeData.bg }}>
      <div className={`flex-1 flex flex-col ${isMobile ? 'overflow-y-auto' : 'md:flex-row'} transition-all duration-700 ${isMemoryOpen ? 'p-0' : 'p-4 md:p-8'}`}>
        <div className={`flex-1 flex flex-col transition-all duration-700 ${!isMobile && isMemoryOpen && prefs.layout === 'right' ? 'md:mr-[340px]' : ''} ${!isMobile && isMemoryOpen && prefs.layout === 'left' ? 'md:ml-[340px]' : ''}`}>

          <header className={`flex items-center justify-between animate-fade-in relative z-50 ${isMobile ? 'mb-4' : 'mb-8'}`}>
            <div className="flex items-center gap-4 md:gap-6">
              <div className={`${isTv ? 'w-24 h-24' : isMobile ? 'w-12 h-12' : 'w-16 h-16'} rounded-[2rem] flex items-center justify-center shadow-2xl transition-all duration-500 border border-white/10 ${state !== AssistantState.IDLE ? `bg-${themeData.primary} rotate-12 scale-110` : 'bg-white/5'}`} style={state !== AssistantState.IDLE ? { boxShadow: `0 0 40px ${themeData.glow}` } : {}}>
                <i className={`fas ${state === AssistantState.THINKING ? 'fa-microchip animate-pulse' : isVisionActive ? 'fa-eye' : isScreenSharing ? 'fa-desktop' : 'fa-atom'} ${isTv ? 'text-5xl' : 'text-xl md:text-3xl'} text-white`}></i>
              </div>
              {!isMobile && (
                <div>
                  <h1 className={`${isTv ? 'text-5xl' : 'text-3xl'} font-black tracking-tighter bg-gradient-to-r from-${themeData.primary} via-${themeData.secondary} to-white bg-clip-text text-transparent`}>{prefs.assistantName}</h1>
                  <p className="text-[10px] text-gray-500 font-bold uppercase tracking-[0.4em] mt-1 flex items-center gap-2"><i className={`fas fa-shield-halved text-[6px] text-${themeData.primary} animate-pulse`}></i> {user.username} // Hub</p>
                </div>
              )}
            </div>
            <div className="flex items-center gap-2 md:gap-4">
               {!isMobile && (
                 <>
                  <button tabIndex={1} onClick={handleScreenToggle} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isScreenSharing ? 'bg-cyan-500' : 'bg-white/5 text-gray-400'}`} title="Screen Share"><i className="fas fa-desktop text-sm"></i></button>
                  <button tabIndex={2} onClick={() => { setIsVisionActive(!isVisionActive); setIsScreenSharing(false); }} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isVisionActive ? 'bg-red-500' : 'bg-white/5 text-gray-400'}`} title="Camera"><i className="fas fa-camera text-sm"></i></button>
                 </>
               )}
               <button tabIndex={3} onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isMemoryOpen ? `bg-${themeData.primary}` : 'bg-white/5 text-gray-400'}`}><i className="fas fa-database text-sm"></i></button>
               <button tabIndex={4} onClick={() => setIsSettingsOpen(true)} className="w-12 h-12 rounded-2xl flex items-center justify-center bg-white/5 text-gray-400"><i className="fas fa-cog text-sm"></i></button>
               <button tabIndex={5} onClick={handleLogout} className="text-gray-600 hover:text-red-400 px-2"><i className="fas fa-sign-out-alt"></i></button>
            </div>
          </header>

          <main className="flex-1 flex flex-col md:flex-row gap-6 min-h-0">
            <div className={`flex-1 flex flex-col min-h-0 bg-white/[0.01] ${isMobile ? 'rounded-[2rem]' : 'rounded-[3rem]'} border border-white/5 backdrop-blur-3xl overflow-hidden relative shadow-inner animate-fade-in`}>
               <div className={`flex-1 flex flex-col items-center justify-center z-10 ${isMobile ? 'p-4' : 'p-8'}`}>
                 {state === AssistantState.IDLE ? (
                   <div className="text-center space-y-6 md:space-y-10 group">
                     <div className={`${isTv ? 'w-64 h-64' : isMobile ? 'w-32 h-32' : 'w-48 h-48'} rounded-[4rem] bg-white/5 border border-white/10 flex items-center justify-center mx-auto shadow-inner relative transition-transform duration-500 group-hover:scale-105`}>
                        <i className={`fas fa-microphone-lines ${isTv ? 'text-8xl' : isMobile ? 'text-4xl' : 'text-7xl'} text-${themeData.primary}/30`}></i>
                     </div>
                     <h2 className={`${isTv ? 'text-6xl' : 'text-2xl md:text-4xl'} font-black mb-4 tracking-tighter uppercase opacity-30`}>Standby</h2>
                   </div>
                 ) : (
                   <div className="w-full max-w-2xl flex flex-col items-center">
                      <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
                   </div>
                 )}
               </div>
               <div className={`${isTv ? 'h-96' : isMobile ? 'h-48' : 'h-80'} bg-black/40 border-t border-white/5 p-4 md:p-8 flex flex-col backdrop-blur-2xl`}>
                 <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-4 pr-2 scrollbar-thin scrollbar-thumb-white/10">
                   {transcriptions.map(e => (
                     <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'}`}>
                       <div className={`max-w-[85%] rounded-[1.5rem] px-4 py-3 md:px-8 md:py-5 text-sm ${e.sender === 'user' ? `bg-${themeData.primary} text-white` : 'bg-white/5 text-gray-300'}`}>{e.text}</div>
                     </div>
                   ))}
                   {streamingAssistantText && <div className="flex flex-col items-start"><div className="max-w-[85%] rounded-[1.5rem] px-4 py-3 md:px-8 md:py-5 text-sm bg-white/10 text-blue-200 animate-pulse">{streamingAssistantText}</div></div>}
                 </div>
               </div>
            </div>
            {(!isMobile && (isVisionActive || isScreenSharing)) && (
              <div className="w-full md:w-80 flex flex-col gap-6 animate-slide-in-right">
                {isVisionActive && <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />}
                {isScreenSharing && screenStream && <ScreenShareMode isActive={isScreenSharing} stream={screenStream} onFrame={(b) => currentFrameRef.current = b} onStop={() => { setIsScreenSharing(false); setScreenStream(null); }} />}
              </div>
            )}
          </main>

          <div className={`flex items-center justify-center ${isMobile ? 'my-4' : 'mt-10'}`}>
             <button tabIndex={6} onClick={state === AssistantState.IDLE ? startSession : stopSession} className={`${isTv ? 'py-10 px-32 text-2xl' : isMobile ? 'py-4 px-10 text-xs' : 'py-7 px-20 text-sm'} ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500/10 border-red-500/20 text-white'} font-black rounded-[2.5rem] transition-all flex items-center gap-6 shadow-2xl`}>
                <i className={`fas ${state === AssistantState.IDLE ? 'fa-play' : 'fa-stop'}`}></i>
                <span className="tracking-[0.3em] uppercase italic">{state === AssistantState.IDLE ? `Initialize ${prefs.assistantName}` : 'Terminate'}</span>
             </button>
          </div>
        </div>
      </div>

      <aside className={`fixed top-0 bottom-0 ${isMobile ? 'w-full' : 'w-[340px]'} z-[60] transition-transform duration-700 transform bg-black/90 border-white/5 shadow-2xl backdrop-blur-2xl ${prefs.layout === 'right' || isMobile ? 'right-0 border-l' : 'left-0 border-r'} ${isMemoryOpen ? 'translate-x-0' : (prefs.layout === 'right' || isMobile) ? 'translate-x-full' : '-translate-x-full'}`}>
         <div className="flex flex-col h-full pt-12">
            <button onClick={() => setIsMemoryOpen(false)} className={`absolute top-12 ${isMobile || prefs.layout === 'right' ? 'right-10' : 'left-10'} text-gray-600 hover:text-white transition-colors`}><i className="fas fa-times text-2xl"></i></button>
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
         </div>
      </aside>

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 md:p-6 bg-black/90 backdrop-blur-2xl animate-fade-in overflow-y-auto">
          <div className={`bg-[#02020a] border border-white/10 ${isMobile ? 'rounded-[2rem]' : 'rounded-[4rem]'} w-full max-w-4xl p-6 md:p-12 shadow-3xl relative my-auto`}>
            <button onClick={() => setIsSettingsOpen(false)} className="absolute top-6 right-6 md:top-10 md:right-10 text-gray-600"><i className="fas fa-times text-3xl"></i></button>
            <header className="mb-6 md:mb-12"><h2 className={`${isTv ? 'text-6xl' : 'text-3xl md:text-5xl'} font-black tracking-tighter uppercase mb-2`}>Neural Config</h2></header>
            <div className={`grid grid-cols-1 ${!isMobile ? 'lg:grid-cols-2' : ''} gap-6 md:gap-12`}>
              <section className="space-y-6 md:space-y-10">
                <div className="space-y-4">
                   <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Personality</label>
                   <div className="grid grid-cols-2 gap-2">
                     {(Object.keys(PERSONALITIES) as PersonalityType[]).map(p => (
                       <button key={p} onClick={() => setPrefs(prev => ({ ...prev, personality: p }))} className={`px-2 py-3 rounded-xl border-2 transition-all font-black text-[9px] uppercase tracking-widest ${prefs.personality === p ? `bg-${themeData.primary}/10 border-${themeData.primary}` : 'bg-white/5 border-white/5 text-gray-600'}`}>{p}</button>
                     ))}
                   </div>
                </div>
                <div className="space-y-4">
                  <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Base Identity</label>
                  <input type="text" value={prefs.assistantName} onChange={(e) => setPrefs(p => ({ ...p, assistantName: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-xl py-3 px-6 font-black focus:outline-none transition-all" />
                </div>
              </section>
              {!isMobile && <section className="bg-white/[0.03] border border-white/5 rounded-[3rem] p-8 space-y-8 flex flex-col justify-center text-center opacity-30"><i className="fas fa-wave-square text-6xl text-blue-500"></i><h3 className="text-xl font-black uppercase">Synthesizer Core</h3></section>}
            </div>
            <footer className="mt-8 md:mt-12 flex flex-col md:flex-row items-center justify-between gap-6">
              <div className="flex items-center gap-4">
                {(Object.keys(THEMES) as UITheme[]).map(t => ( <button key={t} onClick={() => setPrefs(p => ({ ...p, theme: t }))} className={`w-8 h-8 rounded-xl border-2 transition-all ${prefs.theme === t ? 'border-white scale-110' : 'border-white/5'}`} style={{ backgroundColor: THEMES[t].bg }} /> ))}
              </div>
              <button onClick={() => setIsSettingsOpen(false)} className="w-full md:w-auto md:flex-1 bg-white text-black font-black py-4 px-12 rounded-[2rem] text-xs tracking-[0.4em] uppercase">Commit Changes</button>
            </footer>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser, UITheme, PersonalityType, UserPreferences, DeviceType } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';
import ScreenShareMode from './components/ScreenShareMode';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const THEMES: Record<UITheme, { primary: string; secondary: string; glow: string; bg: string }> = {
  cosmic: { primary: 'blue-500', secondary: 'indigo-500', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: 'emerald-500', secondary: 'teal-500', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: 'rose-500', secondary: 'orange-500', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: 'slate-400', secondary: 'zinc-500', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: VOICES[0].id,
  assistantName: 'Nova'
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [device, setDevice] = useState<DeviceType>('desktop');
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [inputText, setInputText] = useState('');
  const [isTypingExpanded, setIsTypingExpanded] = useState(false);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const detectDevice = () => {
      const w = window.innerWidth;
      const h = window.innerHeight;
      const ua = navigator.userAgent.toLowerCase();
      const isAndroid = ua.includes('android');
      const isLandscape = w > h;
      const isAutoDimensions = w >= 800 && w <= 1280 && h >= 400 && h <= 800;

      if (w <= 300) setDevice('wear');
      else if (isAndroid && isLandscape && isAutoDimensions) setDevice('auto');
      else if (ua.includes('tv') || ua.includes('google-tv') || ua.includes('android-tv') || w >= 1920) setDevice('tv');
      else if (w < 1024) setDevice('mobile');
      else setDevice('desktop');
    };
    detectDevice();
    window.addEventListener('resize', detectDevice);
    return () => window.removeEventListener('resize', detectDevice);
  }, []);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
      setUser({ 
        username: sessionUser, 
        preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS 
      });
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      const savedMemories = localStorage.getItem(`nova_${user.username}_memories`);
      if (savedMemories) setMemories(JSON.parse(savedMemories));
      const savedLogs = localStorage.getItem(`nova_${user.username}_logs`);
      setTranscriptions(savedLogs ? JSON.parse(savedLogs) : []);
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme], [prefs.theme]);

  const addTranscription = (sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
  }, [screenStream]);

  const startSession = async () => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? prefs.customPersonality : PERSONALITIES[prefs.personality];
      const contextHint = device === 'auto' ? "IMPORTANT: The user is currently driving. Be extremely concise." : "";

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools: [{ functionDeclarations: [saveKnowledgeTool] }],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. User: ${user?.username}. Memories: ${facts}. Personality: ${personalityPrompt}. Device: ${device}. ${contextHint} Real-time communication protocol active. Assist via voice/text.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              if (!sessionRef.current) return;
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: audioUtils.createPcmBlob(inputData) }); });
              if (currentFrameRef.current && sessionRef.current) {
                const frame = currentFrameRef.current;
                sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } }); });
                currentFrameRef.current = null;
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = (fc.args as any).fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => { if (sessionRef.current) s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Memory saved." } } }); });
                }
              }
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); 
              s.buffer = buffer; 
              s.connect(outputCtx.destination);
              s.onended = () => { 
                activeSourcesRef.current.delete(s); 
                if (activeSourcesRef.current.size === 0 && sessionRef.current) setState(AssistantState.LISTENING); 
              };
              s.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration; 
              activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            if (message.serverContent?.turnComplete) {
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) addTranscription('assistant', a); return ''; });
            }
          },
          onerror: (err) => { stopSession(); },
          onclose: () => { stopSession(); }
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(err.message || "Link failed."); setState(AssistantState.IDLE); }
  };

  const handleSendText = async () => {
    if (!inputText.trim()) return;
    const msg = inputText.trim();
    setInputText('');
    addTranscription('user', msg);
    if (sessionRef.current) {
      sessionRef.current.sendRealtimeInput({ parts: [{ text: msg }] });
    } else {
      await startSession();
      // Wait briefly for connection before sending if it was idle
      setTimeout(() => {
        if (sessionRef.current) sessionRef.current.sendRealtimeInput({ parts: [{ text: msg }] });
      }, 1000);
    }
    inputRef.current?.blur();
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendText();
    }
  };

  // ---------------------------------------------------------------------------------
  // ANDROID AUTO RENDER PATH
  // ---------------------------------------------------------------------------------
  if (device === 'auto') {
    if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;
    return (
      <div className="h-screen w-full bg-black text-white p-6 flex flex-col font-sans">
        <header className="flex items-center justify-between mb-4 border-b border-white/10 pb-4">
          <div className="flex items-center gap-4">
            <i className={`fas fa-car-side text-2xl text-${themeData.primary}`}></i>
            <h1 className="text-3xl font-black tracking-tighter uppercase">{prefs.assistantName} // Driving</h1>
          </div>
          <div className="bg-white/5 px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest text-gray-400">Link: {state === AssistantState.IDLE ? 'STBY' : 'ACTV'}</div>
        </header>
        <main className="flex-1 flex items-center gap-8">
          <div className="w-1/3 flex flex-col items-center justify-center">
             <div className={`w-64 h-64 rounded-full border-8 border-${themeData.primary}/20 flex items-center justify-center bg-black shadow-[0_0_60px_rgba(0,0,0,1)]`}>
                <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
             </div>
          </div>
          <div className="flex-1 flex flex-col justify-center gap-4">
            <div className="bg-white/[0.02] border border-white/10 rounded-[2rem] p-8 h-48 flex items-center shadow-inner overflow-hidden">
              <p className="text-3xl font-bold leading-tight text-blue-100">{streamingAssistantText || transcriptions[transcriptions.length-1]?.text || 'Neural link established. Drive safe.'}</p>
            </div>
            {streamingUserText && <p className="text-sm uppercase tracking-[0.3em] text-gray-500 animate-pulse ml-4 italic">User: {streamingUserText}</p>}
          </div>
        </main>
        <footer className="mt-4">
          <button onClick={state === AssistantState.IDLE ? startSession : stopSession} className={`w-full ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-600 text-white'} font-black py-8 rounded-[2rem] text-2xl uppercase tracking-[0.2em] shadow-2xl flex items-center justify-center gap-6`}>
            <i className={`fas ${state === AssistantState.IDLE ? 'fa-play' : 'fa-stop-circle'}`}></i>
            {state === AssistantState.IDLE ? 'Initialize Link' : 'Terminate Link'}
          </button>
        </footer>
      </div>
    );
  }

  // ---------------------------------------------------------------------------------
  // WEAROS RENDER PATH
  // ---------------------------------------------------------------------------------
  if (device === 'wear') {
    if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;
    return (
      <div className="wear-screen bg-black flex flex-col items-center justify-center p-4">
        <div className={`w-full h-full border-4 rounded-full flex flex-col items-center justify-center relative transition-colors duration-1000 border-${themeData.primary}/30`}>
          {!isTypingExpanded ? (
            <>
              <div className="absolute top-6"><h2 className={`text-[10px] font-black tracking-widest uppercase text-${themeData.primary}`}>{prefs.assistantName}</h2></div>
              <div className="flex-1 flex flex-col items-center justify-center w-full">
                <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
                <div className="h-10 overflow-hidden text-center mt-2 px-4"><p className="text-[9px] text-gray-400 line-clamp-2 italic">{streamingAssistantText || transcriptions[transcriptions.length-1]?.text || 'Standby...'}</p></div>
              </div>
              <div className="absolute bottom-4 flex gap-2">
                <button onClick={() => setIsTypingExpanded(true)} className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center"><i className="fas fa-keyboard text-[8px]"></i></button>
                <button onClick={state === AssistantState.IDLE ? startSession : stopSession} className={`w-10 h-10 rounded-full flex items-center justify-center transition-all shadow-lg ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500 text-white'}`}><i className={`fas ${state === AssistantState.IDLE ? 'fa-play' : 'fa-stop'} text-xs`}></i></button>
              </div>
            </>
          ) : (
            <div className="w-full h-full p-4 flex flex-col items-center justify-center bg-black/80 backdrop-blur-sm z-50">
               <input 
                 autoFocus
                 type="text" 
                 value={inputText} 
                 onChange={(e) => setInputText(e.target.value)}
                 onKeyDown={handleKeyPress}
                 placeholder="Comm..." 
                 className="w-24 bg-white/10 border border-white/20 rounded-full py-1 px-3 text-[10px] focus:outline-none mb-2" 
               />
               <div className="flex gap-2">
                 <button onClick={() => { handleSendText(); setIsTypingExpanded(false); }} className={`w-8 h-8 rounded-full bg-${themeData.primary} text-white flex items-center justify-center`}><i className="fas fa-paper-plane text-[8px]"></i></button>
                 <button onClick={() => setIsTypingExpanded(false)} className="w-8 h-8 rounded-full bg-white/10 text-white flex items-center justify-center"><i className="fas fa-times text-[8px]"></i></button>
               </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  // ---------------------------------------------------------------------------------
  // MAIN RENDER PATH (Mobile, Desktop, TV)
  // ---------------------------------------------------------------------------------
  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;

  const isTv = device === 'tv';
  const isMobile = device === 'mobile';

  return (
    <div className={`flex flex-col h-screen w-full text-white overflow-hidden font-sans transition-colors duration-1000 ${isTv ? 'text-xl' : 'text-base'}`} style={{ backgroundColor: themeData.bg }}>
      <div className={`flex-1 flex flex-col ${isMobile ? 'overflow-y-auto' : 'md:flex-row'} transition-all duration-700 ${isMemoryOpen ? 'p-0' : 'p-4 md:p-8'}`}>
        <div className={`flex-1 flex flex-col transition-all duration-700 ${!isMobile && isMemoryOpen && prefs.layout === 'right' ? 'md:mr-[340px]' : ''} ${!isMobile && isMemoryOpen && prefs.layout === 'left' ? 'md:ml-[340px]' : ''}`}>

          <header className={`flex items-center justify-between animate-fade-in relative z-50 ${isMobile ? 'mb-4' : 'mb-8'}`}>
            <div className="flex items-center gap-4 md:gap-6">
              <div className={`${isTv ? 'w-24 h-24' : isMobile ? 'w-12 h-12' : 'w-16 h-16'} rounded-[2rem] flex items-center justify-center shadow-2xl transition-all duration-500 border border-white/10 ${state !== AssistantState.IDLE ? `bg-${themeData.primary} rotate-12 scale-110` : 'bg-white/5'}`} style={state !== AssistantState.IDLE ? { boxShadow: `0 0 40px ${themeData.glow}` } : {}}>
                <i className={`fas ${state === AssistantState.THINKING ? 'fa-microchip animate-pulse' : isVisionActive ? 'fa-eye' : isScreenSharing ? 'fa-desktop' : 'fa-atom'} ${isTv ? 'text-5xl' : 'text-xl md:text-3xl'} text-white`}></i>
              </div>
              {!isMobile && (
                <div>
                  <h1 className={`${isTv ? 'text-5xl' : 'text-3xl'} font-black tracking-tighter bg-gradient-to-r from-${themeData.primary} via-${themeData.secondary} to-white bg-clip-text text-transparent`}>{prefs.assistantName}</h1>
                  <p className="text-[10px] text-gray-500 font-bold uppercase tracking-[0.4em] mt-1 flex items-center gap-2"><i className={`fas fa-shield-halved text-[6px] text-${themeData.primary} animate-pulse`}></i> {user.username} // Hub</p>
                </div>
              )}
            </div>
            <div className="flex items-center gap-2 md:gap-4">
               {!isMobile && (
                 <>
                  <button tabIndex={1} onClick={() => { setIsScreenSharing(!isScreenSharing); setIsVisionActive(false); }} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isScreenSharing ? 'bg-cyan-500' : 'bg-white/5 text-gray-400'}`}><i className="fas fa-desktop text-sm"></i></button>
                  <button tabIndex={2} onClick={() => { setIsVisionActive(!isVisionActive); setIsScreenSharing(false); }} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isVisionActive ? 'bg-red-500' : 'bg-white/5 text-gray-400'}`}><i className="fas fa-camera text-sm"></i></button>
                 </>
               )}
               <button tabIndex={3} onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isMemoryOpen ? `bg-${themeData.primary}` : 'bg-white/5 text-gray-400'}`}><i className="fas fa-database text-sm"></i></button>
               <button tabIndex={4} onClick={() => setIsSettingsOpen(true)} className="w-12 h-12 rounded-2xl flex items-center justify-center bg-white/5 text-gray-400"><i className="fas fa-cog text-sm"></i></button>
               <button tabIndex={5} onClick={handleLogout} className="text-gray-600 hover:text-red-400 px-2"><i className="fas fa-sign-out-alt"></i></button>
            </div>
          </header>

          <main className="flex-1 flex flex-col md:flex-row gap-6 min-h-0">
            <div className={`flex-1 flex flex-col min-h-0 bg-white/[0.01] ${isMobile ? 'rounded-[2rem]' : 'rounded-[3rem]'} border border-white/5 backdrop-blur-3xl overflow-hidden relative shadow-inner animate-fade-in`}>
               <div className={`flex-1 flex flex-col items-center justify-center z-10 ${isMobile ? 'p-4' : 'p-8'}`}>
                 {state === AssistantState.IDLE ? (
                   <div className="text-center space-y-6 md:space-y-10 group">
                     <div className={`${isTv ? 'w-64 h-64' : isMobile ? 'w-32 h-32' : 'w-48 h-48'} rounded-[4rem] bg-white/5 border border-white/10 flex items-center justify-center mx-auto shadow-inner relative transition-transform duration-500 group-hover:scale-105`}>
                        <i className={`fas fa-microphone-lines ${isTv ? 'text-8xl' : isMobile ? 'text-4xl' : 'text-7xl'} text-${themeData.primary}/30`}></i>
                     </div>
                     <h2 className={`${isTv ? 'text-6xl' : 'text-2xl md:text-4xl'} font-black mb-4 tracking-tighter uppercase opacity-30`}>Standby</h2>
                   </div>
                 ) : (
                   <div className="w-full max-w-2xl flex flex-col items-center"><VoiceVisualizer state={state} analyser={analyserRef.current || undefined} /></div>
                 )}
               </div>
               <div className={`${isTv ? 'h-96' : isMobile ? 'h-56' : 'h-80'} bg-black/40 border-t border-white/5 p-4 md:p-8 flex flex-col backdrop-blur-2xl`}>
                 <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-4 pr-2 scrollbar-thin scrollbar-thumb-white/10">
                   {transcriptions.map(e => (
                     <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'}`}>
                       <div className={`max-w-[85%] rounded-[1.5rem] px-4 py-3 md:px-8 md:py-5 text-sm ${e.sender === 'user' ? `bg-${themeData.primary} text-white` : 'bg-white/5 text-gray-300'}`}>{e.text}</div>
                     </div>
                   ))}
                   {streamingAssistantText && <div className="flex flex-col items-start"><div className="max-w-[85%] rounded-[1.5rem] px-4 py-3 md:px-8 md:py-5 text-sm bg-white/10 text-blue-200 animate-pulse">{streamingAssistantText}</div></div>}
                 </div>

                 {/* Neural Input Matrix (Typing Bar) */}
                 <div className="mt-4 flex gap-3 animate-slide-up">
                    <div className="flex-1 relative">
                       <input 
                         ref={inputRef}
                         type="text" 
                         value={inputText}
                         onChange={(e) => setInputText(e.target.value)}
                         onKeyDown={handleKeyPress}
                         placeholder={`Transmit to ${prefs.assistantName}...`}
                         className={`w-full bg-white/5 border border-white/10 rounded-2xl py-3 px-6 text-sm focus:outline-none focus:border-${themeData.primary}/50 transition-all font-medium placeholder:text-gray-600`}
                       />
                       <div className={`absolute right-4 top-1/2 -translate-y-1/2 text-${themeData.primary} opacity-30`}><i className="fas fa-bolt-lightning text-xs"></i></div>
                    </div>
                    <button 
                      onClick={handleSendText}
                      disabled={!inputText.trim()}
                      className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${inputText.trim() ? `bg-${themeData.primary} text-white shadow-lg` : 'bg-white/5 text-gray-600 cursor-not-allowed'}`}
                      style={inputText.trim() ? { boxShadow: `0 0 20px ${themeData.glow}` } : {}}
                    >
                      <i className="fas fa-paper-plane text-xs"></i>
                    </button>
                 </div>
               </div>
            </div>
            {(!isMobile && (isVisionActive || isScreenSharing)) && (
              <div className="w-full md:w-80 flex flex-col gap-6 animate-slide-in-right">
                {isVisionActive && <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />}
                {isScreenSharing && screenStream && <ScreenShareMode isActive={isScreenSharing} stream={screenStream} onFrame={(b) => currentFrameRef.current = b} onStop={() => { setIsScreenSharing(false); setScreenStream(null); }} />}
              </div>
            )}
          </main>

          <div className={`flex items-center justify-center ${isMobile ? 'my-4' : 'mt-10'}`}>
             <button tabIndex={6} onClick={state === AssistantState.IDLE ? startSession : stopSession} className={`${isTv ? 'py-10 px-32 text-2xl' : isMobile ? 'py-4 px-10 text-xs' : 'py-7 px-20 text-sm'} ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500/10 border-red-500/20 text-white'} font-black rounded-[2.5rem] transition-all flex items-center gap-6 shadow-2xl`}>
                <i className={`fas ${state === AssistantState.IDLE ? 'fa-play' : 'fa-stop'}`}></i>
                <span className="tracking-[0.3em] uppercase italic">{state === AssistantState.IDLE ? `Initialize ${prefs.assistantName}` : 'Terminate'}</span>
             </button>
          </div>
        </div>
      </div>

      <aside className={`fixed top-0 bottom-0 ${isMobile ? 'w-full' : 'w-[340px]'} z-[60] transition-transform duration-700 transform bg-black/90 border-white/5 shadow-2xl backdrop-blur-2xl ${prefs.layout === 'right' || isMobile ? 'right-0 border-l' : 'left-0 border-r'} ${isMemoryOpen ? 'translate-x-0' : (prefs.layout === 'right' || isMobile) ? 'translate-x-full' : '-translate-x-full'}`}>
         <div className="flex flex-col h-full pt-12">
            <button onClick={() => setIsMemoryOpen(false)} className={`absolute top-12 ${isMobile || prefs.layout === 'right' ? 'right-10' : 'left-10'} text-gray-600 hover:text-white transition-colors`}><i className="fas fa-times text-2xl"></i></button>
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
         </div>
      </aside>

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 md:p-6 bg-black/90 backdrop-blur-2xl animate-fade-in overflow-y-auto">
          <div className={`bg-[#02020a] border border-white/10 ${isMobile ? 'rounded-[2rem]' : 'rounded-[4rem]'} w-full max-w-4xl p-6 md:p-12 shadow-3xl relative my-auto`}>
            <button onClick={() => setIsSettingsOpen(false)} className="absolute top-6 right-6 md:top-10 md:right-10 text-gray-600"><i className="fas fa-times text-3xl"></i></button>
            <header className="mb-6 md:mb-12"><h2 className={`${isTv ? 'text-6xl' : 'text-3xl md:text-5xl'} font-black tracking-tighter uppercase mb-2`}>Neural Config</h2></header>
            <div className={`grid grid-cols-1 ${!isMobile ? 'lg:grid-cols-2' : ''} gap-6 md:gap-12`}>
              <section className="space-y-6 md:space-y-10">
                <div className="space-y-4">
                   <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Personality</label>
                   <div className="grid grid-cols-2 gap-2">
                     {(Object.keys(PERSONALITIES) as PersonalityType[]).map(p => (
                       <button key={p} onClick={() => setPrefs(prev => ({ ...prev, personality: p }))} className={`px-2 py-3 rounded-xl border-2 transition-all font-black text-[9px] uppercase tracking-widest ${prefs.personality === p ? `bg-${themeData.primary}/10 border-${themeData.primary}` : 'bg-white/5 border-white/5 text-gray-600'}`}>{p}</button>
                     ))}
                   </div>
                </div>
                <div className="space-y-4">
                  <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Base Identity</label>
                  <input type="text" value={prefs.assistantName} onChange={(e) => setPrefs(p => ({ ...p, assistantName: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-xl py-3 px-6 font-black focus:outline-none transition-all" />
                </div>
              </section>
              {!isMobile && <section className="bg-white/[0.03] border border-white/5 rounded-[3rem] p-8 space-y-8 flex flex-col justify-center text-center opacity-30"><i className="fas fa-wave-square text-6xl text-blue-500"></i><h3 className="text-xl font-black uppercase">Synthesizer Core</h3></section>}
            </div>
            <footer className="mt-8 md:mt-12 flex flex-col md:flex-row items-center justify-between gap-6">
              <div className="flex items-center gap-4">
                {(Object.keys(THEMES) as UITheme[]).map(t => ( <button key={t} onClick={() => setPrefs(p => ({ ...p, theme: t }))} className={`w-8 h-8 rounded-xl border-2 transition-all ${prefs.theme === t ? 'border-white scale-110' : 'border-white/5'}`} style={{ backgroundColor: THEMES[t].bg }} /> ))}
              </div>
              <button onClick={() => setIsSettingsOpen(false)} className="w-full md:w-auto md:flex-1 bg-white text-black font-black py-4 px-12 rounded-[2rem] text-xs tracking-[0.4em] uppercase">Commit Changes</button>
            </footer>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser, UITheme, PersonalityType, UserPreferences, DeviceType } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';
import ScreenShareMode from './components/ScreenShareMode';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const THEMES: Record<UITheme, { primary: string; secondary: string; glow: string; bg: string }> = {
  cosmic: { primary: 'blue-500', secondary: 'indigo-500', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: 'emerald-500', secondary: 'teal-500', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: 'rose-500', secondary: 'orange-500', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: 'slate-400', secondary: 'zinc-500', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: VOICES[0].id,
  assistantName: 'Nova'
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [device, setDevice] = useState<DeviceType>('desktop');
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [inputText, setInputText] = useState('');
  const [isTypingExpanded, setIsTypingExpanded] = useState(false);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const detectDevice = () => {
      const w = window.innerWidth;
      const h = window.innerHeight;
      const ua = navigator.userAgent.toLowerCase();
      const isAndroid = ua.includes('android');
      const isLandscape = w > h;
      const isAutoDimensions = w >= 800 && w <= 1280 && h >= 400 && h <= 800;

      if (w <= 300) setDevice('wear');
      else if (isAndroid && isLandscape && isAutoDimensions) setDevice('auto');
      else if (ua.includes('tv') || ua.includes('google-tv') || ua.includes('android-tv') || w >= 1920) setDevice('tv');
      else if (w < 1024) setDevice('mobile');
      else setDevice('desktop');
    };
    detectDevice();
    window.addEventListener('resize', detectDevice);
    return () => window.removeEventListener('resize', detectDevice);
  }, []);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
      setUser({ 
        username: sessionUser, 
        preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS 
      });
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      const savedMemories = localStorage.getItem(`nova_${user.username}_memories`);
      if (savedMemories) setMemories(JSON.parse(savedMemories));
      const savedLogs = localStorage.getItem(`nova_${user.username}_logs`);
      setTranscriptions(savedLogs ? JSON.parse(savedLogs) : []);
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme], [prefs.theme]);

  const addTranscription = (sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
  }, [screenStream]);

  // Fix: Implemented handleLogout to correctly clear user session state
  const handleLogout = useCallback(() => {
    stopSession();
    setUser(null);
    sessionStorage.removeItem('nova_session_user');
  }, [stopSession]);

  const startSession = async () => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? prefs.customPersonality : PERSONALITIES[prefs.personality];
      const contextHint = device === 'auto' ? "IMPORTANT: The user is currently driving. Be extremely concise." : "";

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools: [{ functionDeclarations: [saveKnowledgeTool] }],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. User: ${user?.username}. Memories: ${facts}. Personality: ${personalityPrompt}. Device: ${device}. ${contextHint} Real-time communication protocol active. Assist via voice/text.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            // Fix: Solely rely on sessionPromise resolves to send inputs to avoid stale closure issues
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = audioUtils.createPcmBlob(inputData);
              sessionPromise.then(s => { 
                if (sessionRef.current) s.sendRealtimeInput({ media: pcmBlob }); 
              });

              if (currentFrameRef.current) {
                const frame = currentFrameRef.current;
                currentFrameRef.current = null;
                sessionPromise.then(s => { 
                  if (sessionRef.current) s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } }); 
                });
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = (fc.args as any).fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => { if (sessionRef.current) s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Memory saved." } } }); });
                }
              }
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); 
              s.buffer = buffer; 
              s.connect(outputCtx.destination);
              s.onended = () => { 
                activeSourcesRef.current.delete(s); 
                if (activeSourcesRef.current.size === 0 && sessionRef.current) setState(AssistantState.LISTENING); 
              };
              s.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration; 
              activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            if (message.serverContent?.turnComplete) {
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) addTranscription('assistant', a); return ''; });
            }
          },
          onerror: (err) => { stopSession(); },
          onclose: () => { stopSession(); }
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(err.message || "Link failed."); setState(AssistantState.IDLE); }
  };

  const handleSendText = async () => {
    if (!inputText.trim()) return;
    const msg = inputText.trim();
    setInputText('');
    addTranscription('user', msg);

    let session = sessionRef.current;
    if (!session) {
      await startSession();
      session = sessionRef.current;
    }

    if (session) {
      session.sendRealtimeInput({ parts: [{ text: msg }] });
    }
    inputRef.current?.blur();
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendText();
    }
  };

  // ---------------------------------------------------------------------------------
  // ANDROID AUTO RENDER PATH
  // ---------------------------------------------------------------------------------
  if (device === 'auto') {
    if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;
    return (
      <div className="h-screen w-full bg-black text-white p-6 flex flex-col font-sans">
        <header className="flex items-center justify-between mb-4 border-b border-white/10 pb-4">
          <div className="flex items-center gap-4">
            <i className={`fas fa-car-side text-2xl text-${themeData.primary}`}></i>
            <h1 className="text-3xl font-black tracking-tighter uppercase">{prefs.assistantName} // Driving</h1>
          </div>
          <div className="bg-white/5 px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest text-gray-400">Link: {state === AssistantState.IDLE ? 'STBY' : 'ACTV'}</div>
        </header>
        <main className="flex-1 flex items-center gap-8">
          <div className="w-1/3 flex flex-col items-center justify-center">
             <div className={`w-64 h-64 rounded-full border-8 border-${themeData.primary}/20 flex items-center justify-center bg-black shadow-[0_0_60px_rgba(0,0,0,1)]`}>
                <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
             </div>
          </div>
          <div className="flex-1 flex flex-col justify-center gap-4">
            <div className="bg-white/[0.02] border border-white/10 rounded-[2rem] p-8 h-48 flex items-center shadow-inner overflow-hidden">
              <p className="text-3xl font-bold leading-tight text-blue-100">{streamingAssistantText || transcriptions[transcriptions.length-1]?.text || 'Neural link established. Drive safe.'}</p>
            </div>
            {streamingUserText && <p className="text-sm uppercase tracking-[0.3em] text-gray-500 animate-pulse ml-4 italic">User: {streamingUserText}</p>}
          </div>
        </main>
        <footer className="mt-4">
          <button onClick={state === AssistantState.IDLE ? startSession : stopSession} className={`w-full ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-600 text-white'} font-black py-8 rounded-[2rem] text-2xl uppercase tracking-[0.2em] shadow-2xl flex items-center justify-center gap-6`}>
            <i className={`fas ${state === AssistantState.IDLE ? 'fa-play' : 'fa-stop-circle'}`}></i>
            {state === AssistantState.IDLE ? 'Initialize Link' : 'Terminate Link'}
          </button>
        </footer>
      </div>
    );
  }

  // ---------------------------------------------------------------------------------
  // WEAROS RENDER PATH
  // ---------------------------------------------------------------------------------
  if (device === 'wear') {
    if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;
    return (
      <div className="wear-screen bg-black flex flex-col items-center justify-center p-4">
        <div className={`w-full h-full border-4 rounded-full flex flex-col items-center justify-center relative transition-colors duration-1000 border-${themeData.primary}/30`}>
          {!isTypingExpanded ? (
            <>
              <div className="absolute top-6"><h2 className={`text-[10px] font-black tracking-widest uppercase text-${themeData.primary}`}>{prefs.assistantName}</h2></div>
              <div className="flex-1 flex flex-col items-center justify-center w-full">
                <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
                <div className="h-10 overflow-hidden text-center mt-2 px-4"><p className="text-[9px] text-gray-400 line-clamp-2 italic">{streamingAssistantText || transcriptions[transcriptions.length-1]?.text || 'Standby...'}</p></div>
              </div>
              <div className="absolute bottom-4 flex gap-2">
                <button onClick={() => setIsTypingExpanded(true)} className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center"><i className="fas fa-keyboard text-[8px]"></i></button>
                <button onClick={state === AssistantState.IDLE ? startSession : stopSession} className={`w-10 h-10 rounded-full flex items-center justify-center transition-all shadow-lg ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500 text-white'}`}><i className={`fas ${state === AssistantState.IDLE ? 'fa-play' : 'fa-stop'} text-xs`}></i></button>
              </div>
            </>
          ) : (
            <div className="w-full h-full p-4 flex flex-col items-center justify-center bg-black/80 backdrop-blur-sm z-50">
               <input 
                 autoFocus
                 type="text" 
                 value={inputText} 
                 onChange={(e) => setInputText(e.target.value)}
                 onKeyDown={handleKeyPress}
                 placeholder="Comm..." 
                 className="w-24 bg-white/10 border border-white/20 rounded-full py-1 px-3 text-[10px] focus:outline-none mb-2" 
               />
               <div className="flex gap-2">
                 <button onClick={() => { handleSendText(); setIsTypingExpanded(false); }} className={`w-8 h-8 rounded-full bg-${themeData.primary} text-white flex items-center justify-center`}><i className="fas fa-paper-plane text-[8px]"></i></button>
                 <button onClick={() => setIsTypingExpanded(false)} className="w-8 h-8 rounded-full bg-white/10 text-white flex items-center justify-center"><i className="fas fa-times text-[8px]"></i></button>
               </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  // ---------------------------------------------------------------------------------
  // MAIN RENDER PATH (Mobile, Desktop, TV)
  // ---------------------------------------------------------------------------------
  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;

  const isTv = device === 'tv';
  const isMobile = device === 'mobile';

  return (
    <div className={`flex flex-col h-screen w-full text-white overflow-hidden font-sans transition-colors duration-1000 ${isTv ? 'text-xl' : 'text-base'}`} style={{ backgroundColor: themeData.bg }}>
      <div className={`flex-1 flex flex-col ${isMobile ? 'overflow-y-auto' : 'md:flex-row'} transition-all duration-700 ${isMemoryOpen ? 'p-0' : 'p-4 md:p-8'}`}>
        <div className={`flex-1 flex flex-col transition-all duration-700 ${!isMobile && isMemoryOpen && prefs.layout === 'right' ? 'md:mr-[340px]' : ''} ${!isMobile && isMemoryOpen && prefs.layout === 'left' ? 'md:ml-[340px]' : ''}`}>

          <header className={`flex items-center justify-between animate-fade-in relative z-50 ${isMobile ? 'mb-4' : 'mb-8'}`}>
            <div className="flex items-center gap-4 md:gap-6">
              <div className={`${isTv ? 'w-24 h-24' : isMobile ? 'w-12 h-12' : 'w-16 h-16'} rounded-[2rem] flex items-center justify-center shadow-2xl transition-all duration-500 border border-white/10 ${state !== AssistantState.IDLE ? `bg-${themeData.primary} rotate-12 scale-110` : 'bg-white/5'}`} style={state !== AssistantState.IDLE ? { boxShadow: `0 0 40px ${themeData.glow}` } : {}}>
                <i className={`fas ${state === AssistantState.THINKING ? 'fa-microchip animate-pulse' : isVisionActive ? 'fa-eye' : isScreenSharing ? 'fa-desktop' : 'fa-atom'} ${isTv ? 'text-5xl' : 'text-xl md:text-3xl'} text-white`}></i>
              </div>
              {!isMobile && (
                <div>
                  <h1 className={`${isTv ? 'text-5xl' : 'text-3xl'} font-black tracking-tighter bg-gradient-to-r from-${themeData.primary} via-${themeData.secondary} to-white bg-clip-text text-transparent`}>{prefs.assistantName}</h1>
                  <p className="text-[10px] text-gray-500 font-bold uppercase tracking-[0.4em] mt-1 flex items-center gap-2"><i className={`fas fa-shield-halved text-[6px] text-${themeData.primary} animate-pulse`}></i> {user.username} // Hub</p>
                </div>
              )}
            </div>
            <div className="flex items-center gap-2 md:gap-4">
               {!isMobile && (
                 <>
                  <button tabIndex={1} onClick={() => { setIsScreenSharing(!isScreenSharing); setIsVisionActive(false); }} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isScreenSharing ? 'bg-cyan-500' : 'bg-white/5 text-gray-400'}`}><i className="fas fa-desktop text-sm"></i></button>
                  <button tabIndex={2} onClick={() => { setIsVisionActive(!isVisionActive); setIsScreenSharing(false); }} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isVisionActive ? 'bg-red-500' : 'bg-white/5 text-gray-400'}`}><i className="fas fa-camera text-sm"></i></button>
                 </>
               )}
               <button tabIndex={3} onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isMemoryOpen ? `bg-${themeData.primary}` : 'bg-white/5 text-gray-400'}`}><i className="fas fa-database text-sm"></i></button>
               <button tabIndex={4} onClick={() => setIsSettingsOpen(true)} className="w-12 h-12 rounded-2xl flex items-center justify-center bg-white/5 text-gray-400"><i className="fas fa-cog text-sm"></i></button>
               <button tabIndex={5} onClick={handleLogout} className="text-gray-600 hover:text-red-400 px-2"><i className="fas fa-sign-out-alt"></i></button>
            </div>
          </header>

          <main className="flex-1 flex flex-col md:flex-row gap-6 min-h-0">
            <div className={`flex-1 flex flex-col min-h-0 bg-white/[0.01] ${isMobile ? 'rounded-[2rem]' : 'rounded-[3rem]'} border border-white/5 backdrop-blur-3xl overflow-hidden relative shadow-inner animate-fade-in`}>
               <div className={`flex-1 flex flex-col items-center justify-center z-10 ${isMobile ? 'p-4' : 'p-8'}`}>
                 {state === AssistantState.IDLE ? (
                   <div className="text-center space-y-6 md:space-y-10 group">
                     <div className={`${isTv ? 'w-64 h-64' : isMobile ? 'w-32 h-32' : 'w-48 h-48'} rounded-[4rem] bg-white/5 border border-white/10 flex items-center justify-center mx-auto shadow-inner relative transition-transform duration-500 group-hover:scale-105`}>
                        <i className={`fas fa-microphone-lines ${isTv ? 'text-8xl' : isMobile ? 'text-4xl' : 'text-7xl'} text-${themeData.primary}/30`}></i>
                     </div>
                     <h2 className={`${isTv ? 'text-6xl' : 'text-2xl md:text-4xl'} font-black mb-4 tracking-tighter uppercase opacity-30`}>Standby</h2>
                   </div>
                 ) : (
                   <div className="w-full max-w-2xl flex flex-col items-center"><VoiceVisualizer state={state} analyser={analyserRef.current || undefined} /></div>
                 )}
               </div>
               <div className={`${isTv ? 'h-96' : isMobile ? 'h-56' : 'h-80'} bg-black/40 border-t border-white/5 p-4 md:p-8 flex flex-col backdrop-blur-2xl`}>
                 <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-4 pr-2 scrollbar-thin scrollbar-thumb-white/10">
                   {transcriptions.map(e => (
                     <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'}`}>
                       <div className={`max-w-[85%] rounded-[1.5rem] px-4 py-3 md:px-8 md:py-5 text-sm ${e.sender === 'user' ? `bg-${themeData.primary} text-white` : 'bg-white/5 text-gray-300'}`}>{e.text}</div>
                     </div>
                   ))}
                   {streamingAssistantText && <div className="flex flex-col items-start"><div className="max-w-[85%] rounded-[1.5rem] px-4 py-3 md:px-8 md:py-5 text-sm bg-white/10 text-blue-200 animate-pulse">{streamingAssistantText}</div></div>}
                 </div>

                 {/* Neural Input Matrix (Typing Bar) */}
                 <div className="mt-4 flex gap-3 animate-slide-up">
                    <div className="flex-1 relative">
                       <input 
                         ref={inputRef}
                         type="text" 
                         value={inputText}
                         onChange={(e) => setInputText(e.target.value)}
                         onKeyDown={handleKeyPress}
                         placeholder={`Transmit to ${prefs.assistantName}...`}
                         className={`w-full bg-white/5 border border-white/10 rounded-2xl py-3 px-6 text-sm focus:outline-none focus:border-${themeData.primary}/50 transition-all font-medium placeholder:text-gray-600`}
                       />
                       <div className={`absolute right-4 top-1/2 -translate-y-1/2 text-${themeData.primary} opacity-30`}><i className="fas fa-bolt-lightning text-xs"></i></div>
                    </div>
                    <button 
                      onClick={handleSendText}
                      disabled={!inputText.trim()}
                      className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${inputText.trim() ? `bg-${themeData.primary} text-white shadow-lg` : 'bg-white/5 text-gray-600 cursor-not-allowed'}`}
                      style={inputText.trim() ? { boxShadow: `0 0 20px ${themeData.glow}` } : {}}
                    >
                      <i className="fas fa-paper-plane text-xs"></i>
                    </button>
                 </div>
               </div>
            </div>
            {(!isMobile && (isVisionActive || isScreenSharing)) && (
              <div className="w-full md:w-80 flex flex-col gap-6 animate-slide-in-right">
                {isVisionActive && <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />}
                {isScreenSharing && screenStream && <ScreenShareMode isActive={isScreenSharing} stream={screenStream} onFrame={(b) => currentFrameRef.current = b} onStop={() => { setIsScreenSharing(false); setScreenStream(null); }} />}
              </div>
            )}
          </main>

          <div className={`flex items-center justify-center ${isMobile ? 'my-4' : 'mt-10'}`}>
             <button tabIndex={6} onClick={state === AssistantState.IDLE ? startSession : stopSession} className={`${isTv ? 'py-10 px-32 text-2xl' : isMobile ? 'py-4 px-10 text-xs' : 'py-7 px-20 text-sm'} ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500/10 border-red-500/20 text-white'} font-black rounded-[2.5rem] transition-all flex items-center gap-6 shadow-2xl`}>
                <i className={`fas ${state === AssistantState.IDLE ? 'fa-play' : 'fa-stop'}`}></i>
                <span className="tracking-[0.3em] uppercase italic">{state === AssistantState.IDLE ? `Initialize ${prefs.assistantName}` : 'Terminate'}</span>
             </button>
          </div>
        </div>
      </div>

      <aside className={`fixed top-0 bottom-0 ${isMobile ? 'w-full' : 'w-[340px]'} z-[60] transition-transform duration-700 transform bg-black/90 border-white/5 shadow-2xl backdrop-blur-2xl ${prefs.layout === 'right' || isMobile ? 'right-0 border-l' : 'left-0 border-r'} ${isMemoryOpen ? 'translate-x-0' : (prefs.layout === 'right' || isMobile) ? 'translate-x-full' : '-translate-x-full'}`}>
         <div className="flex flex-col h-full pt-12">
            <button onClick={() => setIsMemoryOpen(false)} className={`absolute top-12 ${isMobile || prefs.layout === 'right' ? 'right-10' : 'left-10'} text-gray-600 hover:text-white transition-colors`}><i className="fas fa-times text-2xl"></i></button>
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
         </div>
      </aside>

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 md:p-6 bg-black/90 backdrop-blur-2xl animate-fade-in overflow-y-auto">
          <div className={`bg-[#02020a] border border-white/10 ${isMobile ? 'rounded-[2rem]' : 'rounded-[4rem]'} w-full max-w-4xl p-6 md:p-12 shadow-3xl relative my-auto`}>
            <button onClick={() => setIsSettingsOpen(false)} className="absolute top-6 right-6 md:top-10 md:right-10 text-gray-600"><i className="fas fa-times text-3xl"></i></button>
            <header className="mb-6 md:mb-12"><h2 className={`${isTv ? 'text-6xl' : 'text-3xl md:text-5xl'} font-black tracking-tighter uppercase mb-2`}>Neural Config</h2></header>
            <div className={`grid grid-cols-1 ${!isMobile ? 'lg:grid-cols-2' : ''} gap-6 md:gap-12`}>
              <section className="space-y-6 md:space-y-10">
                <div className="space-y-4">
                   <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Personality</label>
                   <div className="grid grid-cols-2 gap-2">
                     {(Object.keys(PERSONALITIES) as PersonalityType[]).map(p => (
                       <button key={p} onClick={() => setPrefs(prev => ({ ...prev, personality: p }))} className={`px-2 py-3 rounded-xl border-2 transition-all font-black text-[9px] uppercase tracking-widest ${prefs.personality === p ? `bg-${themeData.primary}/10 border-${themeData.primary}` : 'bg-white/5 border-white/5 text-gray-600'}`}>{p}</button>
                     ))}
                   </div>
                </div>
                <div className="space-y-4">
                  <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Base Identity</label>
                  <input type="text" value={prefs.assistantName} onChange={(e) => setPrefs(p => ({ ...p, assistantName: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-xl py-3 px-6 font-black focus:outline-none transition-all" />
                </div>
              </section>
              {!isMobile && <section className="bg-white/[0.03] border border-white/5 rounded-[3rem] p-8 space-y-8 flex flex-col justify-center text-center opacity-30"><i className="fas fa-wave-square text-6xl text-blue-500"></i><h3 className="text-xl font-black uppercase">Synthesizer Core</h3></section>}
            </div>
            <footer className="mt-8 md:mt-12 flex flex-col md:flex-row items-center justify-between gap-6">
              <div className="flex items-center gap-4">
                {(Object.keys(THEMES) as UITheme[]).map(t => ( <button key={t} onClick={() => setPrefs(p => ({ ...p, theme: t }))} className={`w-8 h-8 rounded-xl border-2 transition-all ${prefs.theme === t ? 'border-white scale-110' : 'border-white/5'}`} style={{ backgroundColor: THEMES[t].bg }} /> ))}
              </div>
              <button onClick={() => setIsSettingsOpen(false)} className="w-full md:w-auto md:flex-1 bg-white text-black font-black py-4 px-12 rounded-[2rem] text-xs tracking-[0.4em] uppercase">Commit Changes</button>
            </footer>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser, UITheme, PersonalityType, UserPreferences, DeviceType } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';
import ScreenShareMode from './components/ScreenShareMode';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
