  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [inputText, setInputText] = useState('');
  const [searchEnabled, setSearchEnabled] = useState(true);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const detectDevice = () => {
      const w = window.innerWidth;
      const h = window.innerHeight;
      const ua = navigator.userAgent.toLowerCase();
      if (w <= 300) setDevice('wear');
      else if (ua.includes('android') && w > h && w <= 1280) setDevice('auto');
      else if (ua.includes('tv') || w >= 1920) setDevice('tv');
      else if (w < 1024) setDevice('mobile');
      else setDevice('desktop');
    };
    detectDevice();
    window.addEventListener('resize', detectDevice);
    return () => window.removeEventListener('resize', detectDevice);
  }, []);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
      setUser({ username: sessionUser, preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS });
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      setMemories(JSON.parse(localStorage.getItem(`nova_${user.username}_memories`) || '[]'));
      setTranscriptions(JSON.parse(localStorage.getItem(`nova_${user.username}_logs`) || '[]'));
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme], [prefs.theme]);

  const addTranscription = useCallback((sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  }, []);

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
    setCurrentSources([]);
  }, [screenStream]);

  const handleLogout = useCallback(() => {
    stopSession();
    setUser(null);
    sessionStorage.removeItem('nova_session_user');
  }, [stopSession]);

  const startSession = async (initialText?: string) => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      audioUtils.playLinkSound(outputCtx);

      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? prefs.customPersonality : PERSONALITIES[prefs.personality];

      const tools: any[] = [{ functionDeclarations: [saveKnowledgeTool] }];
      if (searchEnabled) tools.push({ googleSearch: {} });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. User: ${user?.username}. Memories: ${facts}. Personality: ${personalityPrompt}. Device: ${device}. SEARCH_ENABLED: ${searchEnabled}. You respond to both voice and text messages with human-like empathy and high intelligence. Always generate audio for every response.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = audioUtils.createPcmBlob(inputData);
              sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: pcmBlob }); });
              if (currentFrameRef.current) {
                const frame = currentFrameRef.current;
                currentFrameRef.current = null;
                sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } }); });
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);

            if (initialText) {
              sessionPromise.then(s => s.sendRealtimeInput({ parts: [{ text: initialText }] }));
            }
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = (fc.args as any).fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => { if (sessionRef.current) s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Memory saved." } } }); });
                }
              }
            }

            const grounding = message.serverContent?.modelTurn?.parts?.find(p => (p as any).groundingMetadata)?.groundingMetadata;
            if (grounding?.groundingChunks) {
              const newSources = grounding.groundingChunks
                .filter((c: any) => c.web)
                .map((c: any) => ({ title: c.web.title, uri: c.web.uri }));
              setCurrentSources(prev => [...prev, ...newSources]);
            }

            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); 
              s.buffer = buffer; 
              s.connect(outputCtx.destination);
              s.onended = () => { 
                activeSourcesRef.current.delete(s); 
                if (activeSourcesRef.current.size === 0 && sessionRef.current) setState(AssistantState.LISTENING); 
              };
              s.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration; 
              activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) {
              setState(AssistantState.SPEAKING);
              setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            }
            if (message.serverContent?.turnComplete) {
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) {
                addTranscription('assistant', a, currentSources);
                audioUtils.playSuccessSound(outputCtx);
              } return ''; });
              setCurrentSources([]);
            }
          },
          onerror: (err) => stopSession(),
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(err.message || "Link failed."); setState(AssistantState.IDLE); }
  };

  /**
   * Fast-Path Response System
   * Delivers instantaneous text replies when the system is IDLE.
   */
  const handleSendText = async () => {
    if (!inputText.trim()) return;
    const msg = inputText.trim();
    setInputText('');
    addTranscription('user', msg);

    if (sessionRef.current) {
      setState(AssistantState.THINKING);
      sessionRef.current.sendRealtimeInput({ parts: [{ text: msg }] });
    } else {
      // FAST PATH: Direct text-to-text response while session warms up
      setState(AssistantState.THINKING);
      const apiKey = process.env.API_KEY;
      if (!apiKey) return;

      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? prefs.customPersonality : PERSONALITIES[prefs.personality];

      try {
        // Parallelized Text and Audio Generation for maximum "speed" feeling
        const [textResponse, audioResponse] = await Promise.all([
          ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Context: ${facts}. Persona: ${personalityPrompt}. Respond to this user message concisely: "${msg}"`,
            config: { maxOutputTokens: 200 }
          }),
          ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: `Respond as ${prefs.assistantName} with ${prefs.personality} personality to: "${msg}"` }] }],
            config: {
              responseModalities: [Modality.AUDIO],
              speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } }
            }
          })
        ]);

        const responseText = textResponse.text || "Neural connection established.";
        addTranscription('assistant', responseText);

        // Play the quick-reply audio
        const base64Audio = audioResponse.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (base64Audio && audioContextRef.current) {
          const { output: outputCtx } = audioContextRef.current;
          const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
          const source = outputCtx.createBufferSource();
          source.buffer = buffer;
          source.connect(outputCtx.destination);
          source.start();
        }

        // Initialize Live Session in background for the next interaction
        startSession();
      } catch (err) {
        // Fallback to normal session if fast path fails
        startSession(msg);
      }
    }
    inputRef.current?.blur();
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendText();
    }
  };

  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;

  const isMobile = device === 'mobile';
  const isTv = device === 'tv';

  return (
    <div className={`flex flex-col h-screen w-full text-white overflow-hidden font-sans transition-colors duration-1000 ${isTv ? 'text-xl' : 'text-base'}`} style={{ backgroundColor: themeData.bg }}>
      <div className={`flex-1 flex flex-col ${isMobile ? 'overflow-y-auto' : 'md:flex-row'} transition-all duration-700 ${isMemoryOpen ? 'p-0' : 'p-4 md:p-8'}`}>
        <div className={`flex-1 flex flex-col transition-all duration-700 ${!isMobile && isMemoryOpen && prefs.layout === 'right' ? 'md:mr-[340px]' : ''} ${!isMobile && isMemoryOpen && prefs.layout === 'left' ? 'md:ml-[340px]' : ''}`}>

          <header className={`flex items-center justify-between animate-fade-in relative z-50 ${isMobile ? 'mb-4' : 'mb-8'}`}>
            <div className="flex items-center gap-4 md:gap-6">
              <div className={`${isTv ? 'w-24 h-24' : isMobile ? 'w-12 h-12' : 'w-16 h-16'} rounded-[2.5rem] flex items-center justify-center shadow-2xl transition-all duration-500 border border-white/10 ${state !== AssistantState.IDLE ? `bg-${themeData.primary} rotate-12 scale-110` : 'bg-white/5'}`} style={state !== AssistantState.IDLE ? { boxShadow: `0 0 50px ${themeData.glow}` } : {}}>
                <i className={`fas ${state === AssistantState.THINKING ? 'fa-bolt animate-pulse' : isVisionActive ? 'fa-eye' : isScreenSharing ? 'fa-desktop' : 'fa-atom'} ${isTv ? 'text-5xl' : 'text-xl md:text-3xl'} text-white`}></i>
              </div>
              {!isMobile && (
                <div>
                  <h1 className={`${isTv ? 'text-5xl' : 'text-3xl'} font-black tracking-tighter bg-gradient-to-r from-${themeData.primary} via-${themeData.secondary} to-white bg-clip-text text-transparent`}>{prefs.assistantName}</h1>
                  <div className="flex items-center gap-4 mt-1">
                     <p className="text-[9px] text-gray-500 font-bold uppercase tracking-[0.4em] flex items-center gap-2">
                       <i className={`fas fa-shield-halved text-[6px] text-${themeData.primary} animate-pulse`}></i> {user.username} // Hub
                     </p>
                     <button onClick={() => setSearchEnabled(!searchEnabled)} className={`flex items-center gap-2 text-[8px] font-black uppercase tracking-widest transition-colors ${searchEnabled ? `text-${themeData.primary}` : 'text-gray-700'}`}>
                        <i className={`fas ${searchEnabled ? 'fa-globe' : 'fa-ghost'}`}></i> {searchEnabled ? 'Search Online' : 'Local Only'}
                     </button>
                  </div>
                </div>
              )}
            </div>
            <div className="flex items-center gap-2 md:gap-4">
               {!isMobile && (
                 <>
                  <button onClick={() => { setIsScreenSharing(!isScreenSharing); setIsVisionActive(false); }} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isScreenSharing ? 'bg-cyan-500 text-white' : 'bg-white/5 text-gray-400 hover:text-white'}`}><i className="fas fa-desktop text-sm"></i></button>
                  <button onClick={() => { setIsVisionActive(!isVisionActive); setIsScreenSharing(false); }} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isVisionActive ? 'bg-red-500 text-white' : 'bg-white/5 text-gray-400 hover:text-white'}`}><i className="fas fa-camera text-sm"></i></button>
                 </>
               )}
               <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isMemoryOpen ? `bg-${themeData.primary} text-white` : 'bg-white/5 text-gray-400 hover:text-white'}`}><i className="fas fa-database text-sm"></i></button>
               <button onClick={() => setIsSettingsOpen(true)} className="w-12 h-12 rounded-2xl flex items-center justify-center bg-white/5 text-gray-400 transition-colors hover:text-white"><i className="fas fa-cog text-sm"></i></button>
               <button onClick={handleLogout} className="text-gray-600 hover:text-red-400 px-2 transition-colors"><i className="fas fa-sign-out-alt"></i></button>
            </div>
          </header>

          <main className="flex-1 flex flex-col md:flex-row gap-6 min-h-0">
            <div className={`flex-1 flex flex-col min-h-0 bg-white/[0.01] ${isMobile ? 'rounded-[2rem]' : 'rounded-[3.5rem]'} border border-white/5 backdrop-blur-3xl overflow-hidden relative shadow-inner animate-fade-in`}>
               <div className={`flex-1 flex flex-col items-center justify-center z-10 ${isMobile ? 'p-4' : 'p-8'}`}>
                 {state === AssistantState.IDLE ? (
                   <div className="text-center space-y-12 group">
                     <div className="relative">
                        <div className={`absolute inset-0 bg-${themeData.primary}/20 blur-[100px] rounded-full animate-pulse-slow`}></div>
                        <div className={`${isTv ? 'w-80 h-80' : isMobile ? 'w-40 h-40' : 'w-64 h-64'} rounded-[5rem] bg-white/5 border border-white/10 flex items-center justify-center mx-auto shadow-inner relative transition-transform duration-700 group-hover:scale-105 group-hover:rotate-2`}>
                           <i className={`fas fa-microchip ${isTv ? 'text-9xl' : isMobile ? 'text-5xl' : 'text-8xl'} text-${themeData.primary} opacity-20`}></i>
                        </div>
                     </div>
                     <div className="space-y-2">
                        <h2 className={`${isTv ? 'text-7xl' : 'text-3xl md:text-5xl'} font-black mb-4 tracking-tighter uppercase opacity-20 group-hover:opacity-40 transition-opacity`}>System Standby</h2>
                        <p className="text-[10px] font-black uppercase tracking-[0.8em] text-gray-700">Neural Link v4.0.1 Ready</p>
                     </div>
                   </div>
                 ) : (
                   <div className="w-full max-w-3xl flex flex-col items-center"><VoiceVisualizer state={state} analyser={analyserRef.current || undefined} /></div>
                 )}
               </div>
               <div className={`${isTv ? 'h-[30rem]' : isMobile ? 'h-72' : 'h-[32rem]'} bg-black/50 border-t border-white/5 p-4 md:p-8 flex flex-col backdrop-blur-2xl`}>
                 <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-6 pr-4 scrollbar-thin scrollbar-thumb-white/10">
                   {transcriptions.map(e => (
                     <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'}`}>
                       <div className={`max-w-[85%] rounded-[2rem] px-6 py-4 md:px-10 md:py-6 text-sm ${e.sender === 'user' ? `bg-${themeData.primary} text-white shadow-[0_0_30px_rgba(59,130,246,0.15)]` : 'bg-white/5 text-gray-300'} border border-white/5`}>
                         <div className="flex items-center gap-3 mb-2 opacity-40">
                            <i className={`fas ${e.sender === 'user' ? 'fa-at' : 'fa-robot'} text-[10px]`}></i>
                            <span className="text-[9px] font-black uppercase tracking-[0.4em]">{e.sender} // {new Date(e.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                         </div>
                         <p className="leading-relaxed font-medium">{e.text}</p>
                         {e.sources && <GroundingSources sources={e.sources} themePrimary={themeData.primary} />}
                       </div>
                     </div>
                   ))}
                   {streamingAssistantText && (
                     <div className="flex flex-col items-start animate-fade-in">
                       <div className="max-w-[85%] rounded-[2rem] px-6 py-4 md:px-10 md:py-6 text-sm bg-white/10 text-blue-100 border border-blue-500/30 shadow-[0_0_40px_rgba(59,130,246,0.1)] relative">
                          <div className="flex items-center gap-3 mb-2">
                            <i className="fas fa-satellite-dish text-[10px] animate-pulse text-blue-400"></i>
                            <span className="text-[9px] font-black uppercase tracking-[0.4em] text-blue-400">Neural Downlink Active</span>
                          </div>
                          <p className="leading-relaxed font-medium">{streamingAssistantText}</p>
                          <span className="ml-1 inline-block w-1.5 h-4 bg-blue-500 animate-pulse align-middle"></span>
                          <GroundingSources sources={currentSources} themePrimary={themeData.primary} />
                       </div>
                     </div>
                   )}
                   {state === AssistantState.THINKING && !streamingAssistantText && (
                     <div className="flex flex-col items-start animate-fade-in opacity-50">
                        <div className="bg-white/5 rounded-full px-8 py-4 border border-white/10 flex items-center gap-4">
                           <div className="flex gap-2">
                              <div className={`w-2 h-2 bg-${themeData.primary} rounded-full animate-bounce [animation-delay:-0.3s]`}></div>
                              <div className={`w-2 h-2 bg-${themeData.primary} rounded-full animate-bounce [animation-delay:-0.15s]`}></div>
                              <div className={`w-2 h-2 bg-${themeData.primary} rounded-full animate-bounce`}></div>
                           </div>
                           <span className="text-[10px] font-black uppercase tracking-[0.6em] text-gray-500">Fast-Path Processing...</span>
                        </div>
                     </div>
                   )}
                 </div>

                 <div className="mt-8 flex gap-4 animate-slide-up relative group/matrix">
                    <div className="flex-1 relative">
                       <input 
                         ref={inputRef}
                         type="text" 
                         value={inputText}
                         onChange={(e) => setInputText(e.target.value)}
                         onKeyDown={handleKeyPress}
                         placeholder={`Neural Uplink: Command ${prefs.assistantName}...`}
                         className={`w-full bg-white/5 border border-white/10 rounded-[1.5rem] py-5 px-8 text-sm focus:outline-none focus:border-${themeData.primary}/40 transition-all font-medium placeholder:text-gray-700 shadow-inner group-focus-within/matrix:shadow-[0_0_30px_rgba(255,255,255,0.01)]`}
                       />
                       <div className={`absolute right-6 top-1/2 -translate-y-1/2 text-${themeData.primary} opacity-20 transition-opacity group-focus-within/matrix:opacity-100`}><i className="fas fa-terminal text-xs"></i></div>
                    </div>
                    <button 
                      onClick={handleSendText}
                      disabled={!inputText.trim()}
                      className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center transition-all ${inputText.trim() ? `bg-${themeData.primary} text-white shadow-lg scale-105 active:scale-95` : 'bg-white/5 text-gray-800 cursor-not-allowed'}`}
                      style={inputText.trim() ? { boxShadow: `0 0 30px ${themeData.glow}` } : {}}
                    >
                      <i className={`fas ${inputText.trim() ? 'fa-paper-plane' : 'fa-bolt'} text-lg`}></i>
                    </button>
                 </div>
               </div>
            </div>
            {(!isMobile && (isVisionActive || isScreenSharing)) && (
              <div className="w-full md:w-[400px] flex flex-col gap-6 animate-slide-in-right">
                {isVisionActive && <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />}
                {isScreenSharing && screenStream && <ScreenShareMode isActive={isScreenSharing} stream={screenStream} onFrame={(b) => currentFrameRef.current = b} onStop={() => { setIsScreenSharing(false); setScreenStream(null); }} />}

                <div className="flex-1 bg-white/[0.02] border border-white/5 rounded-[3rem] p-8 flex flex-col justify-between backdrop-blur-3xl shadow-2xl">
                   <div className="space-y-6">
                      <h4 className="text-[10px] font-black uppercase tracking-[0.4em] text-gray-600 border-b border-white/5 pb-4">Internal Systems</h4>
                      <div className="space-y-6">
                         {[
                           { label: 'Neural Fidelity', val: '99.2%', icon: 'fa-brain' },
                           { label: 'Fast-Path Latency', val: '12ms', icon: 'fa-bolt-lightning' },
                           { label: 'Sync Status', val: 'Optimized', icon: 'fa-circle-check' }
                         ].map(s => (
                           <div key={s.label} className="flex items-center justify-between group/stat">
                              <div className="flex items-center gap-4 text-gray-500 group-hover/stat:text-white transition-colors">
                                <i className={`fas ${s.icon} text-xs`}></i>
                                <span className="text-[10px] font-bold uppercase tracking-widest">{s.label}</span>
                              </div>
                              <span className={`text-[10px] font-black text-${themeData.primary}`}>{s.val}</span>
                           </div>
                         ))}
                      </div>
                   </div>
                   <div className="pt-6 border-t border-white/5">
                      <div className="h-1 w-full bg-white/5 rounded-full overflow-hidden">
                         <div className={`h-full bg-${themeData.primary} animate-pulse-slow`} style={{ width: '92%' }}></div>
                      </div>
                      <p className="text-[8px] text-gray-700 mt-3 text-center uppercase tracking-widest">Dual-Channel Response Active</p>
                   </div>
                </div>
              </div>
            )}
          </main>

          <div className={`flex items-center justify-center ${isMobile ? 'my-6' : 'mt-12'}`}>
             <button onClick={state === AssistantState.IDLE ? () => startSession() : stopSession} className={`${isTv ? 'py-12 px-40 text-3xl' : isMobile ? 'py-5 px-14 text-xs' : 'py-8 px-24 text-sm'} ${state === AssistantState.IDLE ? 'bg-white text-black hover:bg-blue-50' : 'bg-red-500/10 border-red-500/20 text-white hover:bg-red-500/20'} font-black rounded-[3rem] transition-all flex items-center gap-8 shadow-2xl hover:scale-105 active:scale-95 group`}>
                <i className={`fas ${state === AssistantState.IDLE ? 'fa-link' : 'fa-unlink'} transition-transform group-hover:rotate-12`}></i>
                <span className="tracking-[0.4em] uppercase italic">{state === AssistantState.IDLE ? `Establish ${prefs.assistantName} Link` : 'Terminate Connection'}</span>
             </button>
          </div>
        </div>
      </div>

      <aside className={`fixed top-0 bottom-0 ${isMobile ? 'w-full' : 'w-[340px]'} z-[60] transition-transform duration-700 transform bg-black/98 border-white/5 shadow-2xl backdrop-blur-2xl ${prefs.layout === 'right' || isMobile ? 'right-0 border-l' : 'left-0 border-r'} ${isMemoryOpen ? 'translate-x-0' : (prefs.layout === 'right' || isMobile) ? 'translate-x-full' : '-translate-x-full'}`}>
         <div className="flex flex-col h-full pt-20">
            <button onClick={() => setIsMemoryOpen(false)} className={`absolute top-12 ${isMobile || prefs.layout === 'right' ? 'right-10' : 'left-10'} text-gray-700 hover:text-white transition-colors`}><i className="fas fa-times text-2xl"></i></button>
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
         </div>
      </aside>

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 md:p-6 bg-black/98 backdrop-blur-2xl animate-fade-in overflow-y-auto">
          <div className={`bg-[#02020a] border border-white/10 ${isMobile ? 'rounded-[2.5rem]' : 'rounded-[5rem]'} w-full max-w-5xl p-8 md:p-16 shadow-3xl relative my-auto`}>
            <button onClick={() => setIsSettingsOpen(false)} className="absolute top-10 right-10 text-gray-700 hover:text-white transition-colors"><i className="fas fa-times text-4xl"></i></button>
            <header className="mb-10 md:mb-16"><h2 className={`${isTv ? 'text-7xl' : 'text-4xl md:text-6xl'} font-black tracking-tighter uppercase mb-2`}>Neural Config</h2></header>
            <div className={`grid grid-cols-1 ${!isMobile ? 'lg:grid-cols-2' : ''} gap-10 md:gap-20`}>
              <section className="space-y-8 md:space-y-12">
                <div className="space-y-6">
                   <label className="text-[11px] font-black text-gray-500 uppercase tracking-[0.4em]">Persona Matrix</label>
                   <div className="grid grid-cols-2 gap-3">
                     {(Object.keys(PERSONALITIES) as PersonalityType[]).map(p => (
                       <button key={p} onClick={() => setPrefs(prev => ({ ...prev, personality: p }))} className={`px-4 py-5 rounded-2xl border-2 transition-all font-black text-[10px] uppercase tracking-widest ${prefs.personality === p ? `bg-${themeData.primary}/10 border-${themeData.primary} text-white` : 'bg-white/5 border-white/5 text-gray-700 hover:border-white/20'}`}>{p}</button>
                     ))}
                   </div>
                </div>
                <div className="space-y-6">
                  <label className="text-[11px] font-black text-gray-500 uppercase tracking-[0.4em]">Base Identity</label>
                  <input type="text" value={prefs.assistantName} onChange={(e) => setPrefs(p => ({ ...p, assistantName: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-2xl py-5 px-8 font-black focus:outline-none focus:border-white/30 transition-all text-xl" />
                </div>
              </section>
              {!isMobile && (
                <section className="bg-white/[0.02] border border-white/5 rounded-[4rem] p-12 space-y-10 flex flex-col justify-center text-center group">
                  <i className={`fas fa-wave-square text-8xl text-${themeData.primary} group-hover:scale-110 transition-transform duration-700`}></i>
                  <div className="space-y-2">
                    <h3 className="text-2xl font-black uppercase tracking-widest">Cerebro Core v4.2</h3>
                    <p className="text-[9px] text-gray-700 uppercase tracking-[0.6em]">Fast-Path Enabled</p>
                  </div>
                </section>
              )}
            </div>
            <footer className="mt-12 md:mt-16 flex flex-col md:flex-row items-center justify-between gap-10">
              <div className="flex items-center gap-6">
                {(Object.keys(THEMES) as UITheme[]).map(t => ( <button key={t} onClick={() => setPrefs(p => ({ ...p, theme: t }))} className={`w-12 h-12 rounded-2xl border-2 transition-all ${prefs.theme === t ? 'border-white scale-125 z-10' : 'border-white/5 hover:border-white/20'}`} style={{ backgroundColor: THEMES[t].bg, boxShadow: prefs.theme === t ? `0 0 30px ${THEMES[t].glow}` : 'none' }} /> ))}
              </div>
              <button onClick={() => setIsSettingsOpen(false)} className="w-full md:w-auto md:flex-1 bg-white text-black font-black py-7 px-16 rounded-[2.5rem] text-sm tracking-[0.6em] uppercase shadow-3xl hover:bg-blue-50 transition-colors">Commit Synthesis</button>
            </footer>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser, UITheme, PersonalityType, UserPreferences, DeviceType } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';
import ScreenShareMode from './components/ScreenShareMode';
import GroundingSources from './components/GroundingSources';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const THEMES: Record<UITheme, { primary: string; secondary: string; glow: string; bg: string }> = {
  cosmic: { primary: 'blue-500', secondary: 'indigo-500', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: 'emerald-500', secondary: 'teal-500', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: 'rose-500', secondary: 'orange-500', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: 'slate-400', secondary: 'zinc-500', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: VOICES[0].id,
  assistantName: 'Nova'
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [device, setDevice] = useState<DeviceType>('desktop');
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [currentSources, setCurrentSources] = useState<GroundingSource[]>([]);
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [inputText, setInputText] = useState('');
  const [searchEnabled, setSearchEnabled] = useState(true);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const detectDevice = useCallback(() => {
    const w = window.innerWidth;
    const h = window.innerHeight;
    const ua = navigator.userAgent.toLowerCase();

    // Improved detection logic for better default sizing
    if (w <= 300 || (ua.includes('watch') && !ua.includes('tv'))) {
      setDevice('wear');
    } else if (ua.includes('android') && w > h && w >= 800 && w <= 1280) {
      setDevice('auto');
    } else if (ua.includes('tv') || ua.includes('viera') || ua.includes('smarttv') || (w >= 1920 && h >= 1080)) {
      setDevice('tv');
    } else if (w < 768 || (w < 1024 && h > w)) {
      setDevice('mobile');
    } else {
      setDevice('desktop');
    }
  }, []);

  useEffect(() => {
    detectDevice();
    window.addEventListener('resize', detectDevice);
    window.addEventListener('orientationchange', detectDevice);
    return () => {
      window.removeEventListener('resize', detectDevice);
      window.removeEventListener('orientationchange', detectDevice);
    };
  }, [detectDevice]);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
      setUser({ username: sessionUser, preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS });
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      setMemories(JSON.parse(localStorage.getItem(`nova_${user.username}_memories`) || '[]'));
      setTranscriptions(JSON.parse(localStorage.getItem(`nova_${user.username}_logs`) || '[]'));
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme], [prefs.theme]);

  const addTranscription = useCallback((sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  }, []);

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
    setCurrentSources([]);
  }, [screenStream]);

  const handleLogout = useCallback(() => {
    stopSession();
    setUser(null);
    sessionStorage.removeItem('nova_session_user');
  }, [stopSession]);

  const startSession = async (initialText?: string) => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      audioUtils.playLinkSound(outputCtx);

      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? prefs.customPersonality : PERSONALITIES[prefs.personality];

      const tools: any[] = [{ functionDeclarations: [saveKnowledgeTool] }];
      if (searchEnabled) tools.push({ googleSearch: {} });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. User: ${user?.username}. Memories: ${facts}. Personality: ${personalityPrompt}. Device: ${device}. SEARCH_ENABLED: ${searchEnabled}. Response Protocol: Real-time, highly intelligent, emotive.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = audioUtils.createPcmBlob(inputData);
              sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: pcmBlob }); });
              if (currentFrameRef.current) {
                const frame = currentFrameRef.current;
                currentFrameRef.current = null;
                sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } }); });
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);

            if (initialText) {
              sessionPromise.then(s => s.sendRealtimeInput({ parts: [{ text: initialText }] }));
            }
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = (fc.args as any).fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => { if (sessionRef.current) s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Memory saved." } } }); });
                }
              }
            }

            const grounding = message.serverContent?.modelTurn?.parts?.find(p => (p as any).groundingMetadata)?.groundingMetadata;
            if (grounding?.groundingChunks) {
              const newSources = grounding.groundingChunks
                .filter((c: any) => c.web)
                .map((c: any) => ({ title: c.web.title, uri: c.web.uri }));
              setCurrentSources(prev => [...prev, ...newSources]);
            }

            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); 
              s.buffer = buffer; 
              s.connect(outputCtx.destination);
              s.onended = () => { 
                activeSourcesRef.current.delete(s); 
                if (activeSourcesRef.current.size === 0 && sessionRef.current) setState(AssistantState.LISTENING); 
              };
              s.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration; 
              activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) {
              setState(AssistantState.SPEAKING);
              setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            }
            if (message.serverContent?.turnComplete) {
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) {
                addTranscription('assistant', a, currentSources);
                audioUtils.playSuccessSound(outputCtx);
              } return ''; });
              setCurrentSources([]);
            }
          },
          onerror: (err) => stopSession(),
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(err.message || "Link failed."); setState(AssistantState.IDLE); }
  };

  const handleSendText = async () => {
    if (!inputText.trim()) return;
    const msg = inputText.trim();
    setInputText('');
    addTranscription('user', msg);

    if (sessionRef.current) {
      setState(AssistantState.THINKING);
      sessionRef.current.sendRealtimeInput({ parts: [{ text: msg }] });
    } else {
      setState(AssistantState.THINKING);
      const apiKey = process.env.API_KEY;
      if (!apiKey) return;
      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? prefs.customPersonality : PERSONALITIES[prefs.personality];

      try {
        const [textResponse, audioResponse] = await Promise.all([
          ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Context: ${facts}. Persona: ${personalityPrompt}. Respond concisely: "${msg}"`,
            config: { maxOutputTokens: 200 }
          }),
          ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: `Respond as ${prefs.assistantName} with ${prefs.personality} personality to: "${msg}"` }] }],
            config: {
              responseModalities: [Modality.AUDIO],
              speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } }
            }
          })
        ]);

        const responseText = textResponse.text || "Connection stable.";
        addTranscription('assistant', responseText);

        const base64Audio = audioResponse.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (base64Audio && audioContextRef.current) {
          const { output: outputCtx } = audioContextRef.current;
          const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
          const source = outputCtx.createBufferSource();
          source.buffer = buffer;
          source.connect(outputCtx.destination);
          source.start();
        }
        startSession();
      } catch (err) { startSession(msg); }
    }
    inputRef.current?.blur();
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendText(); }
  };

  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;

  const isMobile = device === 'mobile';
  const isTv = device === 'tv';
  const isWear = device === 'wear';
  const isAuto = device === 'auto';

  // ---------------------------------------------------------------------------------
  // VIEW RENDERER
  // ---------------------------------------------------------------------------------

  // WEAR OS
  if (isWear) {
    return (
      <div className="wear-screen">
        <div className={`w-full h-full flex flex-col items-center justify-center p-6 border-4 rounded-full transition-colors duration-1000 border-${themeData.primary}/30 relative`}>
          <div className="text-[10px] font-black uppercase tracking-widest text-gray-500 absolute top-8">{prefs.assistantName}</div>
          <div className="flex-1 flex flex-col items-center justify-center scale-75">
             <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
          </div>
          <div className="absolute bottom-10 flex gap-2">
            <button onClick={state === AssistantState.IDLE ? () => startSession() : stopSession} className={`w-12 h-12 rounded-full flex items-center justify-center ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500 text-white shadow-[0_0_20px_rgba(239,68,68,0.5)]'}`}>
              <i className={`fas ${state === AssistantState.IDLE ? 'fa-play' : 'fa-stop'} text-xs`}></i>
            </button>
          </div>
        </div>
      </div>
    );
  }

  // ANDROID AUTO
  if (isAuto) {
    return (
      <div className="h-full w-full bg-black flex flex-col p-8 font-sans overflow-hidden">
        <header className="flex items-center justify-between mb-8">
          <div className="flex items-center gap-6">
            <i className={`fas fa-car-side text-4xl text-${themeData.primary}`}></i>
            <h1 className="text-4xl font-black uppercase tracking-tighter italic">Drive Assist // {prefs.assistantName}</h1>
          </div>
          <div className="text-xl font-bold opacity-30">{new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</div>
        </header>
        <main className="flex-1 flex gap-10 items-center">
           <div className="w-1/3 flex justify-center">
              <div className={`w-64 h-64 rounded-full border-[16px] border-${themeData.primary}/10 flex items-center justify-center bg-black`}>
                <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
              </div>
           </div>
           <div className="flex-1 bg-white/5 rounded-[3rem] p-10 h-full flex flex-col justify-center border border-white/10 shadow-2xl">
              <p className="text-4xl font-bold leading-tight">
                {streamingAssistantText || (transcriptions.length > 0 ? transcriptions[transcriptions.length - 1].text : `Neural link established. Focused for road.`)}
              </p>
           </div>
        </main>
        <footer className="mt-8">
           <button onClick={state === AssistantState.IDLE ? () => startSession() : stopSession} className={`w-full py-12 rounded-[3rem] text-3xl font-black uppercase tracking-[0.4em] flex items-center justify-center gap-8 ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-600 text-white shadow-3xl'}`}>
             <i className={`fas ${state === AssistantState.IDLE ? 'fa-play' : 'fa-stop'}`}></i>
             {state === AssistantState.IDLE ? 'Enable Assistant' : 'End Connection'}
           </button>
        </footer>
      </div>
    );
  }

  // DEFAULT (Mobile, Desktop, TV)
  return (
    <div className={`flex flex-col h-full w-full text-white overflow-hidden font-sans transition-colors duration-1000 ${isTv ? 'scale-[1.15] origin-top' : ''}`} style={{ backgroundColor: themeData.bg }}>
      <div className={`flex-1 flex flex-col min-h-0 ${isMobile ? 'p-3' : 'md:flex-row p-4 lg:p-8'} layout-transition`}>
        <div className={`flex-1 flex flex-col min-h-0 relative ${!isMobile && isMemoryOpen && prefs.layout === 'right' ? 'md:mr-[340px]' : ''} ${!isMobile && isMemoryOpen && prefs.layout === 'left' ? 'md:ml-[340px]' : ''} layout-transition`}>

          <header className={`flex items-center justify-between animate-fade-in relative z-50 ${isMobile ? 'mb-4' : 'mb-8'}`}>
            <div className="flex items-center gap-3 lg:gap-6">
              <div className={`${isTv ? 'w-24 h-24' : isMobile ? 'w-10 h-10' : 'w-14 h-14 lg:w-16 lg:h-16'} rounded-[1.5rem] lg:rounded-[2.5rem] flex items-center justify-center shadow-2xl transition-all duration-500 border border-white/10 ${state !== AssistantState.IDLE ? `bg-${themeData.primary} rotate-12 scale-110` : 'bg-white/5'}`} style={state !== AssistantState.IDLE ? { boxShadow: `0 0 50px ${themeData.glow}` } : {}}>
                <i className={`fas ${state === AssistantState.THINKING ? 'fa-bolt animate-pulse' : isVisionActive ? 'fa-eye' : isScreenSharing ? 'fa-desktop' : 'fa-atom'} ${isTv ? 'text-5xl' : isMobile ? 'text-lg' : 'text-2xl lg:text-3xl'} text-white`}></i>
              </div>
              {!isMobile && (
                <div>
                  <h1 className={`${isTv ? 'text-5xl' : 'text-2xl lg:text-3xl'} font-black tracking-tighter bg-gradient-to-r from-${themeData.primary} via-${themeData.secondary} to-white bg-clip-text text-transparent`}>{prefs.assistantName}</h1>
                  <div className="flex items-center gap-4 mt-1">
                     <p className="text-[9px] text-gray-500 font-bold uppercase tracking-[0.4em] flex items-center gap-2">
