      <aside className={`fixed top-0 bottom-0 ${isMobile ? 'w-full' : 'w-[340px]'} z-[60] transition-transform duration-700 transform bg-black/98 backdrop-blur-2xl ${prefs.layout === 'right' || isMobile ? 'right-0 border-l' : 'left-0 border-r'} border-white/5 ${isMemoryOpen ? 'translate-x-0' : (prefs.layout === 'right' || isMobile) ? 'translate-x-full' : '-translate-x-full'}`}>
         <div className="flex flex-col h-full pt-20">
            <button onClick={() => setIsMemoryOpen(false)} className={`absolute top-10 ${isMobile || prefs.layout === 'right' ? 'right-10' : 'left-10'} text-gray-700 hover:text-white transition-colors`}><i className="fas fa-times text-2xl"></i></button>
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
         </div>
      </aside>

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/98 backdrop-blur-2xl animate-fade-in overflow-y-auto">
          <div className={`bg-[#02020a] border border-white/10 ${isMobile ? 'rounded-[2rem] p-6' : 'rounded-[4rem] p-12 lg:p-16'} w-full max-w-5xl shadow-3xl relative my-auto`}>
            <button onClick={() => setIsSettingsOpen(false)} className="absolute top-8 right-8 text-gray-700 hover:text-white transition-colors"><i className="fas fa-times text-3xl"></i></button>
            <header className="mb-8 lg:mb-16"><h2 className="text-3xl lg:text-5xl font-black tracking-tighter uppercase">Configuration</h2></header>
            <div className={`grid grid-cols-1 ${!isMobile ? 'lg:grid-cols-2' : ''} gap-8 lg:gap-20`}>
              <section className="space-y-6 lg:space-y-12">
                <div className="space-y-4">
                   <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Persona</label>
                   <div className="grid grid-cols-2 gap-2">
                     {(Object.keys(PERSONALITIES) as PersonalityType[]).map(p => (
                       <button key={p} onClick={() => setPrefs(prev => ({ ...prev, personality: p }))} className={`px-4 py-3 rounded-xl border-2 transition-all font-black text-[9px] uppercase tracking-widest ${prefs.personality === p ? `bg-${themeData.primary}/10 border-${themeData.primary} text-white` : 'bg-white/5 border-white/5 text-gray-700 hover:border-white/20'}`}>{p}</button>
                     ))}
                   </div>
                </div>
                <div className="space-y-4">
                  <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Name</label>
                  <input type="text" value={prefs.assistantName} onChange={(e) => setPrefs(p => ({ ...p, assistantName: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-xl py-4 px-6 font-black focus:outline-none text-lg" />
                </div>
              </section>
              {!isMobile && (
                <section className="bg-white/[0.02] border border-white/5 rounded-[3rem] p-10 space-y-8 flex flex-col justify-center text-center group">
                  <i className={`fas fa-wave-square text-7xl text-${themeData.primary} group-hover:scale-110 transition-transform duration-500`}></i>
                  <h3 className="text-xl font-black uppercase tracking-widest opacity-40">Core v4.2</h3>
                </section>
              )}
            </div>
            <footer className="mt-8 lg:mt-16 flex flex-col md:flex-row items-center justify-between gap-8">
              <div className="flex items-center gap-4">
                {(Object.keys(THEMES) as UITheme[]).map(t => ( <button key={t} onClick={() => setPrefs(p => ({ ...p, theme: t }))} className={`w-10 h-10 rounded-xl border-2 transition-all ${prefs.theme === t ? 'border-white scale-125 z-10' : 'border-white/5'}`} style={{ backgroundColor: THEMES[t].bg, boxShadow: prefs.theme === t ? `0 0 20px ${THEMES[t].glow}` : 'none' }} /> ))}
              </div>
              <button onClick={() => setIsSettingsOpen(false)} className="w-full md:w-auto md:flex-1 bg-white text-black font-black py-5 lg:py-7 px-12 lg:px-16 rounded-full text-xs lg:text-sm tracking-widest uppercase shadow-3xl hover:bg-blue-50">Commit Settings</button>
            </footer>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser, UITheme, PersonalityType, UserPreferences, DeviceType } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';
import ScreenShareMode from './components/ScreenShareMode';
import GroundingSources from './components/GroundingSources';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const THEMES: Record<UITheme, { primary: string; secondary: string; glow: string; bg: string }> = {
  cosmic: { primary: 'blue-500', secondary: 'indigo-500', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: 'emerald-500', secondary: 'teal-500', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: 'rose-500', secondary: 'orange-500', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: 'slate-400', secondary: 'zinc-500', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: VOICES[0].id,
  assistantName: 'Nova'
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [device, setDevice] = useState<DeviceType>('desktop');
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [currentSources, setCurrentSources] = useState<GroundingSource[]>([]);
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [inputText, setInputText] = useState('');
  const [searchEnabled, setSearchEnabled] = useState(true);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const detectDevice = useCallback(() => {
    const w = window.innerWidth;
    const h = window.innerHeight;
    const ua = navigator.userAgent.toLowerCase();

    if (w <= 300 || (ua.includes('watch') && !ua.includes('tv'))) {
      setDevice('wear');
    } else if (ua.includes('android') && w > h && w >= 800 && w <= 1280) {
      setDevice('auto');
    } else if (ua.includes('tv') || ua.includes('viera') || ua.includes('smarttv') || (w >= 1920 && h >= 1080)) {
      setDevice('tv');
    } else if (w < 768 || (w < 1024 && h > w)) {
      setDevice('mobile');
    } else {
      setDevice('desktop');
    }
  }, []);

  useEffect(() => {
    detectDevice();
    window.addEventListener('resize', detectDevice);
    window.addEventListener('orientationchange', detectDevice);
    return () => {
      window.removeEventListener('resize', detectDevice);
      window.removeEventListener('orientationchange', detectDevice);
    };
  }, [detectDevice]);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
      setUser({ username: sessionUser, preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS });
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      setMemories(JSON.parse(localStorage.getItem(`nova_${user.username}_memories`) || '[]'));
      setTranscriptions(JSON.parse(localStorage.getItem(`nova_${user.username}_logs`) || '[]'));
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme], [prefs.theme]);

  const scrollToTop = () => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const scrollToBottom = () => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  };

  const addTranscription = useCallback((sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  }, []);

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
    setCurrentSources([]);
  }, [screenStream]);

  const handleLogout = useCallback(() => {
    stopSession();
    setUser(null);
    sessionStorage.removeItem('nova_session_user');
  }, [stopSession]);

  const startSession = async (initialText?: string) => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      audioUtils.playLinkSound(outputCtx);

      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? prefs.customPersonality : PERSONALITIES[prefs.personality];

      const tools: any[] = [{ functionDeclarations: [saveKnowledgeTool] }];
      if (searchEnabled) tools.push({ googleSearch: {} });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. User: ${user?.username}. Memories: ${facts}. Personality: ${personalityPrompt}. Device: ${device}. SEARCH_ENABLED: ${searchEnabled}. Response Protocol: Real-time, highly intelligent, emotive.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = audioUtils.createPcmBlob(inputData);
              sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: pcmBlob }); });
              if (currentFrameRef.current) {
                const frame = currentFrameRef.current;
                currentFrameRef.current = null;
                sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } }); });
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);

            if (initialText) {
              sessionPromise.then(s => s.sendRealtimeInput({ parts: [{ text: initialText }] }));
            }
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = (fc.args as any).fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => { if (sessionRef.current) s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Memory saved." } } }); });
                }
              }
            }

            const grounding = message.serverContent?.modelTurn?.parts?.find(p => (p as any).groundingMetadata)?.groundingMetadata;
            if (grounding?.groundingChunks) {
              const newSources = grounding.groundingChunks
                .filter((c: any) => c.web)
                .map((c: any) => ({ title: c.web.title, uri: c.web.uri }));
              setCurrentSources(prev => [...prev, ...newSources]);
            }

            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); 
              s.buffer = buffer; 
              s.connect(outputCtx.destination);
              s.onended = () => { 
                activeSourcesRef.current.delete(s); 
                if (activeSourcesRef.current.size === 0 && sessionRef.current) setState(AssistantState.LISTENING); 
              };
              s.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration; 
              activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) {
              setState(AssistantState.SPEAKING);
              setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            }
            if (message.serverContent?.turnComplete) {
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) {
                addTranscription('assistant', a, currentSources);
                audioUtils.playSuccessSound(outputCtx);
              } return ''; });
              setCurrentSources([]);
            }
          },
          onerror: (err) => stopSession(),
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(err.message || "Link failed."); setState(AssistantState.IDLE); }
  };

  const handleSendText = async () => {
    if (!inputText.trim()) return;
    const msg = inputText.trim();
    setInputText('');
    addTranscription('user', msg);

    if (sessionRef.current) {
      setState(AssistantState.THINKING);
      sessionRef.current.sendRealtimeInput({ parts: [{ text: msg }] });
    } else {
      setState(AssistantState.THINKING);
      const apiKey = process.env.API_KEY;
      if (!apiKey) return;
      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? prefs.customPersonality : PERSONALITIES[prefs.personality];

      try {
        const [textResponse, audioResponse] = await Promise.all([
          ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Context: ${facts}. Persona: ${personalityPrompt}. Respond concisely: "${msg}"`,
            config: { maxOutputTokens: 200 }
          }),
          ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: `Respond as ${prefs.assistantName} with ${prefs.personality} personality to: "${msg}"` }] }],
            config: {
              responseModalities: [Modality.AUDIO],
              speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } }
            }
          })
        ]);

        const responseText = textResponse.text || "Connection stable.";
        addTranscription('assistant', responseText);

        const base64Audio = audioResponse.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (base64Audio && audioContextRef.current) {
          const { output: outputCtx } = audioContextRef.current;
          const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
          const source = outputCtx.createBufferSource();
          source.buffer = buffer;
          source.connect(outputCtx.destination);
          source.start();
        }
        startSession();
      } catch (err) { startSession(msg); }
    }
    inputRef.current?.blur();
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendText(); }
  };

  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;

  const isMobile = device === 'mobile';
  const isTv = device === 'tv';
  const isWear = device === 'wear';
  const isAuto = device === 'auto';

  // ---------------------------------------------------------------------------------
  // VIEW RENDERER
  // ---------------------------------------------------------------------------------

  // WEAR OS
  if (isWear) {
    return (
      <div className="wear-screen">
        <div className={`w-full h-full flex flex-col items-center justify-center p-6 border-4 rounded-full transition-colors duration-1000 border-${themeData.primary}/30 relative`}>
          <div className="text-[10px] font-black uppercase tracking-widest text-gray-500 absolute top-8">{prefs.assistantName}</div>
          <div className="flex-1 flex flex-col items-center justify-center scale-75">
             <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
          </div>
          <div className="absolute bottom-10 flex gap-2">
            <button onClick={state === AssistantState.IDLE ? () => startSession() : stopSession} className={`w-12 h-12 rounded-full flex items-center justify-center ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500 text-white shadow-[0_0_20px_rgba(239,68,68,0.5)]'}`}>
              <i className={`fas ${state === AssistantState.IDLE ? 'fa-play' : 'fa-stop'} text-xs`}></i>
            </button>
          </div>
        </div>
      </div>
    );
  }

  // ANDROID AUTO
  if (isAuto) {
    return (
      <div className="h-full w-full bg-black flex flex-col p-8 font-sans overflow-hidden">
        <header className="flex items-center justify-between mb-8">
          <div className="flex items-center gap-6">
            <i className={`fas fa-car-side text-4xl text-${themeData.primary}`}></i>
            <h1 className="text-4xl font-black uppercase tracking-tighter italic">Drive Assist // {prefs.assistantName}</h1>
          </div>
          <div className="text-xl font-bold opacity-30">{new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</div>
        </header>
        <main className="flex-1 flex gap-10 items-center">
           <div className="w-1/3 flex justify-center">
              <div className={`w-64 h-64 rounded-full border-[16px] border-${themeData.primary}/10 flex items-center justify-center bg-black`}>
                <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
              </div>
           </div>
           <div className="flex-1 bg-white/5 rounded-[3rem] p-10 h-full flex flex-col justify-center border border-white/10 shadow-2xl">
              <p className="text-4xl font-bold leading-tight">
                {streamingAssistantText || (transcriptions.length > 0 ? transcriptions[transcriptions.length - 1].text : `Neural link established. Focused for road.`)}
              </p>
           </div>
        </main>
        <footer className="mt-8">
           <button onClick={state === AssistantState.IDLE ? () => startSession() : stopSession} className={`w-full py-12 rounded-[3rem] text-3xl font-black uppercase tracking-[0.4em] flex items-center justify-center gap-8 ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-600 text-white shadow-3xl'}`}>
             <i className={`fas ${state === AssistantState.IDLE ? 'fa-play' : 'fa-stop'}`}></i>
             {state === AssistantState.IDLE ? 'Enable Assistant' : 'End Connection'}
           </button>
        </footer>
      </div>
    );
  }

  // DEFAULT (Mobile, Desktop, TV)
  return (
    <div className={`flex flex-col h-full w-full text-white overflow-hidden font-sans transition-colors duration-1000 ${isTv ? 'scale-[1.15] origin-top' : ''}`} style={{ backgroundColor: themeData.bg }}>
      <div className={`flex-1 flex flex-col min-h-0 ${isMobile ? 'p-3' : 'md:flex-row p-4 lg:p-8'} layout-transition`}>
        <div className={`flex-1 flex flex-col min-h-0 relative ${!isMobile && isMemoryOpen && prefs.layout === 'right' ? 'md:mr-[340px]' : ''} ${!isMobile && isMemoryOpen && prefs.layout === 'left' ? 'md:ml-[340px]' : ''} layout-transition`}>

          <header className={`flex items-center justify-between animate-fade-in relative z-50 ${isMobile ? 'mb-4' : 'mb-8'}`}>
            <div className="flex items-center gap-3 lg:gap-6">
              <div className={`${isTv ? 'w-24 h-24' : isMobile ? 'w-10 h-10' : 'w-14 h-14 lg:w-16 lg:h-16'} rounded-[1.5rem] lg:rounded-[2.5rem] flex items-center justify-center shadow-2xl transition-all duration-500 border border-white/10 ${state !== AssistantState.IDLE ? `bg-${themeData.primary} rotate-12 scale-110` : 'bg-white/5'}`} style={state !== AssistantState.IDLE ? { boxShadow: `0 0 50px ${themeData.glow}` } : {}}>
                <i className={`fas ${state === AssistantState.THINKING ? 'fa-bolt animate-pulse' : isVisionActive ? 'fa-eye' : isScreenSharing ? 'fa-desktop' : 'fa-atom'} ${isTv ? 'text-5xl' : isMobile ? 'text-lg' : 'text-2xl lg:text-3xl'} text-white`}></i>
              </div>
              {!isMobile && (
                <div>
                  <h1 className={`${isTv ? 'text-5xl' : 'text-2xl lg:text-3xl'} font-black tracking-tighter bg-gradient-to-r from-${themeData.primary} via-${themeData.secondary} to-white bg-clip-text text-transparent`}>{prefs.assistantName}</h1>
                  <div className="flex items-center gap-4 mt-1">
                     <p className="text-[9px] text-gray-500 font-bold uppercase tracking-[0.4em] flex items-center gap-2">
                       <i className={`fas fa-shield-halved text-[6px] text-${themeData.primary} animate-pulse`}></i> {user.username}
                     </p>
                  </div>
                </div>
              )}
            </div>
            <div className="flex items-center gap-2 lg:gap-4">
               {!isMobile && (
                 <>
                  <button onClick={() => { setIsScreenSharing(!isScreenSharing); setIsVisionActive(false); }} className={`w-10 h-10 lg:w-12 lg:h-12 rounded-2xl flex items-center justify-center transition-all ${isScreenSharing ? 'bg-cyan-500 text-white' : 'bg-white/5 text-gray-400 hover:text-white'}`}><i className="fas fa-desktop text-sm"></i></button>
                  <button onClick={() => { setIsVisionActive(!isVisionActive); setIsScreenSharing(false); }} className={`w-10 h-10 lg:w-12 lg:h-12 rounded-2xl flex items-center justify-center transition-all ${isVisionActive ? 'bg-red-500 text-white' : 'bg-white/5 text-gray-400 hover:text-white'}`}><i className="fas fa-camera text-sm"></i></button>
                 </>
               )}
               <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-10 h-10 lg:w-12 lg:h-12 rounded-2xl flex items-center justify-center transition-all ${isMemoryOpen ? `bg-${themeData.primary} text-white` : 'bg-white/5 text-gray-400 hover:text-white'}`}><i className="fas fa-database text-sm"></i></button>
               <button onClick={() => setIsSettingsOpen(true)} className="w-10 h-10 lg:w-12 lg:h-12 rounded-2xl flex items-center justify-center bg-white/5 text-gray-400 transition-colors hover:text-white"><i className="fas fa-cog text-sm"></i></button>
               <button onClick={handleLogout} className="text-gray-600 hover:text-red-400 px-2 transition-colors"><i className="fas fa-sign-out-alt"></i></button>
            </div>
          </header>

          <main className="flex-1 flex flex-col md:flex-row gap-4 lg:gap-6 min-h-0">
            <div className={`flex-1 flex flex-col min-h-0 bg-white/[0.01] ${isMobile ? 'rounded-[2rem]' : 'rounded-[3rem]'} border border-white/5 backdrop-blur-3xl overflow-hidden relative shadow-inner animate-fade-in`}>
               <div className={`flex-1 flex flex-col items-center justify-center z-10 p-4 lg:p-8`}>
                 {state === AssistantState.IDLE ? (
                   <div className="text-center space-y-6 lg:space-y-12 group">
                     <div className="relative">
                        <div className={`absolute inset-0 bg-${themeData.primary}/20 blur-[100px] rounded-full animate-pulse-slow`}></div>
                        <div className={`${isTv ? 'w-80 h-80' : isMobile ? 'w-32 h-32' : 'w-48 h-48 lg:w-64 lg:h-64'} rounded-[3rem] lg:rounded-[5rem] bg-white/5 border border-white/10 flex items-center justify-center mx-auto shadow-inner relative transition-transform duration-700 group-hover:scale-105`}>
                           <i className={`fas fa-microchip ${isTv ? 'text-9xl' : isMobile ? 'text-4xl' : 'text-7xl lg:text-8xl'} text-${themeData.primary} opacity-20`}></i>
                        </div>
                     </div>
                     <div className="space-y-1">
                        <h2 className={`${isTv ? 'text-7xl' : 'text-2xl lg:text-4xl'} font-black tracking-tighter uppercase opacity-20`}>Standby</h2>
                        <p className="text-[8px] lg:text-[10px] font-black uppercase tracking-[0.6em] text-gray-700">Neural Link Active</p>
                     </div>
                   </div>
                 ) : (
                   <div className="w-full max-w-3xl flex flex-col items-center"><VoiceVisualizer state={state} analyser={analyserRef.current || undefined} /></div>
                 )}
               </div>

               <div className={`${isMobile ? 'h-72' : 'h-1/2 lg:h-[32rem]'} bg-black/50 border-t border-white/5 p-4 lg:p-8 flex flex-col backdrop-blur-2xl relative group/chat-area`}>
                 {/* Floating Scroll Controls */}
                 <div className="absolute right-4 top-1/2 -translate-y-1/2 flex flex-col gap-2 opacity-0 group-hover/chat-area:opacity-100 transition-opacity z-20">
                   <button 
                     onClick={scrollToTop}
                     className="w-10 h-10 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-gray-400 hover:text-white hover:bg-white/10 hover:scale-110 transition-all shadow-xl backdrop-blur-md"
                     title="Scroll to start"
                   >
                     <i className="fas fa-chevron-up text-xs"></i>
                   </button>
                   <button 
                     onClick={scrollToBottom}
                     className="w-10 h-10 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-gray-400 hover:text-white hover:bg-white/10 hover:scale-110 transition-all shadow-xl backdrop-blur-md"
                     title="Scroll to end"
                   >
                     <i className="fas fa-chevron-down text-xs"></i>
                   </button>
                 </div>

                 <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-4 lg:space-y-6 pr-2 lg:pr-4 scrollbar-thin scrollbar-thumb-white/10">
                   {transcriptions.map(e => (
                     <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'}`}>
                       <div className={`max-w-[90%] lg:max-w-[85%] rounded-[1.5rem] lg:rounded-[2rem] px-5 py-3 lg:px-10 lg:py-6 text-xs lg:text-sm ${e.sender === 'user' ? `bg-${themeData.primary} text-white shadow-[0_5px_15px_rgba(0,0,0,0.3)]` : 'bg-white/5 text-gray-300'} border border-white/5`}>
                         <div className="flex items-center gap-2 mb-1 opacity-40">
                            <span className="text-[8px] font-black uppercase tracking-widest">{e.sender}</span>
                         </div>
                         <p className="leading-relaxed">{e.text}</p>
                         {e.sources && <GroundingSources sources={e.sources} themePrimary={themeData.primary} />}
                       </div>
                     </div>
                   ))}
                   {streamingAssistantText && (
                     <div className="flex flex-col items-start animate-fade-in">
                       <div className="max-w-[90%] lg:max-w-[85%] rounded-[1.5rem] lg:rounded-[2rem] px-5 py-3 lg:px-10 lg:py-6 text-xs lg:text-sm bg-white/10 text-blue-100 border border-blue-500/30">
                          <p className="leading-relaxed">{streamingAssistantText}</p>
                          <span className="ml-1 inline-block w-1.5 h-4 bg-blue-500 animate-pulse align-middle"></span>
                       </div>
                     </div>
                   )}
                 </div>

                 <div className={`mt-4 lg:mt-8 flex gap-3 lg:gap-4 animate-slide-up relative group/matrix ${isMobile ? 'mb-2' : ''}`}>
                    <div className="flex-1 relative">
                       <input 
                         ref={inputRef}
                         type="text" 
                         value={inputText}
                         onChange={(e) => setInputText(e.target.value)}
                         onKeyDown={handleKeyPress}
                         placeholder={`Message ${prefs.assistantName}...`}
                         className={`w-full bg-white/5 border border-white/10 rounded-[1.2rem] lg:rounded-[1.5rem] py-3 lg:py-5 px-5 lg:px-8 text-xs lg:text-sm focus:outline-none focus:border-${themeData.primary}/40 transition-all font-medium`}
                       />
                    </div>
                    <button 
                      onClick={handleSendText}
                      disabled={!inputText.trim()}
                      className={`w-12 h-12 lg:w-16 lg:h-16 rounded-[1.2rem] lg:rounded-[1.5rem] flex items-center justify-center transition-all ${inputText.trim() ? `bg-${themeData.primary} text-white shadow-lg` : 'bg-white/5 text-gray-800'}`}
                    >
                      <i className={`fas ${inputText.trim() ? 'fa-paper-plane' : 'fa-bolt'} text-lg`}></i>
                    </button>
                 </div>
               </div>
            </div>
            {(!isMobile && (isVisionActive || isScreenSharing)) && (
              <div className="w-full md:w-[320px] lg:w-[400px] flex flex-col gap-4 lg:gap-6 animate-slide-in-right">
                {isVisionActive && <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />}
                {isScreenSharing && screenStream && <ScreenShareMode isActive={isScreenSharing} stream={screenStream} onFrame={(b) => currentFrameRef.current = b} onStop={() => { setIsScreenSharing(false); setScreenStream(null); }} />}

                <div className="flex-1 bg-white/[0.02] border border-white/5 rounded-[2.5rem] lg:rounded-[3rem] p-6 lg:p-8 flex flex-col justify-between backdrop-blur-3xl shadow-2xl">
                   <div className="space-y-4 lg:space-y-6">
                      <h4 className="text-[10px] font-black uppercase tracking-[0.4em] text-gray-600 border-b border-white/5 pb-4 text-center">Diagnostics</h4>
                      <div className="space-y-4">
                         {[
                           { label: 'Neural Fidelity', val: '99.2%', icon: 'fa-brain' },
                           { label: 'Latency', val: '12ms', icon: 'fa-bolt-lightning' },
                         ].map(s => (
                           <div key={s.label} className="flex items-center justify-between">
                              <div className="flex items-center gap-3 text-gray-500">
                                <i className={`fas ${s.icon} text-[10px]`}></i>
                                <span className="text-[9px] font-bold uppercase tracking-widest">{s.label}</span>
                              </div>
                              <span className={`text-[10px] font-black text-${themeData.primary}`}>{s.val}</span>
                           </div>
                         ))}
                      </div>
                   </div>
                   <div className="pt-4 lg:pt-6 border-t border-white/5">
                      <div className="h-1 w-full bg-white/5 rounded-full overflow-hidden">
                         <div className={`h-full bg-${themeData.primary} animate-pulse-slow`} style={{ width: '92%' }}></div>
                      </div>
                   </div>
                </div>
              </div>
            )}
          </main>

          <div className={`flex items-center justify-center ${isMobile ? 'my-4' : 'mt-8 lg:mt-12'}`}>
             <button onClick={state === AssistantState.IDLE ? () => startSession() : stopSession} className={`${isTv ? 'py-10 px-32 text-2xl' : isMobile ? 'py-4 px-10 text-[10px]' : 'py-6 px-16 lg:py-8 lg:px-24 text-xs lg:text-sm'} ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500/10 border-red-500/20 text-white'} font-black rounded-full transition-all flex items-center gap-4 lg:gap-8 shadow-2xl hover:scale-105 active:scale-95 group`}>
                <i className={`fas ${state === AssistantState.IDLE ? 'fa-link' : 'fa-unlink'}`}></i>
                <span className="tracking-[0.4em] uppercase italic">{state === AssistantState.IDLE ? `Initialize Link` : 'Kill Link'}</span>
             </button>
          </div>
        </div>
      </div>

      <aside className={`fixed top-0 bottom-0 ${isMobile ? 'w-full' : 'w-[340px]'} z-[60] transition-transform duration-700 transform bg-black/98 backdrop-blur-2xl ${prefs.layout === 'right' || isMobile ? 'right-0 border-l' : 'left-0 border-r'} border-white/5 ${isMemoryOpen ? 'translate-x-0' : (prefs.layout === 'right' || isMobile) ? 'translate-x-full' : '-translate-x-full'}`}>
         <div className="flex flex-col h-full pt-20">
            <button onClick={() => setIsMemoryOpen(false)} className={`absolute top-10 ${isMobile || prefs.layout === 'right' ? 'right-10' : 'left-10'} text-gray-700 hover:text-white transition-colors`}><i className="fas fa-times text-2xl"></i></button>
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
         </div>
      </aside>

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/98 backdrop-blur-2xl animate-fade-in overflow-y-auto">
          <div className={`bg-[#02020a] border border-white/10 ${isMobile ? 'rounded-[2rem] p-6' : 'rounded-[4rem] p-12 lg:p-16'} w-full max-w-5xl shadow-3xl relative my-auto`}>
            <button onClick={() => setIsSettingsOpen(false)} className="absolute top-8 right-8 text-gray-700 hover:text-white transition-colors"><i className="fas fa-times text-3xl"></i></button>
            <header className="mb-8 lg:mb-16"><h2 className="text-3xl lg:text-5xl font-black tracking-tighter uppercase">Configuration</h2></header>
            <div className={`grid grid-cols-1 ${!isMobile ? 'lg:grid-cols-2' : ''} gap-8 lg:gap-20`}>
              <section className="space-y-6 lg:space-y-12">
                <div className="space-y-4">
                   <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Persona</label>
                   <div className="grid grid-cols-2 gap-2">
                     {(Object.keys(PERSONALITIES) as PersonalityType[]).map(p => (
                       <button key={p} onClick={() => setPrefs(prev => ({ ...prev, personality: p }))} className={`px-4 py-3 rounded-xl border-2 transition-all font-black text-[9px] uppercase tracking-widest ${prefs.personality === p ? `bg-${themeData.primary}/10 border-${themeData.primary} text-white` : 'bg-white/5 border-white/5 text-gray-700 hover:border-white/20'}`}>{p}</button>
                     ))}
                   </div>
                </div>
                <div className="space-y-4">
                  <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Name</label>
                  <input type="text" value={prefs.assistantName} onChange={(e) => setPrefs(p => ({ ...p, assistantName: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-xl py-4 px-6 font-black focus:outline-none text-lg" />
                </div>
              </section>
              {!isMobile && (
                <section className="bg-white/[0.02] border border-white/5 rounded-[3rem] p-10 space-y-8 flex flex-col justify-center text-center group">
                  <i className={`fas fa-wave-square text-7xl text-${themeData.primary} group-hover:scale-110 transition-transform duration-500`}></i>
                  <h3 className="text-xl font-black uppercase tracking-widest opacity-40">Core v4.2</h3>
                </section>
              )}
            </div>
            <footer className="mt-8 lg:mt-16 flex flex-col md:flex-row items-center justify-between gap-8">
              <div className="flex items-center gap-4">
                {(Object.keys(THEMES) as UITheme[]).map(t => ( <button key={t} onClick={() => setPrefs(p => ({ ...p, theme: t }))} className={`w-10 h-10 rounded-xl border-2 transition-all ${prefs.theme === t ? 'border-white scale-125 z-10' : 'border-white/5'}`} style={{ backgroundColor: THEMES[t].bg, boxShadow: prefs.theme === t ? `0 0 20px ${THEMES[t].glow}` : 'none' }} /> ))}
              </div>
              <button onClick={() => setIsSettingsOpen(false)} className="w-full md:w-auto md:flex-1 bg-white text-black font-black py-5 lg:py-7 px-12 lg:px-16 rounded-full text-xs lg:text-sm tracking-widest uppercase shadow-3xl hover:bg-blue-50">Commit Settings</button>
            </footer>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser, UITheme, PersonalityType, UserPreferences, DeviceType } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';
import ScreenShareMode from './components/ScreenShareMode';
import GroundingSources from './components/GroundingSources';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const THEMES: Record<UITheme, { primary: string; secondary: string; glow: string; bg: string }> = {
  cosmic: { primary: 'blue-500', secondary: 'indigo-500', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: 'emerald-500', secondary: 'teal-500', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: 'rose-500', secondary: 'orange-500', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: 'slate-400', secondary: 'zinc-500', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: VOICES[0].id,
  assistantName: 'Nova'
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [device, setDevice] = useState<DeviceType>('desktop');
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [currentSources, setCurrentSources] = useState<GroundingSource[]>([]);
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [inputText, setInputText] = useState('');
  const [searchEnabled, setSearchEnabled] = useState(true);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const detectDevice = useCallback(() => {
    const w = window.innerWidth;
    const h = window.innerHeight;
    const ua = navigator.userAgent.toLowerCase();

    if (w <= 300 || (ua.includes('watch') && !ua.includes('tv'))) {
      setDevice('wear');
    } else if (ua.includes('android') && w > h && w >= 800 && w <= 1280) {
      setDevice('auto');
    } else if (ua.includes('tv') || ua.includes('viera') || ua.includes('smarttv') || (w >= 1920 && h >= 1080)) {
      setDevice('tv');
    } else if (w < 768 || (w < 1024 && h > w)) {
      setDevice('mobile');
    } else {
      setDevice('desktop');
    }
  }, []);

  useEffect(() => {
    detectDevice();
    window.addEventListener('resize', detectDevice);
    window.addEventListener('orientationchange', detectDevice);
    return () => {
      window.removeEventListener('resize', detectDevice);
      window.removeEventListener('orientationchange', detectDevice);
    };
  }, [detectDevice]);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
      setUser({ username: sessionUser, preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS });
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      setMemories(JSON.parse(localStorage.getItem(`nova_${user.username}_memories`) || '[]'));
      setTranscriptions(JSON.parse(localStorage.getItem(`nova_${user.username}_logs`) || '[]'));
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme], [prefs.theme]);

  const scrollToTop = () => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const scrollToBottom = () => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  };

  const addTranscription = useCallback((sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  }, []);

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
    setCurrentSources([]);
  }, [screenStream]);

  const handleLogout = useCallback(() => {
    stopSession();
    setUser(null);
    sessionStorage.removeItem('nova_session_user');
  }, [stopSession]);

  const startSession = async (initialText?: string) => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      audioUtils.playLinkSound(outputCtx);

      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? (prefs.customPersonality || 'Be helpful.') : PERSONALITIES[prefs.personality];

      const tools: any[] = [{ functionDeclarations: [saveKnowledgeTool] }];
      if (searchEnabled) tools.push({ googleSearch: {} });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. User: ${user?.username}. Memories: ${facts}. Personality: ${personalityPrompt}. Device: ${device}. SEARCH_ENABLED: ${searchEnabled}. Response Protocol: Real-time, highly intelligent, emotive.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = audioUtils.createPcmBlob(inputData);
              sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: pcmBlob }); });
              if (currentFrameRef.current) {
                const frame = currentFrameRef.current;
                currentFrameRef.current = null;
                sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } }); });
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);

            if (initialText) {
              sessionPromise.then(s => s.sendRealtimeInput({ parts: [{ text: initialText }] }));
            }
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = (fc.args as any).fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => { if (sessionRef.current) s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Memory saved." } } }); });
                }
              }
            }

            const grounding = message.serverContent?.modelTurn?.parts?.find(p => (p as any).groundingMetadata)?.groundingMetadata;
            if (grounding?.groundingChunks) {
              const newSources = grounding.groundingChunks
                .filter((c: any) => c.web)
                .map((c: any) => ({ title: c.web.title, uri: c.web.uri }));
              setCurrentSources(prev => [...prev, ...newSources]);
            }

            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); 
              s.buffer = buffer; 
              s.connect(outputCtx.destination);
              s.onended = () => { 
                activeSourcesRef.current.delete(s); 
                if (activeSourcesRef.current.size === 0 && sessionRef.current) setState(AssistantState.LISTENING); 
              };
              s.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration; 
              activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) {
              setState(AssistantState.SPEAKING);
              setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            }
            if (message.serverContent?.turnComplete) {
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) {
                addTranscription('assistant', a, currentSources);
                audioUtils.playSuccessSound(outputCtx);
              } return ''; });
              setCurrentSources([]);
            }
          },
          onerror: (err) => stopSession(),
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(err.message || "Link failed."); setState(AssistantState.IDLE); }
  };

  const handleSendText = async () => {
    if (!inputText.trim()) return;
    const msg = inputText.trim();
    setInputText('');
    addTranscription('user', msg);

    if (sessionRef.current) {
      setState(AssistantState.THINKING);
      sessionRef.current.sendRealtimeInput({ parts: [{ text: msg }] });
    } else {
      setState(AssistantState.THINKING);
      const apiKey = process.env.API_KEY;
      if (!apiKey) return;
      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? (prefs.customPersonality || 'Be helpful.') : PERSONALITIES[prefs.personality];

      try {
        const [textResponse, audioResponse] = await Promise.all([
          ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Context: ${facts}. Persona: ${personalityPrompt}. Respond concisely: "${msg}"`,
            config: { maxOutputTokens: 200 }
          }),
          ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: `Respond as ${prefs.assistantName} with ${prefs.personality} personality to: "${msg}"` }] }],
            config: {
              responseModalities: [Modality.AUDIO],
              speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } }
            }
          })
        ]);

        const responseText = textResponse.text || "Connection stable.";
        addTranscription('assistant', responseText);

        const base64Audio = audioResponse.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (base64Audio && audioContextRef.current) {
          const { output: outputCtx } = audioContextRef.current;
          const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
          const source = outputCtx.createBufferSource();
          source.buffer = buffer;
          source.connect(outputCtx.destination);
          source.start();
        }
        startSession();
      } catch (err) { startSession(msg); }
    }
    inputRef.current?.blur();
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendText(); }
  };

  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;

  const isMobile = device === 'mobile';
  const isTv = device === 'tv';
  const isWear = device === 'wear';
  const isAuto = device === 'auto';

  // DEFAULT (Mobile, Desktop, TV)
  return (
    <div className={`flex flex-col h-full w-full text-white overflow-hidden font-sans transition-colors duration-1000 ${isTv ? 'scale-[1.15] origin-top' : ''}`} style={{ backgroundColor: themeData.bg }}>
      <div className={`flex-1 flex flex-col min-h-0 ${isMobile ? 'p-3' : 'md:flex-row p-4 lg:p-8'} layout-transition`}>
        <div className={`flex-1 flex flex-col min-h-0 relative ${!isMobile && isMemoryOpen && prefs.layout === 'right' ? 'md:mr-[340px]' : ''} ${!isMobile && isMemoryOpen && prefs.layout === 'left' ? 'md:ml-[340px]' : ''} layout-transition`}>

          <header className={`flex items-center justify-between animate-fade-in relative z-50 ${isMobile ? 'mb-4' : 'mb-8'}`}>
            <div className="flex items-center gap-3 lg:gap-6">
              <div className={`${isTv ? 'w-24 h-24' : isMobile ? 'w-10 h-10' : 'w-14 h-14 lg:w-16 lg:h-16'} rounded-[1.5rem] lg:rounded-[2.5rem] flex items-center justify-center shadow-2xl transition-all duration-500 border border-white/10 ${state !== AssistantState.IDLE ? `bg-${themeData.primary} rotate-12 scale-110` : 'bg-white/5'}`} style={state !== AssistantState.IDLE ? { boxShadow: `0 0 50px ${themeData.glow}` } : {}}>
                <i className={`fas ${state === AssistantState.THINKING ? 'fa-bolt animate-pulse' : isVisionActive ? 'fa-eye' : isScreenSharing ? 'fa-desktop' : 'fa-atom'} ${isTv ? 'text-5xl' : isMobile ? 'text-lg' : 'text-2xl lg:text-3xl'} text-white`}></i>
              </div>
              {!isMobile && (
                <div>
                  <h1 className={`${isTv ? 'text-5xl' : 'text-2xl lg:text-3xl'} font-black tracking-tighter bg-gradient-to-r from-${themeData.primary} via-${themeData.secondary} to-white bg-clip-text text-transparent`}>{prefs.assistantName}</h1>
                  <div className="flex items-center gap-4 mt-1">
                     <p className="text-[9px] text-gray-500 font-bold uppercase tracking-[0.4em] flex items-center gap-2">
                       <i className={`fas fa-shield-halved text-[6px] text-${themeData.primary} animate-pulse`}></i> {user.username}
                     </p>
                  </div>
                </div>
              )}
            </div>
            <div className="flex items-center gap-2 lg:gap-4">
               {!isMobile && (
                 <>
                  <button onClick={() => { setIsScreenSharing(!isScreenSharing); setIsVisionActive(false); }} className={`w-10 h-10 lg:w-12 lg:h-12 rounded-2xl flex items-center justify-center transition-all ${isScreenSharing ? 'bg-cyan-500 text-white' : 'bg-white/5 text-gray-400 hover:text-white'}`}><i className="fas fa-desktop text-sm"></i></button>
                  <button onClick={() => { setIsVisionActive(!isVisionActive); setIsScreenSharing(false); }} className={`w-10 h-10 lg:w-12 lg:h-12 rounded-2xl flex items-center justify-center transition-all ${isVisionActive ? 'bg-red-500 text-white' : 'bg-white/5 text-gray-400 hover:text-white'}`}><i className="fas fa-camera text-sm"></i></button>
                 </>
               )}
               <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-10 h-10 lg:w-12 lg:h-12 rounded-2xl flex items-center justify-center transition-all ${isMemoryOpen ? `bg-${themeData.primary} text-white` : 'bg-white/5 text-gray-400 hover:text-white'}`}><i className="fas fa-database text-sm"></i></button>
               <button onClick={() => setIsSettingsOpen(true)} className="w-10 h-10 lg:w-12 lg:h-12 rounded-2xl flex items-center justify-center bg-white/5 text-gray-400 transition-colors hover:text-white"><i className="fas fa-cog text-sm"></i></button>
               <button onClick={handleLogout} className="text-gray-600 hover:text-red-400 px-2 transition-colors"><i className="fas fa-sign-out-alt"></i></button>
            </div>
          </header>

          <main className="flex-1 flex flex-col md:flex-row gap-4 lg:gap-6 min-h-0">
            <div className={`flex-1 flex flex-col min-h-0 bg-white/[0.01] ${isMobile ? 'rounded-[2rem]' : 'rounded-[3rem]'} border border-white/5 backdrop-blur-3xl overflow-hidden relative shadow-inner animate-fade-in`}>
               <div className={`flex-1 flex flex-col items-center justify-center z-10 p-4 lg:p-8`}>
                 {state === AssistantState.IDLE ? (
                   <div className="text-center space-y-6 lg:space-y-12 group">
                     <div className="relative">
                        <div className={`absolute inset-0 bg-${themeData.primary}/20 blur-[100px] rounded-full animate-pulse-slow`}></div>
                        <div className={`${isTv ? 'w-80 h-80' : isMobile ? 'w-32 h-32' : 'w-48 h-48 lg:w-64 lg:h-64'} rounded-[3rem] lg:rounded-[5rem] bg-white/5 border border-white/10 flex items-center justify-center mx-auto shadow-inner relative transition-transform duration-700 group-hover:scale-105`}>
                           <i className={`fas fa-microchip ${isTv ? 'text-9xl' : isMobile ? 'text-4xl' : 'text-7xl lg:text-8xl'} text-${themeData.primary} opacity-20`}></i>
                        </div>
                     </div>
                     <div className="space-y-1">
                        <h2 className={`${isTv ? 'text-7xl' : 'text-2xl lg:text-4xl'} font-black tracking-tighter uppercase opacity-20`}>Standby</h2>
                        <p className="text-[8px] lg:text-[10px] font-black uppercase tracking-[0.6em] text-gray-700">Neural Link Active</p>
                     </div>
                   </div>
                 ) : (
                   <div className="w-full max-w-3xl flex flex-col items-center"><VoiceVisualizer state={state} analyser={analyserRef.current || undefined} /></div>
                 )}
               </div>

               <div className={`${isMobile ? 'h-72' : 'h-1/2 lg:h-[32rem]'} bg-black/50 border-t border-white/5 p-4 lg:p-8 flex flex-col backdrop-blur-2xl relative group/chat-area`}>
                 {/* Floating Scroll Controls */}
                 <div className="absolute right-4 top-1/2 -translate-y-1/2 flex flex-col gap-2 opacity-0 group-hover/chat-area:opacity-100 transition-opacity z-20">
                   <button 
                     onClick={scrollToTop}
                     className="w-10 h-10 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-gray-400 hover:text-white hover:bg-white/10 hover:scale-110 transition-all shadow-xl backdrop-blur-md"
                     title="Scroll to start"
                   >
                     <i className="fas fa-chevron-up text-xs"></i>
                   </button>
                   <button 
                     onClick={scrollToBottom}
                     className="w-10 h-10 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-gray-400 hover:text-white hover:bg-white/10 hover:scale-110 transition-all shadow-xl backdrop-blur-md"
                     title="Scroll to end"
                   >
                     <i className="fas fa-chevron-down text-xs"></i>
                   </button>
                 </div>

                 <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-4 lg:space-y-6 pr-2 lg:pr-4 scrollbar-thin scrollbar-thumb-white/10">
                   {transcriptions.map(e => (
                     <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'}`}>
                       <div className={`max-w-[90%] lg:max-w-[85%] rounded-[1.5rem] lg:rounded-[2rem] px-5 py-3 lg:px-10 lg:py-6 text-xs lg:text-sm ${e.sender === 'user' ? `bg-${themeData.primary} text-white shadow-[0_5px_15px_rgba(0,0,0,0.3)]` : 'bg-white/5 text-gray-300'} border border-white/5`}>
                         <div className="flex items-center gap-2 mb-1 opacity-40">
                            <span className="text-[8px] font-black uppercase tracking-widest">{e.sender}</span>
                         </div>
                         <p className="leading-relaxed">{e.text}</p>
                         {e.sources && <GroundingSources sources={e.sources} themePrimary={themeData.primary} />}
                       </div>
                     </div>
                   ))}
                   {streamingAssistantText && (
                     <div className="flex flex-col items-start animate-fade-in">
                       <div className="max-w-[90%] lg:max-w-[85%] rounded-[1.5rem] lg:rounded-[2rem] px-5 py-3 lg:px-10 lg:py-6 text-xs lg:text-sm bg-white/10 text-blue-100 border border-blue-500/30">
                          <p className="leading-relaxed">{streamingAssistantText}</p>
                          <span className="ml-1 inline-block w-1.5 h-4 bg-blue-500 animate-pulse align-middle"></span>
                       </div>
                     </div>
                   )}
                 </div>

                 <div className={`mt-4 lg:mt-8 flex gap-3 lg:gap-4 animate-slide-up relative group/matrix ${isMobile ? 'mb-2' : ''}`}>
                    <div className="flex-1 relative">
                       <input 
                         ref={inputRef}
                         type="text" 
                         value={inputText}
                         onChange={(e) => setInputText(e.target.value)}
                         onKeyDown={handleKeyPress}
                         placeholder={`Message ${prefs.assistantName}...`}
                         className={`w-full bg-white/5 border border-white/10 rounded-[1.2rem] lg:rounded-[1.5rem] py-3 lg:py-5 px-5 lg:px-8 text-xs lg:text-sm focus:outline-none focus:border-${themeData.primary}/40 transition-all font-medium`}
                       />
                    </div>
                    <button 
                      onClick={handleSendText}
                      disabled={!inputText.trim()}
                      className={`w-12 h-12 lg:w-16 lg:h-16 rounded-[1.2rem] lg:rounded-[1.5rem] flex items-center justify-center transition-all ${inputText.trim() ? `bg-${themeData.primary} text-white shadow-lg` : 'bg-white/5 text-gray-800'}`}
                    >
                      <i className={`fas ${inputText.trim() ? 'fa-paper-plane' : 'fa-bolt'} text-lg`}></i>
                    </button>
                 </div>
               </div>
            </div>
            {(!isMobile && (isVisionActive || isScreenSharing)) && (
              <div className="w-full md:w-[320px] lg:w-[400px] flex flex-col gap-4 lg:gap-6 animate-slide-in-right">
                {isVisionActive && <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />}
                {isScreenSharing && screenStream && <ScreenShareMode isActive={isScreenSharing} stream={screenStream} onFrame={(b) => currentFrameRef.current = b} onStop={() => { setIsScreenSharing(false); setScreenStream(null); }} />}

                <div className="flex-1 bg-white/[0.02] border border-white/5 rounded-[2.5rem] lg:rounded-[3rem] p-6 lg:p-8 flex flex-col justify-between backdrop-blur-3xl shadow-2xl">
                   <div className="space-y-4 lg:space-y-6">
                      <h4 className="text-[10px] font-black uppercase tracking-[0.4em] text-gray-600 border-b border-white/5 pb-4 text-center">Diagnostics</h4>
                      <div className="space-y-4">
                         {[
                           { label: 'Neural Fidelity', val: '99.2%', icon: 'fa-brain' },
                           { label: 'Latency', val: '12ms', icon: 'fa-bolt-lightning' },
                         ].map(s => (
                           <div key={s.label} className="flex items-center justify-between">
                              <div className="flex items-center gap-3 text-gray-500">
                                <i className={`fas ${s.icon} text-[10px]`}></i>
                                <span className="text-[9px] font-bold uppercase tracking-widest">{s.label}</span>
                              </div>
                              <span className={`text-[10px] font-black text-${themeData.primary}`}>{s.val}</span>
                           </div>
                         ))}
                      </div>
                   </div>
                   <div className="pt-4 lg:pt-6 border-t border-white/5">
                      <div className="h-1 w-full bg-white/5 rounded-full overflow-hidden">
                         <div className={`h-full bg-${themeData.primary} animate-pulse-slow`} style={{ width: '92%' }}></div>
                      </div>
                   </div>
                </div>
              </div>
            )}
          </main>

          <div className={`flex items-center justify-center ${isMobile ? 'my-4' : 'mt-8 lg:mt-12'}`}>
             <button onClick={state === AssistantState.IDLE ? () => startSession() : stopSession} className={`${isTv ? 'py-10 px-32 text-2xl' : isMobile ? 'py-4 px-10 text-[10px]' : 'py-6 px-16 lg:py-8 lg:px-24 text-xs lg:text-sm'} ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500/10 border-red-500/20 text-white'} font-black rounded-full transition-all flex items-center gap-4 lg:gap-8 shadow-2xl hover:scale-105 active:scale-95 group`}>
                <i className={`fas ${state === AssistantState.IDLE ? 'fa-link' : 'fa-unlink'}`}></i>
                <span className="tracking-[0.4em] uppercase italic">{state === AssistantState.IDLE ? `Initialize Link` : 'Kill Link'}</span>
             </button>
          </div>
        </div>
      </div>

      <aside className={`fixed top-0 bottom-0 ${isMobile ? 'w-full' : 'w-[340px]'} z-[60] transition-transform duration-700 transform bg-black/98 backdrop-blur-2xl ${prefs.layout === 'right' || isMobile ? 'right-0 border-l' : 'left-0 border-r'} border-white/5 ${isMemoryOpen ? 'translate-x-0' : (prefs.layout === 'right' || isMobile) ? 'translate-x-full' : '-translate-x-full'}`}>
         <div className="flex flex-col h-full pt-20">
            <button onClick={() => setIsMemoryOpen(false)} className={`absolute top-10 ${isMobile || prefs.layout === 'right' ? 'right-10' : 'left-10'} text-gray-700 hover:text-white transition-colors`}><i className="fas fa-times text-2xl"></i></button>
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
         </div>
      </aside>

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/98 backdrop-blur-2xl animate-fade-in overflow-y-auto">
          <div className={`bg-[#02020a] border border-white/10 ${isMobile ? 'rounded-[2rem] p-6' : 'rounded-[4rem] p-12 lg:p-16'} w-full max-w-5xl shadow-3xl relative my-auto`}>
            <button onClick={() => setIsSettingsOpen(false)} className="absolute top-8 right-8 text-gray-700 hover:text-white transition-colors"><i className="fas fa-times text-3xl"></i></button>
            <header className="mb-8 lg:mb-16"><h2 className="text-3xl lg:text-5xl font-black tracking-tighter uppercase">Configuration</h2></header>
            <div className={`grid grid-cols-1 ${!isMobile ? 'lg:grid-cols-2' : ''} gap-8 lg:gap-20`}>
              <section className="space-y-6 lg:space-y-12">
                <div className="space-y-4">
                   <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Persona</label>
                   <div className="grid grid-cols-2 gap-2">
                     {(Object.keys(PERSONALITIES) as PersonalityType[]).map(p => (
                       <button key={p} onClick={() => setPrefs(prev => ({ ...prev, personality: p }))} className={`px-4 py-3 rounded-xl border-2 transition-all font-black text-[9px] uppercase tracking-widest ${prefs.personality === p ? `bg-${themeData.primary}/10 border-${themeData.primary} text-white` : 'bg-white/5 border-white/5 text-gray-700 hover:border-white/20'}`}>{p}</button>
                     ))}
                   </div>
                   {prefs.personality === 'custom' && (
                     <div className="mt-4 animate-fade-in">
                       <label className="text-[9px] font-black text-blue-500 uppercase tracking-widest mb-2 block">Define Custom Persona</label>
                       <textarea 
                         value={prefs.customPersonality || ''}
                         onChange={(e) => setPrefs(p => ({ ...p, customPersonality: e.target.value }))}
                         placeholder="e.g. You are a futuristic navigator from the Year 3022..."
                         className="w-full bg-white/5 border border-white/10 rounded-xl py-4 px-5 text-sm focus:outline-none focus:border-blue-500/40 transition-all min-h-[100px] font-medium text-gray-200"
                       />
                     </div>
                   )}
                </div>
                <div className="space-y-4">
                  <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Name</label>
                  <input type="text" value={prefs.assistantName} onChange={(e) => setPrefs(p => ({ ...p, assistantName: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-xl py-4 px-6 font-black focus:outline-none text-lg" />
                </div>
              </section>
              {!isMobile && (
                <section className="bg-white/[0.02] border border-white/5 rounded-[3rem] p-10 space-y-8 flex flex-col justify-center text-center group">
                  <i className={`fas fa-wave-square text-7xl text-${themeData.primary} group-hover:scale-110 transition-transform duration-500`}></i>
                  <h3 className="text-xl font-black uppercase tracking-widest opacity-40">Core v4.2</h3>
                </section>
              )}
            </div>
            <footer className="mt-8 lg:mt-16 flex flex-col md:flex-row items-center justify-between gap-8">
              <div className="flex items-center gap-4">
                {(Object.keys(THEMES) as UITheme[]).map(t => ( <button key={t} onClick={() => setPrefs(p => ({ ...p, theme: t }))} className={`w-10 h-10 rounded-xl border-2 transition-all ${prefs.theme === t ? 'border-white scale-125 z-10' : 'border-white/5'}`} style={{ backgroundColor: THEMES[t].bg, boxShadow: prefs.theme === t ? `0 0 20px ${THEMES[t].glow}` : 'none' }} /> ))}
              </div>
              <button onClick={() => setIsSettingsOpen(false)} className="w-full md:w-auto md:flex-1 bg-white text-black font-black py-5 lg:py-7 px-12 lg:px-16 rounded-full text-xs lg:text-sm tracking-widest uppercase shadow-3xl hover:bg-blue-50">Commit Settings</button>
            </footer>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export enum AssistantState {
  IDLE = 'IDLE',
  CONNECTING = 'CONNECTING',
  LISTENING = 'LISTENING',
  SPEAKING = 'SPEAKING',
  THINKING = 'THINKING',
  OBSERVING = 'OBSERVING',
  ERROR = 'ERROR'
}

export type DeviceType = 'wear' | 'mobile' | 'desktop' | 'tv' | 'auto';

export type UITheme = 'cosmic' | 'emerald' | 'ruby' | 'obsidian';
export type PersonalityType = 'professional' | 'friendly' | 'witty' | 'minimalist' | 'alluring' | 'custom';

export interface GroundingSource {
  title: string;
  uri: string;
}

export interface TranscriptionEntry {
  id: string;
  sender: 'user' | 'assistant';
  text: string;
  timestamp: Date;
  isThinking?: boolean;
  isStreaming?: boolean;
  sources?: GroundingSource[];
}

export interface MemoryEntry {
  id: string;
  fact: string;
  timestamp: Date;
}

export interface UserPreferences {
  theme: UITheme;
  personality: PersonalityType;
  customPersonality?: string;
  layout: 'left' | 'right';
  voiceId: string;
  assistantName: string;
  assistantProfilePic?: string; // Base64 string for custom AI avatar
}

export interface AuthUser {
  username: string;
  preferences: UserPreferences;
}

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser, UITheme, PersonalityType, UserPreferences, DeviceType } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';
import ScreenShareMode from './components/ScreenShareMode';
import GroundingSources from './components/GroundingSources';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const THEMES: Record<UITheme, { primary: string; secondary: string; glow: string; bg: string }> = {
  cosmic: { primary: 'blue-500', secondary: 'indigo-500', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: 'emerald-500', secondary: 'teal-500', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: 'rose-500', secondary: 'orange-500', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: 'slate-400', secondary: 'zinc-500', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: VOICES[0].id,
  assistantName: 'Nova'
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [device, setDevice] = useState<DeviceType>('desktop');
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [currentSources, setCurrentSources] = useState<GroundingSource[]>([]);
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [inputText, setInputText] = useState('');
  const [searchEnabled, setSearchEnabled] = useState(true);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const detectDevice = useCallback(() => {
    const w = window.innerWidth;
    const h = window.innerHeight;
    const ua = navigator.userAgent.toLowerCase();

    if (w <= 300 || (ua.includes('watch') && !ua.includes('tv'))) {
      setDevice('wear');
    } else if (ua.includes('android') && w > h && w >= 800 && w <= 1280) {
      setDevice('auto');
    } else if (ua.includes('tv') || ua.includes('viera') || ua.includes('smarttv') || (w >= 1920 && h >= 1080)) {
      setDevice('tv');
    } else if (w < 768 || (w < 1024 && h > w)) {
      setDevice('mobile');
    } else {
      setDevice('desktop');
    }
  }, []);

  useEffect(() => {
    detectDevice();
    window.addEventListener('resize', detectDevice);
    window.addEventListener('orientationchange', detectDevice);
    return () => {
      window.removeEventListener('resize', detectDevice);
      window.removeEventListener('orientationchange', detectDevice);
    };
  }, [detectDevice]);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
      setUser({ username: sessionUser, preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS });
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      setMemories(JSON.parse(localStorage.getItem(`nova_${user.username}_memories`) || '[]'));
      setTranscriptions(JSON.parse(localStorage.getItem(`nova_${user.username}_logs`) || '[]'));
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme], [prefs.theme]);

  const scrollToTop = () => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const scrollToBottom = () => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  };

  const addTranscription = useCallback((sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  }, []);

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
    setCurrentSources([]);
  }, [screenStream]);

  const handleLogout = useCallback(() => {
    stopSession();
    setUser(null);
    sessionStorage.removeItem('nova_session_user');
  }, [stopSession]);

  const handleProfilePicChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPrefs(p => ({ ...p, assistantProfilePic: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const startSession = async (initialText?: string) => {
    try {
      setState(AssistantState.CONNECTING);
      setError(null);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      audioUtils.playLinkSound(outputCtx);

      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? (prefs.customPersonality || 'Be helpful.') : PERSONALITIES[prefs.personality];

      const tools: any[] = [{ functionDeclarations: [saveKnowledgeTool] }];
      if (searchEnabled) tools.push({ googleSearch: {} });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. User: ${user?.username}. Memories: ${facts}. Personality: ${personalityPrompt}. Device: ${device}. SEARCH_ENABLED: ${searchEnabled}. Response Protocol: Real-time, highly intelligent, emotive.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = audioUtils.createPcmBlob(inputData);
              sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: pcmBlob }); });
              if (currentFrameRef.current) {
                const frame = currentFrameRef.current;
                currentFrameRef.current = null;
                sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } }); });
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);

            if (initialText) {
              sessionPromise.then(s => s.sendRealtimeInput({ parts: [{ text: initialText }] }));
            }
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = (fc.args as any).fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => { if (sessionRef.current) s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Memory saved." } } }); });
                }
              }
            }

            const grounding = message.serverContent?.modelTurn?.parts?.find(p => (p as any).groundingMetadata)?.groundingMetadata;
            if (grounding?.groundingChunks) {
              const newSources = grounding.groundingChunks
                .filter((c: any) => c.web)
                .map((c: any) => ({ title: c.web.title, uri: c.web.uri }));
              setCurrentSources(prev => [...prev, ...newSources]);
            }

            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); 
              s.buffer = buffer; 
              s.connect(outputCtx.destination);
              s.onended = () => { 
                activeSourcesRef.current.delete(s); 
                if (activeSourcesRef.current.size === 0 && sessionRef.current) setState(AssistantState.LISTENING); 
              };
              s.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration; 
              activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) {
              setState(AssistantState.SPEAKING);
              setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            }
            if (message.serverContent?.turnComplete) {
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) {
                addTranscription('assistant', a, currentSources);
                audioUtils.playSuccessSound(outputCtx);
              } return ''; });
              setCurrentSources([]);
            }
          },
          onerror: (err) => stopSession(),
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(err.message || "Link failed."); setState(AssistantState.IDLE); }
  };

  const handleSendText = async () => {
    if (!inputText.trim()) return;
    const msg = inputText.trim();
    setInputText('');
    addTranscription('user', msg);

    if (sessionRef.current) {
      setState(AssistantState.THINKING);
      sessionRef.current.sendRealtimeInput({ parts: [{ text: msg }] });
    } else {
      setState(AssistantState.THINKING);
      const apiKey = process.env.API_KEY;
      if (!apiKey) return;
      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? (prefs.customPersonality || 'Be helpful.') : PERSONALITIES[prefs.personality];

      try {
        const [textResponse, audioResponse] = await Promise.all([
          ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Context: ${facts}. Persona: ${personalityPrompt}. Respond concisely: "${msg}"`,
            config: { maxOutputTokens: 200 }
          }),
          ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: `Respond as ${prefs.assistantName} with ${prefs.personality} personality to: "${msg}"` }] }],
            config: {
              responseModalities: [Modality.AUDIO],
              speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } }
            }
          })
        ]);

        const responseText = textResponse.text || "Connection stable.";
        addTranscription('assistant', responseText);

        const base64Audio = audioResponse.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (base64Audio && audioContextRef.current) {
          const { output: outputCtx } = audioContextRef.current;
          const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
          const source = outputCtx.createBufferSource();
          source.buffer = buffer;
          source.connect(outputCtx.destination);
          source.start();
        }
        startSession();
      } catch (err) { startSession(msg); }
    }
    inputRef.current?.blur();
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendText(); }
  };

  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;

  const isMobile = device === 'mobile';
  const isTv = device === 'tv';
  const isWear = device === 'wear';
  const isAuto = device === 'auto';

  // Assistant Identity Display Logic
  const renderIdentityIcon = (size: string, iconSize: string) => {
    const commonStyles = `${size} rounded-[1.5rem] lg:rounded-[2.5rem] flex items-center justify-center shadow-2xl transition-all duration-500 border border-white/10 overflow-hidden`;
    const activeStyles = state !== AssistantState.IDLE ? `bg-${themeData.primary} rotate-12 scale-110` : 'bg-white/5';
    const glowStyle = state !== AssistantState.IDLE ? { boxShadow: `0 0 50px ${themeData.glow}` } : {};

    if (prefs.assistantProfilePic) {
      return (
        <div className={`${commonStyles} ${activeStyles}`} style={glowStyle}>
           <img src={prefs.assistantProfilePic} alt={prefs.assistantName} className="w-full h-full object-cover" />
        </div>
      );
    }

    return (
      <div className={`${commonStyles} ${activeStyles}`} style={glowStyle}>
        <i className={`fas ${state === AssistantState.THINKING ? 'fa-bolt animate-pulse' : isVisionActive ? 'fa-eye' : isScreenSharing ? 'fa-desktop' : 'fa-atom'} ${iconSize} text-white`}></i>
      </div>
    );
  };

  // DEFAULT (Mobile, Desktop, TV)
  return (
    <div className={`flex flex-col h-full w-full text-white overflow-hidden font-sans transition-colors duration-1000 ${isTv ? 'scale-[1.15] origin-top' : ''}`} style={{ backgroundColor: themeData.bg }}>
      <div className={`flex-1 flex flex-col min-h-0 ${isMobile ? 'p-3' : 'md:flex-row p-4 lg:p-8'} layout-transition`}>
        <div className={`flex-1 flex flex-col min-h-0 relative ${!isMobile && isMemoryOpen && prefs.layout === 'right' ? 'md:mr-[340px]' : ''} ${!isMobile && isMemoryOpen && prefs.layout === 'left' ? 'md:ml-[340px]' : ''} layout-transition`}>

          <header className={`flex items-center justify-between animate-fade-in relative z-50 ${isMobile ? 'mb-4' : 'mb-8'}`}>
            <div className="flex items-center gap-3 lg:gap-6">
              {renderIdentityIcon(
                isTv ? 'w-24 h-24' : isMobile ? 'w-10 h-10' : 'w-14 h-14 lg:w-16 lg:h-16',
                isTv ? 'text-5xl' : isMobile ? 'text-lg' : 'text-2xl lg:text-3xl'
              )}
              {!isMobile && (
                <div>
                  <h1 className={`${isTv ? 'text-5xl' : 'text-2xl lg:text-3xl'} font-black tracking-tighter bg-gradient-to-r from-${themeData.primary} via-${themeData.secondary} to-white bg-clip-text text-transparent`}>{prefs.assistantName}</h1>
                  <div className="flex items-center gap-4 mt-1">
                     <p className="text-[9px] text-gray-500 font-bold uppercase tracking-[0.4em] flex items-center gap-2">
                       <i className={`fas fa-shield-halved text-[6px] text-${themeData.primary} animate-pulse`}></i> {user.username}
                     </p>
                  </div>
                </div>
              )}
            </div>
            <div className="flex items-center gap-2 lg:gap-4">
               {!isMobile && (
                 <>
                  <button onClick={() => { setIsScreenSharing(!isScreenSharing); setIsVisionActive(false); }} className={`w-10 h-10 lg:w-12 lg:h-12 rounded-2xl flex items-center justify-center transition-all ${isScreenSharing ? 'bg-cyan-500 text-white' : 'bg-white/5 text-gray-400 hover:text-white'}`}><i className="fas fa-desktop text-sm"></i></button>
                  <button onClick={() => { setIsVisionActive(!isVisionActive); setIsScreenSharing(false); }} className={`w-10 h-10 lg:w-12 lg:h-12 rounded-2xl flex items-center justify-center transition-all ${isVisionActive ? 'bg-red-500 text-white' : 'bg-white/5 text-gray-400 hover:text-white'}`}><i className="fas fa-camera text-sm"></i></button>
                 </>
               )}
               <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-10 h-10 lg:w-12 lg:h-12 rounded-2xl flex items-center justify-center transition-all ${isMemoryOpen ? `bg-${themeData.primary} text-white` : 'bg-white/5 text-gray-400 hover:text-white'}`}><i className="fas fa-database text-sm"></i></button>
               <button onClick={() => setIsSettingsOpen(true)} className="w-10 h-10 lg:w-12 lg:h-12 rounded-2xl flex items-center justify-center bg-white/5 text-gray-400 transition-colors hover:text-white"><i className="fas fa-cog text-sm"></i></button>
               <button onClick={handleLogout} className="text-gray-600 hover:text-red-400 px-2 transition-colors"><i className="fas fa-sign-out-alt"></i></button>
            </div>
          </header>

          <main className="flex-1 flex flex-col md:flex-row gap-4 lg:gap-6 min-h-0">
            <div className={`flex-1 flex flex-col min-h-0 bg-white/[0.01] ${isMobile ? 'rounded-[2rem]' : 'rounded-[3rem]'} border border-white/5 backdrop-blur-3xl overflow-hidden relative shadow-inner animate-fade-in`}>
               <div className={`flex-1 flex flex-col items-center justify-center z-10 p-4 lg:p-8`}>
                 {state === AssistantState.IDLE ? (
                   <div className="text-center space-y-6 lg:space-y-12 group">
                     <div className="relative">
                        <div className={`absolute inset-0 bg-${themeData.primary}/20 blur-[100px] rounded-full animate-pulse-slow`}></div>
                        <div className={`${isTv ? 'w-80 h-80' : isMobile ? 'w-32 h-32' : 'w-48 h-48 lg:w-64 lg:h-64'} rounded-[3rem] lg:rounded-[5rem] bg-white/5 border border-white/10 flex items-center justify-center mx-auto shadow-inner relative transition-transform duration-700 group-hover:scale-105 overflow-hidden`}>
                           {prefs.assistantProfilePic ? (
                             <img src={prefs.assistantProfilePic} alt={prefs.assistantName} className="w-full h-full object-cover opacity-60 group-hover:opacity-100 transition-opacity" />
                           ) : (
                             <i className={`fas fa-microchip ${isTv ? 'text-9xl' : isMobile ? 'text-4xl' : 'text-7xl lg:text-8xl'} text-${themeData.primary} opacity-20`}></i>
                           )}
                        </div>
                     </div>
                     <div className="space-y-1">
                        <h2 className={`${isTv ? 'text-7xl' : 'text-2xl lg:text-4xl'} font-black tracking-tighter uppercase opacity-20`}>Standby</h2>
                        <p className="text-[8px] lg:text-[10px] font-black uppercase tracking-[0.6em] text-gray-700">Neural Link Active</p>
                     </div>
                   </div>
                 ) : (
                   <div className="w-full max-w-3xl flex flex-col items-center"><VoiceVisualizer state={state} analyser={analyserRef.current || undefined} /></div>
                 )}
               </div>

               <div className={`${isMobile ? 'h-72' : 'h-1/2 lg:h-[32rem]'} bg-black/50 border-t border-white/5 p-4 lg:p-8 flex flex-col backdrop-blur-2xl relative group/chat-area`}>
                 {/* Floating Scroll Controls */}
                 <div className="absolute right-4 top-1/2 -translate-y-1/2 flex flex-col gap-2 opacity-0 group-hover/chat-area:opacity-100 transition-opacity z-20">
                   <button 
                     onClick={scrollToTop}
                     className="w-10 h-10 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-gray-400 hover:text-white hover:bg-white/10 hover:scale-110 transition-all shadow-xl backdrop-blur-md"
                     title="Scroll to start"
                   >
                     <i className="fas fa-chevron-up text-xs"></i>
                   </button>
                   <button 
                     onClick={scrollToBottom}
                     className="w-10 h-10 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-gray-400 hover:text-white hover:bg-white/10 hover:scale-110 transition-all shadow-xl backdrop-blur-md"
                     title="Scroll to end"
                   >
                     <i className="fas fa-chevron-down text-xs"></i>
                   </button>
                 </div>

                 <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-4 lg:space-y-6 pr-2 lg:pr-4 scrollbar-thin scrollbar-thumb-white/10">
                   {transcriptions.map(e => (
                     <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'}`}>
                       <div className={`max-w-[90%] lg:max-w-[85%] rounded-[1.5rem] lg:rounded-[2rem] px-5 py-3 lg:px-10 lg:py-6 text-xs lg:text-sm ${e.sender === 'user' ? `bg-${themeData.primary} text-white shadow-[0_5px_15px_rgba(0,0,0,0.3)]` : 'bg-white/5 text-gray-300'} border border-white/5`}>
                         <div className="flex items-center gap-2 mb-1 opacity-40">
                            <span className="text-[8px] font-black uppercase tracking-widest">{e.sender}</span>
                         </div>
                         <p className="leading-relaxed">{e.text}</p>
                         {e.sources && <GroundingSources sources={e.sources} themePrimary={themeData.primary} />}
                       </div>
                     </div>
                   ))}
                   {streamingAssistantText && (
                     <div className="flex flex-col items-start animate-fade-in">
                       <div className="max-w-[90%] lg:max-w-[85%] rounded-[1.5rem] lg:rounded-[2rem] px-5 py-3 lg:px-10 lg:py-6 text-xs lg:text-sm bg-white/10 text-blue-100 border border-blue-500/30">
                          <p className="leading-relaxed">{streamingAssistantText}</p>
                          <span className="ml-1 inline-block w-1.5 h-4 bg-blue-500 animate-pulse align-middle"></span>
                       </div>
                     </div>
                   )}
                 </div>

                 <div className={`mt-4 lg:mt-8 flex gap-3 lg:gap-4 animate-slide-up relative group/matrix ${isMobile ? 'mb-2' : ''}`}>
                    <div className="flex-1 relative">
                       <input 
                         ref={inputRef}
                         type="text" 
                         value={inputText}
                         onChange={(e) => setInputText(e.target.value)}
                         onKeyDown={handleKeyPress}
                         placeholder={`Message ${prefs.assistantName}...`}
                         className={`w-full bg-white/5 border border-white/10 rounded-[1.2rem] lg:rounded-[1.5rem] py-3 lg:py-5 px-5 lg:px-8 text-xs lg:text-sm focus:outline-none focus:border-${themeData.primary}/40 transition-all font-medium`}
                       />
                    </div>
                    <button 
                      onClick={handleSendText}
                      disabled={!inputText.trim()}
                      className={`w-12 h-12 lg:w-16 lg:h-16 rounded-[1.2rem] lg:rounded-[1.5rem] flex items-center justify-center transition-all ${inputText.trim() ? `bg-${themeData.primary} text-white shadow-lg` : 'bg-white/5 text-gray-800'}`}
                    >
                      <i className={`fas ${inputText.trim() ? 'fa-paper-plane' : 'fa-bolt'} text-lg`}></i>
                    </button>
                 </div>
               </div>
            </div>
            {(!isMobile && (isVisionActive || isScreenSharing)) && (
              <div className="w-full md:w-[320px] lg:w-[400px] flex flex-col gap-4 lg:gap-6 animate-slide-in-right">
                {isVisionActive && <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />}
                {isScreenSharing && screenStream && <ScreenShareMode isActive={isScreenSharing} stream={screenStream} onFrame={(b) => currentFrameRef.current = b} onStop={() => { setIsScreenSharing(false); setScreenStream(null); }} />}

                <div className="flex-1 bg-white/[0.02] border border-white/5 rounded-[2.5rem] lg:rounded-[3rem] p-6 lg:p-8 flex flex-col justify-between backdrop-blur-3xl shadow-2xl">
                   <div className="space-y-4 lg:space-y-6">
                      <h4 className="text-[10px] font-black uppercase tracking-[0.4em] text-gray-600 border-b border-white/5 pb-4 text-center">Diagnostics</h4>
                      <div className="space-y-4">
                         {[
                           { label: 'Neural Fidelity', val: '99.2%', icon: 'fa-brain' },
                           { label: 'Latency', val: '12ms', icon: 'fa-bolt-lightning' },
                         ].map(s => (
                           <div key={s.label} className="flex items-center justify-between">
                              <div className="flex items-center gap-3 text-gray-500">
                                <i className={`fas ${s.icon} text-[10px]`}></i>
                                <span className="text-[9px] font-bold uppercase tracking-widest">{s.label}</span>
                              </div>
                              <span className={`text-[10px] font-black text-${themeData.primary}`}>{s.val}</span>
                           </div>
                         ))}
                      </div>
                   </div>
                   <div className="pt-4 lg:pt-6 border-t border-white/5">
                      <div className="h-1 w-full bg-white/5 rounded-full overflow-hidden">
                         <div className={`h-full bg-${themeData.primary} animate-pulse-slow`} style={{ width: '92%' }}></div>
                      </div>
                   </div>
                </div>
              </div>
            )}
          </main>

          <div className={`flex items-center justify-center ${isMobile ? 'my-4' : 'mt-8 lg:mt-12'}`}>
             <button onClick={state === AssistantState.IDLE ? () => startSession() : stopSession} className={`${isTv ? 'py-10 px-32 text-2xl' : isMobile ? 'py-4 px-10 text-[10px]' : 'py-6 px-16 lg:py-8 lg:px-24 text-xs lg:text-sm'} ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500/10 border-red-500/20 text-white'} font-black rounded-full transition-all flex items-center gap-4 lg:gap-8 shadow-2xl hover:scale-105 active:scale-95 group`}>
                <i className={`fas ${state === AssistantState.IDLE ? 'fa-link' : 'fa-unlink'}`}></i>
                <span className="tracking-[0.4em] uppercase italic">{state === AssistantState.IDLE ? `Initialize Link` : 'Kill Link'}</span>
             </button>
          </div>
        </div>
      </div>

      <aside className={`fixed top-0 bottom-0 ${isMobile ? 'w-full' : 'w-[340px]'} z-[60] transition-transform duration-700 transform bg-black/98 backdrop-blur-2xl ${prefs.layout === 'right' || isMobile ? 'right-0 border-l' : 'left-0 border-r'} border-white/5 ${isMemoryOpen ? 'translate-x-0' : (prefs.layout === 'right' || isMobile) ? 'translate-x-full' : '-translate-x-full'}`}>
         <div className="flex flex-col h-full pt-20">
            <button onClick={() => setIsMemoryOpen(false)} className={`absolute top-10 ${isMobile || prefs.layout === 'right' ? 'right-10' : 'left-10'} text-gray-700 hover:text-white transition-colors`}><i className="fas fa-times text-2xl"></i></button>
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
         </div>
      </aside>

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/98 backdrop-blur-2xl animate-fade-in overflow-y-auto">
          <div className={`bg-[#02020a] border border-white/10 ${isMobile ? 'rounded-[2rem] p-6' : 'rounded-[4rem] p-12 lg:p-16'} w-full max-w-5xl shadow-3xl relative my-auto`}>
            <button onClick={() => setIsSettingsOpen(false)} className="absolute top-8 right-8 text-gray-700 hover:text-white transition-colors"><i className="fas fa-times text-3xl"></i></button>
            <header className="mb-8 lg:mb-16"><h2 className="text-3xl lg:text-5xl font-black tracking-tighter uppercase">Configuration</h2></header>
            <div className={`grid grid-cols-1 ${!isMobile ? 'lg:grid-cols-2' : ''} gap-8 lg:gap-20`}>
              <section className="space-y-6 lg:space-y-12">
                <div className="space-y-4">
                  <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest block mb-4">Identity Visual</label>
                  <div className="flex items-center gap-6">
                     <div 
                       onClick={() => fileInputRef.current?.click()}
                       className={`w-24 h-24 rounded-3xl border-2 border-dashed border-white/10 flex items-center justify-center cursor-pointer hover:border-${themeData.primary}/50 transition-all overflow-hidden relative group`}
                     >
                       {prefs.assistantProfilePic ? (
                         <>
                           <img src={prefs.assistantProfilePic} alt="Preview" className="w-full h-full object-cover" />
                           <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                              <i className="fas fa-camera text-white"></i>
                           </div>
                         </>
                       ) : (
                         <i className="fas fa-image text-2xl text-gray-700"></i>
                       )}
                     </div>
                     <div className="space-y-2">
                        <button onClick={() => fileInputRef.current?.click()} className="text-[10px] font-black uppercase text-blue-400 hover:text-blue-300 block">Upload Avatar</button>
                        {prefs.assistantProfilePic && (
                          <button onClick={() => setPrefs(p => ({ ...p, assistantProfilePic: undefined }))} className="text-[10px] font-black uppercase text-red-500 hover:text-red-400 block">Reset to Default</button>
                        )}
                        <input ref={fileInputRef} type="file" accept="image/*" onChange={handleProfilePicChange} className="hidden" />
                     </div>
                  </div>
                </div>

                <div className="space-y-4">
                   <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Persona</label>
                   <div className="grid grid-cols-2 gap-2">
                     {(Object.keys(PERSONALITIES) as PersonalityType[]).map(p => (
                       <button key={p} onClick={() => setPrefs(prev => ({ ...prev, personality: p }))} className={`px-4 py-3 rounded-xl border-2 transition-all font-black text-[9px] uppercase tracking-widest ${prefs.personality === p ? `bg-${themeData.primary}/10 border-${themeData.primary} text-white` : 'bg-white/5 border-white/5 text-gray-700 hover:border-white/20'}`}>{p}</button>
                     ))}
                   </div>
                   {prefs.personality === 'custom' && (
                     <div className="mt-4 animate-fade-in">
                       <label className="text-[9px] font-black text-blue-500 uppercase tracking-widest mb-2 block">Define Custom Persona</label>
                       <textarea 
                         value={prefs.customPersonality || ''}
                         onChange={(e) => setPrefs(p => ({ ...p, customPersonality: e.target.value }))}
                         placeholder="e.g. You are a futuristic navigator from the Year 3022..."
                         className="w-full bg-white/5 border border-white/10 rounded-xl py-4 px-5 text-sm focus:outline-none focus:border-blue-500/40 transition-all min-h-[100px] font-medium text-gray-200"
                       />
                     </div>
                   )}
                </div>
                <div className="space-y-4">
                  <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Name</label>
                  <input type="text" value={prefs.assistantName} onChange={(e) => setPrefs(p => ({ ...p, assistantName: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-xl py-4 px-6 font-black focus:outline-none text-lg" />
                </div>
              </section>
              {!isMobile && (
                <section className="bg-white/[0.02] border border-white/5 rounded-[3rem] p-10 space-y-8 flex flex-col justify-center text-center group">
                  <div className="relative mx-auto">
                    <div className={`absolute inset-0 bg-${themeData.primary}/10 blur-[60px] rounded-full animate-pulse`}></div>
                    {prefs.assistantProfilePic ? (
                      <img src={prefs.assistantProfilePic} className={`w-32 h-32 rounded-[2.5rem] object-cover border-4 border-${themeData.primary}/20 shadow-2xl relative z-10`} alt="Core" />
                    ) : (
                      <i className={`fas fa-wave-square text-7xl text-${themeData.primary} group-hover:scale-110 transition-transform duration-500 relative z-10`}></i>
                    )}
                  </div>
                  <h3 className="text-xl font-black uppercase tracking-widest opacity-40">Core v4.2</h3>
                </section>
              )}
            </div>
            <footer className="mt-8 lg:mt-16 flex flex-col md:flex-row items-center justify-between gap-8">
              <div className="flex items-center gap-4">
                {(Object.keys(THEMES) as UITheme[]).map(t => ( <button key={t} onClick={() => setPrefs(p => ({ ...p, theme: t }))} className={`w-10 h-10 rounded-xl border-2 transition-all ${prefs.theme === t ? 'border-white scale-125 z-10' : 'border-white/5'}`} style={{ backgroundColor: THEMES[t].bg, boxShadow: prefs.theme === t ? `0 0 20px ${THEMES[t].glow}` : 'none' }} /> ))}
              </div>
              <button onClick={() => setIsSettingsOpen(false)} className="w-full md:w-auto md:flex-1 bg-white text-black font-black py-5 lg:py-7 px-12 lg:px-16 rounded-full text-xs lg:text-sm tracking-widest uppercase shadow-3xl hover:bg-blue-50">Commit Settings</button>
            </footer>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

{
  "name": "Nova Virtual Assistant - Ultimate Edition",
  "description": "A high-fidelity AI companion featuring real-time voice, vision, deep reasoning, and secure biometric access.",
  "requestFramePermissions": [
    "microphone",
    "camera",
    "display-capture",
    "geolocation"
  ]
}

export enum AssistantState {
  IDLE = 'IDLE',
  CONNECTING = 'CONNECTING',
  LISTENING = 'LISTENING',
  SPEAKING = 'SPEAKING',
  THINKING = 'THINKING',
  OBSERVING = 'OBSERVING',
  ERROR = 'ERROR'
}

export type DeviceType = 'wear' | 'mobile' | 'desktop' | 'tv' | 'auto';

export type UITheme = 'cosmic' | 'emerald' | 'ruby' | 'obsidian';
export type PersonalityType = 'professional' | 'friendly' | 'witty' | 'minimalist' | 'alluring' | 'custom';

export interface GroundingSource {
  title: string;
  uri: string;
}

export interface SensorData {
  battery?: number;
  charging?: boolean;
  online: boolean;
  platform: string;
  location?: { lat: number; lng: number };
}

export interface TranscriptionEntry {
  id: string;
  sender: 'user' | 'assistant';
  text: string;
  timestamp: Date;
  isThinking?: boolean;
  isStreaming?: boolean;
  sources?: GroundingSource[];
}

export interface MemoryEntry {
  id: string;
  fact: string;
  timestamp: Date;
}

export interface UserPreferences {
  theme: UITheme;
  personality: PersonalityType;
  customPersonality?: string;
  layout: 'left' | 'right';
  voiceId: string;
  assistantName: string;
  assistantProfilePic?: string; // Base64 string for custom AI avatar
}

export interface AuthUser {
  username: string;
  preferences: UserPreferences;
}

import React from 'react';
import { SensorData, DeviceType } from '../types';

interface HardwareSensorsProps {
  data: SensorData;
  deviceType: DeviceType;
  themeColor: string;
}

const HardwareSensors: React.FC<HardwareSensorsProps> = ({ data, deviceType, themeColor }) => {
  return (
    <div className="flex items-center gap-4 px-4 py-2 bg-white/5 rounded-2xl border border-white/5 backdrop-blur-md">
      <div className="flex items-center gap-2 group cursor-help" title={`Platform: ${data.platform}`}>
        <i className={`fas ${deviceType === 'mobile' ? 'fa-mobile-screen' : deviceType === 'wear' ? 'fa-watch' : deviceType === 'tv' ? 'fa-tv' : deviceType === 'auto' ? 'fa-car' : 'fa-desktop'} text-[10px] text-${themeColor}`}></i>
        <span className="text-[8px] font-black uppercase tracking-widest text-gray-500 group-hover:text-white transition-colors">{deviceType}</span>
      </div>

      <div className="w-[1px] h-3 bg-white/10"></div>

      <div className="flex items-center gap-2">
        <i className={`fas ${data.online ? 'fa-wifi' : 'fa-plane'} text-[10px] ${data.online ? 'text-emerald-500' : 'text-red-500'}`}></i>
        <span className="text-[8px] font-black text-gray-500 uppercase tracking-widest">{data.online ? 'Online' : 'Offline'}</span>
      </div>

      {data.battery !== undefined && (
        <>
          <div className="w-[1px] h-3 bg-white/10"></div>
          <div className="flex items-center gap-2">
            <i className={`fas ${data.charging ? 'fa-battery-bolt' : 'fa-battery-three-quarters'} text-[10px] ${data.battery < 20 ? 'text-red-500' : 'text-emerald-500'}`}></i>
            <span className="text-[8px] font-black text-gray-500 uppercase tracking-widest">{Math.round(data.battery * 100)}%</span>
          </div>
        </>
      )}

      {data.location && (
        <>
          <div className="w-[1px] h-3 bg-white/10"></div>
          <div className="flex items-center gap-2">
            <i className={`fas fa-location-crosshairs text-[10px] text-blue-400 animate-pulse`}></i>
            <span className="text-[8px] font-black text-gray-500 uppercase tracking-widest">GPS_LOCK</span>
          </div>
        </>
      )}
    </div>
  );
};

export default HardwareSensors;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser, UITheme, PersonalityType, UserPreferences, DeviceType, SensorData } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';
import ScreenShareMode from './components/ScreenShareMode';
import GroundingSources from './components/GroundingSources';
import HardwareSensors from './components/HardwareSensors';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const THEMES: Record<UITheme, { primary: string; secondary: string; glow: string; bg: string }> = {
  cosmic: { primary: 'blue-500', secondary: 'indigo-500', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: 'emerald-500', secondary: 'teal-500', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: 'rose-500', secondary: 'orange-500', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: 'slate-400', secondary: 'zinc-500', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: VOICES[0].id,
  assistantName: 'Nova'
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [device, setDevice] = useState<DeviceType>('desktop');
  const [isScanning, setIsScanning] = useState(true);
  const [sensorData, setSensorData] = useState<SensorData>({ online: navigator.onLine, platform: navigator.platform });
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [currentSources, setCurrentSources] = useState<GroundingSource[]>([]);
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [inputText, setInputText] = useState('');
  const [searchEnabled, setSearchEnabled] = useState(true);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Advanced Device & Sensor Detection
  const detectHardware = useCallback(async () => {
    const w = window.innerWidth;
    const h = window.innerHeight;
    const ua = navigator.userAgent.toLowerCase();

    let detectedDevice: DeviceType = 'desktop';
    if (w <= 300 || (ua.includes('watch') && !ua.includes('tv'))) {
      detectedDevice = 'wear';
    } else if (ua.includes('android') && w > h && w >= 800 && w <= 1280) {
      detectedDevice = 'auto';
    } else if (ua.includes('tv') || ua.includes('smarttv') || (w >= 1920 && h >= 1080)) {
      detectedDevice = 'tv';
    } else if (w < 768 || (w < 1024 && h > w)) {
      detectedDevice = 'mobile';
    }
    setDevice(detectedDevice);

    const sensorPayload: SensorData = {
      online: navigator.onLine,
      platform: navigator.platform
    };

    if ('getBattery' in navigator) {
      try {
        const battery = await (navigator as any).getBattery();
        sensorPayload.battery = battery.level;
        sensorPayload.charging = battery.charging;
      } catch (e) {}
    }

    if (['auto', 'mobile', 'desktop'].includes(detectedDevice)) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          setSensorData(prev => ({ 
            ...prev, 
            location: { lat: pos.coords.latitude, lng: pos.coords.longitude } 
          }));
        },
        null,
        { enableHighAccuracy: true }
      );
    }

    setSensorData(prev => ({ ...prev, ...sensorPayload }));
    // Scanning phase aesthetic
    setTimeout(() => setIsScanning(false), 2500);
  }, []);

  useEffect(() => {
    detectHardware();
    window.addEventListener('resize', detectHardware);
    window.addEventListener('online', () => setSensorData(p => ({ ...p, online: true })));
    window.addEventListener('offline', () => setSensorData(p => ({ ...p, online: false })));
    return () => window.removeEventListener('resize', detectHardware);
  }, [detectHardware]);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
      setUser({ username: sessionUser, preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS });
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      setMemories(JSON.parse(localStorage.getItem(`nova_${user.username}_memories`) || '[]'));
      setTranscriptions(JSON.parse(localStorage.getItem(`nova_${user.username}_logs`) || '[]'));
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme], [prefs.theme]);

  const scrollToTop = () => { if (scrollRef.current) scrollRef.current.scrollTo({ top: 0, behavior: 'smooth' }); };
  const scrollToBottom = () => { if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' }); };

  const addTranscription = useCallback((sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  }, []);

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
    setCurrentSources([]);
  }, [screenStream]);

  const handleLogout = useCallback(() => {
    stopSession();
    setUser(null);
    sessionStorage.removeItem('nova_session_user');
  }, [stopSession]);

  const handleProfilePicChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setPrefs(p => ({ ...p, assistantProfilePic: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const startSession = async (initialText?: string) => {
    try {
      setState(AssistantState.CONNECTING);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      audioUtils.playLinkSound(outputCtx);

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const facts = memories.map(m => m.fact).join('; ');
      const personalityPrompt = prefs.personality === 'custom' ? (prefs.customPersonality || 'Be helpful.') : PERSONALITIES[prefs.personality];

      const tools: any[] = [{ functionDeclarations: [saveKnowledgeTool] }];
      if (searchEnabled) tools.push({ googleSearch: {} });
      if (sensorData.location) tools.push({ googleMaps: {} });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools,
          toolConfig: sensorData.location ? {
            retrievalConfig: {
              latLng: {
                latitude: sensorData.location.lat,
                longitude: sensorData.location.lng
              }
            }
          } : undefined,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. Platform: ${device}. Location: ${JSON.stringify(sensorData.location)}. Personality: ${personalityPrompt}. Status: ${JSON.stringify(sensorData)}. Response: Real-time, highly intelligent, emotive.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = audioUtils.createPcmBlob(inputData);
              sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: pcmBlob }); });
              if (currentFrameRef.current) {
                const frame = currentFrameRef.current;
                currentFrameRef.current = null;
                sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } }); });
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
            if (initialText) sessionPromise.then(s => s.sendRealtimeInput({ parts: [{ text: initialText }] }));
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = (fc.args as any).fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => { if (sessionRef.current) s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Memory saved." } } }); });
                }
              }
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); 
              s.buffer = buffer; 
              s.connect(outputCtx.destination);
              s.onended = () => { 
                activeSourcesRef.current.delete(s); 
                if (activeSourcesRef.current.size === 0 && sessionRef.current) setState(AssistantState.LISTENING); 
              };
              s.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration; 
              activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            if (message.serverContent?.turnComplete) {
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) {
                addTranscription('assistant', a, currentSources);
                audioUtils.playSuccessSound(outputCtx);
              } return ''; });
              setCurrentSources([]);
            }
          },
          onerror: (err) => stopSession(),
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setState(AssistantState.IDLE); }
  };

  const handleSendText = async () => {
    if (!inputText.trim()) return;
    const msg = inputText.trim();
    setInputText('');
    addTranscription('user', msg);
    if (sessionRef.current) {
      setState(AssistantState.THINKING);
      sessionRef.current.sendRealtimeInput({ parts: [{ text: msg }] });
    } else {
      startSession(msg);
    }
  };

  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;

  // Scanning Phase Overlay
  if (isScanning) {
    return (
      <div className="fixed inset-0 bg-[#02020a] flex flex-col items-center justify-center z-[200] animate-fade-in">
        <div className="relative w-64 h-64 flex items-center justify-center">
          <div className={`absolute inset-0 border-4 border-t-${themeData.primary} border-r-transparent border-b-transparent border-l-transparent rounded-full animate-spin`}></div>
          <div className={`absolute inset-4 border-2 border-b-${themeData.secondary} border-t-transparent border-r-transparent border-l-transparent rounded-full animate-spin`} style={{ animationDirection: 'reverse', animationDuration: '3s' }}></div>
          <i className="fas fa-microchip text-4xl text-white/20"></i>
        </div>
        <div className="mt-12 text-center">
          <h2 className="text-xl font-black tracking-[0.5em] uppercase text-white mb-2">Scanning Hardware</h2>
          <p className="text-[10px] font-mono text-gray-500">{sensorData.platform} // ENV_CALIBRATION</p>
        </div>
      </div>
    );
  }

  // Identity Icon Generator
  const renderIdentity = (size: string) => (
    <div className={`${size} rounded-[2rem] overflow-hidden border border-white/10 shadow-2xl relative group`}>
      {prefs.assistantProfilePic ? (
        <img src={prefs.assistantProfilePic} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt="AI" />
      ) : (
        <div className={`w-full h-full bg-${themeData.primary}/10 flex items-center justify-center`}>
          <i className="fas fa-atom text-2xl text-white"></i>
        </div>
      )}
      <div className={`absolute inset-0 bg-${themeData.primary}/20 mix-blend-overlay animate-pulse-slow`}></div>
    </div>
  );

  // VIEW RENDERING BY DEVICE
  if (device === 'wear') {
    return (
      <div className="wear-screen">
        <div className="flex flex-col items-center justify-center p-8 space-y-4">
          <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
          <button onClick={state === AssistantState.IDLE ? () => startSession() : stopSession} className={`w-14 h-14 rounded-full flex items-center justify-center ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500'}`}>
            <i className={`fas ${state === AssistantState.IDLE ? 'fa-play' : 'fa-stop'}`}></i>
          </button>
        </div>
      </div>
    );
  }

  if (device === 'auto') {
    return (
      <div className="h-full w-full bg-black p-12 flex gap-12 items-center">
        <div className="w-1/3 flex flex-col items-center gap-8">
           {renderIdentity('w-64 h-64')}
           <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
           <button onClick={state === AssistantState.IDLE ? () => startSession() : stopSession} className="w-full py-8 bg-white text-black rounded-[2rem] font-black uppercase tracking-widest text-2xl">
             {state === AssistantState.IDLE ? 'Activate' : 'End Trip'}
           </button>
        </div>
        <div className="flex-1 bg-white/5 rounded-[4rem] p-12 h-full overflow-hidden border border-white/10">
           <div className="h-full flex flex-col">
              <div className="flex-1 overflow-y-auto space-y-8 pr-4 scrollbar-thin">
                {transcriptions.map(e => (
                  <div key={e.id} className="text-3xl font-bold opacity-60">
                    <span className="text-blue-400">[{e.sender}]</span> {e.text}
                  </div>
                ))}
              </div>
              {streamingAssistantText && <div className="text-4xl font-black text-white mt-4">{streamingAssistantText}</div>}
           </div>
        </div>
      </div>
    );
  }

  // DEFAULT (Desktop/Mobile/TV)
  return (
    <div className={`flex flex-col h-full w-full transition-colors duration-1000 ${device === 'tv' ? 'scale-110 origin-top' : ''}`} style={{ backgroundColor: themeData.bg }}>
      <header className="px-6 py-4 lg:px-12 lg:py-8 flex items-center justify-between z-50">
        <div className="flex items-center gap-4 lg:gap-8">
          {renderIdentity('w-12 h-12 lg:w-16 lg:h-16')}
          <div>
            <h1 className="text-xl lg:text-3xl font-black tracking-tighter bg-gradient-to-r from-white to-gray-500 bg-clip-text text-transparent">{prefs.assistantName}</h1>
            <HardwareSensors data={sensorData} deviceType={device} themeColor={themeData.primary} />
          </div>
        </div>
        <div className="flex items-center gap-4">
           {!isMobile && (
             <button onClick={() => setIsSettingsOpen(true)} className="w-12 h-12 rounded-2xl bg-white/5 hover:bg-white/10 flex items-center justify-center transition-colors">
               <i className="fas fa-cog text-gray-400"></i>
             </button>
           )}
           <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isMemoryOpen ? 'bg-blue-500 text-white' : 'bg-white/5 text-gray-400'}`}>
             <i className="fas fa-brain"></i>
           </button>
           <button onClick={handleLogout} className="text-gray-600 hover:text-white transition-colors">
             <i className="fas fa-sign-out-alt"></i>
           </button>
        </div>
      </header>

      <main className="flex-1 flex flex-col md:flex-row min-h-0 p-4 lg:p-12 gap-8">
        <div className="flex-1 flex flex-col bg-white/[0.02] rounded-[3rem] border border-white/5 overflow-hidden backdrop-blur-3xl relative">
          <div className="flex-1 p-6 lg:p-12 overflow-y-auto space-y-8 scrollbar-thin" ref={scrollRef}>
             {transcriptions.length === 0 && (
               <div className="h-full flex flex-col items-center justify-center opacity-10">
                 <i className="fas fa-atom text-9xl mb-8"></i>
                 <p className="text-2xl font-black uppercase tracking-[1em]">Listening</p>
               </div>
             )}
             {transcriptions.map(e => (
               <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'}`}>
                 <div className={`max-w-[85%] px-8 py-4 rounded-[2rem] ${e.sender === 'user' ? `bg-${themeData.primary} text-white` : 'bg-white/5 text-gray-300'}`}>
                   <p className="text-sm font-medium">{e.text}</p>
                   {e.sources && <GroundingSources sources={e.sources} themePrimary={themeData.primary} />}
                 </div>
               </div>
             ))}
             {streamingAssistantText && (
               <div className="flex flex-col items-start animate-fade-in">
                 <div className="max-w-[85%] px-8 py-4 rounded-[2rem] bg-white/10 text-white">
                   <p className="text-sm font-medium">{streamingAssistantText}</p>
                 </div>
               </div>
             )}
          </div>

          <div className="p-6 lg:p-10 border-t border-white/5 bg-black/40 relative">
             <div className="absolute right-8 -top-12 flex gap-2">
                <button onClick={scrollToTop} className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-xs text-gray-500 hover:text-white"><i className="fas fa-arrow-up"></i></button>
                <button onClick={scrollToBottom} className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-xs text-gray-500 hover:text-white"><i className="fas fa-arrow-down"></i></button>
             </div>
             <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
             <div className="mt-6 flex gap-4">
                <input 
                  type="text" 
                  value={inputText}
                  onChange={(e) => setInputText(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSendText()}
                  placeholder={`Command ${prefs.assistantName}...`}
                  className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-6 py-4 focus:outline-none focus:border-blue-500/40 transition-all"
                />
                <button 
                  onClick={state === AssistantState.IDLE ? () => startSession() : stopSession}
                  className={`w-16 h-16 rounded-2xl flex items-center justify-center transition-all ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500 text-white animate-pulse'}`}
                >
                  <i className={`fas ${state === AssistantState.IDLE ? 'fa-microphone' : 'fa-square'}`}></i>
                </button>
             </div>
          </div>
        </div>

        {isMemoryOpen && (
          <div className="w-full md:w-[360px] animate-slide-in-right">
             <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
          </div>
        )}
      </main>

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[150] bg-black/95 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
          <div className="w-full max-w-4xl bg-[#02020a] border border-white/10 rounded-[4rem] p-12 relative">
             <button onClick={() => setIsSettingsOpen(false)} className="absolute top-12 right-12 text-gray-700 hover:text-white text-2xl"><i className="fas fa-times"></i></button>
             <h2 className="text-4xl font-black tracking-tighter uppercase mb-12">Configuration</h2>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                <section className="space-y-8">
                   <div className="space-y-4">
                      <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Avatar Signature</label>
                      <div className="flex items-center gap-6">
                        <div className="w-24 h-24 rounded-3xl overflow-hidden border-2 border-dashed border-white/10 flex items-center justify-center">
                           {prefs.assistantProfilePic ? <img src={prefs.assistantProfilePic} className="w-full h-full object-cover" alt="S" /> : <i className="fas fa-camera text-gray-800"></i>}
                        </div>
                        <button onClick={() => fileInputRef.current?.click()} className="px-6 py-3 rounded-xl bg-white/5 text-[10px] font-black uppercase tracking-widest hover:bg-white/10">Upload Image</button>
                        <input ref={fileInputRef} type="file" className="hidden" onChange={handleProfilePicChange} accept="image/*" />
                      </div>
                   </div>
                   <div className="space-y-4">
                      <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Assistant Designation</label>
                      <input type="text" value={prefs.assistantName} onChange={(e) => setPrefs(p => ({ ...p, assistantName: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 font-black text-xl" />
                   </div>
                </section>

                <section className="space-y-8">
                   <div className="space-y-4">
                      <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Neural Persona</label>
                      <div className="grid grid-cols-2 gap-3">
                         {(Object.keys(PERSONALITIES) as PersonalityType[]).map(p => (
                           <button key={p} onClick={() => setPrefs(pr => ({ ...pr, personality: p }))} className={`py-4 rounded-xl border-2 transition-all font-black text-[9px] uppercase tracking-widest ${prefs.personality === p ? `bg-blue-500/10 border-blue-500` : 'border-white/5 text-gray-700'}`}>{p}</button>
                         ))}
                      </div>
                   </div>
                   {prefs.personality === 'custom' && (
                     <textarea 
                       value={prefs.customPersonality || ''}
                       onChange={(e) => setPrefs(pr => ({ ...pr, customPersonality: e.target.value }))}
                       placeholder="Specify custom directive..."
                       className="w-full h-32 bg-white/5 border border-white/10 rounded-2xl p-4 text-sm"
                     />
                   )}
                </section>
             </div>
             <button onClick={() => setIsSettingsOpen(false)} className="mt-12 w-full py-6 bg-white text-black font-black uppercase tracking-widest rounded-full hover:scale-[1.02] transition-transform">Synchronize Core</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser, UITheme, PersonalityType, UserPreferences, DeviceType, SensorData } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';
import ScreenShareMode from './components/ScreenShareMode';
import GroundingSources from './components/GroundingSources';
import HardwareSensors from './components/HardwareSensors';

const VOICES = [
  { id: 'Zephyr', name: 'Zephyr (Smooth)' },
  { id: 'Puck', name: 'Puck (Playful)' },
  { id: 'Kore', name: 'Kore (Clear)' },
  { id: 'Charon', name: 'Charon (Deep)' },
  { id: 'Fenrir', name: 'Fenrir (Vibrant)' }
];

const THEMES: Record<UITheme, { primary: string; secondary: string; glow: string; bg: string }> = {
  cosmic: { primary: 'blue-500', secondary: 'indigo-500', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: 'emerald-500', secondary: 'teal-500', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: 'rose-500', secondary: 'orange-500', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: 'slate-400', secondary: 'zinc-500', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: VOICES[0].id,
  assistantName: 'Nova'
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [device, setDevice] = useState<DeviceType>('desktop');
  const [isScanning, setIsScanning] = useState(true);
  const [sensorData, setSensorData] = useState<SensorData>({ online: navigator.onLine, platform: navigator.platform });
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [currentSources, setCurrentSources] = useState<GroundingSource[]>([]);
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [inputText, setInputText] = useState('');
  const [searchEnabled, setSearchEnabled] = useState(true);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Advanced Device & Sensor Detection
  const detectHardware = useCallback(async () => {
    const w = window.innerWidth;
    const h = window.innerHeight;
    const ua = navigator.userAgent.toLowerCase();

    let detectedDevice: DeviceType = 'desktop';
    if (w <= 300 || (ua.includes('watch') && !ua.includes('tv'))) {
      detectedDevice = 'wear';
    } else if (ua.includes('android') && w > h && w >= 800 && w <= 1280) {
      detectedDevice = 'auto';
    } else if (ua.includes('tv') || ua.includes('smarttv') || (w >= 1920 && h >= 1080)) {
      detectedDevice = 'tv';
    } else if (w < 768 || (w < 1024 && h > w)) {
      detectedDevice = 'mobile';
    }
    setDevice(detectedDevice);

    const sensorPayload: SensorData = {
      online: navigator.onLine,
      platform: navigator.platform
    };

    if ('getBattery' in navigator) {
      try {
        const battery = await (navigator as any).getBattery();
        sensorPayload.battery = battery.level;
        sensorPayload.charging = battery.charging;
      } catch (e) {}
    }

    if (['auto', 'mobile', 'desktop'].includes(detectedDevice)) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          setSensorData(prev => ({ 
            ...prev, 
            location: { lat: pos.coords.latitude, lng: pos.coords.longitude } 
          }));
        },
        null,
        { enableHighAccuracy: true }
      );
    }

    setSensorData(prev => ({ ...prev, ...sensorPayload }));
    // Scanning phase aesthetic
    setTimeout(() => setIsScanning(false), 2500);
  }, []);

  useEffect(() => {
    detectHardware();
    window.addEventListener('resize', detectHardware);
    window.addEventListener('online', () => setSensorData(p => ({ ...p, online: true })));
    window.addEventListener('offline', () => setSensorData(p => ({ ...p, online: false })));
    return () => window.removeEventListener('resize', detectHardware);
  }, [detectHardware]);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
      setUser({ username: sessionUser, preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS });
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      setMemories(JSON.parse(localStorage.getItem(`nova_${user.username}_memories`) || '[]'));
      setTranscriptions(JSON.parse(localStorage.getItem(`nova_${user.username}_logs`) || '[]'));
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme], [prefs.theme]);

  // Derived state to fix missing isMobile variable
  const isMobile = useMemo(() => device === 'mobile' || device === 'wear', [device]);

  const scrollToTop = () => { if (scrollRef.current) scrollRef.current.scrollTo({ top: 0, behavior: 'smooth' }); };
  const scrollToBottom = () => { if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' }); };

  const addTranscription = useCallback((sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  }, []);

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
    setCurrentSources([]);
  }, [screenStream]);

  const handleLogout = useCallback(() => {
    stopSession();
    setUser(null);
    sessionStorage.removeItem('nova_session_user');
  }, [stopSession]);

  const handleProfilePicChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setPrefs(p => ({ ...p, assistantProfilePic: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const startSession = async (initialText?: string) => {
    try {
      setState(AssistantState.CONNECTING);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      audioUtils.playLinkSound(outputCtx);

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const personalityPrompt = prefs.personality === 'custom' ? (prefs.customPersonality || 'Be helpful.') : PERSONALITIES[prefs.personality];

      const tools: any[] = [{ functionDeclarations: [saveKnowledgeTool] }];
      if (searchEnabled) tools.push({ googleSearch: {} });
      if (sensorData.location) tools.push({ googleMaps: {} });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools,
          toolConfig: sensorData.location ? {
            retrievalConfig: {
              latLng: {
                latitude: sensorData.location.lat,
                longitude: sensorData.location.lng
              }
            }
          } : undefined,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. Platform: ${device}. Location: ${JSON.stringify(sensorData.location)}. Personality: ${personalityPrompt}. Status: ${JSON.stringify(sensorData)}. Response: Real-time, highly intelligent, emotive.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = audioUtils.createPcmBlob(inputData);
              sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: pcmBlob }); });
              if (currentFrameRef.current) {
                const frame = currentFrameRef.current;
                currentFrameRef.current = null;
                sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } }); });
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
            if (initialText) sessionPromise.then(s => s.sendRealtimeInput({ parts: [{ text: initialText }] }));
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = (fc.args as any).fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => { if (sessionRef.current) s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Memory saved." } } }); });
                }
              }
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); 
              s.buffer = buffer; 
              s.connect(outputCtx.destination);
              s.onended = () => { 
                activeSourcesRef.current.delete(s); 
                if (activeSourcesRef.current.size === 0 && sessionRef.current) setState(AssistantState.LISTENING); 
              };
              s.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration; 
              activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            if (message.serverContent?.turnComplete) {
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) {
                addTranscription('assistant', a, currentSources);
                audioUtils.playSuccessSound(outputCtx);
              } return ''; });
              setCurrentSources([]);
            }
          },
          onerror: (err) => stopSession(),
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setState(AssistantState.IDLE); }
  };

  const handleSendText = async () => {
    if (!inputText.trim()) return;
    const msg = inputText.trim();
    setInputText('');
    addTranscription('user', msg);
    if (sessionRef.current) {
      setState(AssistantState.THINKING);
      sessionRef.current.sendRealtimeInput({ parts: [{ text: msg }] });
    } else {
      startSession(msg);
    }
  };

  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;

  // Scanning Phase Overlay
  if (isScanning) {
    return (
      <div className="fixed inset-0 bg-[#02020a] flex flex-col items-center justify-center z-[200] animate-fade-in">
        <div className="relative w-64 h-64 flex items-center justify-center">
          <div className={`absolute inset-0 border-4 border-t-${themeData.primary} border-r-transparent border-b-transparent border-l-transparent rounded-full animate-spin`}></div>
          <div className={`absolute inset-4 border-2 border-b-${themeData.secondary} border-t-transparent border-r-transparent border-l-transparent rounded-full animate-spin`} style={{ animationDirection: 'reverse', animationDuration: '3s' }}></div>
          <i className="fas fa-microchip text-4xl text-white/20"></i>
        </div>
        <div className="mt-12 text-center">
          <h2 className="text-xl font-black tracking-[0.5em] uppercase text-white mb-2">Scanning Hardware</h2>
          <p className="text-[10px] font-mono text-gray-500">{sensorData.platform} // ENV_CALIBRATION</p>
        </div>
      </div>
    );
  }

  // Identity Icon Generator
  const renderIdentity = (size: string) => (
    <div className={`${size} rounded-[2rem] overflow-hidden border border-white/10 shadow-2xl relative group`}>
      {prefs.assistantProfilePic ? (
        <img src={prefs.assistantProfilePic} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt="AI" />
      ) : (
        <div className={`w-full h-full bg-${themeData.primary}/10 flex items-center justify-center`}>
          <i className="fas fa-atom text-2xl text-white"></i>
        </div>
      )}
      <div className={`absolute inset-0 bg-${themeData.primary}/20 mix-blend-overlay animate-pulse-slow`}></div>
    </div>
  );

  // VIEW RENDERING BY DEVICE
  if (device === 'wear') {
    return (
      <div className="wear-screen">
        <div className="flex flex-col items-center justify-center p-8 space-y-4">
          <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
          <button onClick={state === AssistantState.IDLE ? () => startSession() : stopSession} className={`w-14 h-14 rounded-full flex items-center justify-center ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500'}`}>
            <i className={`fas ${state === AssistantState.IDLE ? 'fa-play' : 'fa-stop'}`}></i>
          </button>
        </div>
      </div>
    );
  }

  if (device === 'auto') {
    return (
      <div className="h-full w-full bg-black p-12 flex gap-12 items-center">
        <div className="w-1/3 flex flex-col items-center gap-8">
           {renderIdentity('w-64 h-64')}
           <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
           <button onClick={state === AssistantState.IDLE ? () => startSession() : stopSession} className="w-full py-8 bg-white text-black rounded-[2rem] font-black uppercase tracking-widest text-2xl">
             {state === AssistantState.IDLE ? 'Activate' : 'End Trip'}
           </button>
        </div>
        <div className="flex-1 bg-white/5 rounded-[4rem] p-12 h-full overflow-hidden border border-white/10">
           <div className="h-full flex flex-col">
              <div className="flex-1 overflow-y-auto space-y-8 pr-4 scrollbar-thin">
                {transcriptions.map(e => (
                  <div key={e.id} className="text-3xl font-bold opacity-60">
                    <span className="text-blue-400">[{e.sender}]</span> {e.text}
                  </div>
                ))}
              </div>
              {streamingAssistantText && <div className="text-4xl font-black text-white mt-4">{streamingAssistantText}</div>}
           </div>
        </div>
      </div>
    );
  }

  // DEFAULT (Desktop/Mobile/TV)
  return (
    <div className={`flex flex-col h-full w-full transition-colors duration-1000 ${device === 'tv' ? 'scale-110 origin-top' : ''}`} style={{ backgroundColor: themeData.bg }}>
      <header className="px-6 py-4 lg:px-12 lg:py-8 flex items-center justify-between z-50">
        <div className="flex items-center gap-4 lg:gap-8">
          {renderIdentity('w-12 h-12 lg:w-16 lg:h-16')}
          <div>
            <h1 className="text-xl lg:text-3xl font-black tracking-tighter bg-gradient-to-r from-white to-gray-500 bg-clip-text text-transparent">{prefs.assistantName}</h1>
            <HardwareSensors data={sensorData} deviceType={device} themeColor={themeData.primary} />
          </div>
        </div>
        <div className="flex items-center gap-4">
           {!isMobile && (
             <button onClick={() => setIsSettingsOpen(true)} className="w-12 h-12 rounded-2xl bg-white/5 hover:bg-white/10 flex items-center justify-center transition-colors">
               <i className="fas fa-cog text-gray-400"></i>
             </button>
           )}
           <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isMemoryOpen ? 'bg-blue-500 text-white' : 'bg-white/5 text-gray-400'}`}>
             <i className="fas fa-brain"></i>
           </button>
           <button onClick={handleLogout} className="text-gray-600 hover:text-white transition-colors">
             <i className="fas fa-sign-out-alt"></i>
           </button>
        </div>
      </header>

      <main className="flex-1 flex flex-col md:flex-row min-h-0 p-4 lg:p-12 gap-8">
        <div className="flex-1 flex flex-col bg-white/[0.02] rounded-[3rem] border border-white/5 overflow-hidden backdrop-blur-3xl relative">
          <div className="flex-1 p-6 lg:p-12 overflow-y-auto space-y-8 scrollbar-thin" ref={scrollRef}>
             {transcriptions.length === 0 && (
               <div className="h-full flex flex-col items-center justify-center opacity-10">
                 <i className="fas fa-atom text-9xl mb-8"></i>
                 <p className="text-2xl font-black uppercase tracking-[1em]">Listening</p>
               </div>
             )}
             {transcriptions.map(e => (
               <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'}`}>
                 <div className={`max-w-[85%] px-8 py-4 rounded-[2rem] ${e.sender === 'user' ? `bg-${themeData.primary} text-white` : 'bg-white/5 text-gray-300'}`}>
                   <p className="text-sm font-medium">{e.text}</p>
                   {e.sources && <GroundingSources sources={e.sources} themePrimary={themeData.primary} />}
                 </div>
               </div>
             ))}
             {streamingAssistantText && (
               <div className="flex flex-col items-start animate-fade-in">
                 <div className="max-w-[85%] px-8 py-4 rounded-[2rem] bg-white/10 text-white">
                   <p className="text-sm font-medium">{streamingAssistantText}</p>
                 </div>
               </div>
             )}
          </div>

          <div className="p-6 lg:p-10 border-t border-white/5 bg-black/40 relative">
             <div className="absolute right-8 -top-12 flex gap-2">
                <button onClick={scrollToTop} className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-xs text-gray-500 hover:text-white"><i className="fas fa-arrow-up"></i></button>
                <button onClick={scrollToBottom} className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-xs text-gray-500 hover:text-white"><i className="fas fa-arrow-down"></i></button>
             </div>
             <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
             <div className="mt-6 flex gap-4">
                <input 
                  type="text" 
                  value={inputText}
                  onChange={(e) => setInputText(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSendText()}
                  placeholder={`Command ${prefs.assistantName}...`}
                  className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-6 py-4 focus:outline-none focus:border-blue-500/40 transition-all"
                />
                <button 
                  onClick={state === AssistantState.IDLE ? () => startSession() : stopSession}
                  className={`w-16 h-16 rounded-2xl flex items-center justify-center transition-all ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500 text-white animate-pulse'}`}
                >
                  <i className={`fas ${state === AssistantState.IDLE ? 'fa-microphone' : 'fa-square'}`}></i>
                </button>
             </div>
          </div>
        </div>

        {isMemoryOpen && (
          <div className="w-full md:w-[360px] animate-slide-in-right">
             <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
          </div>
        )}
      </main>

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[150] bg-black/95 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
          <div className="w-full max-w-4xl bg-[#02020a] border border-white/10 rounded-[4rem] p-12 relative">
             <button onClick={() => setIsSettingsOpen(false)} className="absolute top-12 right-12 text-gray-700 hover:text-white text-2xl"><i className="fas fa-times"></i></button>
             <h2 className="text-4xl font-black tracking-tighter uppercase mb-12">Configuration</h2>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                <section className="space-y-8">
                   <div className="space-y-4">
                      <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Avatar Signature</label>
                      <div className="flex items-center gap-6">
                        <div className="w-24 h-24 rounded-3xl overflow-hidden border-2 border-dashed border-white/10 flex items-center justify-center">
                           {prefs.assistantProfilePic ? <img src={prefs.assistantProfilePic} className="w-full h-full object-cover" alt="S" /> : <i className="fas fa-camera text-gray-800"></i>}
                        </div>
                        <button onClick={() => fileInputRef.current?.click()} className="px-6 py-3 rounded-xl bg-white/5 text-[10px] font-black uppercase tracking-widest hover:bg-white/10">Upload Image</button>
                        <input ref={fileInputRef} type="file" className="hidden" onChange={handleProfilePicChange} accept="image/*" />
                      </div>
                   </div>
                   <div className="space-y-4">
                      <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Assistant Designation</label>
                      <input type="text" value={prefs.assistantName} onChange={(e) => setPrefs(p => ({ ...p, assistantName: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 font-black text-xl" />
                   </div>
                </section>

                <section className="space-y-8">
                   <div className="space-y-4">
                      <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Neural Persona</label>
                      <div className="grid grid-cols-2 gap-3">
                         {(Object.keys(PERSONALITIES) as PersonalityType[]).map(p => (
                           <button key={p} onClick={() => setPrefs(pr => ({ ...pr, personality: p }))} className={`py-4 rounded-xl border-2 transition-all font-black text-[9px] uppercase tracking-widest ${prefs.personality === p ? `bg-blue-500/10 border-blue-500` : 'border-white/5 text-gray-700'}`}>{p}</button>
                         ))}
                      </div>
                   </div>
                   {prefs.personality === 'custom' && (
                     <textarea 
                       value={prefs.customPersonality || ''}
                       onChange={(e) => setPrefs(pr => ({ ...pr, customPersonality: e.target.value }))}
                       placeholder="Specify custom directive..."
                       className="w-full h-32 bg-white/5 border border-white/10 rounded-2xl p-4 text-sm"
                     />
                   )}
                </section>
             </div>
             <button onClick={() => setIsSettingsOpen(false)} className="mt-12 w-full py-6 bg-white text-black font-black uppercase tracking-widest rounded-full hover:scale-[1.02] transition-transform">Synchronize Core</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser, UITheme, PersonalityType, UserPreferences, DeviceType, SensorData } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';
import ScreenShareMode from './components/ScreenShareMode';
import GroundingSources from './components/GroundingSources';
import HardwareSensors from './components/HardwareSensors';

const VOICES = [
  { id: 'Charon', name: 'Charon', tone: 'Deep & Authoritative', gender: 'masculine' },
  { id: 'Puck', name: 'Puck', tone: 'Playful & Energetic', gender: 'masculine' },
  { id: 'Fenrir', name: 'Fenrir', tone: 'Sharp & Vibrant', gender: 'masculine' },
  { id: 'Kore', name: 'Kore', tone: 'Clear & Professional', gender: 'feminine' },
  { id: 'Zephyr', name: 'Zephyr', tone: 'Warm & Smooth', gender: 'feminine' },
  { id: 'Aoede', name: 'Aoede', tone: 'Serene & Classical', gender: 'feminine' }
];

const THEMES: Record<UITheme, { primary: string; secondary: string; glow: string; bg: string }> = {
  cosmic: { primary: 'blue-500', secondary: 'indigo-500', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: 'emerald-500', secondary: 'teal-500', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: 'rose-500', secondary: 'orange-500', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: 'slate-400', secondary: 'zinc-500', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: VOICES[0].id,
  assistantName: 'Nova'
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [device, setDevice] = useState<DeviceType>('desktop');
  const [isScanning, setIsScanning] = useState(true);
  const [sensorData, setSensorData] = useState<SensorData>({ online: navigator.onLine, platform: navigator.platform });
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [currentSources, setCurrentSources] = useState<GroundingSource[]>([]);
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [inputText, setInputText] = useState('');
  const [searchEnabled, setSearchEnabled] = useState(true);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Advanced Device & Sensor Detection
  const detectHardware = useCallback(async () => {
    const w = window.innerWidth;
    const h = window.innerHeight;
    const ua = navigator.userAgent.toLowerCase();

    let detectedDevice: DeviceType = 'desktop';
    if (w <= 300 || (ua.includes('watch') && !ua.includes('tv'))) {
      detectedDevice = 'wear';
    } else if (ua.includes('android') && w > h && w >= 800 && w <= 1280) {
      detectedDevice = 'auto';
    } else if (ua.includes('tv') || ua.includes('smarttv') || (w >= 1920 && h >= 1080)) {
      detectedDevice = 'tv';
    } else if (w < 768 || (w < 1024 && h > w)) {
      detectedDevice = 'mobile';
    }
    setDevice(detectedDevice);

    const sensorPayload: SensorData = {
      online: navigator.onLine,
      platform: navigator.platform
    };

    if ('getBattery' in navigator) {
      try {
        const battery = await (navigator as any).getBattery();
        sensorPayload.battery = battery.level;
        sensorPayload.charging = battery.charging;
      } catch (e) {}
    }

    if (['auto', 'mobile', 'desktop'].includes(detectedDevice)) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          setSensorData(prev => ({ 
            ...prev, 
            location: { lat: pos.coords.latitude, lng: pos.coords.longitude } 
          }));
        },
        null,
        { enableHighAccuracy: true }
      );
    }

    setSensorData(prev => ({ ...prev, ...sensorPayload }));
    // Scanning phase aesthetic
    setTimeout(() => setIsScanning(false), 2500);
  }, []);

  useEffect(() => {
    detectHardware();
    window.addEventListener('resize', detectHardware);
    window.addEventListener('online', () => setSensorData(p => ({ ...p, online: true })));
    window.addEventListener('offline', () => setSensorData(p => ({ ...p, online: false })));
    return () => window.removeEventListener('resize', detectHardware);
  }, [detectHardware]);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
      setUser({ username: sessionUser, preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS });
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      setMemories(JSON.parse(localStorage.getItem(`nova_${user.username}_memories`) || '[]'));
      setTranscriptions(JSON.parse(localStorage.getItem(`nova_${user.username}_logs`) || '[]'));
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme], [prefs.theme]);

  // Derived state to fix missing isMobile variable
  const isMobile = useMemo(() => device === 'mobile' || device === 'wear', [device]);

  const scrollToTop = () => { if (scrollRef.current) scrollRef.current.scrollTo({ top: 0, behavior: 'smooth' }); };
  const scrollToBottom = () => { if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' }); };

  const addTranscription = useCallback((sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  }, []);

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
    setCurrentSources([]);
  }, [screenStream]);

  const handleLogout = useCallback(() => {
    stopSession();
    setUser(null);
    sessionStorage.removeItem('nova_session_user');
  }, [stopSession]);

  const handleProfilePicChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setPrefs(p => ({ ...p, assistantProfilePic: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const startSession = async (initialText?: string) => {
    try {
      setState(AssistantState.CONNECTING);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      audioUtils.playLinkSound(outputCtx);

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const personalityPrompt = prefs.personality === 'custom' ? (prefs.customPersonality || 'Be helpful.') : PERSONALITIES[prefs.personality];

      const tools: any[] = [{ functionDeclarations: [saveKnowledgeTool] }];
      if (searchEnabled) tools.push({ googleSearch: {} });
      if (sensorData.location) tools.push({ googleMaps: {} });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools,
          toolConfig: sensorData.location ? {
            retrievalConfig: {
              latLng: {
                latitude: sensorData.location.lat,
                longitude: sensorData.location.lng
              }
            }
          } : undefined,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. Platform: ${device}. Location: ${JSON.stringify(sensorData.location)}. Personality: ${personalityPrompt}. Status: ${JSON.stringify(sensorData)}. Response: Real-time, highly intelligent, emotive.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = audioUtils.createPcmBlob(inputData);
              sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: pcmBlob }); });
              if (currentFrameRef.current) {
                const frame = currentFrameRef.current;
                currentFrameRef.current = null;
                sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } }); });
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
            if (initialText) sessionPromise.then(s => s.sendRealtimeInput({ parts: [{ text: initialText }] }));
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = (fc.args as any).fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => { if (sessionRef.current) s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Memory saved." } } }); });
                }
              }
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); 
              s.buffer = buffer; 
              s.connect(outputCtx.destination);
              s.onended = () => { 
                activeSourcesRef.current.delete(s); 
                if (activeSourcesRef.current.size === 0 && sessionRef.current) setState(AssistantState.LISTENING); 
              };
              s.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration; 
              activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            if (message.serverContent?.turnComplete) {
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) {
                addTranscription('assistant', a, currentSources);
                audioUtils.playSuccessSound(outputCtx);
              } return ''; });
              setCurrentSources([]);
            }
          },
          onerror: (err) => stopSession(),
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setState(AssistantState.IDLE); }
  };

  const handleSendText = async () => {
    if (!inputText.trim()) return;
    const msg = inputText.trim();
    setInputText('');
    addTranscription('user', msg);
    if (sessionRef.current) {
      setState(AssistantState.THINKING);
      sessionRef.current.sendRealtimeInput({ parts: [{ text: msg }] });
    } else {
      startSession(msg);
    }
  };

  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;

  // Scanning Phase Overlay
  if (isScanning) {
    return (
      <div className="fixed inset-0 bg-[#02020a] flex flex-col items-center justify-center z-[200] animate-fade-in">
        <div className="relative w-64 h-64 flex items-center justify-center">
          <div className={`absolute inset-0 border-4 border-t-${themeData.primary} border-r-transparent border-b-transparent border-l-transparent rounded-full animate-spin`}></div>
          <div className={`absolute inset-4 border-2 border-b-${themeData.secondary} border-t-transparent border-r-transparent border-l-transparent rounded-full animate-spin`} style={{ animationDirection: 'reverse', animationDuration: '3s' }}></div>
          <i className="fas fa-microchip text-4xl text-white/20"></i>
        </div>
        <div className="mt-12 text-center">
          <h2 className="text-xl font-black tracking-[0.5em] uppercase text-white mb-2">Scanning Hardware</h2>
          <p className="text-[10px] font-mono text-gray-500">{sensorData.platform} // ENV_CALIBRATION</p>
        </div>
      </div>
    );
  }

  // Identity Icon Generator
  const renderIdentity = (size: string) => (
    <div className={`${size} rounded-[2rem] overflow-hidden border border-white/10 shadow-2xl relative group`}>
      {prefs.assistantProfilePic ? (
        <img src={prefs.assistantProfilePic} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt="AI" />
      ) : (
        <div className={`w-full h-full bg-${themeData.primary}/10 flex items-center justify-center`}>
          <i className="fas fa-atom text-2xl text-white"></i>
        </div>
      )}
      <div className={`absolute inset-0 bg-${themeData.primary}/20 mix-blend-overlay animate-pulse-slow`}></div>
    </div>
  );

  // VIEW RENDERING BY DEVICE
  if (device === 'wear') {
    return (
      <div className="wear-screen">
        <div className="flex flex-col items-center justify-center p-8 space-y-4">
          <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
          <button onClick={state === AssistantState.IDLE ? () => startSession() : stopSession} className={`w-14 h-14 rounded-full flex items-center justify-center ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500'}`}>
            <i className={`fas ${state === AssistantState.IDLE ? 'fa-play' : 'fa-stop'}`}></i>
          </button>
        </div>
      </div>
