  if (device === 'auto') {
    return (
      <div className="h-full w-full bg-black p-12 flex gap-12 items-center">
        <div className="w-1/3 flex flex-col items-center gap-8">
           {renderIdentity('w-64 h-64')}
           <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
           <button onClick={state === AssistantState.IDLE ? () => startSession() : stopSession} className="w-full py-8 bg-white text-black rounded-[2rem] font-black uppercase tracking-widest text-2xl">
             {state === AssistantState.IDLE ? 'Activate' : 'End Trip'}
           </button>
        </div>
        <div className="flex-1 bg-white/5 rounded-[4rem] p-12 h-full overflow-hidden border border-white/10">
           <div className="h-full flex flex-col">
              <div className="flex-1 overflow-y-auto space-y-8 pr-4 scrollbar-thin">
                {transcriptions.map(e => (
                  <div key={e.id} className="text-3xl font-bold opacity-60">
                    <span className="text-blue-400">[{e.sender}]</span> {e.text}
                  </div>
                ))}
              </div>
              {streamingAssistantText && <div className="text-4xl font-black text-white mt-4">{streamingAssistantText}</div>}
           </div>
        </div>
      </div>
    );
  }

  // DEFAULT (Desktop/Mobile/TV)
  return (
    <div className={`flex flex-col h-full w-full transition-colors duration-1000 ${device === 'tv' ? 'scale-110 origin-top' : ''}`} style={{ backgroundColor: themeData.bg }}>
      <header className="px-6 py-4 lg:px-12 lg:py-8 flex items-center justify-between z-50">
        <div className="flex items-center gap-4 lg:gap-8">
          {renderIdentity('w-12 h-12 lg:w-16 lg:h-16')}
          <div>
            <h1 className="text-xl lg:text-3xl font-black tracking-tighter bg-gradient-to-r from-white to-gray-500 bg-clip-text text-transparent">{prefs.assistantName}</h1>
            <HardwareSensors data={sensorData} deviceType={device} themeColor={themeData.primary} />
          </div>
        </div>
        <div className="flex items-center gap-4">
           {!isMobile && (
             <button onClick={() => setIsSettingsOpen(true)} className="w-12 h-12 rounded-2xl bg-white/5 hover:bg-white/10 flex items-center justify-center transition-colors">
               <i className="fas fa-cog text-gray-400"></i>
             </button>
           )}
           <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isMemoryOpen ? 'bg-blue-500 text-white' : 'bg-white/5 text-gray-400'}`}>
             <i className="fas fa-brain"></i>
           </button>
           <button onClick={handleLogout} className="text-gray-600 hover:text-white transition-colors">
             <i className="fas fa-sign-out-alt"></i>
           </button>
        </div>
      </header>

      <main className="flex-1 flex flex-col md:flex-row min-h-0 p-4 lg:p-12 gap-8">
        <div className="flex-1 flex flex-col bg-white/[0.02] rounded-[3rem] border border-white/5 overflow-hidden backdrop-blur-3xl relative">
          <div className="flex-1 p-6 lg:p-12 overflow-y-auto space-y-8 scrollbar-thin" ref={scrollRef}>
             {transcriptions.length === 0 && (
               <div className="h-full flex flex-col items-center justify-center opacity-10">
                 <i className="fas fa-atom text-9xl mb-8"></i>
                 <p className="text-2xl font-black uppercase tracking-[1em]">Listening</p>
               </div>
             )}
             {transcriptions.map(e => (
               <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'}`}>
                 <div className={`max-w-[85%] px-8 py-4 rounded-[2rem] ${e.sender === 'user' ? `bg-${themeData.primary} text-white` : 'bg-white/5 text-gray-300'}`}>
                   <p className="text-sm font-medium">{e.text}</p>
                   {e.sources && <GroundingSources sources={e.sources} themePrimary={themeData.primary} />}
                 </div>
               </div>
             ))}
             {streamingAssistantText && (
               <div className="flex flex-col items-start animate-fade-in">
                 <div className="max-w-[85%] px-8 py-4 rounded-[2rem] bg-white/10 text-white">
                   <p className="text-sm font-medium">{streamingAssistantText}</p>
                 </div>
               </div>
             )}
          </div>

          <div className="p-6 lg:p-10 border-t border-white/5 bg-black/40 relative">
             <div className="absolute right-8 -top-12 flex gap-2">
                <button onClick={scrollToTop} className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-xs text-gray-500 hover:text-white"><i className="fas fa-arrow-up"></i></button>
                <button onClick={scrollToBottom} className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-xs text-gray-500 hover:text-white"><i className="fas fa-arrow-down"></i></button>
             </div>
             <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
             <div className="mt-6 flex gap-4">
                <input 
                  type="text" 
                  value={inputText}
                  onChange={(e) => setInputText(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSendText()}
                  placeholder={`Command ${prefs.assistantName}...`}
                  className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-6 py-4 focus:outline-none focus:border-blue-500/40 transition-all"
                />
                <button 
                  onClick={state === AssistantState.IDLE ? () => startSession() : stopSession}
                  className={`w-16 h-16 rounded-2xl flex items-center justify-center transition-all ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500 text-white animate-pulse'}`}
                >
                  <i className={`fas ${state === AssistantState.IDLE ? 'fa-microphone' : 'fa-square'}`}></i>
                </button>
             </div>
          </div>
        </div>

        {isMemoryOpen && (
          <div className="w-full md:w-[360px] animate-slide-in-right">
             <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
          </div>
        )}
      </main>

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[150] bg-black/95 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
          <div className="w-full max-w-5xl bg-[#02020a] border border-white/10 rounded-[4rem] p-12 relative overflow-y-auto max-h-[90vh] scrollbar-thin">
             <button onClick={() => setIsSettingsOpen(false)} className="absolute top-12 right-12 text-gray-700 hover:text-white text-2xl"><i className="fas fa-times"></i></button>
             <h2 className="text-4xl font-black tracking-tighter uppercase mb-12">Configuration</h2>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                <section className="space-y-8">
                   <div className="space-y-4">
                      <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Avatar Signature</label>
                      <div className="flex items-center gap-6">
                        <div className="w-24 h-24 rounded-3xl overflow-hidden border-2 border-dashed border-white/10 flex items-center justify-center">
                           {prefs.assistantProfilePic ? <img src={prefs.assistantProfilePic} className="w-full h-full object-cover" alt="S" /> : <i className="fas fa-camera text-gray-800"></i>}
                        </div>
                        <button onClick={() => fileInputRef.current?.click()} className="px-6 py-3 rounded-xl bg-white/5 text-[10px] font-black uppercase tracking-widest hover:bg-white/10">Upload Image</button>
                        <input ref={fileInputRef} type="file" className="hidden" onChange={handleProfilePicChange} accept="image/*" />
                      </div>
                   </div>

                   {/* Voice Selection Section */}
                   <div className="space-y-6">
                      <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest block mb-4">Neural Voice Core</label>
                      <div className="grid grid-cols-1 gap-3">
                         {VOICES.map(v => (
                           <button 
                             key={v.id} 
                             onClick={() => setPrefs(pr => ({ ...pr, voiceId: v.id }))} 
                             className={`flex items-center justify-between px-6 py-4 rounded-2xl border-2 transition-all group ${prefs.voiceId === v.id ? 'bg-blue-500/10 border-blue-500' : 'bg-white/5 border-white/5 hover:border-white/10'}`}
                           >
                             <div className="flex items-center gap-4 text-left">
                               <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${v.gender === 'masculine' ? 'bg-blue-900/40 text-blue-400' : 'bg-pink-900/40 text-pink-400'}`}>
                                 <i className={`fas ${v.gender === 'masculine' ? 'fa-mars' : 'fa-venus'}`}></i>
                               </div>
                               <div>
                                 <p className={`text-sm font-black uppercase tracking-widest ${prefs.voiceId === v.id ? 'text-white' : 'text-gray-400'}`}>{v.name}</p>
                                 <p className="text-[10px] text-gray-600 font-medium">{v.tone}</p>
                               </div>
                             </div>
                             {prefs.voiceId === v.id && <i className="fas fa-check-circle text-blue-500 animate-fade-in"></i>}
                           </button>
                         ))}
                      </div>
                   </div>
                </section>

                <section className="space-y-8">
                   <div className="space-y-4">
                      <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Neural Persona</label>
                      <div className="grid grid-cols-2 gap-3">
                         {(Object.keys(PERSONALITIES) as PersonalityType[]).map(p => (
                           <button key={p} onClick={() => setPrefs(pr => ({ ...pr, personality: p }))} className={`py-4 rounded-xl border-2 transition-all font-black text-[9px] uppercase tracking-widest ${prefs.personality === p ? `bg-blue-500/10 border-blue-500` : 'border-white/5 text-gray-700'}`}>{p}</button>
                         ))}
                      </div>
                   </div>
                   {prefs.personality === 'custom' && (
                     <textarea 
                       value={prefs.customPersonality || ''}
                       onChange={(e) => setPrefs(pr => ({ ...pr, customPersonality: e.target.value }))}
                       placeholder="Specify custom directive..."
                       className="w-full h-32 bg-white/5 border border-white/10 rounded-2xl p-4 text-sm"
                     />
                   )}
                   <div className="space-y-4">
                      <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Assistant Designation</label>
                      <input type="text" value={prefs.assistantName} onChange={(e) => setPrefs(p => ({ ...p, assistantName: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 font-black text-xl" />
                   </div>
                   <div className="p-8 bg-blue-500/5 border border-blue-500/10 rounded-3xl">
                      <p className="text-[10px] text-blue-400 font-black uppercase tracking-widest mb-2 flex items-center gap-2">
                        <i className="fas fa-info-circle"></i> Adaptive Context
                      </p>
                      <p className="text-xs text-gray-500 leading-relaxed">Neural signatures are calibrated per device. Your choice of voice and persona affects real-time emotional synthesis.</p>
                   </div>
                </section>
             </div>
             <button onClick={() => setIsSettingsOpen(false)} className="mt-12 w-full py-6 bg-white text-black font-black uppercase tracking-widest rounded-full hover:scale-[1.02] transition-transform shadow-3xl">Synchronize Core</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser, UITheme, PersonalityType, UserPreferences, DeviceType, SensorData } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';
import ScreenShareMode from './components/ScreenShareMode';
import GroundingSources from './components/GroundingSources';
import HardwareSensors from './components/HardwareSensors';

const VOICES = [
  { id: 'Charon', name: 'Charon', tone: 'Deep, Bass, Authoritative', gender: 'masculine' },
  { id: 'Puck', name: 'Puck', tone: 'Energetic, Bright, Playful', gender: 'masculine' },
  { id: 'Fenrir', name: 'Fenrir', tone: 'Vibrant, Sharp, Focused', gender: 'masculine' },
  { id: 'Kore', name: 'Kore', tone: 'Clear, Professional, Calm', gender: 'feminine' },
  { id: 'Zephyr', name: 'Zephyr', tone: 'Warm, Smooth, Melodic', gender: 'feminine' }
];

const THEMES: Record<UITheme, { primary: string; secondary: string; glow: string; bg: string }> = {
  cosmic: { primary: 'blue-500', secondary: 'indigo-500', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: 'emerald-500', secondary: 'teal-500', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: 'rose-500', secondary: 'orange-500', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: 'slate-400', secondary: 'zinc-500', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: VOICES[0].id,
  assistantName: 'Nova'
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [device, setDevice] = useState<DeviceType>('desktop');
  const [isScanning, setIsScanning] = useState(true);
  const [sensorData, setSensorData] = useState<SensorData>({ online: navigator.onLine, platform: navigator.platform });
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [currentSources, setCurrentSources] = useState<GroundingSource[]>([]);
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [inputText, setInputText] = useState('');
  const [searchEnabled, setSearchEnabled] = useState(true);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Advanced Device & Sensor Detection
  const detectHardware = useCallback(async () => {
    const w = window.innerWidth;
    const h = window.innerHeight;
    const ua = navigator.userAgent.toLowerCase();

    let detectedDevice: DeviceType = 'desktop';
    if (w <= 300 || (ua.includes('watch') && !ua.includes('tv'))) {
      detectedDevice = 'wear';
    } else if (ua.includes('android') && w > h && w >= 800 && w <= 1280) {
      detectedDevice = 'auto';
    } else if (ua.includes('tv') || ua.includes('smarttv') || (w >= 1920 && h >= 1080)) {
      detectedDevice = 'tv';
    } else if (w < 768 || (w < 1024 && h > w)) {
      detectedDevice = 'mobile';
    }
    setDevice(detectedDevice);

    const sensorPayload: SensorData = {
      online: navigator.onLine,
      platform: navigator.platform
    };

    if ('getBattery' in navigator) {
      try {
        const battery = await (navigator as any).getBattery();
        sensorPayload.battery = battery.level;
        sensorPayload.charging = battery.charging;
      } catch (e) {}
    }

    if (['auto', 'mobile', 'desktop'].includes(detectedDevice)) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          setSensorData(prev => ({ 
            ...prev, 
            location: { lat: pos.coords.latitude, lng: pos.coords.longitude } 
          }));
        },
        null,
        { enableHighAccuracy: true }
      );
    }

    setSensorData(prev => ({ ...prev, ...sensorPayload }));
    // Scanning phase aesthetic
    setTimeout(() => setIsScanning(false), 2500);
  }, []);

  useEffect(() => {
    detectHardware();
    window.addEventListener('resize', detectHardware);
    window.addEventListener('online', () => setSensorData(p => ({ ...p, online: true })));
    window.addEventListener('offline', () => setSensorData(p => ({ ...p, online: false })));
    return () => window.removeEventListener('resize', detectHardware);
  }, [detectHardware]);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
      setUser({ username: sessionUser, preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS });
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      setMemories(JSON.parse(localStorage.getItem(`nova_${user.username}_memories`) || '[]'));
      setTranscriptions(JSON.parse(localStorage.getItem(`nova_${user.username}_logs`) || '[]'));
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme], [prefs.theme]);

  // Derived state to fix missing isMobile variable
  const isMobile = useMemo(() => device === 'mobile' || device === 'wear', [device]);

  const scrollToTop = () => { if (scrollRef.current) scrollRef.current.scrollTo({ top: 0, behavior: 'smooth' }); };
  const scrollToBottom = () => { if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' }); };

  const addTranscription = useCallback((sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev,
      { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  }, []);

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
    setCurrentSources([]);
  }, [screenStream]);

  const handleLogout = useCallback(() => {
    stopSession();
    setUser(null);
    sessionStorage.removeItem('nova_session_user');
  }, [stopSession]);

  const handleProfilePicChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setPrefs(p => ({ ...p, assistantProfilePic: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const startSession = async (initialText?: string) => {
    try {
      setState(AssistantState.CONNECTING);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("Key missing");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
          output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      audioUtils.playLinkSound(outputCtx);

      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const personalityPrompt = prefs.personality === 'custom' ? (prefs.customPersonality || 'Be helpful.') : PERSONALITIES[prefs.personality];

      const tools: any[] = [{ functionDeclarations: [saveKnowledgeTool] }];
      if (searchEnabled) tools.push({ googleSearch: {} });
      if (sensorData.location) tools.push({ googleMaps: {} });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools,
          toolConfig: sensorData.location ? {
            retrievalConfig: {
              latLng: {
                latitude: sensorData.location.lat,
                longitude: sensorData.location.lng
              }
            }
          } : undefined,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. Platform: ${device}. Location: ${JSON.stringify(sensorData.location)}. Personality: ${personalityPrompt}. Status: ${JSON.stringify(sensorData)}. Response: Real-time, highly intelligent, emotive.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = audioUtils.createPcmBlob(inputData);
              sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: pcmBlob }); });
              if (currentFrameRef.current) {
                const frame = currentFrameRef.current;
                currentFrameRef.current = null;
                sessionPromise.then(s => { if (sessionRef.current) s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } }); });
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
            if (initialText) sessionPromise.then(s => s.sendRealtimeInput({ parts: [{ text: initialText }] }));
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = (fc.args as any).fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => { if (sessionRef.current) s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Memory saved." } } }); });
                }
              }
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); 
              s.buffer = buffer; 
              s.connect(outputCtx.destination);
              s.onended = () => { 
                activeSourcesRef.current.delete(s); 
                if (activeSourcesRef.current.size === 0 && sessionRef.current) setState(AssistantState.LISTENING); 
              };
              s.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration; 
              activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            if (message.serverContent?.turnComplete) {
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) {
                addTranscription('assistant', a, currentSources);
                audioUtils.playSuccessSound(outputCtx);
              } return ''; });
              setCurrentSources([]);
            }
          },
          onerror: (err) => stopSession(),
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setState(AssistantState.IDLE); }
  };

  const handleSendText = async () => {
    if (!inputText.trim()) return;
    const msg = inputText.trim();
    setInputText('');
    addTranscription('user', msg);
    if (sessionRef.current) {
      setState(AssistantState.THINKING);
      sessionRef.current.sendRealtimeInput({ parts: [{ text: msg }] });
    } else {
      startSession(msg);
    }
  };

  if (!user) return <LoginPage onLogin={(u) => setUser({ username: u, preferences: DEFAULT_PREFS })} />;

  // Scanning Phase Overlay
  if (isScanning) {
    return (
      <div className="fixed inset-0 bg-[#02020a] flex flex-col items-center justify-center z-[200] animate-fade-in">
        <div className="relative w-64 h-64 flex items-center justify-center">
          <div className={`absolute inset-0 border-4 border-t-${themeData.primary} border-r-transparent border-b-transparent border-l-transparent rounded-full animate-spin`}></div>
          <div className={`absolute inset-4 border-2 border-b-${themeData.secondary} border-t-transparent border-r-transparent border-l-transparent rounded-full animate-spin`} style={{ animationDirection: 'reverse', animationDuration: '3s' }}></div>
          <i className="fas fa-microchip text-4xl text-white/20"></i>
        </div>
        <div className="mt-12 text-center">
          <h2 className="text-xl font-black tracking-[0.5em] uppercase text-white mb-2">Scanning Hardware</h2>
          <p className="text-[10px] font-mono text-gray-500">{sensorData.platform} // ENV_CALIBRATION</p>
        </div>
      </div>
    );
  }

  // Identity Icon Generator
  const renderIdentity = (size: string) => (
    <div className={`${size} rounded-[2rem] overflow-hidden border border-white/10 shadow-2xl relative group`}>
      {prefs.assistantProfilePic ? (
        <img src={prefs.assistantProfilePic} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt="AI" />
      ) : (
        <div className={`w-full h-full bg-${themeData.primary}/10 flex items-center justify-center`}>
          <i className="fas fa-atom text-2xl text-white"></i>
        </div>
      )}
      <div className={`absolute inset-0 bg-${themeData.primary}/20 mix-blend-overlay animate-pulse-slow`}></div>
    </div>
  );

  // VIEW RENDERING BY DEVICE
  if (device === 'wear') {
    return (
      <div className="wear-screen">
        <div className="flex flex-col items-center justify-center p-8 space-y-4">
          <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
          <button onClick={state === AssistantState.IDLE ? () => startSession() : stopSession} className={`w-14 h-14 rounded-full flex items-center justify-center ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500'}`}>
            <i className={`fas ${state === AssistantState.IDLE ? 'fa-play' : 'fa-stop'}`}></i>
          </button>
        </div>
      </div>
    );
  }

  if (device === 'auto') {
    return (
      <div className="h-full w-full bg-black p-12 flex gap-12 items-center">
        <div className="w-1/3 flex flex-col items-center gap-8">
           {renderIdentity('w-64 h-64')}
           <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
           <button onClick={state === AssistantState.IDLE ? () => startSession() : stopSession} className="w-full py-8 bg-white text-black rounded-[2rem] font-black uppercase tracking-widest text-2xl">
             {state === AssistantState.IDLE ? 'Activate' : 'End Trip'}
           </button>
        </div>
        <div className="flex-1 bg-white/5 rounded-[4rem] p-12 h-full overflow-hidden border border-white/10">
           <div className="h-full flex flex-col">
              <div className="flex-1 overflow-y-auto space-y-8 pr-4 scrollbar-thin">
                {transcriptions.map(e => (
                  <div key={e.id} className="text-3xl font-bold opacity-60">
                    <span className="text-blue-400">[{e.sender}]</span> {e.text}
                  </div>
                ))}
              </div>
              {streamingAssistantText && <div className="text-4xl font-black text-white mt-4">{streamingAssistantText}</div>}
           </div>
        </div>
      </div>
    );
  }

  // DEFAULT (Desktop/Mobile/TV)
  return (
    <div className={`flex flex-col h-full w-full transition-colors duration-1000 ${device === 'tv' ? 'scale-110 origin-top' : ''}`} style={{ backgroundColor: themeData.bg }}>
      <header className="px-6 py-4 lg:px-12 lg:py-8 flex items-center justify-between z-50">
        <div className="flex items-center gap-4 lg:gap-8">
          {renderIdentity('w-12 h-12 lg:w-16 lg:h-16')}
          <div>
            <h1 className="text-xl lg:text-3xl font-black tracking-tighter bg-gradient-to-r from-white to-gray-500 bg-clip-text text-transparent">{prefs.assistantName}</h1>
            <HardwareSensors data={sensorData} deviceType={device} themeColor={themeData.primary} />
          </div>
        </div>
        <div className="flex items-center gap-4">
           {!isMobile && (
             <button onClick={() => setIsSettingsOpen(true)} className="w-12 h-12 rounded-2xl bg-white/5 hover:bg-white/10 flex items-center justify-center transition-colors">
               <i className="fas fa-cog text-gray-400"></i>
             </button>
           )}
           <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isMemoryOpen ? 'bg-blue-500 text-white' : 'bg-white/5 text-gray-400'}`}>
             <i className="fas fa-brain"></i>
           </button>
           <button onClick={handleLogout} className="text-gray-600 hover:text-white transition-colors">
             <i className="fas fa-sign-out-alt"></i>
           </button>
        </div>
      </header>

      <main className="flex-1 flex flex-col md:flex-row min-h-0 p-4 lg:p-12 gap-8">
        <div className="flex-1 flex flex-col bg-white/[0.02] rounded-[3rem] border border-white/5 overflow-hidden backdrop-blur-3xl relative">
          <div className="flex-1 p-6 lg:p-12 overflow-y-auto space-y-8 scrollbar-thin" ref={scrollRef}>
             {transcriptions.length === 0 && (
               <div className="h-full flex flex-col items-center justify-center opacity-10">
                 <i className="fas fa-atom text-9xl mb-8"></i>
                 <p className="text-2xl font-black uppercase tracking-[1em]">Listening</p>
               </div>
             )}
             {transcriptions.map(e => (
               <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'}`}>
                 <div className={`max-w-[85%] px-8 py-4 rounded-[2rem] ${e.sender === 'user' ? `bg-${themeData.primary} text-white` : 'bg-white/5 text-gray-300'}`}>
                   <p className="text-sm font-medium">{e.text}</p>
                   {e.sources && <GroundingSources sources={e.sources} themePrimary={themeData.primary} />}
                 </div>
               </div>
             ))}
             {streamingAssistantText && (
               <div className="flex flex-col items-start animate-fade-in">
                 <div className="max-w-[85%] px-8 py-4 rounded-[2rem] bg-white/10 text-white">
                   <p className="text-sm font-medium">{streamingAssistantText}</p>
                 </div>
               </div>
             )}
          </div>

          <div className="p-6 lg:p-10 border-t border-white/5 bg-black/40 relative">
             <div className="absolute right-8 -top-12 flex gap-2">
                <button onClick={scrollToTop} className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-xs text-gray-500 hover:text-white"><i className="fas fa-arrow-up"></i></button>
                <button onClick={scrollToBottom} className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-xs text-gray-500 hover:text-white"><i className="fas fa-arrow-down"></i></button>
             </div>
             <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
             <div className="mt-6 flex gap-4">
                <input 
                  type="text" 
                  value={inputText}
                  onChange={(e) => setInputText(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSendText()}
                  placeholder={`Command ${prefs.assistantName}...`}
                  className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-6 py-4 focus:outline-none focus:border-blue-500/40 transition-all"
                />
                <button 
                  onClick={state === AssistantState.IDLE ? () => startSession() : stopSession}
                  className={`w-16 h-16 rounded-2xl flex items-center justify-center transition-all ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-500 text-white animate-pulse'}`}
                >
                  <i className={`fas ${state === AssistantState.IDLE ? 'fa-microphone' : 'fa-square'}`}></i>
                </button>
             </div>
          </div>
        </div>

        {isMemoryOpen && (
          <div className="w-full md:w-[360px] animate-slide-in-right">
             <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
          </div>
        )}
      </main>

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[150] bg-black/95 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
          <div className="w-full max-w-5xl bg-[#02020a] border border-white/10 rounded-[4rem] p-12 relative overflow-y-auto max-h-[90vh] scrollbar-thin">
             <button onClick={() => setIsSettingsOpen(false)} className="absolute top-12 right-12 text-gray-700 hover:text-white text-2xl"><i className="fas fa-times"></i></button>
             <h2 className="text-4xl font-black tracking-tighter uppercase mb-12">Configuration</h2>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                <section className="space-y-12">
                   <div className="space-y-4">
                      <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Avatar Signature</label>
                      <div className="flex items-center gap-6">
                        <div className="w-24 h-24 rounded-3xl overflow-hidden border-2 border-dashed border-white/10 flex items-center justify-center">
                           {prefs.assistantProfilePic ? <img src={prefs.assistantProfilePic} className="w-full h-full object-cover" alt="S" /> : <i className="fas fa-camera text-gray-800"></i>}
                        </div>
                        <button onClick={() => fileInputRef.current?.click()} className="px-6 py-3 rounded-xl bg-white/5 text-[10px] font-black uppercase tracking-widest hover:bg-white/10">Upload Image</button>
                        <input ref={fileInputRef} type="file" className="hidden" onChange={handleProfilePicChange} accept="image/*" />
                      </div>
                   </div>

                   {/* Gendered Voice Selection Section */}
                   <div className="space-y-8">
                      <div>
                        <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest block mb-4">Neural Profile: Masculine</label>
                        <div className="grid grid-cols-1 gap-3">
                           {VOICES.filter(v => v.gender === 'masculine').map(v => (
                             <button 
                               key={v.id} 
                               onClick={() => setPrefs(pr => ({ ...pr, voiceId: v.id }))} 
                               className={`flex items-center justify-between px-6 py-4 rounded-2xl border-2 transition-all group ${prefs.voiceId === v.id ? 'bg-blue-500/10 border-blue-500' : 'bg-white/5 border-white/5 hover:border-white/10'}`}
                             >
                               <div className="flex items-center gap-4 text-left">
                                 <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${prefs.voiceId === v.id ? 'bg-blue-500 text-white' : 'bg-blue-900/20 text-blue-500/50'}`}>
                                   <i className="fas fa-mars"></i>
                                 </div>
                                 <div>
                                   <p className={`text-sm font-black uppercase tracking-widest ${prefs.voiceId === v.id ? 'text-white' : 'text-gray-400'}`}>{v.name}</p>
                                   <p className="text-[9px] text-gray-600 font-medium uppercase tracking-tighter">{v.tone}</p>
                                 </div>
                               </div>
                               {prefs.voiceId === v.id && <i className="fas fa-circle-check text-blue-500"></i>}
                             </button>
                           ))}
                        </div>
                      </div>

                      <div>
                        <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest block mb-4">Neural Profile: Feminine</label>
                        <div className="grid grid-cols-1 gap-3">
                           {VOICES.filter(v => v.gender === 'feminine').map(v => (
                             <button 
                               key={v.id} 
                               onClick={() => setPrefs(pr => ({ ...pr, voiceId: v.id }))} 
                               className={`flex items-center justify-between px-6 py-4 rounded-2xl border-2 transition-all group ${prefs.voiceId === v.id ? 'bg-emerald-500/10 border-emerald-500' : 'bg-white/5 border-white/5 hover:border-white/10'}`}
                             >
                               <div className="flex items-center gap-4 text-left">
                                 <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${prefs.voiceId === v.id ? 'bg-emerald-500 text-white' : 'bg-emerald-900/20 text-emerald-500/50'}`}>
                                   <i className="fas fa-venus"></i>
                                 </div>
                                 <div>
                                   <p className={`text-sm font-black uppercase tracking-widest ${prefs.voiceId === v.id ? 'text-white' : 'text-gray-400'}`}>{v.name}</p>
                                   <p className="text-[9px] text-gray-600 font-medium uppercase tracking-tighter">{v.tone}</p>
                                 </div>
                               </div>
                               {prefs.voiceId === v.id && <i className="fas fa-circle-check text-emerald-500"></i>}
                             </button>
                           ))}
                        </div>
                      </div>
                   </div>
                </section>

                <section className="space-y-12">
                   <div className="space-y-4">
                      <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Neural Persona</label>
                      <div className="grid grid-cols-2 gap-3">
                         {(Object.keys(PERSONALITIES) as PersonalityType[]).map(p => (
                           <button key={p} onClick={() => setPrefs(pr => ({ ...pr, personality: p }))} className={`py-4 rounded-xl border-2 transition-all font-black text-[9px] uppercase tracking-widest ${prefs.personality === p ? `bg-blue-500/10 border-blue-500` : 'border-white/5 text-gray-700'}`}>{p}</button>
                         ))}
                      </div>
                   </div>
                   {prefs.personality === 'custom' && (
                     <textarea 
                       value={prefs.customPersonality || ''}
                       onChange={(e) => setPrefs(pr => ({ ...pr, customPersonality: e.target.value }))}
                       placeholder="Specify custom directive..."
                       className="w-full h-32 bg-white/5 border border-white/10 rounded-2xl p-4 text-sm"
                     />
                   )}
                   <div className="space-y-4">
                      <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Assistant Designation</label>
                      <input type="text" value={prefs.assistantName} onChange={(e) => setPrefs(p => ({ ...p, assistantName: e.target.value }))} className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 font-black text-xl" />
                   </div>
                   <div className="p-8 bg-blue-500/5 border border-blue-500/10 rounded-3xl">
                      <p className="text-[10px] text-blue-400 font-black uppercase tracking-widest mb-2 flex items-center gap-2">
                        <i className="fas fa-heart text-[8px]"></i> Personalization Note
                      </p>
                      <p className="text-xs text-gray-500 leading-relaxed">Male neural profiles (Charon, Puck, Fenrir) are optimized for deep-frequency resonance. Combined with 'Alluring' or 'Friendly' personas, they provide a distinct companion experience.</p>
                   </div>
                </section>
             </div>
             <button onClick={() => setIsSettingsOpen(false)} className="mt-12 w-full py-6 bg-white text-black font-black uppercase tracking-widest rounded-full hover:scale-[1.02] transition-transform shadow-3xl">Commit Neural Changes</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

