             <button onClick={() => setIsSettingsOpen(false)} className="mt-12 w-full py-6 bg-white text-black font-black uppercase tracking-widest rounded-full hover:scale-[1.02] transition-transform shadow-3xl">Commit Neural Changes</button>
          </div>
