            <div className="absolute -bottom-2 -left-2 w-6 h-6 bg-indigo-600 rounded-bl-full"></div>
            <i className="fas fa-comment text-white/20 absolute text-4xl"></i>
          </div>
          <div className="relative w-20 h-16 bg-gradient-to-tr from-rose-400 to-orange-500 rounded-[1.5rem] shadow-xl mt-4 flex items-center justify-center">
            <div className="w-8 h-1 bg-white/30 rounded-full"></div>
            <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-orange-500 rounded-br-full"></div>
          </div>
        </div>

        {/* Logo Text */}
        <div className="relative flex flex-col items-center">
          <div className={`flex items-baseline transition-all duration-700 ${stage >= 2 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'}`}>
            <span className="text-6xl md:text-8xl font-black tracking-tighter text-gray-400 drop-shadow-md">Project</span>
            <div className="flex ml-4">
              {'Chatty'.split('').map((char, i) => {
                const colors = ['text-blue-500', 'text-red-500', 'text-yellow-500', 'text-blue-500', 'text-green-500', 'text-red-500'];
                return (
                  <span 
                    key={i} 
                    className={`${colors[i % colors.length]} text-6xl md:text-8xl font-black transition-all duration-500 delay-${i * 100} transform ${stage >= 2 ? 'scale-100' : 'scale-0'}`}
                  >
                    {char}
                  </span>
                );
              })}
            </div>
          </div>

          <div className={`mt-2 transition-all duration-1000 ${stage >= 3 ? 'opacity-100' : 'opacity-0'}`}>
            <span className="text-4xl md:text-5xl font-black text-gray-300 tracking-widest animate-pulse">...</span>
          </div>
        </div>

        {/* Floating Particles/Bubbles like in video */}
        {stage >= 2 && (
          <>
            <div className="absolute -top-10 -right-20 w-4 h-4 rounded-full bg-blue-300/40 blur-sm animate-ping"></div>
            <div className="absolute top-20 -left-24 w-6 h-6 rounded-full bg-red-300/30 blur-sm animate-pulse"></div>
            <div className="absolute -bottom-10 left-10 w-3 h-3 rounded-full bg-green-300/40 blur-sm animate-bounce"></div>
          </>
        )}
      </div>

      {/* Screen Overlay for final transition */}
      <div className={`absolute inset-0 bg-[#02020a] transition-opacity duration-1000 pointer-events-none ${stage === 4 ? 'opacity-100' : 'opacity-0'}`}></div>
    </div>
  );
};

