      audioUtils.playLinkSound(outputCtx);

      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: { echoCancellation: true, noiseSuppression: true, sampleRate: 16000, channelCount: 1 } 
      });
      micStreamRef.current = stream;

      const source = inputCtx.createMediaStreamSource(stream);
      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const personalityPrompt = prefs.personality === 'custom' ? (prefs.customPersonality || 'Be helpful.') : PERSONALITIES[prefs.personality];

      const tools: any[] = [];
      if (sensorData.location) tools.push({ googleMaps: {} });
      if (searchEnabled) tools.push({ googleSearch: {} });
      if (!searchEnabled && !sensorData.location) tools.push({ functionDeclarations: [saveKnowledgeTool] });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools,
          toolConfig: sensorData.location ? {
            retrievalConfig: { latLng: { latitude: sensorData.location.lat, longitude: sensorData.location.lng } }
          } : undefined,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. Platform: ${device}. Personality: ${personalityPrompt}.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const resampledData = downsample(inputData, inputCtx.sampleRate, 16000);
              const pcmBlob = audioUtils.createPcmBlob(resampledData);
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
              if (currentFrameRef.current) {
                const frame = currentFrameRef.current;
                currentFrameRef.current = null;
                sessionPromise.then(s => s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } }));
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
            if (initialText) sessionPromise.then(s => s.sendRealtimeInput({ text: initialText }));
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = (fc.args as any).fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Saved." } } }));
                }
              }
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); 
              s.buffer = buffer; 
              s.connect(outputCtx.destination);
              s.onended = () => { activeSourcesRef.current.delete(s); if (activeSourcesRef.current.size === 0) setState(AssistantState.LISTENING); };
              s.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration; 
              activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            if (message.serverContent?.turnComplete) {
              const chunks = message.serverContent?.groundingMetadata?.groundingChunks || [];
              const sources: GroundingSource[] = chunks.map((c: any) => {
                if (c.web) return { title: c.web.title, uri: c.web.uri };
                if (c.maps) return { title: c.maps.title, uri: c.maps.uri };
                return null;
              }).filter(Boolean) as GroundingSource[];

              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) { addTranscription('assistant', a, sources); audioUtils.playSuccessSound(outputCtx); } return ''; });
            }
          },
          onerror: (err: any) => stopSession(),
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { 
      setErrorToast(err.message);
      setState(AssistantState.IDLE); 
      setTimeout(() => setErrorToast(null), 5000);
    }
  };

  const handleToggleScreenShare = async () => {
    if (isScreenSharing) {
      setIsScreenSharing(false);
      if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    } else {
      try {
        const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
        setScreenStream(stream);
        setIsVisionActive(false);
        setIsScreenSharing(true);
        if (state === AssistantState.IDLE) startSession();
        stream.getVideoTracks()[0].onended = () => { setIsScreenSharing(false); setScreenStream(null); };
      } catch (err: any) {
        setErrorToast(err.message);
      }
    }
  };

  const handleToggleVision = async () => {
    if (isVisionActive) {
      setIsVisionActive(false);
    } else {
      try {
        await navigator.mediaDevices.getUserMedia({ video: true });
        setIsScreenSharing(false);
        setIsVisionActive(true);
        if (state === AssistantState.IDLE) startSession();
      } catch (err: any) {
        setErrorToast("Optic access denied.");
      }
    }
  };

  const handleSendText = () => {
    if (!inputText.trim()) return;
    const msg = inputText.trim();
    setInputText('');
    addTranscription('user', msg);
    if (sessionRef.current) {
      setState(AssistantState.THINKING);
      sessionRef.current.sendRealtimeInput({ text: msg });
    } else {
      startSession(msg);
    }
  };

  if (showIntro) return <IntroSequence onComplete={() => setShowIntro(false)} />;
  if (!user) return <LoginPage onLogin={handleLogin} />;

  if (isScanning) {
    return (
      <div className="fixed inset-0 bg-[#02020a] flex flex-col items-center justify-center z-[200] animate-fade-in overflow-hidden">
        <div className="absolute inset-0 animate-scan bg-gradient-to-b from-transparent via-blue-500/10 to-transparent pointer-events-none opacity-20"></div>
        <div className="relative w-48 h-48 flex items-center justify-center animate-pulse-slow">
          <div className={`absolute inset-0 border-4 border-t-${themeData.primary} border-r-transparent border-b-transparent border-l-transparent rounded-full animate-spin opacity-40`}></div>
          <i className="fas fa-microchip text-4xl text-white/20"></i>
        </div>
        <h2 className="mt-8 text-xl font-black tracking-[0.5em] uppercase text-white mb-2 text-center animate-slide-up">Synchronizing Neural Core</h2>
        <p className="text-[10px] text-gray-600 font-black uppercase tracking-widest animate-pulse">Establishing link...</p>
      </div>
    );
  }

  return (
    <div className={`flex flex-col h-full w-full transition-all duration-1000 overflow-hidden ${isTV ? 'tv-view' : ''}`} style={{ backgroundColor: themeData.bg }}>
      {errorToast && (
        <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[300] bg-red-600 text-white px-8 py-4 rounded-2xl font-black uppercase tracking-widest text-[10px] shadow-2xl animate-pop-in flex items-center gap-4">
          <i className="fas fa-exclamation-triangle"></i>
          {errorToast}
          <button onClick={() => setErrorToast(null)} className="ml-4 opacity-50 hover:opacity-100"><i className="fas fa-times"></i></button>
        </div>
      )}

      {/* Header */}
      <header className={`${isTV ? 'px-20 py-12 m-8 rounded-[4rem]' : 'px-6 py-4 lg:px-12 lg:py-6 m-4 rounded-[2.5rem]'} flex items-center justify-between z-50 glass animate-fade-in`}>
        <div className="flex items-center gap-4 lg:gap-8 group">
          <div className={`${isTV ? 'w-24 h-24 rounded-[3rem]' : 'w-12 h-12 lg:w-16 lg:h-16 rounded-[2rem]'} overflow-hidden border border-white/10 relative transition-transform group-hover:scale-110`}>
            {prefs.assistantProfilePic ? <img src={prefs.assistantProfilePic} className="w-full h-full object-cover" alt="AI" /> : <div className="w-full h-full bg-blue-500/10 flex items-center justify-center"><i className="fas fa-atom text-white"></i></div>}
          </div>
          {!isMobile && (
            <div className="animate-slide-in-right">
              <h1 className={`${isTV ? 'text-5xl' : 'text-xl lg:text-3xl'} font-black tracking-tighter text-white`}>{prefs.assistantName}</h1>
              <HardwareSensors data={sensorData} deviceType={device} themeColor={themeData.primary} />
            </div>
          )}
        </div>
        <div className="flex items-center gap-3 md:gap-4">
           <button onClick={() => setIsSettingsOpen(true)} className={`${isTV ? 'w-20 h-20' : 'w-10 h-10 md:w-12 md:h-12'} rounded-2xl bg-white/5 flex items-center justify-center hover:bg-white/10 transition-all active:scale-90`}><i className="fas fa-cog text-lg md:text-xl"></i></button>
           <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`${isTV ? 'w-20 h-20' : 'w-10 h-10 md:w-12 md:h-12'} rounded-2xl flex items-center justify-center transition-all active:scale-90 ${isMemoryOpen ? 'bg-blue-500 text-white shadow-lg' : 'bg-white/5 text-gray-400'}`}><i className="fas fa-brain text-lg md:text-xl"></i></button>
           <button onClick={handleLogout} className={`${isTV ? 'px-10 h-20' : 'px-2 md:px-4 h-12'} text-gray-600 hover:text-red-500 transition-colors active:scale-90`}><i className="fas fa-sign-out-alt text-lg md:text-xl"></i></button>
        </div>
      </header>

      <main className={`flex-1 flex ${isMobile ? 'flex-col' : 'flex-row'} min-h-0 ${isTV ? 'p-12 gap-12' : 'p-4 lg:p-8 gap-8'} overflow-hidden`}>
        <div className="flex-1 flex flex-col gap-4 lg:gap-8 min-h-0 animate-slide-up">
          {(isVisionActive || isScreenSharing) && (
            <div className={`${isTV ? 'h-96' : 'h-64 md:h-80'} w-full animate-pop-in flex-shrink-0`}>
              {isVisionActive && <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />}
              {isScreenSharing && screenStream && <ScreenShareMode isActive={isScreenSharing} stream={screenStream} onFrame={(b) => currentFrameRef.current = b} onStop={() => setIsScreenSharing(false)} />}
            </div>
          )}

          <div className="flex-1 flex flex-col glass rounded-[3rem] overflow-hidden relative min-h-0 group">
            <div className="absolute inset-0 bg-gradient-to-b from-blue-500/5 to-transparent pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity"></div>

            <div className={`flex-1 ${isTV ? 'p-12 space-y-12' : 'p-6 lg:p-10 space-y-6'} overflow-y-auto scrollbar-thin transcription-list`} ref={scrollRef}>
              {transcriptions.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center opacity-10 animate-pulse-slow">
                  <i className={`fas fa-atom ${isTV ? 'text-[12rem]' : 'text-9xl'} mb-8`}></i>
                  <p className={`${isTV ? 'text-4xl' : 'text-2xl'} font-black uppercase tracking-[1em]`}>Awaiting Input</p>
                </div>
              )}

              {transcriptions.map((e, idx) => (
                <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'}`}>
                  <div className={`${isTV ? 'max-w-[90%]' : 'max-w-[85%]'} ${isTV ? 'px-10 py-8 rounded-[4rem]' : 'px-6 py-4 rounded-[2rem]'} ${e.sender === 'user' ? `bg-${themeData.primary} text-white theme-glow` : 'bg-white/5 text-gray-300 border border-white/5 shadow-2xl'}`}>
                    <p className={`${isTV ? 'text-3xl' : 'text-base'} font-bold leading-relaxed whitespace-pre-wrap`}>{e.text}</p>
                    {e.sources && <GroundingSources sources={e.sources} themePrimary={themeData.primary} />}
                  </div>
                  <span className="text-[10px] text-gray-600 font-black uppercase tracking-widest mt-2 mx-4 opacity-50">{new Date(e.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                </div>
              ))}
              {streamingAssistantText && (
                <div className="items-start flex flex-col animate-fade-in">
                  <div className="max-w-[85%] px-6 py-4 rounded-[2rem] bg-white/5 text-white/50 animate-pulse font-mono text-xs">
                    {streamingAssistantText}
                  </div>
                </div>
              )}
            </div>

            {/* Controls */}
            <div className={`${isTV ? 'p-12' : 'p-6 lg:p-10'} border-t border-white/5 bg-black/40 flex flex-col animate-slide-up`}>
              <div className="w-full relative">
                <div className="absolute inset-0 bg-blue-500/10 blur-[40px] rounded-full animate-pulse-slow"></div>
                <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
              </div>

              <div className={`mt-6 flex ${isMobile ? 'flex-col gap-4' : 'gap-4'} items-center`}>
                  <div className="flex gap-3 w-full md:w-auto">
                    <button onClick={handleToggleVision} className={`${isTV ? 'w-20 h-20' : 'w-12 h-12 flex-1 md:flex-none'} rounded-xl glass flex items-center justify-center active:scale-90 ${isVisionActive ? 'bg-red-500 text-white' : 'text-gray-500 hover:text-white'}`}><i className="fas fa-camera"></i></button>
                    <button onClick={handleToggleScreenShare} className={`${isTV ? 'w-20 h-20' : 'w-12 h-12 flex-1 md:flex-none'} rounded-xl glass flex items-center justify-center active:scale-90 ${isScreenSharing ? 'bg-cyan-500 text-white' : 'text-gray-500 hover:text-white'}`}><i className="fas fa-desktop"></i></button>
                  </div>

                  <input 
                    type="text" 
                    value={inputText} 
                    onChange={(e) => setInputText(e.target.value)} 
                    onKeyDown={(e) => e.key === 'Enter' && handleSendText()} 
                    placeholder="Input neural directive..." 
                    className={`flex-1 bg-white/5 border border-white/10 rounded-2xl ${isTV ? 'px-10 py-6 text-2xl' : 'px-6 py-4 text-base'} focus:outline-none focus:border-blue-500/40 text-white font-bold transition-all`} 
                  />

                  <button 
                    onClick={inputText.trim() ? handleSendText : (state === AssistantState.IDLE ? () => startSession() : stopSession)} 
                    className={`${isTV ? 'w-96 h-24 text-3xl' : 'w-full md:w-52 h-16'} rounded-2xl flex items-center justify-center transition-all gap-4 neo-button ${state === AssistantState.IDLE ? 'bg-white text-black hover:scale-105' : 'bg-red-500 text-white animate-pulse'}`}
                  >
                    <i className={`fas ${inputText.trim() ? 'fa-paper-plane' : (state === AssistantState.IDLE ? 'fa-microphone' : 'fa-square')}`}></i>
                    <span className="font-black uppercase tracking-widest text-[10px]">
                      {inputText.trim() ? 'Dispatch' : (state === AssistantState.IDLE ? 'Initialize' : 'Halt')}
                    </span>
                  </button>
              </div>
            </div>
          </div>
        </div>

        {isMemoryOpen && !isMobile && (
          <div className={`${isTV ? 'w-[500px]' : 'w-full md:w-[360px]'} flex-shrink-0 h-full animate-slide-in-right`}>
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
          </div>
        )}
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        prefs={prefs}
        setPrefs={setPrefs}
        voices={VOICES}
        personalities={PERSONALITIES}
        isTV={isTV}
        isWearable={isWearable}
        onPreviewVoice={handlePreviewVoice}
        previewingVoiceId={previewingVoiceId}
      />
    </div>
  );
};

export default App;

import React, { useEffect, useState } from 'react';

interface IntroSequenceProps {
  onComplete: () => void;
}

const IntroSequence: React.FC<IntroSequenceProps> = ({ onComplete }) => {
  const [stage, setStage] = useState(0);

  useEffect(() => {
    const timers = [
      setTimeout(() => setStage(1), 500),   // Bubbles appear
      setTimeout(() => setStage(2), 1500),  // "PROJECT CHATTY" appears
      setTimeout(() => setStage(3), 3500),  // Full logo + dots
      setTimeout(() => setStage(4), 5000),  // Transition to black
      setTimeout(() => onComplete(), 5800)  // Exit
    ];
    return () => timers.forEach(clearTimeout);
  }, [onComplete]);

  return (
    <div className={`fixed inset-0 z-[1000] flex items-center justify-center overflow-hidden font-sans transition-colors duration-1000 ${stage === 4 ? 'bg-[#02020a]' : 'bg-[#f8f9fa]'}`}>
      {/* Floating Background Bubbles */}
      <div className="absolute inset-0 opacity-40">
        <div className="absolute top-[20%] left-[15%] w-12 h-12 bg-blue-400/20 rounded-full blur-xl animate-bounce"></div>
        <div className="absolute bottom-[25%] right-[20%] w-24 h-24 bg-purple-400/10 rounded-full blur-2xl animate-pulse"></div>
        <div className="absolute top-[60%] left-[40%] w-8 h-8 bg-orange-400/20 rounded-full blur-lg animate-bounce delay-700"></div>
      </div>

      <div className="relative flex flex-col items-center">
        {/* Animated Speech Bubbles */}
        <div className={`flex gap-6 mb-12 transition-all duration-1000 transform ${stage >= 1 ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-50 translate-y-10'}`}>
          <div className="relative w-28 h-24 bg-gradient-to-br from-blue-400 to-indigo-600 rounded-[2.5rem] shadow-2xl flex items-center justify-center animate-float">
            <div className="w-14 h-1.5 bg-white/30 rounded-full mb-1"></div>
            <div className="absolute -bottom-2 -left-2 w-8 h-8 bg-indigo-600 rounded-bl-full shadow-lg"></div>
            <i className="fas fa-comment text-white/10 absolute text-5xl"></i>
          </div>
          <div className="relative w-24 h-20 bg-gradient-to-tr from-rose-400 to-orange-500 rounded-[2rem] shadow-xl mt-6 flex items-center justify-center animate-float [animation-delay:1s]">
            <div className="w-10 h-1 bg-white/30 rounded-full"></div>
            <div className="absolute -bottom-1 -right-1 w-5 h-5 bg-orange-500 rounded-br-full shadow-lg"></div>
          </div>
        </div>

        {/* Logo Text */}
        <div className="relative flex flex-col items-center">
          <div className={`flex items-baseline transition-all duration-1000 transform ${stage >= 2 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-20'}`}>
            <span className="text-6xl md:text-9xl font-black tracking-tighter text-gray-500/80 drop-shadow-2xl uppercase">PROJECT</span>
            <div className="flex ml-6">
              {'CHATTY'.split('').map((char, i) => {
                const colors = ['text-blue-500', 'text-red-500', 'text-yellow-500', 'text-blue-500', 'text-green-500', 'text-red-500'];
                return (
                  <span 
                    key={i} 
                    className={`${colors[i % colors.length]} text-6xl md:text-9xl font-black transition-all duration-700 transform ${stage >= 2 ? 'scale-100 rotate-0' : 'scale-0 rotate-12'}`}
                    style={{ transitionDelay: `${i * 100}ms` }}
                  >
                    {char}
                  </span>
                );
              })}
            </div>
          </div>

          <div className={`mt-4 transition-all duration-1000 ${stage >= 3 ? 'opacity-100 scale-110' : 'opacity-0 scale-50'}`}>
            <span className="text-5xl md:text-7xl font-black text-gray-400 tracking-[0.5em] animate-pulse">...</span>
          </div>
        </div>

        {/* Floating Particles/Bubbles like in video */}
        {stage >= 2 && (
          <div className="absolute inset-0 pointer-events-none overflow-visible">
            <div className="absolute -top-20 -right-40 w-12 h-12 rounded-full bg-blue-300/30 blur-md animate-ping"></div>
            <div className="absolute top-40 -left-48 w-16 h-16 rounded-full bg-red-300/20 blur-lg animate-pulse"></div>
            <div className="absolute -bottom-20 left-20 w-8 h-8 rounded-full bg-green-300/30 blur-sm animate-bounce"></div>
            <div className="absolute bottom-40 right-40 w-10 h-10 rounded-full bg-yellow-300/20 blur-md animate-pulse [animation-delay:0.5s]"></div>
          </div>
        )}
      </div>

      {/* Screen Overlay for final transition */}
      <div className={`absolute inset-0 bg-[#02020a] transition-opacity duration-1000 pointer-events-none ${stage === 4 ? 'opacity-100' : 'opacity-0'}`}></div>
    </div>
  );
};

