const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: VOICES[0].id,
  assistantName: 'Project Chatty',
  customPersonality: 'You are a highly capable AI assistant.'
};

const App: React.FC = () => {
  const [showIntro, setShowIntro] = useState(true);
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [device, setDevice] = useState<DeviceType>('desktop');
  const [isScanning, setIsScanning] = useState(true);
  const [sensorData, setSensorData] = useState<SensorData>({ online: navigator.onLine, platform: navigator.platform });
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [inputText, setInputText] = useState('');
  const [searchEnabled, setSearchEnabled] = useState(true);
  const [errorToast, setErrorToast] = useState<string | null>(null);
  const [previewingVoiceId, setPreviewingVoiceId] = useState<string | null>(null);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  const detectHardware = useCallback(async () => {
    try {
      const w = window.innerWidth;
      const h = window.innerHeight;
      const ua = navigator.userAgent.toLowerCase();

      let detectedDevice: DeviceType = 'desktop';
      if (w <= 300 || (ua.includes('watch') && !ua.includes('tv'))) {
        detectedDevice = 'wear';
      } else if (ua.includes('android') && w > h && w >= 800 && w <= 1280) {
        detectedDevice = 'auto';
      } else if (ua.includes('tv') || ua.includes('smarttv') || (w >= 1920 && h >= 1080)) {
        detectedDevice = 'tv';
      } else if (w < 768 || (w < 1024 && h > w)) {
        detectedDevice = 'mobile';
      }
      setDevice(detectedDevice);
      document.documentElement.setAttribute('data-device', detectedDevice);

      const sensorPayload: SensorData = { online: navigator.onLine, platform: navigator.platform };

      if (navigator && 'getBattery' in navigator) {
        try {
          const battery = await (navigator as any).getBattery();
          sensorPayload.battery = battery.level;
          sensorPayload.charging = battery.charging;
        } catch (e) {
          console.warn("Battery API inaccessible");
        }
      }

      if (navigator.geolocation && ['auto', 'mobile', 'desktop'].includes(detectedDevice)) {
        navigator.geolocation.getCurrentPosition(
          (pos) => setSensorData(prev => ({ ...prev, location: { lat: pos.coords.latitude, lng: pos.coords.longitude } })),
          (err) => console.warn("GPS locked", err.message),
          { enableHighAccuracy: false, timeout: 5000 }
        );
      }
      setSensorData(prev => ({ ...prev, ...sensorPayload }));
    } catch (err) {
      console.error("Hardware probe failure", err);
    } finally {
      setTimeout(() => setIsScanning(false), 2000);
    }
  }, []);

  useEffect(() => {
    detectHardware();
    window.addEventListener('resize', detectHardware);
    return () => window.removeEventListener('resize', detectHardware);
  }, [detectHardware]);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      try {
        const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
        if (savedPrefs) {
          setUser({ username: sessionUser, preferences: JSON.parse(savedPrefs) });
        } else {
          setUser({ username: sessionUser, preferences: DEFAULT_PREFS });
        }
      } catch (e) {
        setUser({ username: sessionUser, preferences: DEFAULT_PREFS });
      }
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      setMemories(JSON.parse(localStorage.getItem(`nova_${user.username}_memories`) || '[]'));
      setTranscriptions(JSON.parse(localStorage.getItem(`nova_${user.username}_logs`) || '[]'));
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme] || THEMES.cosmic, [prefs.theme]);

  const isWearable = device === 'wear';
  const isAuto = device === 'auto';
  const isTV = device === 'tv';
  const isMobile = device === 'mobile';

  const addTranscription = useCallback((sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev, { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  }, []);

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
  }, [screenStream]);

  const handleLogout = useCallback(() => {
    stopSession();
    setUser(null);
    sessionStorage.removeItem('nova_session_user');
  }, [stopSession]);

  const handleLogin = (username: string, initialPrefs?: Partial<UserPreferences>) => {
    const finalPrefs = { ...DEFAULT_PREFS, ...initialPrefs };
    setUser({ username, preferences: finalPrefs });
  };

  const downsample = (buffer: Float32Array, fromRate: number, toRate: number) => {
    if (fromRate === toRate) return buffer;
    const sampleRateRatio = fromRate / toRate;
    const newLength = Math.round(buffer.length / sampleRateRatio);
    const result = new Float32Array(newLength);
    let offsetResult = 0;
    let offsetBuffer = 0;
    while (offsetResult < result.length) {
      let nextOffsetBuffer = Math.round((offsetResult + 1) * sampleRateRatio);
      let accum = 0, count = 0;
      for (let i = offsetBuffer; i < nextOffsetBuffer && i < buffer.length; i++) {
        accum += buffer[i];
        count++;
      }
      result[offsetResult] = accum / count;
      offsetResult++;
      offsetBuffer = nextOffsetBuffer;
    }
    return result;
  };

  const handlePreviewVoice = async (voiceId: string) => {
    if (previewingVoiceId) return;
    try {
      setPreviewingVoiceId(voiceId);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key required for voice synthesis.");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)(),
          output: new (window.AudioContext || (window as any).webkitAudioContext)()
        };
      }
      const outputCtx = audioContextRef.current.output;
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      const ai = new GoogleGenAI({ apiKey });
      const voice = VOICES.find(v => v.id === voiceId);
      const prompt = `Say: Hello, I am ${voice?.name}. I am your neural voice profile.`;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: voiceId },
            },
          },
        },
      });

      const audioPart = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
      if (audioPart?.inlineData?.data) {
        const audioBuffer = await audioUtils.decodeAudioData(
          audioUtils.decode(audioPart.inlineData.data),
          outputCtx,
          24000,
          1
        );
        const source = outputCtx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(outputCtx.destination);
        source.onended = () => setPreviewingVoiceId(null);
        source.start(0);
      } else {
        setPreviewingVoiceId(null);
      }
    } catch (err: any) {
      setPreviewingVoiceId(null);
    }
  };

  const startSession = async (initialText?: string) => {
    try {
      setState(AssistantState.CONNECTING);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Authentication failure.");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)(),
          output: new (window.AudioContext || (window as any).webkitAudioContext)()
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      audioUtils.playLinkSound(outputCtx);

      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: { echoCancellation: true, noiseSuppression: true, sampleRate: 16000, channelCount: 1 } 
      });
      micStreamRef.current = stream;

      const source = inputCtx.createMediaStreamSource(stream);
      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const personalityPrompt = prefs.personality === 'custom' ? (prefs.customPersonality || 'Be helpful.') : PERSONALITIES[prefs.personality];

      const tools: any[] = [];
      if (sensorData.location) tools.push({ googleMaps: {} });
      if (searchEnabled) tools.push({ googleSearch: {} });
      if (!searchEnabled && !sensorData.location) tools.push({ functionDeclarations: [saveKnowledgeTool] });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools,
          toolConfig: sensorData.location ? {
            retrievalConfig: { latLng: { latitude: sensorData.location.lat, longitude: sensorData.location.lng } }
          } : undefined,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. Platform: ${device}. Personality: ${personalityPrompt}.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const resampledData = downsample(inputData, inputCtx.sampleRate, 16000);
              const pcmBlob = audioUtils.createPcmBlob(resampledData);
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
              if (currentFrameRef.current) {
                const frame = currentFrameRef.current;
                currentFrameRef.current = null;
                sessionPromise.then(s => s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } }));
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
            if (initialText) sessionPromise.then(s => s.sendRealtimeInput({ text: initialText }));
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = (fc.args as any).fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Saved." } } }));
                }
              }
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); 
              s.buffer = buffer; 
              s.connect(outputCtx.destination);
              s.onended = () => { activeSourcesRef.current.delete(s); if (activeSourcesRef.current.size === 0) setState(AssistantState.LISTENING); };
              s.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration; 
              activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            if (message.serverContent?.turnComplete) {
              const chunks = message.serverContent?.groundingMetadata?.groundingChunks || [];
              const sources: GroundingSource[] = chunks.map((c: any) => {
                if (c.web) return { title: c.web.title, uri: c.web.uri };
                if (c.maps) return { title: c.maps.title, uri: c.maps.uri };
                return null;
              }).filter(Boolean) as GroundingSource[];

              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) { addTranscription('assistant', a, sources); audioUtils.playSuccessSound(outputCtx); } return ''; });
            }
          },
          onerror: (err: any) => stopSession(),
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { 
      setErrorToast(err.message);
      setState(AssistantState.IDLE); 
      setTimeout(() => setErrorToast(null), 5000);
    }
  };

  const handleToggleScreenShare = async () => {
    if (isScreenSharing) {
      setIsScreenSharing(false);
      if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    } else {
      try {
        const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
        setScreenStream(stream);
        setIsVisionActive(false);
        setIsScreenSharing(true);
        if (state === AssistantState.IDLE) startSession();
        stream.getVideoTracks()[0].onended = () => { setIsScreenSharing(false); setScreenStream(null); };
      } catch (err: any) {
        setErrorToast(err.message);
      }
    }
  };

  const handleToggleVision = async () => {
    if (isVisionActive) {
      setIsVisionActive(false);
    } else {
      try {
        await navigator.mediaDevices.getUserMedia({ video: true });
        setIsScreenSharing(false);
        setIsVisionActive(true);
        if (state === AssistantState.IDLE) startSession();
      } catch (err: any) {
        setErrorToast("Optic access denied.");
      }
    }
  };

  const handleSendText = () => {
    if (!inputText.trim()) return;
    const msg = inputText.trim();
    setInputText('');
    addTranscription('user', msg);
    if (sessionRef.current) {
      setState(AssistantState.THINKING);
      sessionRef.current.sendRealtimeInput({ text: msg });
    } else {
      startSession(msg);
    }
  };

  if (showIntro) return <IntroSequence onComplete={() => setShowIntro(false)} />;
  if (!user) return <LoginPage onLogin={handleLogin} />;

  if (isScanning) {
    return (
      <div className="fixed inset-0 bg-[#02020a] flex flex-col items-center justify-center z-[200] animate-fade-blur-in overflow-hidden">
        <div className="absolute inset-0 animate-scan-v bg-gradient-to-b from-transparent via-blue-500/20 to-transparent pointer-events-none opacity-40"></div>
        <div className="relative w-64 h-64 flex items-center justify-center animate-float-3d">
          <div className="absolute inset-0 border-4 border-t-blue-500 border-r-transparent border-b-transparent border-l-transparent rounded-full animate-spin"></div>
          <div className="absolute inset-4 border-2 border-b-purple-500 border-t-transparent border-r-transparent border-l-transparent rounded-full animate-spin [animation-duration:3s]"></div>
          <i className="fas fa-atom text-6xl text-white animate-pulse"></i>
        </div>
        <h2 className="mt-12 text-2xl font-black tracking-[0.5em] uppercase text-white mb-2 text-center animate-slide-up-reveal">Neural Sync Active</h2>
        <p className="text-[11px] text-blue-500 font-black uppercase tracking-[0.3em] animate-pulse">Linking Bio-Core...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full w-full transition-all duration-1000 overflow-hidden" style={{ backgroundColor: themeData.bg }}>
      {errorToast && (
        <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[300] bg-red-600/90 backdrop-blur-xl text-white px-8 py-5 rounded-[2rem] font-black uppercase tracking-widest text-[10px] shadow-[0_20px_60px_rgba(220,38,38,0.4)] animate-pop flex items-center gap-4">
          <i className="fas fa-exclamation-triangle"></i>
          {errorToast}
          <button onClick={() => setErrorToast(null)} className="ml-4 opacity-50 hover:opacity-100"><i className="fas fa-times"></i></button>
        </div>
      )}

      {/* Header */}
      <header className={`${isTV ? 'px-20 py-12 m-8 rounded-[4rem]' : 'px-6 py-4 lg:px-12 lg:py-6 m-4 rounded-[2.5rem]'} flex items-center justify-between z-50 glass animate-fade-blur-in`}>
        <div className="flex items-center gap-4 lg:gap-8 group">
          <div className={`${isTV ? 'w-24 h-24 rounded-[3rem]' : 'w-12 h-12 lg:w-16 lg:h-16 rounded-[2rem]'} overflow-hidden border border-white/10 relative transition-all duration-700 group-hover:scale-110 group-hover:rotate-3 shadow-xl group-hover:shadow-blue-500/20`}>
            {prefs.assistantProfilePic ? <img src={prefs.assistantProfilePic} className="w-full h-full object-cover" alt="AI" /> : <div className="w-full h-full bg-blue-500/10 flex items-center justify-center"><i className="fas fa-atom text-white"></i></div>}
          </div>
          {!isMobile && (
            <div className="animate-slide-in-right-bounce">
              <h1 className={`${isTV ? 'text-5xl' : 'text-xl lg:text-3xl'} font-black tracking-tighter text-white uppercase`}>{prefs.assistantName}</h1>
              <HardwareSensors data={sensorData} deviceType={device} themeColor={themeData.primary} />
            </div>
          )}
        </div>
        <div className="flex items-center gap-3 md:gap-4">
           <button onClick={() => setIsSettingsOpen(true)} className={`${isTV ? 'w-20 h-20' : 'w-10 h-10 md:w-12 md:h-12'} rounded-2xl bg-white/5 flex items-center justify-center hover:bg-white/10 transition-all active:scale-90 border border-white/5 shadow-lg`}><i className="fas fa-cog text-lg md:text-xl"></i></button>
           <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`${isTV ? 'w-20 h-20' : 'w-10 h-10 md:w-12 md:h-12'} rounded-2xl flex items-center justify-center transition-all active:scale-90 border border-white/5 ${isMemoryOpen ? 'bg-blue-600 text-white shadow-[0_0_30px_rgba(37,99,235,0.4)]' : 'bg-white/5 text-gray-400 hover:bg-white/10'}`}><i className="fas fa-brain text-lg md:text-xl"></i></button>
           <button onClick={handleLogout} className={`${isTV ? 'px-10 h-20' : 'px-2 md:px-4 h-12'} text-gray-600 hover:text-red-500 transition-colors active:scale-90`}><i className="fas fa-power-off text-lg md:text-xl"></i></button>
        </div>
      </header>

      <main className={`flex-1 flex ${isMobile ? 'flex-col' : 'flex-row'} min-h-0 ${isTV ? 'p-12 gap-12' : 'p-4 lg:p-8 gap-8'} overflow-hidden`}>
        <div className="flex-1 flex flex-col gap-4 lg:gap-8 min-h-0">
          {(isVisionActive || isScreenSharing) && (
            <div className={`${isTV ? 'h-96' : 'h-64 md:h-80'} w-full animate-pop flex-shrink-0 relative group`}>
              <div className="absolute -inset-1 bg-gradient-to-r from-blue-500 to-purple-600 rounded-[2.5rem] blur opacity-20 group-hover:opacity-40 transition-opacity"></div>
              {isVisionActive && <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />}
              {isScreenSharing && screenStream && <ScreenShareMode isActive={isScreenSharing} stream={screenStream} onFrame={(b) => currentFrameRef.current = b} onStop={() => setIsScreenSharing(false)} />}
            </div>
          )}

          <div className="flex-1 flex flex-col glass rounded-[3rem] overflow-hidden relative min-h-0 group shadow-2xl">
            <div className="absolute inset-0 bg-gradient-to-br from-blue-500/5 via-transparent to-purple-500/5 pointer-events-none opacity-40"></div>

            <div className={`flex-1 ${isTV ? 'p-12 space-y-12' : 'p-6 lg:p-10 space-y-8'} overflow-y-auto scrollbar-thin transcription-list`} ref={scrollRef}>
              {transcriptions.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center opacity-20 animate-float-3d">
                  <i className={`fas fa-comment-dots ${isTV ? 'text-[14rem]' : 'text-9xl'} mb-10 text-gray-600`}></i>
                  <p className={`${isTV ? 'text-5xl' : 'text-3xl'} font-black uppercase tracking-[1em] shimmer-text-fast`}>Neural Core</p>
                </div>
              )}

              {transcriptions.map((e, idx) => (
                <div 
                  key={e.id} 
                  className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'} animate-slide-up-reveal`}
                  style={{ animationDelay: `${Math.min(idx * 50, 500)}ms` }}
                >
                  <div className={`
                    ${isTV ? 'max-w-[90%]' : 'max-w-[85%]'} 
                    ${isTV ? 'px-12 py-10 rounded-[4rem]' : 'px-7 py-5 rounded-[2rem]'} 
                    shadow-xl transition-transform hover:scale-[1.01]
                    ${e.sender === 'user' 
                      ? `bg-gradient-to-br from-${themeData.primary} to-indigo-600 text-white animate-slide-in-right-bounce` 
                      : 'bg-white/[0.04] text-gray-200 border border-white/5 backdrop-blur-xl animate-pop'
                    }
                  `}>
                    <p className={`${isTV ? 'text-4xl' : 'text-lg'} font-bold leading-relaxed whitespace-pre-wrap`}>{e.text}</p>
                    {e.sources && <GroundingSources sources={e.sources} themePrimary={themeData.primary} />}
                  </div>
                  <span className="text-[11px] text-gray-600 font-black uppercase tracking-widest mt-2 mx-5 opacity-40">{new Date(e.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                </div>
              ))}

              {(streamingAssistantText || state === AssistantState.THINKING) && (
                <div className="items-start flex flex-col animate-pop">
                  <div className="max-w-[85%] px-7 py-5 rounded-[2rem] bg-white/[0.03] text-white/60 border border-white/5 shadow-lg">
                    {streamingAssistantText ? (
                      <p className="font-mono text-sm leading-relaxed">{streamingAssistantText}</p>
                    ) : (
                      <div className="typing-indicator">
                        <span></span><span></span><span></span>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>

            {/* Controls */}
            <div className={`${isTV ? 'p-12' : 'p-8 lg:p-12'} border-t border-white/5 bg-black/50 backdrop-blur-2xl flex flex-col`}>
              <div className="w-full relative mb-6">
                <div className={`absolute inset-0 blur-[60px] rounded-full opacity-20 transition-colors duration-1000 ${state === AssistantState.SPEAKING ? 'bg-blue-500' : state === AssistantState.LISTENING ? 'bg-emerald-500' : 'bg-transparent'}`}></div>
                <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
              </div>

              <div className={`flex ${isMobile ? 'flex-col gap-5' : 'gap-5'} items-center`}>
                  <div className="flex gap-3 w-full md:w-auto">
                    <button onClick={handleToggleVision} title="Optic Link" className={`${isTV ? 'w-24 h-24' : 'w-14 h-14 flex-1 md:flex-none'} rounded-2xl glass flex items-center justify-center active:scale-90 ${isVisionActive ? 'bg-red-500 text-white shadow-[0_0_30px_rgba(239,68,68,0.4)]' : 'text-gray-500 hover:text-white'}`}><i className="fas fa-camera text-xl"></i></button>
                    <button onClick={handleToggleScreenShare} title="Desktop Uplink" className={`${isTV ? 'w-24 h-24' : 'w-14 h-14 flex-1 md:flex-none'} rounded-2xl glass flex items-center justify-center active:scale-90 ${isScreenSharing ? 'bg-cyan-500 text-white shadow-[0_0_30px_rgba(6,182,212,0.4)]' : 'text-gray-500 hover:text-white'}`}><i className="fas fa-desktop text-xl"></i></button>
                  </div>

                  <input 
                    type="text" 
                    value={inputText} 
                    onChange={(e) => setInputText(e.target.value)} 
                    onKeyDown={(e) => e.key === 'Enter' && handleSendText()} 
                    placeholder="Neural directive..." 
                    className={`flex-1 bg-white/5 border border-white/10 rounded-[2rem] ${isTV ? 'px-12 py-8 text-3xl' : 'px-8 py-5 text-lg'} focus:outline-none focus:border-blue-500/50 text-white font-bold transition-all shadow-inner placeholder-gray-700`} 
                  />

                  <button 
                    onClick={inputText.trim() ? handleSendText : (state === AssistantState.IDLE ? () => startSession() : stopSession)} 
                    className={`${isTV ? 'w-[400px] h-28 text-4xl' : 'w-full md:w-64 h-20'} rounded-[2rem] flex items-center justify-center transition-all gap-4 neo-button shadow-2xl ${state === AssistantState.IDLE ? 'bg-white text-black hover:scale-105 active:scale-95' : 'bg-red-600 text-white animate-pulse'}`}
                  >
                    <i className={`fas ${inputText.trim() ? 'fa-paper-plane' : (state === AssistantState.IDLE ? 'fa-microphone' : 'fa-square')} text-lg`}></i>
                    <span className="font-black uppercase tracking-[0.2em] text-[11px]">
                      {inputText.trim() ? 'DISPATCH' : (state === AssistantState.IDLE ? 'INITIALIZE' : 'TERMINATE')}
                    </span>
                  </button>
              </div>
            </div>
          </div>
        </div>

        {isMemoryOpen && !isMobile && (
          <div className={`${isTV ? 'w-[600px]' : 'w-full md:w-[420px]'} flex-shrink-0 h-full animate-slide-in-right-bounce`}>
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
          </div>
        )}
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        prefs={prefs}
        setPrefs={setPrefs}
        voices={VOICES}
        personalities={PERSONALITIES}
        isTV={isTV}
        isWearable={isWearable}
        onPreviewVoice={handlePreviewVoice}
        previewingVoiceId={previewingVoiceId}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { UserPreferences, PersonalityType } from '../types';

interface Voice {
  id: string;
  name: string;
  tone: string;
  gender: string;
}

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  prefs: UserPreferences;
  setPrefs: React.Dispatch<React.SetStateAction<UserPreferences>>;
  voices: Voice[];
  personalities: Record<PersonalityType, string>;
  isTV: boolean;
  isWearable: boolean;
  onPreviewVoice?: (voiceId: string) => void;
  previewingVoiceId?: string | null;
}

const SettingsModal: React.FC<SettingsModalProps> = ({
  isOpen,
  onClose,
  prefs,
  setPrefs,
  voices,
  personalities,
  isTV,
  isWearable,
  onPreviewVoice,
  previewingVoiceId,
}) => {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[150] bg-black/95 backdrop-blur-2xl flex items-center justify-center p-4 lg:p-8">
      <div className={`w-full ${isTV ? 'max-w-6xl p-20' : 'max-w-4xl p-12'} bg-[#02020a] border border-white/10 ${isTV ? 'rounded-[6rem]' : 'rounded-[4rem]'} relative overflow-y-auto max-h-[90vh] scrollbar-thin`}>
        <button onClick={onClose} className="absolute top-8 right-8 lg:top-12 lg:right-12 text-gray-700 hover:text-white text-2xl">
          <i className="fas fa-times"></i>
        </button>
        <h2 className={`${isTV ? 'text-6xl' : 'text-4xl'} font-black tracking-tighter uppercase mb-12`}>Configuration</h2>
        <div className={`grid grid-cols-1 ${isWearable ? '' : 'lg:grid-cols-2'} gap-8 lg:gap-12`}>
          <section className="space-y-8 lg:space-y-12">
            <div className="space-y-4">
              <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Assistant Designation</label>
              <input 
                type="text" 
                value={prefs.assistantName} 
                onChange={(e) => setPrefs(p => ({ ...p, assistantName: e.target.value }))} 
                className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 font-black text-xl" 
              />
            </div>
            <div className="space-y-4">
              <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest block mb-4">Neural Profile</label>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                {voices.map(v => (
                  <div 
                    key={v.id} 
                    className={`flex items-center justify-between px-4 py-3 rounded-2xl border-2 transition-all group ${prefs.voiceId === v.id ? 'bg-blue-500/10 border-blue-500' : 'bg-white/5 border-white/5 hover:border-white/10'}`}
                  >
                    <button 
                      onClick={() => setPrefs(pr => ({ ...pr, voiceId: v.id }))} 
                      className="flex items-center gap-3 text-left flex-1"
                    >
                      <div className={`w-8 h-8 rounded-xl flex items-center justify-center flex-shrink-0 ${v.gender === 'masculine' ? 'bg-blue-900/20 text-blue-500' : 'bg-emerald-900/20 text-emerald-500'}`}>
                        <i className={`fas ${v.gender === 'masculine' ? 'fa-male' : 'fa-female'} text-xs`}></i>
                      </div>
                      <div className="overflow-hidden">
                        <p className={`text-xs font-black uppercase tracking-widest truncate ${prefs.voiceId === v.id ? 'text-white' : 'text-gray-400'}`}>{v.name}</p>
                        <p className="text-[8px] text-gray-600 truncate">{v.tone}</p>
                      </div>
                    </button>

                    <div className="flex items-center gap-2">
                      <button 
                        onClick={(e) => { e.stopPropagation(); onPreviewVoice?.(v.id); }}
                        className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all ${previewingVoiceId === v.id ? 'bg-blue-500 text-white animate-pulse' : 'bg-white/5 text-gray-600 hover:text-white hover:bg-white/10'}`}
                        title="Neural Preview"
                      >
                        {previewingVoiceId === v.id ? (
                          <i className="fas fa-circle-notch fa-spin text-[10px]"></i>
                        ) : (
                          <i className="fas fa-volume-up text-[10px]"></i>
                        )}
                      </button>
                      {prefs.voiceId === v.id && <i className="fas fa-check-circle text-blue-500 text-xs"></i>}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </section>
          <section className="space-y-8 lg:space-y-12">
            <div className="space-y-4">
              <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Neural Persona</label>
              <div className="grid grid-cols-2 gap-3">
                {(Object.keys(personalities) as PersonalityType[]).map(p => (
                  <button 
                    key={p} 
                    onClick={() => setPrefs(pr => ({ ...pr, personality: p }))} 
                    className={`py-4 rounded-xl border-2 transition-all font-black text-[9px] uppercase tracking-widest ${prefs.personality === p ? `bg-blue-500/10 border-blue-500` : 'border-white/5 text-gray-700'}`}
                  >
                    {p}
                  </button>
                ))}
              </div>

              {prefs.personality === 'custom' && (
                <div className="mt-6 animate-slide-up space-y-4">
                  <label className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Behavioral Directives</label>
                  <textarea 
                    value={prefs.customPersonality} 
                    onChange={(e) => setPrefs(p => ({ ...p, customPersonality: e.target.value }))}
                    placeholder="Instruct the assistant on how to think, act, and respond..."
                    className="w-full h-32 bg-white/5 border border-white/10 rounded-2xl p-4 text-xs font-mono text-gray-300 focus:outline-none focus:border-blue-500/50 resize-none"
                  />
                </div>
              )}
            </div>
            {!isWearable && (
              <div className="p-8 bg-blue-500/5 border border-blue-500/10 rounded-3xl">
                <p className="text-[10px] text-blue-400 font-black uppercase tracking-widest mb-2 flex items-center gap-2">
                  <i className="fas fa-shield-halved"></i> Security Node
                </p>
                <p className="text-xs text-gray-500 leading-relaxed">
                  Optic and audio uplinks require explicit user activation to ensure privacy standards. Configuration changes propagate across the neural segment instantly.
                </p>
              </div>
            )}
          </section>
        </div>
        <button 
          onClick={onClose} 
          className="mt-12 w-full py-6 bg-white text-black font-black uppercase tracking-widest rounded-full hover:scale-[1.02] transition-transform"
        >
          Apply Neural Configuration
        </button>
      </div>
    </div>
  );
};

export default SettingsModal;

export enum AssistantState {
  IDLE = 'IDLE',
  CONNECTING = 'CONNECTING',
  LISTENING = 'LISTENING',
  SPEAKING = 'SPEAKING',
  THINKING = 'THINKING',
  OBSERVING = 'OBSERVING',
  ERROR = 'ERROR'
}

export type DeviceType = 'wear' | 'mobile' | 'desktop' | 'tv' | 'auto';

export type UITheme = 'cosmic' | 'emerald' | 'ruby' | 'obsidian';
export type PersonalityType = 'professional' | 'friendly' | 'witty' | 'minimalist' | 'alluring' | 'custom';

export interface GroundingSource {
  title: string;
  uri: string;
}

export interface SensorData {
  battery?: number;
  charging?: boolean;
  online: boolean;
  platform: string;
  location?: { lat: number; lng: number };
}

export interface TranscriptionEntry {
  id: string;
  sender: 'user' | 'assistant';
  text: string;
  timestamp: Date;
  isThinking?: boolean;
  isStreaming?: boolean;
  sources?: GroundingSource[];
}

export interface MemoryEntry {
  id: string;
  fact: string;
  timestamp: Date;
}

export interface GeneratedAsset {
  id: string;
  type: 'image' | 'video';
  url: string;
  prompt: string;
  timestamp: Date;
}

export interface UserPreferences {
  theme: UITheme;
  personality: PersonalityType;
  customPersonality?: string;
  layout: 'left' | 'right';
  voiceId: string;
  assistantName: string;
  assistantProfilePic?: string;
  modality: 'masculine' | 'feminine';
}

export interface AuthUser {
  username: string;
  preferences: UserPreferences;
}

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, GroundingSource, AuthUser, UITheme, PersonalityType, UserPreferences, DeviceType, SensorData } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';
import ScreenShareMode from './components/ScreenShareMode';
import HardwareSensors from './components/HardwareSensors';
import GroundingSources from './components/GroundingSources';
import SettingsModal from './components/SettingsModal';
import IntroSequence from './components/IntroSequence';

const THEMES: Record<UITheme, { primary: string; secondary: string; glow: string; bg: string }> = {
  cosmic: { primary: 'blue-500', secondary: 'indigo-500', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: 'emerald-500', secondary: 'teal-500', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: 'rose-500', secondary: 'orange-500', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: 'slate-400', secondary: 'zinc-500', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: 'achernar',
  assistantName: 'Project Chatty',
  customPersonality: 'You are a highly capable AI assistant.',
  modality: 'masculine'
};

const App: React.FC = () => {
  const [showIntro, setShowIntro] = useState(true);
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [device, setDevice] = useState<DeviceType>('desktop');
  const [isScanning, setIsScanning] = useState(true);
  const [sensorData, setSensorData] = useState<SensorData>({ online: navigator.onLine, platform: navigator.platform });
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [inputText, setInputText] = useState('');
  const [searchEnabled, setSearchEnabled] = useState(true);
  const [errorToast, setErrorToast] = useState<string | null>(null);
  const [previewingVoiceId, setPreviewingVoiceId] = useState<string | null>(null);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  const dynamicVoices = useMemo(() => {
    const isFem = prefs.modality === 'feminine';
    return [
      { id: 'achernar', name: isFem ? 'Paula' : 'Caleb', tone: 'Smooth, Resonant, Clear', gender: isFem ? 'feminine' : 'masculine' },
      { id: 'puck', name: 'Jake', tone: 'Energetic, Bright, Playful', gender: 'masculine' },
      { id: 'fenrir', name: isFem ? 'Kai' : 'Able', tone: 'Vibrant, Sharp, Focused', gender: isFem ? 'feminine' : 'masculine' },
      { id: 'charon', name: isFem ? 'Gabby' : 'John', tone: 'Deep, Bass, Authoritative', gender: isFem ? 'feminine' : 'masculine' },
      { id: 'zephyr', name: 'Jane', tone: 'Warm, Smooth, Melodic', gender: 'feminine' },
      { id: 'kore', name: 'Kayla', tone: 'Clear, Professional, Calm', gender: 'feminine' },
      { id: 'aoede', name: 'Ninni', tone: 'Poetic, Soulful, Expressive', gender: 'feminine' },
      { id: 'leda', name: 'Clarissa', tone: 'Bright, Airy, Gentle', gender: 'feminine' }
    ];
  }, [prefs.modality]);

  const detectHardware = useCallback(async () => {
    try {
      const w = window.innerWidth;
      const h = window.innerHeight;
      const ua = navigator.userAgent.toLowerCase();

      let detectedDevice: DeviceType = 'desktop';
      if (w <= 300 || (ua.includes('watch') && !ua.includes('tv'))) {
        detectedDevice = 'wear';
      } else if (ua.includes('android') && w > h && w >= 800 && w <= 1280) {
        detectedDevice = 'auto';
      } else if (ua.includes('tv') || ua.includes('smarttv') || (w >= 1920 && h >= 1080)) {
        detectedDevice = 'tv';
      } else if (w < 768 || (w < 1024 && h > w)) {
        detectedDevice = 'mobile';
      }
      setDevice(detectedDevice);
      document.documentElement.setAttribute('data-device', detectedDevice);

      const sensorPayload: SensorData = { online: navigator.onLine, platform: navigator.platform };

      if (navigator && 'getBattery' in navigator) {
        try {
          const battery = await (navigator as any).getBattery();
          sensorPayload.battery = battery.level;
          sensorPayload.charging = battery.charging;
        } catch (e) {
          console.warn("Battery API inaccessible");
        }
      }

      if (navigator.geolocation && ['auto', 'mobile', 'desktop'].includes(detectedDevice)) {
        navigator.geolocation.getCurrentPosition(
          (pos) => setSensorData(prev => ({ ...prev, location: { lat: pos.coords.latitude, lng: pos.coords.longitude } })),
          (err) => console.warn("GPS locked", err.message),
          { enableHighAccuracy: false, timeout: 5000 }
        );
      }
      setSensorData(prev => ({ ...prev, ...sensorPayload }));
    } catch (err) {
      console.error("Hardware probe failure", err);
    } finally {
      setTimeout(() => setIsScanning(false), 2000);
    }
  }, []);

  useEffect(() => {
    detectHardware();
    window.addEventListener('resize', detectHardware);
    return () => window.removeEventListener('resize', detectHardware);
  }, [detectHardware]);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user');
    if (sessionUser) {
      try {
        const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
        if (savedPrefs) {
          setUser({ username: sessionUser, preferences: JSON.parse(savedPrefs) });
        } else {
          setUser({ username: sessionUser, preferences: DEFAULT_PREFS });
        }
      } catch (e) {
        setUser({ username: sessionUser, preferences: DEFAULT_PREFS });
      }
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      setMemories(JSON.parse(localStorage.getItem(`nova_${user.username}_memories`) || '[]'));
      setTranscriptions(JSON.parse(localStorage.getItem(`nova_${user.username}_logs`) || '[]'));
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const themeData = useMemo(() => THEMES[prefs.theme] || THEMES.cosmic, [prefs.theme]);

  const isWearable = device === 'wear';
  const isAuto = device === 'auto';
  const isTV = device === 'tv';
  const isMobile = device === 'mobile';

  const addTranscription = useCallback((sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text.trim()) return;
    setTranscriptions(prev => [
      ...prev, { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  }, []);

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
  }, [screenStream]);

  const handleLogout = useCallback(() => {
    stopSession();
    setUser(null);
    sessionStorage.removeItem('nova_session_user');
  }, [stopSession]);

  const handleLogin = (username: string, initialPrefs?: Partial<UserPreferences>) => {
    const finalPrefs = { ...DEFAULT_PREFS, ...initialPrefs };
    setUser({ username, preferences: finalPrefs });
  };

  const downsample = (buffer: Float32Array, fromRate: number, toRate: number) => {
    if (fromRate === toRate) return buffer;
    const sampleRateRatio = fromRate / toRate;
    const newLength = Math.round(buffer.length / sampleRateRatio);
    const result = new Float32Array(newLength);
    let offsetResult = 0;
    let offsetBuffer = 0;
    while (offsetResult < result.length) {
      let nextOffsetBuffer = Math.round((offsetResult + 1) * sampleRateRatio);
      let accum = 0, count = 0;
      for (let i = offsetBuffer; i < nextOffsetBuffer && i < buffer.length; i++) {
        accum += buffer[i];
        count++;
      }
      result[offsetResult] = accum / count;
      offsetResult++;
      offsetBuffer = nextOffsetBuffer;
    }
    return result;
  };

  const handlePreviewVoice = async (voiceId: string) => {
    if (previewingVoiceId) return;
    try {
      setPreviewingVoiceId(voiceId);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key required for voice synthesis.");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)(),
          output: new (window.AudioContext || (window as any).webkitAudioContext)()
        };
      }
      const outputCtx = audioContextRef.current.output;
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      const ai = new GoogleGenAI({ apiKey });
      const voice = dynamicVoices.find(v => v.id === voiceId);
      const prompt = `Say: Hello, I am ${voice?.name}. I am your neural voice profile.`;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: voiceId },
            },
          },
        },
      });

      const audioPart = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
      if (audioPart?.inlineData?.data) {
        const audioBuffer = await audioUtils.decodeAudioData(
          audioUtils.decode(audioPart.inlineData.data),
          outputCtx,
          24000,
          1
        );
        const source = outputCtx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(outputCtx.destination);
        source.onended = () => setPreviewingVoiceId(null);
        source.start(0);
      } else {
        setPreviewingVoiceId(null);
      }
    } catch (err: any) {
      setPreviewingVoiceId(null);
    }
  };

  const startSession = async (initialText?: string) => {
    try {
      setState(AssistantState.CONNECTING);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Authentication failure.");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)(),
          output: new (window.AudioContext || (window as any).webkitAudioContext)()
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      audioUtils.playLinkSound(outputCtx);

      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: { echoCancellation: true, noiseSuppression: true, sampleRate: 16000, channelCount: 1 } 
      });
      micStreamRef.current = stream;

      const source = inputCtx.createMediaStreamSource(stream);
      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const personalityPrompt = prefs.personality === 'custom' ? (prefs.customPersonality || 'Be helpful.') : PERSONALITIES[prefs.personality];

      const tools: any[] = [];
      if (sensorData.location) tools.push({ googleMaps: {} });
      if (searchEnabled) tools.push({ googleSearch: {} });
      if (!searchEnabled && !sensorData.location) tools.push({ functionDeclarations: [saveKnowledgeTool] });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools,
          toolConfig: sensorData.location ? {
            retrievalConfig: { latLng: { latitude: sensorData.location.lat, longitude: sensorData.location.lng } }
          } : undefined,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. Platform: ${device}. Personality: ${personalityPrompt}.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        },
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const resampledData = downsample(inputData, inputCtx.sampleRate, 16000);
              const pcmBlob = audioUtils.createPcmBlob(resampledData);
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
              if (currentFrameRef.current) {
                const frame = currentFrameRef.current;
                currentFrameRef.current = null;
                sessionPromise.then(s => s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } }));
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
            if (initialText) sessionPromise.then(s => s.sendRealtimeInput({ text: initialText }));
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = (fc.args as any).fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Saved." } } }));
                }
              }
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setState(AssistantState.SPEAKING);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
              const s = outputCtx.createBufferSource(); 
              s.buffer = buffer; 
              s.connect(outputCtx.destination);
              s.onended = () => { activeSourcesRef.current.delete(s); if (activeSourcesRef.current.size === 0) setState(AssistantState.LISTENING); };
              s.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration; 
              activeSourcesRef.current.add(s);
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent!.inputTranscription!.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent!.outputTranscription!.text);
            if (message.serverContent?.turnComplete) {
              const chunks = message.serverContent?.groundingMetadata?.groundingChunks || [];
              const sources: GroundingSource[] = chunks.map((c: any) => {
                if (c.web) return { title: c.web.title, uri: c.web.uri };
                if (c.maps) return { title: c.maps.title, uri: c.maps.uri };
                return null;
              }).filter(Boolean) as GroundingSource[];

              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) { addTranscription('assistant', a, sources); audioUtils.playSuccessSound(outputCtx); } return ''; });
            }
          },
          onerror: (err: any) => stopSession(),
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { 
      setErrorToast(err.message);
      setState(AssistantState.IDLE); 
      setTimeout(() => setErrorToast(null), 5000);
    }
  };

  const handleToggleScreenShare = async () => {
    if (isScreenSharing) {
      setIsScreenSharing(false);
      if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    } else {
      try {
        const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
        setScreenStream(stream);
        setIsVisionActive(false);
        setIsScreenSharing(true);
        if (state === AssistantState.IDLE) startSession();
        stream.getVideoTracks()[0].onended = () => { setIsScreenSharing(false); setScreenStream(null); };
      } catch (err: any) {
        setErrorToast(err.message);
      }
    }
  };

  const handleToggleVision = async () => {
    if (isVisionActive) {
      setIsVisionActive(false);
    } else {
      try {
        await navigator.mediaDevices.getUserMedia({ video: true });
        setIsScreenSharing(false);
        setIsVisionActive(true);
        if (state === AssistantState.IDLE) startSession();
      } catch (err: any) {
        setErrorToast("Optic access denied.");
      }
    }
  };

  const handleSendText = () => {
    if (!inputText.trim()) return;
    const msg = inputText.trim();
    setInputText('');
    addTranscription('user', msg);
    if (sessionRef.current) {
      setState(AssistantState.THINKING);
      sessionRef.current.sendRealtimeInput({ text: msg });
    } else {
      startSession(msg);
    }
  };

  if (showIntro) return <IntroSequence onComplete={() => setShowIntro(false)} />;
  if (!user) return <LoginPage onLogin={handleLogin} />;

  if (isScanning) {
    return (
      <div className="fixed inset-0 bg-[#02020a] flex flex-col items-center justify-center z-[200] animate-fade-blur-in overflow-hidden">
        <div className="absolute inset-0 animate-scan-v bg-gradient-to-b from-transparent via-blue-500/20 to-transparent pointer-events-none opacity-40"></div>
        <div className="relative w-64 h-64 flex items-center justify-center animate-float-3d">
          <div className="absolute inset-0 border-4 border-t-blue-500 border-r-transparent border-b-transparent border-l-transparent rounded-full animate-spin"></div>
          <div className="absolute inset-4 border-2 border-b-purple-500 border-t-transparent border-r-transparent border-l-transparent rounded-full animate-spin [animation-duration:3s]"></div>
          <i className="fas fa-atom text-6xl text-white animate-pulse"></i>
        </div>
        <h2 className="mt-12 text-2xl font-black tracking-[0.5em] uppercase text-white mb-2 text-center animate-slide-up-reveal">Neural Sync Active</h2>
        <p className="text-[11px] text-blue-500 font-black uppercase tracking-[0.3em] animate-pulse">Linking Bio-Core...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full w-full transition-all duration-1000 overflow-hidden" style={{ backgroundColor: themeData.bg }}>
      {errorToast && (
        <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[300] bg-red-600/90 backdrop-blur-xl text-white px-8 py-5 rounded-[2rem] font-black uppercase tracking-widest text-[10px] shadow-[0_20px_60px_rgba(220,38,38,0.4)] animate-pop flex items-center gap-4">
          <i className="fas fa-exclamation-triangle"></i>
          {errorToast}
          <button onClick={() => setErrorToast(null)} className="ml-4 opacity-50 hover:opacity-100"><i className="fas fa-times"></i></button>
        </div>
      )}

      {/* Header */}
      <header className={`${isTV ? 'px-20 py-12 m-8 rounded-[4rem]' : 'px-6 py-4 lg:px-12 lg:py-6 m-4 rounded-[2.5rem]'} flex items-center justify-between z-50 glass animate-fade-blur-in`}>
        <div className="flex items-center gap-4 lg:gap-8 group">
          <div className={`${isTV ? 'w-24 h-24 rounded-[3rem]' : 'w-12 h-12 lg:w-16 lg:h-16 rounded-[2rem]'} overflow-hidden border border-white/10 relative transition-all duration-700 group-hover:scale-110 group-hover:rotate-3 shadow-xl group-hover:shadow-blue-500/20`}>
            {prefs.assistantProfilePic ? <img src={prefs.assistantProfilePic} className="w-full h-full object-cover" alt="AI" /> : <div className="w-full h-full bg-blue-500/10 flex items-center justify-center"><i className="fas fa-atom text-white"></i></div>}
          </div>
          {!isMobile && (
            <div className="animate-slide-in-right-bounce">
              <h1 className={`${isTV ? 'text-5xl' : 'text-xl lg:text-3xl'} font-black tracking-tighter text-white uppercase`}>{prefs.assistantName}</h1>
              <HardwareSensors data={sensorData} deviceType={device} themeColor={themeData.primary} />
            </div>
          )}
        </div>
        <div className="flex items-center gap-3 md:gap-4">
           <button onClick={() => setIsSettingsOpen(true)} className={`${isTV ? 'w-20 h-20' : 'w-10 h-10 md:w-12 md:h-12'} rounded-2xl bg-white/5 flex items-center justify-center hover:bg-white/10 transition-all active:scale-90 border border-white/5 shadow-lg`}><i className="fas fa-cog text-lg md:text-xl"></i></button>
           <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`${isTV ? 'w-20 h-20' : 'w-10 h-10 md:w-12 md:h-12'} rounded-2xl flex items-center justify-center transition-all active:scale-90 border border-white/5 ${isMemoryOpen ? 'bg-blue-600 text-white shadow-[0_0_30px_rgba(37,99,235,0.4)]' : 'bg-white/5 text-gray-400 hover:bg-white/10'}`}><i className="fas fa-brain text-lg md:text-xl"></i></button>
           <button onClick={handleLogout} className={`${isTV ? 'px-10 h-20' : 'px-2 md:px-4 h-12'} text-gray-600 hover:text-red-500 transition-colors active:scale-90`}><i className="fas fa-power-off text-lg md:text-xl"></i></button>
        </div>
      </header>

      <main className={`flex-1 flex ${isMobile ? 'flex-col' : 'flex-row'} min-h-0 ${isTV ? 'p-12 gap-12' : 'p-4 lg:p-8 gap-8'} overflow-hidden`}>
        <div className="flex-1 flex flex-col gap-4 lg:gap-8 min-h-0">
          {(isVisionActive || isScreenSharing) && (
            <div className={`${isTV ? 'h-96' : 'h-64 md:h-80'} w-full animate-pop flex-shrink-0 relative group`}>
              <div className="absolute -inset-1 bg-gradient-to-r from-blue-500 to-purple-600 rounded-[2.5rem] blur opacity-20 group-hover:opacity-40 transition-opacity"></div>
              {isVisionActive && <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />}
              {isScreenSharing && screenStream && <ScreenShareMode isActive={isScreenSharing} stream={screenStream} onFrame={(b) => currentFrameRef.current = b} onStop={() => setIsScreenSharing(false)} />}
            </div>
          )}

          <div className="flex-1 flex flex-col glass rounded-[3rem] overflow-hidden relative min-h-0 group shadow-2xl">
            <div className="absolute inset-0 bg-gradient-to-br from-blue-500/5 via-transparent to-purple-500/5 pointer-events-none opacity-40"></div>

            <div className={`flex-1 ${isTV ? 'p-12 space-y-12' : 'p-6 lg:p-10 space-y-8'} overflow-y-auto scrollbar-thin transcription-list`} ref={scrollRef}>
              {transcriptions.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center opacity-20 animate-float-3d">
                  <i className={`fas fa-comment-dots ${isTV ? 'text-[14rem]' : 'text-9xl'} mb-10 text-gray-600`}></i>
                  <p className={`${isTV ? 'text-5xl' : 'text-3xl'} font-black uppercase tracking-[1em] shimmer-text-fast`}>Neural Core</p>
                </div>
              )}

              {transcriptions.map((e, idx) => (
                <div 
                  key={e.id} 
                  className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'} animate-slide-up-reveal`}
                  style={{ animationDelay: `${Math.min(idx * 50, 500)}ms` }}
                >
                  <div className={`
                    ${isTV ? 'max-w-[90%]' : 'max-w-[85%]'} 
                    ${isTV ? 'px-12 py-10 rounded-[4rem]' : 'px-7 py-5 rounded-[2rem]'} 
                    shadow-xl transition-transform hover:scale-[1.01]
                    ${e.sender === 'user' 
                      ? `bg-gradient-to-br from-${themeData.primary} to-indigo-600 text-white animate-slide-in-right-bounce` 
                      : 'bg-white/[0.04] text-gray-200 border border-white/5 backdrop-blur-xl animate-pop'
                    }
                  `}>
                    <p className={`${isTV ? 'text-4xl' : 'text-lg'} font-bold leading-relaxed whitespace-pre-wrap`}>{e.text}</p>
                    {e.sources && <GroundingSources sources={e.sources} themePrimary={themeData.primary} />}
                  </div>
                  <span className="text-[11px] text-gray-600 font-black uppercase tracking-widest mt-2 mx-5 opacity-40">{new Date(e.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                </div>
              ))}

              {(streamingAssistantText || state === AssistantState.THINKING) && (
                <div className="items-start flex flex-col animate-pop">
                  <div className="max-w-[85%] px-7 py-5 rounded-[2rem] bg-white/[0.03] text-white/60 border border-white/5 shadow-lg">
                    {streamingAssistantText ? (
                      <p className="font-mono text-sm leading-relaxed">{streamingAssistantText}</p>
                    ) : (
                      <div className="typing-indicator">
                        <span></span><span></span><span></span>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>

            {/* Controls */}
            <div className={`${isTV ? 'p-12' : 'p-8 lg:p-12'} border-t border-white/5 bg-black/50 backdrop-blur-2xl flex flex-col`}>
              <div className="w-full relative mb-6">
                <div className={`absolute inset-0 blur-[60px] rounded-full opacity-20 transition-colors duration-1000 ${state === AssistantState.SPEAKING ? 'bg-blue-500' : state === AssistantState.LISTENING ? 'bg-emerald-500' : 'bg-transparent'}`}></div>
                <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
              </div>

              <div className={`flex ${isMobile ? 'flex-col gap-5' : 'gap-5'} items-center`}>
                  <div className="flex gap-3 w-full md:w-auto">
                    <button onClick={handleToggleVision} title="Optic Link" className={`${isTV ? 'w-24 h-24' : 'w-14 h-14 flex-1 md:flex-none'} rounded-2xl glass flex items-center justify-center active:scale-90 ${isVisionActive ? 'bg-red-500 text-white shadow-[0_0_30px_rgba(239,68,68,0.4)]' : 'text-gray-500 hover:text-white'}`}><i className="fas fa-camera text-xl"></i></button>
                    <button onClick={handleToggleScreenShare} title="Desktop Uplink" className={`${isTV ? 'w-24 h-24' : 'w-14 h-14 flex-1 md:flex-none'} rounded-2xl glass flex items-center justify-center active:scale-90 ${isScreenSharing ? 'bg-cyan-500 text-white shadow-[0_0_30px_rgba(6,182,212,0.4)]' : 'text-gray-500 hover:text-white'}`}><i className="fas fa-desktop text-xl"></i></button>
                  </div>

                  <input 
                    type="text" 
                    value={inputText} 
                    onChange={(e) => setInputText(e.target.value)} 
                    onKeyDown={(e) => e.key === 'Enter' && handleSendText()} 
                    placeholder="Neural directive..." 
                    className={`flex-1 bg-white/5 border border-white/10 rounded-[2rem] ${isTV ? 'px-12 py-8 text-3xl' : 'px-8 py-5 text-lg'} focus:outline-none focus:border-blue-500/50 text-white font-bold transition-all shadow-inner placeholder-gray-700`} 
                  />

                  <button 
                    onClick={inputText.trim() ? handleSendText : (state === AssistantState.IDLE ? () => startSession() : stopSession)} 
                    className={`${isTV ? 'w-[400px] h-28 text-4xl' : 'w-full md:w-64 h-20'} rounded-[2rem] flex items-center justify-center transition-all gap-4 neo-button shadow-2xl ${state === AssistantState.IDLE ? 'bg-white text-black hover:scale-105 active:scale-95' : 'bg-red-600 text-white animate-pulse'}`}
                  >
                    <i className={`fas ${inputText.trim() ? 'fa-paper-plane' : (state === AssistantState.IDLE ? 'fa-microphone' : 'fa-square')} text-lg`}></i>
                    <span className="font-black uppercase tracking-[0.2em] text-[11px]">
                      {inputText.trim() ? 'DISPATCH' : (state === AssistantState.IDLE ? 'INITIALIZE' : 'TERMINATE')}
                    </span>
                  </button>
              </div>
            </div>
          </div>
        </div>

        {isMemoryOpen && !isMobile && (
          <div className={`${isTV ? 'w-[600px]' : 'w-full md:w-[420px]'} flex-shrink-0 h-full animate-slide-in-right-bounce`}>
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
          </div>
        )}
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        prefs={prefs}
        setPrefs={setPrefs}
        voices={dynamicVoices}
        personalities={PERSONALITIES}
        isTV={isTV}
        isWearable={isWearable}
        onPreviewVoice={handlePreviewVoice}
        previewingVoiceId={previewingVoiceId}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { UserPreferences } from '../types';

interface LoginPageProps {
  onLogin: (username: string, initialPrefs?: Partial<UserPreferences>) => void;
}

type AuthMode = 'VAULT' | 'SIGN_UP' | 'SAFETY_GATE' | 'VOICE_SELECT' | 'VERIFY';

const LoginPage: React.FC<LoginPageProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [age, setAge] = useState<number | ''>('');
  const [genderPref, setGenderPref] = useState<'masculine' | 'feminine'>('masculine');
  const [showPassword, setShowPassword] = useState(false);
  const [mode, setMode] = useState<AuthMode>('VAULT');
  const [selectedProfile, setSelectedProfile] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);

  const getStoredUsers = (): Record<string, string> => {
    try {
      const stored = localStorage.getItem('nova_credentials');
      return stored ? JSON.parse(stored) : {};
    } catch (e) {
      return {};
    }
  };

  useEffect(() => {
    const users = getStoredUsers();
    if (Object.keys(users).length === 0) {
      setMode('SIGN_UP');
    }
  }, []);

  const handleSignUpStart = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    const users = getStoredUsers();
    if (users[username]) {
      setError("Designation already registered.");
      return;
    }
    setMode('SAFETY_GATE');
  };

  const handleAgeCheck = (e: React.FormEvent) => {
    e.preventDefault();
    if (age === '' || age < 13) {
      setError("Safety Protocol: Access denied for individuals under 13.");
      return;
    }
    setError(null);
    setMode('VOICE_SELECT');
  };

  const finalizeSignUp = () => {
    setIsSyncing(true);
    const users = getStoredUsers();
    setTimeout(() => {
      const updatedUsers = { ...users, [username]: password };
      localStorage.setItem('nova_credentials', JSON.stringify(updatedUsers));

      const identities = JSON.parse(localStorage.getItem('nova_identities') || '[]');
      localStorage.setItem('nova_identities', JSON.stringify([...new Set([username, ...identities])]));

      const defaultVoiceId = genderPref === 'masculine' ? 'achernar' : 'achernar'; // Both resolve to appropriate names
      onLogin(username, { 
        voiceId: defaultVoiceId,
        modality: genderPref 
      });
    }, 1500);
  };

  const handleVerify = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    const users = getStoredUsers();
    if (users[selectedProfile!] === password) {
      setIsSyncing(true);
      setTimeout(() => onLogin(selectedProfile!), 1200);
    } else {
      setError("Neural passcode mismatch.");
    }
  };

  const identities = JSON.parse(localStorage.getItem('nova_identities') || '[]');

  return (
    <div className="min-h-screen w-full flex items-center justify-center p-6 bg-[#02020a] relative overflow-hidden font-sans">
      {/* Dynamic Background */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute top-[-10%] left-[-10%] w-[60%] h-[60%] bg-blue-600/5 rounded-full blur-[150px] animate-pulse-slow"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[60%] h-[60%] bg-purple-600/5 rounded-full blur-[150px] animate-pulse-slow"></div>
        <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20 mix-blend-overlay"></div>
      </div>

      <div className="w-full max-w-4xl z-10">
        {mode === 'VAULT' ? (
          <div className="space-y-12 animate-fade-in">
            <header className="text-center space-y-6">
              <div className="inline-flex items-center gap-3 px-4 py-2 rounded-full bg-blue-500/10 border border-blue-500/20 text-blue-400 text-[10px] font-black uppercase tracking-[0.5em] mb-4 mx-auto animate-float">
                <i className="fas fa-vault"></i> Identity Vault Active
              </div>
              <h1 className="text-7xl font-black tracking-tighter text-white drop-shadow-2xl">
                Neural Link <span className="shimmer-text">Established</span>
              </h1>
              <p className="text-gray-500 uppercase tracking-widest text-[10px] font-bold">Select biological segment to proceed</p>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {identities.map((name: string, i: number) => (
                <button
                  key={name}
                  onClick={() => { setSelectedProfile(name); setMode('VERIFY'); }}
                  style={{ animationDelay: `${i * 100}ms` }}
                  className="group relative bg-white/[0.02] hover:bg-white/[0.08] border border-white/5 rounded-[3rem] p-10 transition-all duration-700 hover:scale-[1.05] text-left glass animate-slide-up"
                >
                  {/* Miniature scanner on profile cards */}
                  <div className="absolute inset-0 overflow-hidden rounded-[3rem] pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity">
                    <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-blue-400 to-transparent animate-biometric"></div>
                  </div>

                  <div className="w-16 h-16 rounded-[2rem] bg-gradient-to-br from-blue-500 to-indigo-600 flex items-center justify-center text-2xl font-black shadow-2xl group-hover:rotate-6 transition-transform relative">
                    {name[0].toUpperCase()}
                    <div className="absolute inset-0 border border-white/20 rounded-[2rem] animate-pulse"></div>
                  </div>
                  <div className="mt-10">
                    <p className="text-2xl font-black text-white truncate">{name}</p>
                    <div className="flex items-center gap-2 mt-2">
                      <div className="w-1.5 h-1.5 rounded-full bg-blue-500 animate-pulse"></div>
                      <p className="text-[10px] text-blue-400 font-black uppercase tracking-[0.2em]">Encrypted Segment</p>
                    </div>
                  </div>
                </button>
              ))}

              <button
                onClick={() => setMode('SIGN_UP')}
                style={{ animationDelay: `${identities.length * 100}ms` }}
                className="flex flex-col items-center justify-center gap-6 bg-white/[0.01] border-2 border-dashed border-white/5 rounded-[3rem] p-10 hover:bg-white/[0.03] transition-all group glass animate-slide-up"
              >
                <div className="w-16 h-16 rounded-[2rem] border-2 border-dashed border-white/10 flex items-center justify-center text-gray-600 group-hover:text-white group-hover:scale-110 transition-all">
                  <i className="fas fa-user-plus text-xl"></i>
                </div>
                <p className="font-black text-gray-500 group-hover:text-white uppercase tracking-widest text-[11px]">Register Biological Data</p>
              </button>
            </div>
          </div>
        ) : (
          <div className="max-w-md mx-auto animate-pop-in">
            <div className="bg-white/[0.03] backdrop-blur-3xl border border-white/10 rounded-[4rem] p-12 shadow-[0_0_100px_rgba(0,0,0,0.5)] relative overflow-hidden glass">

              {/* Main Card Biometric Scanner Beam */}
              <div className="absolute inset-0 pointer-events-none z-0">
                <div className="absolute top-0 left-0 w-full h-[2px] bg-gradient-to-r from-transparent via-cyan-400 to-transparent shadow-[0_0_20px_rgba(34,211,238,0.8)] opacity-60 animate-biometric"></div>
                {/* Subtle Grid revealed by scanner */}
                <div className="absolute inset-0 bg-[linear-gradient(rgba(34,211,238,0.03)_1px,transparent_1px),linear-gradient(90deg,rgba(34,211,238,0.03)_1px,transparent_1px)] bg-[size:20px_20px]"></div>
              </div>

              <div className="relative z-10">
                {mode === 'SIGN_UP' && (
                  <form onSubmit={handleSignUpStart} className="space-y-8">
                    <div className="text-center space-y-2">
                      <div className="w-20 h-20 rounded-full border border-blue-500/20 bg-blue-500/5 flex items-center justify-center mx-auto mb-4 animate-float">
                        <i className="fas fa-fingerprint text-3xl text-blue-400"></i>
                      </div>
                      <h2 className="text-3xl font-black tracking-tighter">Initialize Identity</h2>
                      <p className="text-[10px] text-gray-600 uppercase tracking-widest font-bold">Neural registration node</p>
                    </div>
                    <div className="space-y-4">
                      <input
                        type="text"
                        required
                        placeholder="Username"
                        className="w-full bg-white/5 border border-white/10 rounded-2xl py-5 px-8 text-white font-bold focus:outline-none focus:border-blue-500/50 transition-all"
                        value={username}
                        onChange={(e) => setUsername(e.target.value)}
                      />
                      <div className="relative">
                        <input
                          type={showPassword ? 'text' : 'password'}
                          required
                          placeholder="Passcode"
                          className="w-full bg-white/5 border border-white/10 rounded-2xl py-5 px-8 text-white font-bold focus:outline-none focus:border-blue-500/50 transition-all"
                          value={password}
                          onChange={(e) => setPassword(e.target.value)}
                        />
                        <button 
                          type="button"
                          onClick={() => setShowPassword(!showPassword)}
                          className="absolute right-6 top-1/2 -translate-y-1/2 text-gray-600 hover:text-white"
                        >
                          <i className={`fas ${showPassword ? 'fa-eye-slash' : 'fa-eye'}`}></i>
                        </button>
                      </div>
                    </div>
                    {error && <p className="text-red-500 text-[10px] font-black uppercase text-center animate-shake">{error}</p>}
                    <button type="submit" className="w-full bg-white text-black font-black py-5 rounded-2xl hover:bg-blue-50 transition-all uppercase tracking-[0.2em] text-xs neo-button">
                      Initialize Core
                    </button>
                  </form>
                )}

                {mode === 'SAFETY_GATE' && (
                  <form onSubmit={handleAgeCheck} className="space-y-8 text-center animate-fade-in">
                    <div className="w-24 h-24 rounded-full bg-red-500/10 border border-red-500/20 flex items-center justify-center mx-auto mb-6 animate-pulse-glow">
                      <i className="fas fa-shield-alt text-4xl text-red-500"></i>
                    </div>
                    <div className="space-y-2">
                      <h2 className="text-3xl font-black tracking-tighter">Safety Gate</h2>
                      <p className="text-gray-500 text-[10px] uppercase tracking-widest font-black">Verify biological cycle maturity</p>
                    </div>
                    <input
                      type="number"
                      required
                      placeholder="21"
                      className="w-full bg-white/5 border border-white/10 rounded-3xl py-8 text-center text-5xl text-white font-black focus:outline-none focus:border-red-500/50"
                      value={age}
                      onChange={(e) => setAge(parseInt(e.target.value) || '')}
                    />
                    {error && <p className="text-red-500 text-[10px] font-black uppercase leading-relaxed">{error}</p>}
                    <button type="submit" className="w-full bg-red-600 text-white font-black py-5 rounded-2xl hover:bg-red-500 transition-all uppercase tracking-widest text-xs">
                      Confirm Maturation
                    </button>
                  </form>
                )}

                {mode === 'VOICE_SELECT' && (
                  <div className="space-y-10 animate-fade-in">
                    <div className="text-center space-y-2">
                      <h2 className="text-3xl font-black tracking-tighter">Auditory Link</h2>
                      <p className="text-gray-500 text-[10px] uppercase tracking-[0.3em] font-black">Select Neural Modality</p>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <button
                        onClick={() => setGenderPref('masculine')}
                        className={`p-8 rounded-[3rem] border-2 transition-all flex flex-col items-center gap-6 ${genderPref === 'masculine' ? 'bg-blue-500/20 border-blue-500 scale-105' : 'bg-white/5 border-white/10 opacity-30'}`}
                      >
                        <i className="fas fa-mars text-5xl"></i>
                        <span className="font-black uppercase tracking-widest text-[11px]">Masculine</span>
                      </button>
                      <button
                        onClick={() => setGenderPref('feminine')}
                        className={`p-8 rounded-[3rem] border-2 transition-all flex flex-col items-center gap-6 ${genderPref === 'feminine' ? 'bg-emerald-500/20 border-emerald-500 scale-105' : 'bg-white/5 border-white/10 opacity-30'}`}
                      >
                        <i className="fas fa-venus text-5xl"></i>
                        <span className="font-black uppercase tracking-widest text-[11px]">Feminine</span>
                      </button>
                    </div>
                    <button onClick={finalizeSignUp} disabled={isSyncing} className="w-full bg-white text-black font-black py-5 rounded-2xl hover:scale-105 transition-all uppercase tracking-widest text-xs disabled:opacity-50">
                      {isSyncing ? 'Synchronizing Neural Segments...' : 'Finalize Identity Sync'}
                    </button>
                  </div>
                )}

                {mode === 'VERIFY' && (
                  <form onSubmit={handleVerify} className="space-y-8">
                    <div className="text-center space-y-2">
                      <div className="w-20 h-20 rounded-full border border-cyan-500/30 bg-cyan-500/10 flex items-center justify-center mx-auto mb-4 animate-pulse-glow">
                        <i className="fas fa-eye text-3xl text-cyan-400"></i>
                      </div>
                      <h2 className="text-3xl font-black tracking-tighter">Authorization</h2>
                      <p className="text-gray-500 text-[10px] uppercase tracking-widest font-black">Identity: {selectedProfile}</p>
                    </div>
                    <input
                      type={showPassword ? 'text' : 'password'}
                      required
                      autoFocus
                      placeholder="Enter Passcode"
                      className="w-full bg-white/5 border border-white/10 rounded-2xl py-5 px-8 text-white font-bold focus:outline-none focus:border-blue-500/50"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                    />
                    {error && <p className="text-red-500 text-[10px] font-black uppercase text-center animate-shake">{error}</p>}
                    <button type="submit" disabled={isSyncing} className="w-full bg-white text-black font-black py-5 rounded-2xl hover:bg-blue-50 transition-all uppercase tracking-widest text-xs">
                      {isSyncing ? 'Accessing Segment...' : 'Establish Neural Link'}
                    </button>
                  </form>
                )}
              </div>

              <button
                onClick={() => { setMode('VAULT'); setError(null); setPassword(''); setUsername(''); setAge(''); }}
                className="mt-10 w-full text-[10px] text-gray-600 hover:text-white font-black uppercase tracking-[0.5em] transition-colors py-2 flex items-center justify-center gap-3 group relative z-10"
              >
                <i className="fas fa-chevron-left text-[8px] group-hover:-translate-x-1 transition-transform"></i> Return to Vault
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

