                    </div>
                    <div className="space-y-2">
                      <h2 className="text-3xl font-black tracking-tighter">Safety Gate</h2>
                      <p className="text-gray-500 text-[10px] uppercase tracking-widest font-black">Verify biological cycle maturity</p>
