                    </div>
                    <input
                      type={showPassword ? 'text' : 'password'}
                      required
                      autoFocus
                      placeholder="Enter Passcode"
                      className="w-full bg-white/5 border border-white/10 rounded-2xl py-5 px-8 text-white font-bold focus:outline-none focus:border-blue-500/50"
