import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AssistantState, TranscriptionEntry, MemoryEntry, AuthUser, UITheme, PersonalityType, UserPreferences, DeviceType, SensorData } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';
import ScreenShareMode from './components/ScreenShareMode';
import HardwareSensors from './components/HardwareSensors';
import SettingsModal from './components/SettingsModal';
import IntroSequence from './components/IntroSequence';
import CreationStudio from './components/CreationStudio';

const THEMES: Record<UITheme, { primary: string; secondary: string; glow: string; bg: string; overlay: string }> = {
  cosmic: { primary: 'blue-500', secondary: 'indigo-500', glow: 'rgba(59,130,246,0.5)', bg: '#02020a', overlay: 'rgba(2, 2, 10, 0.75)' },
  emerald: { primary: 'emerald-500', secondary: 'teal-500', glow: 'rgba(16,185,129,0.5)', bg: '#020a05', overlay: 'rgba(2, 10, 5, 0.75)' },
  ruby: { primary: 'rose-500', secondary: 'orange-500', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202', overlay: 'rgba(10, 2, 2, 0.75)' },
  obsidian: { primary: 'slate-400', secondary: 'zinc-500', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a', overlay: 'rgba(10, 10, 10, 0.85)' }
};

const PERSONALITIES: Record<PersonalityType, string> = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool: FunctionDeclaration = {
  name: 'save_knowledge',
  parameters: {
    type: Type.OBJECT,
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: Type.STRING, description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: 'Charon',
  assistantName: 'Project Chatty',
  customPersonality: 'You are a highly capable AI assistant.',
  modality: 'masculine'
};

const App: React.FC = () => {
  const [showIntro, setShowIntro] = useState(true);
  const [user, setUser] = useState<AuthUser | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [device, setDevice] = useState<DeviceType>('desktop');
  const [isScanning, setIsScanning] = useState(true);
  const [sensorData, setSensorData] = useState<SensorData>({ online: navigator.onLine, platform: navigator.platform });
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [isStudioOpen, setIsStudioOpen] = useState(false);

  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  const dynamicVoices = useMemo(() => {
    const isFem = prefs.modality === 'feminine';
    return isFem ? [
      { id: 'Zephyr', name: 'Gabby', tone: 'Warm, Smooth, Melodic', gender: 'feminine' },
      { id: 'Kore', name: 'Paula', tone: 'Clear, Professional, Calm', gender: 'feminine' },
      { id: 'Aoede', name: 'Kai', tone: 'Poetic, Soulful, Expressive', gender: 'feminine' },
      { id: 'Leda', name: 'Jessie', tone: 'Bright, Airy, Gentle', gender: 'feminine' }
    ] : [
      { id: 'Charon', name: 'John', tone: 'Deep, Bass, Authoritative', gender: 'masculine' },
      { id: 'Puck', name: 'Caleb', tone: 'Energetic, Bright, Playful', gender: 'masculine' },
      { id: 'Fenrir', name: 'Able', tone: 'Vibrant, Sharp, Focused', gender: 'masculine' },
      { id: 'Charon', name: 'Jake', tone: 'Deep, Resonant, Command', gender: 'masculine' }
    ];
  }, [prefs.modality]);

  // Handle hardware detection and sensors
  const detectHardware = useCallback(async () => {
    try {
      const w = window.innerWidth;
      const ua = navigator.userAgent.toLowerCase();
      let detectedDevice: DeviceType = 'desktop';
      if (w <= 300) detectedDevice = 'wear';
      else if (w < 768) detectedDevice = 'mobile';
      setDevice(detectedDevice);

      const sensorPayload: SensorData = { online: navigator.onLine, platform: navigator.platform };
      if ('getBattery' in navigator) {
        const battery = await (navigator as any).getBattery();
        sensorPayload.battery = battery.level;
        sensorPayload.charging = battery.charging;
      }
      setSensorData(prev => ({ ...prev, ...sensorPayload }));
    } catch (err) {
      console.error("Hardware probe failure", err);
    } finally {
      setTimeout(() => setIsScanning(false), 2000);
    }
  }, []);

  useEffect(() => {
    detectHardware();
  }, [detectHardware]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const handleLogin = (username: string, initialPrefs?: Partial<UserPreferences>) => {
    setUser({ username, preferences: { ...prefs, ...initialPrefs } });
    if (initialPrefs) setPrefs(p => ({ ...p, ...initialPrefs }));
  };

  // Disconnect from the Live Session
  const disconnectLive = () => {
    if (scriptProcessorRef.current) {
      scriptProcessorRef.current.disconnect();
      scriptProcessorRef.current = null;
    }
    if (micStreamRef.current) {
      micStreamRef.current.getTracks().forEach(track => track.stop());
      micStreamRef.current = null;
    }
    activeSourcesRef.current.forEach(s => s.stop());
    activeSourcesRef.current.clear();
    setState(AssistantState.IDLE);
    sessionPromiseRef.current = null;
  };

  // Establish Connection to Gemini Live API
  const connectLive = async () => {
    if (state !== AssistantState.IDLE) return;
    setState(AssistantState.CONNECTING);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    if (!audioContextRef.current) {
      audioContextRef.current = {
        input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
        output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
      };
      analyserRef.current = audioContextRef.current.input.createAnalyser();
    }

    const { input: inputCtx, output: outputCtx } = audioContextRef.current;

    const sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId as any } } },
        systemInstruction: `${PERSONALITIES[prefs.personality]} Your name is ${prefs.assistantName}.`,
        tools: [{ functionDeclarations: [saveKnowledgeTool] }],
        inputAudioTranscription: {},
        outputAudioTranscription: {}
      },
      callbacks: {
        onopen: async () => {
          setState(AssistantState.LISTENING);
          audioUtils.playLinkSound(outputCtx);
          const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
          micStreamRef.current = stream;
          const source = inputCtx.createMediaStreamSource(stream);
          source.connect(analyserRef.current!);

          const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
          scriptProcessorRef.current = scriptProcessor;
          scriptProcessor.onaudioprocess = (e) => {
            const inputData = e.inputBuffer.getChannelData(0);
            const pcmBlob = audioUtils.createPcmBlob(inputData);
            sessionPromise.then(session => {
              session.sendRealtimeInput({ media: pcmBlob });
              if (currentFrameRef.current) {
                session.sendRealtimeInput({ media: { data: currentFrameRef.current, mimeType: 'image/jpeg' } });
                currentFrameRef.current = null;
              }
            });
          };
          source.connect(scriptProcessor);
          scriptProcessor.connect(inputCtx.destination);
        },
        onmessage: async (msg: LiveServerMessage) => {
          const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
          if (audioData) {
            setState(AssistantState.SPEAKING);
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
            const buffer = await audioUtils.decodeAudioData(audioUtils.decode(audioData), outputCtx, 24000, 1);
            const source = outputCtx.createBufferSource();
            source.buffer = buffer;
            source.connect(outputCtx.destination);
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += buffer.duration;
            activeSourcesRef.current.add(source);
            source.onended = () => {
                activeSourcesRef.current.delete(source);
                if (activeSourcesRef.current.size === 0) setState(AssistantState.LISTENING);
            };
          }
          if (msg.serverContent?.interrupted) {
            activeSourcesRef.current.forEach(s => s.stop());
            activeSourcesRef.current.clear();
            nextStartTimeRef.current = 0;
          }
          if (msg.serverContent?.inputTranscription) setStreamingUserText(t => t + msg.serverContent!.inputTranscription!.text);
          if (msg.serverContent?.outputTranscription) setStreamingAssistantText(t => t + msg.serverContent!.outputTranscription!.text);
          if (msg.serverContent?.turnComplete) {
            setTranscriptions(prev => {
              const next = [...prev];
              if (streamingUserText) next.push({ id: Date.now().toString(), sender: 'user', text: streamingUserText, timestamp: new Date() });
              if (streamingAssistantText) next.push({ id: (Date.now() + 1).toString(), sender: 'assistant', text: streamingAssistantText, timestamp: new Date() });
              return next;
            });
            setStreamingUserText('');
            setStreamingAssistantText('');
          }
          if (msg.toolCall) {
            msg.toolCall.functionCalls.forEach(fc => {
              if (fc.name === 'save_knowledge') {
                const fact = (fc.args as any).fact;
                setMemories(prev => [...prev, { id: Date.now().toString(), fact, timestamp: new Date() }]);
                sessionPromise.then(s => s.sendToolResponse({
                    functionResponses: [{ id: fc.id, name: fc.name, response: { result: 'Information stored in memory.' } }]
                }));
              }
            });
          }
        },
        onerror: (e) => { console.error(e); setState(AssistantState.ERROR); },
        onclose: () => setState(AssistantState.IDLE)
      }
    });
    sessionPromiseRef.current = sessionPromise;
  };

  if (showIntro) return <IntroSequence onComplete={() => setShowIntro(false)} />;
  if (!user) return <LoginPage onLogin={handleLogin} />;

  const theme = THEMES[prefs.theme];

  return (
    <div className={`min-h-screen bg-[#02020a] text-white flex overflow-hidden font-sans`}>
      <div className={`flex-1 flex flex-col relative ${prefs.layout === 'left' ? 'order-2' : 'order-1'}`}>
        <header className="p-6 flex justify-between items-center border-b border-white/5 bg-black/20 backdrop-blur-md z-10">
          <div className="flex items-center gap-4">
            <div className={`w-3 h-3 rounded-full animate-pulse ${state === AssistantState.LISTENING ? 'bg-emerald-500 shadow-[0_0_10px_#10b981]' : state === AssistantState.SPEAKING ? 'bg-blue-500 shadow-[0_0_10px_#3b82f6]' : 'bg-gray-500'}`}></div>
            <h1 className="font-black tracking-tighter text-xl uppercase">{prefs.assistantName}</h1>
            <HardwareSensors data={sensorData} deviceType={device} themeColor={theme.primary} />
          </div>
          <div className="flex gap-2">
            <button onClick={() => setIsStudioOpen(true)} className="w-10 h-10 rounded-xl bg-white/5 flex items-center justify-center hover:bg-white/10 transition-all border border-white/5"><i className="fas fa-wand-magic-sparkles"></i></button>
            <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all border ${isMemoryOpen ? 'bg-blue-500/20 border-blue-500' : 'bg-white/5 border-white/5 hover:bg-white/10'}`}><i className="fas fa-brain"></i></button>
            <button onClick={() => setIsSettingsOpen(true)} className="w-10 h-10 rounded-xl bg-white/5 flex items-center justify-center hover:bg-white/10 transition-all border border-white/5"><i className="fas fa-sliders"></i></button>
          </div>
        </header>

        <main className="flex-1 overflow-y-auto p-6 space-y-6 scrollbar-thin" ref={scrollRef}>
          {transcriptions.map(t => (
            <div key={t.id} className={`flex ${t.sender === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in`}>
              <div className={`max-w-[80%] p-6 rounded-3xl ${t.sender === 'user' ? 'bg-white/5 border border-white/10 text-right' : `bg-${theme.primary}/10 border border-${theme.primary}/20`}`}>
                <p className="text-sm font-medium leading-relaxed">{t.text}</p>
                <span className="text-[8px] text-gray-600 block mt-2 uppercase tracking-widest">{t.timestamp.toLocaleTimeString()}</span>
              </div>
            </div>
          ))}
          {(streamingUserText || streamingAssistantText) && (
             <div className="flex flex-col gap-4 italic text-gray-500 text-xs animate-pulse p-4 bg-white/[0.02] rounded-2xl border border-white/5">
               {streamingUserText && <div className="text-right">Listening: {streamingUserText}</div>}
               {streamingAssistantText && <div className="text-left">Thinking: {streamingAssistantText}</div>}
             </div>
          )}
        </main>

        <footer className="p-8 border-t border-white/5 bg-black/40 backdrop-blur-xl">
          <div className="max-w-4xl mx-auto space-y-8">
            <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
            <div className="flex justify-center items-center gap-8">
              <button 
                onClick={() => setIsVisionActive(!isVisionActive)} 
                className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center transition-all ${isVisionActive ? 'bg-blue-600 text-white shadow-[0_0_20px_rgba(37,99,235,0.4)]' : 'bg-white/5 text-gray-400 hover:bg-white/10 border border-white/5'}`}
                title="Visual Interface"
              >
                <i className="fas fa-video text-xl"></i>
              </button>

              <button 
                onClick={state === AssistantState.IDLE ? connectLive : disconnectLive} 
                className={`w-24 h-24 rounded-[2rem] flex items-center justify-center transition-all transform hover:scale-105 active:scale-95 ${state === AssistantState.IDLE ? 'bg-white text-black shadow-2xl' : 'bg-red-500 text-white shadow-[0_0_30px_rgba(239,68,68,0.5)] animate-pulse'}`}
              >
                <i className={`fas ${state === AssistantState.IDLE ? 'fa-microphone' : 'fa-stop'} text-3xl`}></i>
              </button>

              <button 
                onClick={() => setIsScreenSharing(!isScreenSharing)} 
