import React, { useState } from 'react';
import { GoogleGenAI } from '@google/genai';
import { GeneratedAsset } from '../types';

interface CreationStudioProps {
  onClose: () => void;
  onAssetGenerated: (asset: GeneratedAsset) => void;
  themePrimary: string;
}

const CreationStudio: React.FC<CreationStudioProps> = ({ onClose, onAssetGenerated, themePrimary }) => {
  const [activeTab, setActiveTab] = useState<'image' | 'video'>('image');
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [statusMessage, setStatusMessage] = useState('');
  const [quality, setQuality] = useState<'flash' | 'pro'>('flash');

  const checkApiKey = async () => {
    const needsPro = quality === 'pro' || activeTab === 'video';
    if (needsPro && window.aistudio) {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        await window.aistudio.openSelectKey();
      }
    }
  };

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setIsGenerating(true);
    setStatusMessage('Initializing chatty link...');

    try {
      await checkApiKey();
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      if (activeTab === 'image') {
        setStatusMessage('Synthesizing pixels...');
        const model = quality === 'flash' ? 'gemini-2.5-flash-image' : 'gemini-3-pro-image-preview';
        const response = await ai.models.generateContent({
          model,
          contents: { parts: [{ text: prompt }] },
          config: { imageConfig: { aspectRatio: "1:1" } }
        });

        // Iterating through all parts as recommended in SDK guidelines
        let imageUrl = null;
        if (response.candidates?.[0]?.content?.parts) {
          for (const part of response.candidates[0].content.parts) {
            if (part.inlineData) {
              imageUrl = `data:image/png;base64,${part.inlineData.data}`;
              break;
            }
          }
        }

        if (imageUrl) {
          onAssetGenerated({
            id: Math.random().toString(36).substr(2, 9),
            type: 'image',
            url: imageUrl,
            prompt,
            timestamp: new Date()
          });
        }
      } else {
        setStatusMessage('Compiling motion sequence...');
        let operation = await ai.models.generateVideos({
          model: 'veo-3.1-fast-generate-preview',
          prompt,
          config: { numberOfVideos: 1, resolution: '720p', aspectRatio: '16:9' }
        });

        while (!operation.done) {
          setStatusMessage(`Rendering sequence... [${new Date().toLocaleTimeString()}]`);
          await new Promise(resolve => setTimeout(resolve, 10000));
          operation = await ai.operations.getVideosOperation({ operation: operation });
        }

        const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
        if (downloadLink) {
          const videoResponse = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
          const blob = await videoResponse.blob();
          const url = URL.createObjectURL(blob);
          onAssetGenerated({
            id: Math.random().toString(36).substr(2, 9),
            type: 'video',
            url,
            prompt,
            timestamp: new Date()
          });
        }
      }
    } catch (err: any) {
      console.error('Forge Error:', err);
      const errorMsg = err.message || JSON.stringify(err);

      if (errorMsg.includes("Requested entity was not found")) {
        setStatusMessage('Access restricted. Updating link...');
        if (window.aistudio) {
          await window.aistudio.openSelectKey();
        }
      } else {
        setStatusMessage(`Forge Error: ${errorMsg}`);
      }
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-xl flex items-center justify-center p-6 animate-fade-in">
      <div className="w-full max-w-4xl bg-[#05050f] border border-white/10 rounded-[3rem] overflow-hidden flex flex-col h-[80vh] shadow-2xl shadow-blue-500/5">
        <div className="flex items-center justify-between p-8 border-b border-white/5">
          <div className="flex gap-4">
            <button 
              onClick={() => setActiveTab('image')} 
              className={`px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'image' ? 'text-white' : 'text-gray-500 hover:text-white'}`}
              style={activeTab === 'image' ? { backgroundColor: themePrimary } : {}}
            >
              Visual Forge
            </button>
            <button 
              onClick={() => setActiveTab('video')} 
              className={`px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'video' ? 'bg-purple-600 text-white' : 'text-gray-500 hover:text-white'}`}
            >
              Motion Engine
            </button>
          </div>
          <button onClick={onClose} className="text-gray-500 hover:text-white transition-colors"><i className="fas fa-times text-xl"></i></button>
        </div>

        <div className="flex-1 overflow-y-auto p-10 space-y-8 scrollbar-thin">
          <div className="space-y-4">
            <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Forge Command</label>
            <textarea 
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder={activeTab === 'image' ? "Envision the visual link..." : "Envision the motion..."}
              className="w-full h-32 bg-white/5 border border-white/10 rounded-2xl p-6 text-white font-medium focus:outline-none focus:border-[var(--theme-primary)]/50 resize-none transition-all"
            />
          </div>

          <div className="flex items-center justify-between">
            <div className="flex flex-col gap-2">
              {activeTab === 'image' && (
                <div className="flex bg-white/5 rounded-xl p-1 w-fit">
                  <button 
                    onClick={() => setQuality('flash')} 
                    className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase tracking-tighter ${quality === 'flash' ? 'bg-white/10 text-white' : 'text-gray-500'}`}
                  >
                    Draft
                  </button>
                  <button 
                    onClick={() => setQuality('pro')} 
                    className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase tracking-tighter transition-colors ${quality === 'pro' ? 'text-blue-400 bg-blue-500/10' : 'text-gray-500'}`}
                    style={quality === 'pro' ? { color: themePrimary, backgroundColor: `${themePrimary}1A` } : {}}
                  >
                    High Fidelity
                  </button>
                </div>
              )}
              <a 
                href="https://ai.google.dev/gemini-api/docs/billing" 
                target="_blank" 
                rel="noopener noreferrer"
                className="text-[8px] text-gray-500 hover:text-blue-400 font-black uppercase tracking-widest transition-colors"
              >
                <i className="fas fa-info-circle mr-1"></i> Billing & Quota info
              </a>
            </div>

            <button 
              onClick={handleGenerate}
              disabled={isGenerating || !prompt.trim()}
              className={`px-10 py-4 rounded-2xl font-black uppercase tracking-widest text-xs flex items-center gap-3 transition-all ${isGenerating ? 'bg-white/10 text-gray-500 cursor-not-allowed' : 'bg-white text-black hover:scale-105 active:scale-95 shadow-lg shadow-white/5'}`}
            >
              {isGenerating ? <i className="fas fa-circle-notch fa-spin"></i> : <i className="fas fa-bolt"></i>}
              {isGenerating ? 'Synthesizing...' : 'Ignite Forge'}
            </button>
          </div>

          {isGenerating && (
            <div className="p-8 border border-white/5 bg-white/[0.02] rounded-[2rem] animate-pulse">
              <div className="flex items-center gap-4 font-mono text-[10px] uppercase tracking-[0.2em]" style={{ color: themePrimary }}>
                <div className="w-2 h-2 rounded-full animate-ping" style={{ backgroundColor: themePrimary }}></div>
                {statusMessage}
              </div>
            </div>
          )}
        </div>

        <div className="p-8 bg-black/40 border-t border-white/5 text-center">
          <p className="text-[9px] text-gray-600 font-black uppercase tracking-[0.5em]">
            Powered by {activeTab === 'video' ? 'VEO 3.1' : quality === 'pro' ? 'Gemini 3 Pro' : 'Gemini 2.5 Flash'}
          </p>
        </div>
      </div>
    </div>
  );
};

export default CreationStudio;

import React, { useRef, useEffect, useState } from 'react';

interface ObservationModeProps {
  isActive: boolean;
  onFrame: (base64: string) => void;
}

const ObservationMode: React.FC<ObservationModeProps> = ({ isActive, onFrame }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isLowLight, setIsLowLight] = useState(false);

  useEffect(() => {
    let stream: MediaStream | null = null;
    let interval: number | null = null;

    const startCamera = async () => {
      try {
        stream = await navigator.mediaDevices.getUserMedia({ 
          video: { 
            facingMode: 'user',
            width: { ideal: 1280 },
            height: { ideal: 720 }
          } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }

        interval = window.setInterval(() => {
          if (videoRef.current && canvasRef.current) {
            const video = videoRef.current;
            const canvas = canvasRef.current;
            const ctx = canvas.getContext('2d');
            if (ctx && video.readyState >= 2) {
              canvas.width = video.videoWidth;
              canvas.height = video.videoHeight;

              if (isLowLight) {
                ctx.filter = 'brightness(1.8) contrast(1.2) saturate(0.7)';
              } else {
                ctx.filter = 'none';
              }

              ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
              ctx.filter = 'none';

              const base64 = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];
              onFrame(base64);
            }
          }
        }, 1000);
      } catch (err) {
        console.error("Camera access failed", err);
      }
    };

    if (isActive) {
      startCamera();
    }

    return () => {
      if (stream) {
        stream.getTracks().forEach(t => t.stop());
      }
      if (interval) {
        clearInterval(interval);
      }
    };
  }, [isActive, onFrame, isLowLight]);

  if (!isActive) return null;

  return (
    <div className="relative h-full w-full rounded-[2rem] overflow-hidden border border-white/20 shadow-2xl bg-black animate-fade-in group transition-all duration-500">
      {/* HUD Scan Line */}
      <div className="optic-scan-line"></div>

      {/* Video Feed */}
      <video 
        ref={videoRef} 
        autoPlay 
        playsInline 
        muted 
        className={`w-full h-full object-cover transition-all duration-700 ${isLowLight ? 'grayscale brightness-[1.4] contrast-[1.2] sepia-[.3] hue-rotate-[100deg]' : ''}`} 
      />

      {/* Canvas for processing */}
      <canvas ref={canvasRef} className="hidden" />

      {/* Scanning HUD Overlays */}
      <div className="absolute inset-0 pointer-events-none">
        {/* Vignette & Grain */}
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_0%,rgba(0,0,0,0.6)_100%)]"></div>

        {/* Tactical Corners */}
        <div className="absolute top-8 left-8 w-8 h-8 border-t-2 border-l-2 border-[var(--theme-primary)] opacity-50 group-hover:opacity-100 group-hover:-translate-x-1 group-hover:-translate-y-1 transition-all duration-500"></div>
        <div className="absolute top-8 right-8 w-8 h-8 border-t-2 border-r-2 border-[var(--theme-primary)] opacity-50 group-hover:opacity-100 group-hover:translate-x-1 group-hover:-translate-y-1 transition-all duration-500"></div>
        <div className="absolute bottom-8 left-8 w-8 h-8 border-b-2 border-l-2 border-[var(--theme-primary)] opacity-50 group-hover:opacity-100 group-hover:-translate-x-1 group-hover:translate-y-1 transition-all duration-500"></div>
        <div className="absolute bottom-8 right-8 w-8 h-8 border-b-2 border-r-2 border-[var(--theme-primary)] opacity-50 group-hover:opacity-100 group-hover:translate-x-1 group-hover:translate-y-1 transition-all duration-500"></div>

        {/* Center Reticle */}
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-12 h-12 flex items-center justify-center opacity-20">
            <div className="w-1 h-1 bg-[var(--theme-primary)] rounded-full"></div>
            <div className="absolute w-8 h-[1px] bg-[var(--theme-primary)]"></div>
            <div className="absolute h-8 w-[1px] bg-[var(--theme-primary)]"></div>
        </div>
      </div>

      {/* Interface Elements */}
      <div className="absolute top-6 left-6 flex gap-3">
        <div className="bg-red-500 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest flex items-center gap-2 animate-pulse shadow-lg shadow-red-500/30 backdrop-blur-md">
          <div className="w-2 h-2 rounded-full bg-white"></div>
          Optic Active
        </div>
        {isLowLight && (
          <div className="bg-emerald-600 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest flex items-center gap-2 animate-pop shadow-lg shadow-emerald-500/30 backdrop-blur-md">
            <i className="fas fa-eye text-[8px]"></i>
            Lumen Boost
          </div>
        )}
      </div>

      <div className="absolute bottom-6 right-6 flex gap-2">
        <button 
          onClick={() => setIsLowLight(!isLowLight)}
          className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all duration-300 backdrop-blur-xl ${isLowLight ? 'bg-emerald-500 text-white shadow-lg' : 'bg-black/40 text-white/70 hover:bg-black/60 border border-white/10'}`}
          title={isLowLight ? "Disable Dark Vision" : "Enable Dark Vision"}
        >
          <i className={`fas ${isLowLight ? 'fa-lightbulb' : 'fa-moon'}`}></i>
        </button>
      </div>

      <div className="absolute bottom-6 left-6 flex flex-col gap-1">
        <div className="flex items-center gap-3">
            <div className="w-1 h-12 bg-white/10 rounded-full overflow-hidden">
                <div className="w-full h-1/2 bg-[var(--theme-primary)] animate-pulse"></div>
            </div>
            <div className="flex flex-col">
                <span className="text-[9px] text-white/40 font-black uppercase tracking-widest">Signal_Str</span>
                <span className="text-[11px] text-white/80 font-mono">CHTY_OPT_01</span>
            </div>
        </div>
      </div>
    </div>
  );
};

