interface IntroSequenceProps {
  onComplete: () => void;
}

const LOGS = [
  "LINKING NEURAL PATHWAYS...",
  "SYNCHRONIZING BIO-SEGMENT...",
  "BYPASSING SECURITY OVERRIDE...",
  "CHARTING TEMPORAL COORDINATES...",
