          style={{
            background: 'radial-gradient(circle, rgba(59,130,246,0.8) 0%, rgba(139,92,246,0.4) 30%, transparent 70%)',
            filter: 'blur(60px)',
            animation: stage >= 1 ? 'singularity-expand 4s forwards, core-pulse 2s infinite alternate ease-in-out' : 'none'
