  const [previewingVoiceId, setPreviewingVoiceId] = useState<string | null>(null);

  const audioContextRef = useRef<{input: AudioContext, output: AudioContext} | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef(0);
  const activeSourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement | null>(null);

  const themeData = useMemo(() => THEMES[prefs.theme] || THEMES.cosmic, [prefs.theme]);

  useEffect(() => {
    document.documentElement.style.setProperty('--theme-primary', themeData.primary);
    document.documentElement.style.setProperty('--theme-secondary', themeData.secondary);
    document.documentElement.style.setProperty('--bg-base', themeData.bg);
    document.documentElement.style.setProperty('--theme-glow', themeData.glow);
  }, [themeData]);

  const dynamicVoices = useMemo(() => {
    const isFem = prefs.modality === 'feminine';
    return isFem ? [
      { id: 'Zephyr', name: 'Gabby', tone: 'Warm, Smooth, Melodic', gender: 'feminine' },
      { id: 'Kore', name: 'Paula', tone: 'Clear, Professional, Calm', gender: 'feminine' },
      { id: 'Aoede', name: 'Kai', tone: 'Poetic, Soulful, Expressive', gender: 'feminine' },
      { id: 'Leda', name: 'Jessie', tone: 'Bright, Airy, Gentle', gender: 'feminine' }
    ] : [
      { id: 'Charon', name: 'John', tone: 'Deep, Bass, Authoritative', gender: 'masculine' },
      { id: 'Puck', name: 'Caleb', tone: 'Energetic, Bright, Playful', gender: 'masculine' },
      { id: 'Fenrir', name: 'Able', tone: 'Vibrant, Sharp, Focused', gender: 'masculine' },
      { id: 'Jake', name: 'Jake', tone: 'Deep, Resonant, Command', gender: 'masculine' }
    ];
  }, [prefs.modality]);

  useEffect(() => {
    const isValid = dynamicVoices.some(v => v.id === prefs.voiceId);
    if (!isValid && dynamicVoices.length > 0) {
      setPrefs(p => ({ ...p, voiceId: dynamicVoices[0].id }));
    }
  }, [dynamicVoices, prefs.voiceId]);

  const detectHardware = useCallback(async (isMounted: boolean) => {
    try {
      const w = window.innerWidth;
      const h = window.innerHeight;
      const ua = navigator.userAgent.toLowerCase();

      let detectedDevice: DeviceType = 'desktop';
      if (w <= 300 || (ua.includes('watch') && !ua.includes('tv'))) detectedDevice = 'wear';
      else if (ua.includes('android') && w > h && w >= 800 && w <= 1280) detectedDevice = 'auto';
      else if (ua.includes('tv') || ua.includes('smarttv') || (w >= 1920 && h >= 1080)) detectedDevice = 'tv';
      else if (w < 768 || (w < 1024 && h > w)) detectedDevice = 'mobile';

      if (isMounted) {
        setDevice(detectedDevice);
        document.documentElement.setAttribute('data-device', detectedDevice);
      }

      const sensorPayload: SensorData = { online: navigator.onLine, platform: navigator.platform };
      if ('getBattery' in navigator) {
        try {
          const battery = await (navigator as any).getBattery();
          sensorPayload.battery = battery.level;
          sensorPayload.charging = battery.charging;
        } catch (e) {}
      }

      if (navigator.geolocation && ['auto', 'mobile', 'desktop'].includes(detectedDevice)) {
        navigator.geolocation.getCurrentPosition(
          (pos) => isMounted && setSensorData(prev => ({ ...prev, location: { lat: pos.coords.latitude, lng: pos.coords.longitude } })),
          undefined,
          { enableHighAccuracy: false, timeout: 5000 }
        );
      }
      if (isMounted) {
        setSensorData(prev => ({ ...prev, ...sensorPayload }));
        setTimeout(() => setIsScanning(false), 2000);
      }
    } catch (err) {
      console.error("Hardware probe failure", err);
    }
  }, []);

  useEffect(() => {
    let isMounted = true;
    detectHardware(isMounted);
    const handleResize = () => detectHardware(isMounted);
    window.addEventListener('resize', handleResize);
    return () => {
      isMounted = false;
      window.removeEventListener('resize', handleResize);
    };
  }, [detectHardware]);

  useEffect(() => {
    // Priority: Session (current tab) -> Persistent (localStorage)
    const sessionUser = sessionStorage.getItem('nova_session_user') || localStorage.getItem('nova_persistent_user');
    if (sessionUser) {
      try {
        const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
        setUser({ username: sessionUser, preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS });
      } catch (e) {
        setUser({ username: sessionUser, preferences: DEFAULT_PREFS });
      }
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      setMemories(JSON.parse(localStorage.getItem(`nova_${user.username}_memories`) || '[]'));
      setTranscriptions(JSON.parse(localStorage.getItem(`nova_${user.username}_logs`) || '[]'));
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  // CHAT BY DAY LOGIC
  const groupedTranscriptions = useMemo(() => {
    const groups: Record<string, TranscriptionEntry[]> = {};
    transcriptions.forEach(entry => {
      const date = new Date(entry.timestamp);
      const dateKey = date.toDateString();
      if (!groups[dateKey]) groups[dateKey] = [];
      groups[dateKey].push(entry);
    });
    return groups;
  }, [transcriptions]);

  const formatDateHeader = (dateStr: string) => {
    const date = new Date(dateStr);
    const today = new Date();
    const yesterday = new Date();
    yesterday.setDate(today.getDate() - 1);

    if (date.toDateString() === today.toDateString()) return "Today";
    if (date.toDateString() === yesterday.toDateString()) return "Yesterday";

    return date.toLocaleDateString(undefined, { 
      weekday: 'long', 
      year: 'numeric', 
      month: 'long', 
      day: 'numeric' 
    });
  };

  const isWearable = device === 'wear';
  const isAuto = device === 'auto';
  const isTV = device === 'tv';
  const isMobile = device === 'mobile';

  const addTranscription = useCallback((sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text?.trim()) return;
    setTranscriptions(prev => [
      ...prev, { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  }, []);

  const deleteTranscription = (id: string) => {
    setTranscriptions(prev => prev.filter(t => t.id !== id));
  };

  const clearAllTranscriptions = () => {
    if (window.confirm("Purge all chat records from this segment?")) {
      setTranscriptions([]);
    }
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
  }, [screenStream]);

  const handleLogout = useCallback(() => {
    stopSession();
    setUser(null);
    sessionStorage.removeItem('nova_session_user');
    localStorage.removeItem('nova_persistent_user');
  }, [stopSession]);

  const handleLogin = (username: string, initialPrefs: any) => {
    setUser({ username, preferences: { ...DEFAULT_PREFS, ...initialPrefs } });
  };

  const downsample = (buffer: Float32Array, fromRate: number, toRate: number) => {
    if (fromRate === toRate) return buffer;
    const ratio = fromRate / toRate;
    const result = new Float32Array(Math.round(buffer.length / ratio));
    for (let i = 0, offset = 0; i < result.length; i++, offset = Math.round(i * ratio)) {
      result[i] = buffer[offset];
    }
    return result;
  };

  const handlePreviewVoice = async (voiceId: string) => {
    if (previewingVoiceId) return;
    try {
      setPreviewingVoiceId(voiceId);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing.");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)(),
          output: new (window.AudioContext || (window as any).webkitAudioContext)()
        };
      }
      const outputCtx = audioContextRef.current.output;
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      const ai = new GoogleGenAI({ apiKey });
      const voice = dynamicVoices.find(v => v.id === voiceId);
      const prompt = `Say: Hello, I am ${voice?.name}. I am your chatty voice profile.`;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voiceId } } },
        },
      });

      const audioPart = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
      if (audioPart?.inlineData?.data) {
        const audioBuffer = await audioUtils.decodeAudioData(audioUtils.decode(audioPart.inlineData.data), outputCtx, 24000, 1);
        const source = outputCtx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(outputCtx.destination);
        source.onended = () => setPreviewingVoiceId(null);
        source.start(0);
      } else setPreviewingVoiceId(null);
    } catch (err) { setPreviewingVoiceId(null); }
  };

  const startSession = async (initialText?: string) => {
    try {
      setState(AssistantState.CONNECTING);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Authentication failure.");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)(),
          output: new (window.AudioContext || (window as any).webkitAudioContext)()
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      audioUtils.playLinkSound(outputCtx);

      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: { echoCancellation: true, noiseSuppression: true, sampleRate: 16000, channelCount: 1 } 
      });
      micStreamRef.current = stream;

      const source = inputCtx.createMediaStreamSource(stream);
      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const personalityPrompt = prefs.personality === 'custom' ? (prefs.customPersonality || 'Be helpful.') : PERSONALITIES[prefs.personality];

      const tools: any[] = [];
      if (sensorData.location) tools.push({ googleMaps: {} });
      if (searchEnabled) tools.push({ googleSearch: {} });
      if (!searchEnabled && !sensorData.location) tools.push({ functionDeclarations: [saveKnowledgeTool] });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools,
          toolConfig: sensorData.location ? {
            retrievalConfig: { latLng: { latitude: sensorData.location.lat, longitude: sensorData.location.lng } }
          } : undefined,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. Platform: ${device}. Personality: ${personalityPrompt}.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        } as any,
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const resampledData = downsample(inputData, inputCtx.sampleRate, 16000);
              const pcmBlob = audioUtils.createPcmBlob(resampledData);
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
              if (currentFrameRef.current) {
                const frame = currentFrameRef.current;
                currentFrameRef.current = null;
                sessionPromise.then(s => s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } }));
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
            if (initialText) sessionPromise.then(s => s.sendRealtimeInput({ text: initialText }));
          },
          onmessage: async (message: any) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = fc.args.fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Saved." } } }));
                }
              }
            }

            const turnParts = message.serverContent?.modelTurn?.parts || [];
            for (const part of turnParts) {
              if (part.inlineData?.data) {
                setState(AssistantState.SPEAKING);
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
                const buffer = await audioUtils.decodeAudioData(audioUtils.decode(part.inlineData.data), outputCtx, 24000, 1);
                const s = outputCtx.createBufferSource(); 
                s.buffer = buffer; 
                s.connect(outputCtx.destination);
                s.onended = () => { activeSourcesRef.current.delete(s); if (activeSourcesRef.current.size === 0) setState(AssistantState.LISTENING); };
                s.start(nextStartTimeRef.current); 
                nextStartTimeRef.current += buffer.duration; 
                activeSourcesRef.current.add(s);
              }
            }

            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent.inputTranscription.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent.outputTranscription.text);
            if (message.serverContent?.turnComplete) {
              const chunks = message.serverContent?.groundingMetadata?.groundingChunks || [];
              const sources = chunks.map((c: any) => {
                if (c.web) return { title: c.web.title, uri: c.web.uri };
                if (c.maps) return { title: c.maps.title, uri: c.maps.uri };
                return null;
              }).filter(Boolean);

              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) { addTranscription('assistant', a, sources); audioUtils.playSuccessSound(outputCtx); } return ''; });
            }
          },
          onerror: () => stopSession(),
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { 
      setErrorToast(err.message);
      setState(AssistantState.IDLE); 
      setTimeout(() => setErrorToast(null), 5000);
    }
  };

  const handleToggleScreenShare = async () => {
    if (isScreenSharing) {
      setIsScreenSharing(false);
      if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    } else {
      try {
        const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
        setScreenStream(stream);
        setIsVisionActive(false);
        setIsScreenSharing(true);
        if (state === AssistantState.IDLE) startSession();
        stream.getVideoTracks()[0].onended = () => { setIsScreenSharing(false); setScreenStream(null); };
      } catch (err: any) { setErrorToast(err.message); }
    }
  };

  const handleToggleVision = async () => {
    if (isVisionActive) setIsVisionActive(false);
    else {
      try {
        await navigator.mediaDevices.getUserMedia({ video: true });
        setIsScreenSharing(false);
        setIsVisionActive(true);
        if (state === AssistantState.IDLE) startSession();
      } catch (err) { setErrorToast("Optic access denied."); }
    }
  };

  const handleSendText = () => {
    if (!inputText.trim()) return;
    const msg = inputText.trim();
    setInputText('');
    addTranscription('user', msg);
    if (sessionRef.current) {
      setState(AssistantState.THINKING);
      sessionRef.current.sendRealtimeInput({ text: msg });
    } else startSession(msg);
  };

  if (showIntro) return <IntroSequence onComplete={() => setShowIntro(false)} />;
  if (!user) return <LoginPage onLogin={handleLogin} />;

  if (isScanning) {
    return (
      <div className="fixed inset-0 bg-[#02020a] flex flex-col items-center justify-center z-[200] animate-fade-blur-in overflow-hidden">
        <div className="absolute inset-0 animate-scan-v bg-gradient-to-b from-transparent via-[var(--theme-primary)]/20 to-transparent pointer-events-none opacity-40"></div>
        <div className="relative w-[30vw] h-[30vw] max-w-64 max-h-64 flex items-center justify-center animate-float-3d">
          <div className="absolute inset-0 border-4 border-t-[var(--theme-primary)] border-r-transparent border-b-transparent border-l-transparent rounded-full animate-spin"></div>
          <div className="absolute inset-4 border-2 border-b-[var(--theme-secondary)] border-t-transparent border-r-transparent border-l-transparent rounded-full animate-spin [animation-duration:3s]"></div>
          <i className="fas fa-atom text-6xl text-white animate-pulse"></i>
        </div>
        <h2 className="mt-12 text-2xl font-black tracking-[0.5em] uppercase text-white mb-2 text-center animate-slide-up-reveal px-6">Chatty Sync Active</h2>
        <p className="text-[11px] text-[var(--theme-primary)] font-black uppercase tracking-[0.3em] animate-pulse">Linking Bio-Core...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full w-full transition-all duration-1000 overflow-hidden">
      {errorToast && (
        <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[300] bg-red-600/90 backdrop-blur-xl text-white px-8 py-5 rounded-[2rem] font-black uppercase tracking-widest text-[10px] shadow-[0_20px_60px_rgba(220,38,38,0.4)] animate-pop flex items-center gap-4">
          <i className="fas fa-exclamation-triangle"></i>
          {errorToast}
          <button onClick={() => setErrorToast(null)} className="ml-4 opacity-50 hover:opacity-100"><i className="fas fa-times"></i></button>
        </div>
      )}

      <header className={`m-[var(--ui-gap)] p-4 lg:p-6 rounded-[var(--ui-radius)] flex items-center justify-between z-50 glass animate-fade-blur-in`}>
        <div className="flex items-center gap-3 lg:gap-6 group">
          <div className={`w-10 h-10 lg:w-14 lg:h-14 rounded-[1.5rem] overflow-hidden border border-white/10 relative transition-all duration-700 group-hover:scale-110 shadow-xl`}>
            {prefs.assistantProfilePic ? <img src={prefs.assistantProfilePic} className="w-full h-full object-cover" alt="AI" /> : <div className="w-full h-full bg-[var(--theme-primary)]/10 flex items-center justify-center"><i className="fas fa-atom text-white text-lg lg:text-xl"></i></div>}
          </div>
          {!isWearable && (
            <div className="animate-slide-in-right-bounce">
              <h1 className="text-sm lg:text-2xl font-black tracking-tighter text-white uppercase truncate max-w-[120px] lg:max-w-none">{prefs.assistantName}</h1>
              {!isMobile && <HardwareSensors data={sensorData} deviceType={device} themeColor={themeColor} />}
            </div>
          )}
        </div>
        <div className="flex items-center gap-2 md:gap-4">
           {transcriptions.length > 0 && !isWearable && (
             <button 
               onClick={clearAllTranscriptions} 
               className="w-10 h-10 lg:w-12 lg:h-12 rounded-xl bg-red-500/10 hover:bg-red-500/20 text-red-400 flex items-center justify-center transition-all active:scale-90"
               title="Clear All History"
             >
               <i className="fas fa-trash-sweep text-sm lg:text-lg"></i>
             </button>
           )}
           {!isWearable && <button onClick={() => setIsSettingsOpen(true)} className="w-10 h-10 lg:w-12 lg:h-12 rounded-xl bg-white/5 flex items-center justify-center hover:bg-white/10 transition-all active:scale-90"><i className="fas fa-cog text-sm lg:text-lg"></i></button>}
           {!isWearable && <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-10 h-10 lg:w-12 lg:h-12 rounded-xl flex items-center justify-center transition-all active:scale-90 ${isMemoryOpen ? 'bg-[var(--theme-primary)] text-white shadow-[0_0_30px_rgba(37,99,235,0.4)]' : 'bg-white/5 text-gray-400'}`}><i className="fas fa-brain text-sm lg:text-lg"></i></button>}
           <button onClick={handleLogout} className="w-10 h-10 lg:w-12 lg:h-12 flex items-center justify-center text-gray-600 hover:text-red-500 transition-colors active:scale-90"><i className="fas fa-power-off text-sm lg:text-lg"></i></button>
        </div>
      </header>

      <main className={`flex-1 flex ${isMobile || isWearable ? 'flex-col' : 'flex-row'} min-h-0 p-[var(--ui-gap)] gap-[var(--ui-gap)] overflow-hidden`}>
        <div className="flex-1 flex flex-col gap-[var(--ui-gap)] min-h-0">
          {(isVisionActive || isScreenSharing) && (
            <div className={`h-48 md:h-72 lg:h-[400px] w-full animate-pop flex-shrink-0 relative group`}>
              <div className={`absolute -inset-1 bg-gradient-to-r from-[var(--theme-primary)] to-[var(--theme-secondary)] rounded-[var(--ui-radius)] blur opacity-20 group-hover:opacity-40 transition-opacity`}></div>
              {isVisionActive && <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />}
              {isScreenSharing && screenStream && <ScreenShareMode isActive={isScreenSharing} stream={screenStream} onFrame={(b) => currentFrameRef.current = b} onStop={() => setIsScreenSharing(false)} />}
            </div>
          )}

          <div className="flex-1 flex flex-col glass rounded-[var(--ui-radius)] overflow-hidden relative min-h-0 group shadow-2xl">
            <div className={`absolute inset-0 bg-gradient-to-br from-[var(--theme-primary)]/5 via-transparent to-[var(--theme-secondary)]/5 pointer-events-none opacity-40`}></div>

            <div className={`flex-1 p-4 lg:p-8 space-y-4 lg:space-y-8 overflow-y-auto scrollbar-thin transcription-list`} ref={scrollRef}>
              {transcriptions.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center opacity-20 animate-float-3d">
                  <i className={`fas fa-comment-dots text-6xl lg:text-9xl mb-6 text-gray-600`}></i>
                  {!isWearable && <p className="text-xl lg:text-3xl font-black uppercase tracking-[0.5em] shimmer-text-fast">Chatty Core</p>}
                </div>
              )}

              {/* RENDER GROUPED TRANSCRIPTIONS BY DAY */}
              {Object.entries(groupedTranscriptions).map(([dateStr, items]) => (
                <React.Fragment key={dateStr}>
                  <div className="day-separator animate-fade-blur-in">
                    <div className="day-line"></div>
                    <div className="day-badge">{formatDateHeader(dateStr)}</div>
                    <div className="day-line"></div>
                  </div>

                  {items.map((e) => (
                    <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'} animate-slide-up-reveal group/item`}>
                      <div className={`
                        max-w-[90%] lg:max-w-[85%] 
                        px-4 py-3 lg:px-7 lg:py-5 
                        rounded-[1.5rem] lg:rounded-[2rem] 
                        shadow-xl transition-all hover:scale-[1.01] relative
                        ${e.sender === 'user' 
                          ? 'bg-gradient-to-br from-[var(--theme-primary)] to-indigo-600 text-white' 
                          : 'bg-white/[0.04] text-gray-200 border border-white/5 backdrop-blur-xl'
                        }
                      `}>
                        {/* Quick Delete Trigger */}
                        <button 
                          onClick={() => deleteTranscription(e.id)}
                          className={`absolute ${e.sender === 'user' ? '-left-8' : '-right-8'} top-1/2 -translate-y-1/2 opacity-0 group-hover/item:opacity-40 hover:!opacity-100 text-red-500 transition-all p-2 active:scale-90`}
                        >
                          <i className="fas fa-trash-alt text-xs lg:text-sm"></i>
                        </button>

                        <p className="text-sm lg:text-lg font-bold leading-relaxed whitespace-pre-wrap">{e.text}</p>
                        {!isWearable && e.sources && <GroundingSources sources={e.sources} themePrimary={themeData.primary} />}
                        <div className={`mt-2 text-[8px] opacity-40 uppercase font-black tracking-widest ${e.sender === 'user' ? 'text-right' : 'text-left'}`}>
                          {new Date(e.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </div>
                      </div>
                    </div>
                  ))}
                </React.Fragment>
              ))}

              {(streamingAssistantText || state === AssistantState.THINKING) && (
                <div className="items-start flex flex-col animate-pop">
                  <div className="max-w-[85%] px-5 py-3 rounded-[1.5rem] bg-white/[0.03] text-white/60 border border-white/5">
                    {streamingAssistantText ? <p className="font-mono text-xs lg:text-sm leading-relaxed">{streamingAssistantText}</p> : <div className="typing-indicator"><span></span><span></span><span></span></div>}
                  </div>
                </div>
              )}
            </div>

            <div className={`p-4 lg:p-8 border-t border-white/5 bg-black/50 backdrop-blur-2xl flex flex-col gap-3 lg:gap-6`}>
              {!isWearable && <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />}
              <div className={`flex ${isWearable ? 'flex-col gap-2' : 'gap-3'} items-center`}>
                  {!isWearable && (
                    <div className="flex gap-2">
                      <button onClick={handleToggleVision} title="Optic Link" className="w-10 h-10 lg:w-14 lg:h-14 rounded-xl glass flex items-center justify-center active:scale-90 transition-all"><i className="fas fa-camera text-sm lg:text-lg"></i></button>
                      <button onClick={handleToggleScreenShare} title="Desktop Uplink" className="w-10 h-10 lg:w-14 lg:h-14 rounded-xl glass flex items-center justify-center active:scale-90 transition-all"><i className="fas fa-desktop text-sm lg:text-lg"></i></button>
                    </div>
                  )}
                  {!isWearable && (
                    <input type="text" value={inputText} onChange={(e) => setInputText(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSendText()} placeholder="Directive..." className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-4 lg:px-6 py-3 lg:py-5 text-sm lg:text-lg focus:outline-none focus:border-[var(--theme-primary)]/50 text-white font-bold transition-all shadow-inner placeholder-gray-700" />
                  )}
                  <button 
                    onClick={inputText.trim() ? handleSendText : (state === AssistantState.IDLE ? () => startSession() : stopSession)} 
                    className={`${isWearable ? 'w-full h-12' : 'flex-1 md:flex-none md:w-48 lg:w-64 h-14 lg:h-20'} rounded-[1.5rem] lg:rounded-[2rem] flex items-center justify-center transition-all gap-2 lg:gap-4 neo-button shadow-2xl ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-600 text-white animate-pulse'}`}
                  >
                    <i className={`fas ${inputText.trim() ? 'fa-paper-plane' : (state === AssistantState.IDLE ? 'fa-microphone' : 'fa-square')} text-sm lg:text-lg`}></i>
                    <span className="font-black uppercase tracking-widest text-[8px] lg:text-[11px]">{inputText.trim() ? 'SEND' : (state === AssistantState.IDLE ? 'INITIALIZE' : 'STOP')}</span>
                  </button>
              </div>
            </div>
          </div>
        </div>

        {isMemoryOpen && !isMobile && !isWearable && (
          <div className="w-full md:w-[350px] lg:w-[420px] flex-shrink-0 h-full animate-slide-in-right-bounce">
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
          </div>
        )}
      </main>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} prefs={prefs} setPrefs={setPrefs} voices={dynamicVoices} personalities={PERSONALITIES} isTV={isTV} isWearable={isWearable} onPreviewVoice={handlePreviewVoice} previewingVoiceId={previewingVoiceId} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality } from '@google/genai';
import { AssistantState, DeviceType, SensorData, UserPreferences, GroundingSource, TranscriptionEntry } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';
import ScreenShareMode from './components/ScreenShareMode';
import HardwareSensors from './components/HardwareSensors';
import GroundingSources from './components/GroundingSources';
import SettingsModal from './components/SettingsModal';
import IntroSequence from './components/IntroSequence';

const THEMES = {
  cosmic: { primary: '#3b82f6', secondary: '#8b5cf6', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: '#10b981', secondary: '#064e3b', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: '#f43f5e', secondary: '#9f1239', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: '#94a3b8', secondary: '#1e293b', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool = {
  name: 'save_knowledge',
  parameters: {
    type: 'OBJECT',
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: 'STRING', description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: 'Charon',
  assistantName: 'Project Chatty',
  customPersonality: 'You are a highly capable AI assistant.',
  modality: 'masculine'
};

const App = () => {
  const [showIntro, setShowIntro] = useState(true);
  const [user, setUser] = useState<{username: string, preferences: UserPreferences} | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [device, setDevice] = useState<DeviceType>('desktop');
  const [isScanning, setIsScanning] = useState(true);
  const [sensorData, setSensorData] = useState<SensorData>({ online: navigator.onLine, platform: navigator.platform });
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [memories, setMemories] = useState<any[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [inputText, setInputText] = useState('');
  const [searchEnabled, setSearchEnabled] = useState(true);
  const [errorToast, setErrorToast] = useState<string | null>(null);
  const [previewingVoiceId, setPreviewingVoiceId] = useState<string | null>(null);

  const audioContextRef = useRef<{input: AudioContext, output: AudioContext} | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef(0);
  const activeSourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement | null>(null);

  const themeData = useMemo(() => THEMES[prefs.theme] || THEMES.cosmic, [prefs.theme]);

  useEffect(() => {
    document.documentElement.style.setProperty('--theme-primary', themeData.primary);
    document.documentElement.style.setProperty('--theme-secondary', themeData.secondary);
    document.documentElement.style.setProperty('--bg-base', themeData.bg);
    document.documentElement.style.setProperty('--theme-glow', themeData.glow);
  }, [themeData]);

  const dynamicVoices = useMemo(() => {
    const isFem = prefs.modality === 'feminine';
    return isFem ? [
      { id: 'Zephyr', name: 'Gabby', tone: 'Warm, Smooth, Melodic', gender: 'feminine' },
      { id: 'Kore', name: 'Paula', tone: 'Clear, Professional, Calm', gender: 'feminine' },
      { id: 'Aoede', name: 'Kai', tone: 'Poetic, Soulful, Expressive', gender: 'feminine' },
      { id: 'Leda', name: 'Jessie', tone: 'Bright, Airy, Gentle', gender: 'feminine' }
    ] : [
      { id: 'Charon', name: 'John', tone: 'Deep, Bass, Authoritative', gender: 'masculine' },
      { id: 'Puck', name: 'Caleb', tone: 'Energetic, Bright, Playful', gender: 'masculine' },
      { id: 'Fenrir', name: 'Able', tone: 'Vibrant, Sharp, Focused', gender: 'masculine' },
      { id: 'Jake', name: 'Jake', tone: 'Deep, Resonant, Command', gender: 'masculine' }
    ];
  }, [prefs.modality]);

  useEffect(() => {
    const isValid = dynamicVoices.some(v => v.id === prefs.voiceId);
    if (!isValid && dynamicVoices.length > 0) {
      setPrefs(p => ({ ...p, voiceId: dynamicVoices[0].id }));
    }
  }, [dynamicVoices, prefs.voiceId]);

  const detectHardware = useCallback(async (isMounted: boolean) => {
    try {
      const w = window.innerWidth;
      const h = window.innerHeight;
      const ua = navigator.userAgent.toLowerCase();

      let detectedDevice: DeviceType = 'desktop';
      if (w <= 300 || (ua.includes('watch') && !ua.includes('tv'))) detectedDevice = 'wear';
      else if (ua.includes('android') && w > h && w >= 800 && w <= 1280) detectedDevice = 'auto';
      else if (ua.includes('tv') || ua.includes('smarttv') || (w >= 1920 && h >= 1080)) detectedDevice = 'tv';
      else if (w < 768 || (w < 1024 && h > w)) detectedDevice = 'mobile';

      if (isMounted) {
        setDevice(detectedDevice);
        document.documentElement.setAttribute('data-device', detectedDevice);
      }

      const sensorPayload: SensorData = { online: navigator.onLine, platform: navigator.platform };
      if ('getBattery' in navigator) {
        try {
          const battery = await (navigator as any).getBattery();
          sensorPayload.battery = battery.level;
          sensorPayload.charging = battery.charging;
        } catch (e) {}
      }

      if (navigator.geolocation && ['auto', 'mobile', 'desktop'].includes(detectedDevice)) {
        navigator.geolocation.getCurrentPosition(
          (pos) => isMounted && setSensorData(prev => ({ ...prev, location: { lat: pos.coords.latitude, lng: pos.coords.longitude } })),
          undefined,
          { enableHighAccuracy: false, timeout: 5000 }
        );
      }
      if (isMounted) {
        setSensorData(prev => ({ ...prev, ...sensorPayload }));
        setTimeout(() => setIsScanning(false), 2000);
      }
    } catch (err) {
      console.error("Hardware probe failure", err);
    }
  }, []);

  useEffect(() => {
    let isMounted = true;
    detectHardware(isMounted);
    const handleResize = () => detectHardware(isMounted);
    window.addEventListener('resize', handleResize);
    return () => {
      isMounted = false;
      window.removeEventListener('resize', handleResize);
    };
  }, [detectHardware]);

  useEffect(() => {
    // Priority: Session (current tab) -> Persistent (localStorage)
    const sessionUser = sessionStorage.getItem('nova_session_user') || localStorage.getItem('nova_persistent_user');
    if (sessionUser) {
      try {
        const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
        setUser({ username: sessionUser, preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS });
      } catch (e) {
        setUser({ username: sessionUser, preferences: DEFAULT_PREFS });
      }
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      setMemories(JSON.parse(localStorage.getItem(`nova_${user.username}_memories`) || '[]'));
      setTranscriptions(JSON.parse(localStorage.getItem(`nova_${user.username}_logs`) || '[]'));
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  // CHAT BY DAY LOGIC
  const groupedTranscriptions = useMemo(() => {
    const groups: Record<string, TranscriptionEntry[]> = {};
    transcriptions.forEach(entry => {
      const date = new Date(entry.timestamp);
      const dateKey = date.toDateString();
      if (!groups[dateKey]) groups[dateKey] = [];
      groups[dateKey].push(entry);
    });
    return groups;
  }, [transcriptions]);

  const formatDateHeader = (dateStr: string) => {
    const date = new Date(dateStr);
    const today = new Date();
    const yesterday = new Date();
    yesterday.setDate(today.getDate() - 1);

    if (date.toDateString() === today.toDateString()) return "Today";
    if (date.toDateString() === yesterday.toDateString()) return "Yesterday";

    return date.toLocaleDateString(undefined, { 
      weekday: 'long', 
      year: 'numeric', 
      month: 'long', 
      day: 'numeric' 
    });
  };

  const isWearable = device === 'wear';
  const isAuto = device === 'auto';
  const isTV = device === 'tv';
  const isMobile = device === 'mobile';

  const addTranscription = useCallback((sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text?.trim()) return;
    setTranscriptions(prev => [
      ...prev, { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  }, []);

  const deleteTranscription = (id: string) => {
    setTranscriptions(prev => prev.filter(t => t.id !== id));
  };

  const clearAllTranscriptions = () => {
    if (window.confirm("Purge all chat records from this segment?")) {
      setTranscriptions([]);
    }
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
  }, [screenStream]);

  const handleLogout = useCallback(() => {
    stopSession();
    setUser(null);
    sessionStorage.removeItem('nova_session_user');
    localStorage.removeItem('nova_persistent_user');
  }, [stopSession]);

  const handleLogin = (username: string, initialPrefs: any) => {
    setUser({ username, preferences: { ...DEFAULT_PREFS, ...initialPrefs } });
  };

  const downsample = (buffer: Float32Array, fromRate: number, toRate: number) => {
    if (fromRate === toRate) return buffer;
    const ratio = fromRate / toRate;
    const result = new Float32Array(Math.round(buffer.length / ratio));
    for (let i = 0, offset = 0; i < result.length; i++, offset = Math.round(i * ratio)) {
      result[i] = buffer[offset];
    }
    return result;
  };

  const handlePreviewVoice = async (voiceId: string) => {
    if (previewingVoiceId) return;
    try {
      setPreviewingVoiceId(voiceId);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing.");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)(),
          output: new (window.AudioContext || (window as any).webkitAudioContext)()
        };
      }
      const outputCtx = audioContextRef.current.output;
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      const ai = new GoogleGenAI({ apiKey });
      const voice = dynamicVoices.find(v => v.id === voiceId);
      const prompt = `Say: Hello, I am ${voice?.name}. I am your chatty voice profile.`;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voiceId } } },
        },
      });

      const audioPart = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
      if (audioPart?.inlineData?.data) {
        const audioBuffer = await audioUtils.decodeAudioData(audioUtils.decode(audioPart.inlineData.data), outputCtx, 24000, 1);
        const source = outputCtx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(outputCtx.destination);
        source.onended = () => setPreviewingVoiceId(null);
        source.start(0);
      } else setPreviewingVoiceId(null);
    } catch (err) { setPreviewingVoiceId(null); }
  };

  const startSession = async (initialText?: string) => {
    try {
      setState(AssistantState.CONNECTING);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Authentication failure.");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)(),
          output: new (window.AudioContext || (window as any).webkitAudioContext)()
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      audioUtils.playLinkSound(outputCtx);

      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: { echoCancellation: true, noiseSuppression: true, sampleRate: 16000, channelCount: 1 } 
      });
      micStreamRef.current = stream;

      const source = inputCtx.createMediaStreamSource(stream);
      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const personalityPrompt = prefs.personality === 'custom' ? (prefs.customPersonality || 'Be helpful.') : PERSONALITIES[prefs.personality];

      const tools: any[] = [];
      if (sensorData.location) tools.push({ googleMaps: {} });
      if (searchEnabled) tools.push({ googleSearch: {} });
      if (!searchEnabled && !sensorData.location) tools.push({ functionDeclarations: [saveKnowledgeTool] });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools,
          toolConfig: sensorData.location ? {
            retrievalConfig: { latLng: { latitude: sensorData.location.lat, longitude: sensorData.location.lng } }
          } : undefined,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. Platform: ${device}. Personality: ${personalityPrompt}.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        } as any,
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const resampledData = downsample(inputData, inputCtx.sampleRate, 16000);
              const pcmBlob = audioUtils.createPcmBlob(resampledData);
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
              if (currentFrameRef.current) {
                const frame = currentFrameRef.current;
                currentFrameRef.current = null;
                sessionPromise.then(s => s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } }));
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
            if (initialText) sessionPromise.then(s => s.sendRealtimeInput({ text: initialText }));
          },
          onmessage: async (message: any) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = fc.args.fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Saved." } } }));
                }
              }
            }

            const turnParts = message.serverContent?.modelTurn?.parts || [];
            for (const part of turnParts) {
              if (part.inlineData?.data) {
                setState(AssistantState.SPEAKING);
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
                const buffer = await audioUtils.decodeAudioData(audioUtils.decode(part.inlineData.data), outputCtx, 24000, 1);
                const s = outputCtx.createBufferSource(); 
                s.buffer = buffer; 
                s.connect(outputCtx.destination);
                s.onended = () => { activeSourcesRef.current.delete(s); if (activeSourcesRef.current.size === 0) setState(AssistantState.LISTENING); };
                s.start(nextStartTimeRef.current); 
                nextStartTimeRef.current += buffer.duration; 
                activeSourcesRef.current.add(s);
              }
            }

            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent.inputTranscription.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent.outputTranscription.text);
            if (message.serverContent?.turnComplete) {
              const chunks = message.serverContent?.groundingMetadata?.groundingChunks || [];
              const sources = chunks.map((c: any) => {
                if (c.web) return { title: c.web.title, uri: c.web.uri };
                if (c.maps) return { title: c.maps.title, uri: c.maps.uri };
                return null;
              }).filter(Boolean);

              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) { addTranscription('assistant', a, sources); audioUtils.playSuccessSound(outputCtx); } return ''; });
            }
          },
          onerror: () => stopSession(),
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { 
      setErrorToast(err.message);
      setState(AssistantState.IDLE); 
      setTimeout(() => setErrorToast(null), 5000);
    }
  };

  const handleToggleScreenShare = async () => {
    if (isScreenSharing) {
      setIsScreenSharing(false);
      if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    } else {
      try {
        const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
        setScreenStream(stream);
        setIsVisionActive(false);
        setIsScreenSharing(true);
        if (state === AssistantState.IDLE) startSession();
        stream.getVideoTracks()[0].onended = () => { setIsScreenSharing(false); setScreenStream(null); };
      } catch (err: any) { setErrorToast(err.message); }
    }
  };

  const handleToggleVision = async () => {
    if (isVisionActive) setIsVisionActive(false);
    else {
      try {
        await navigator.mediaDevices.getUserMedia({ video: true });
        setIsScreenSharing(false);
        setIsVisionActive(true);
        if (state === AssistantState.IDLE) startSession();
      } catch (err) { setErrorToast("Optic access denied."); }
    }
  };

  const handleSendText = () => {
    if (!inputText.trim()) return;
    const msg = inputText.trim();
    setInputText('');
    addTranscription('user', msg);
    if (sessionRef.current) {
      setState(AssistantState.THINKING);
      sessionRef.current.sendRealtimeInput({ text: msg });
    } else startSession(msg);
  };

  if (showIntro) return <IntroSequence onComplete={() => setShowIntro(false)} />;
  if (!user) return <LoginPage onLogin={handleLogin} />;

  if (isScanning) {
    return (
      <div className="fixed inset-0 bg-[#02020a] flex flex-col items-center justify-center z-[200] animate-fade-blur-in overflow-hidden">
        <div className="absolute inset-0 animate-scan-v bg-gradient-to-b from-transparent via-[var(--theme-primary)]/20 to-transparent pointer-events-none opacity-40"></div>
        <div className="relative w-[30vw] h-[30vw] max-w-64 max-h-64 flex items-center justify-center animate-float-3d">
          <div className="absolute inset-0 border-4 border-t-[var(--theme-primary)] border-r-transparent border-b-transparent border-l-transparent rounded-full animate-spin"></div>
          <div className="absolute inset-4 border-2 border-b-[var(--theme-secondary)] border-t-transparent border-r-transparent border-l-transparent rounded-full animate-spin [animation-duration:3s]"></div>
          <i className="fas fa-atom text-6xl text-white animate-pulse"></i>
        </div>
        <h2 className="mt-12 text-2xl font-black tracking-[0.5em] uppercase text-white mb-2 text-center animate-slide-up-reveal px-6">Chatty Sync Active</h2>
        <p className="text-[11px] text-[var(--theme-primary)] font-black uppercase tracking-[0.3em] animate-pulse">Linking Bio-Core...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full w-full transition-all duration-1000 overflow-hidden">
      {errorToast && (
        <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[300] bg-red-600/90 backdrop-blur-xl text-white px-8 py-5 rounded-[2rem] font-black uppercase tracking-widest text-[10px] shadow-[0_20px_60px_rgba(220,38,38,0.4)] animate-pop flex items-center gap-4">
          <i className="fas fa-exclamation-triangle"></i>
          {errorToast}
          <button onClick={() => setErrorToast(null)} className="ml-4 opacity-50 hover:opacity-100"><i className="fas fa-times"></i></button>
        </div>
      )}

      <header className={`m-[var(--ui-gap)] p-4 lg:p-6 rounded-[var(--ui-radius)] flex items-center justify-between z-50 glass animate-fade-blur-in`}>
        <div className="flex items-center gap-3 lg:gap-6 group">
          <div className={`w-10 h-10 lg:w-14 lg:h-14 rounded-[1.5rem] overflow-hidden border border-white/10 relative transition-all duration-700 group-hover:scale-110 shadow-xl`}>
            {prefs.assistantProfilePic ? <img src={prefs.assistantProfilePic} className="w-full h-full object-cover" alt="AI" /> : <div className="w-full h-full bg-[var(--theme-primary)]/10 flex items-center justify-center"><i className="fas fa-atom text-white text-lg lg:text-xl"></i></div>}
          </div>
          {!isWearable && (
            <div className="animate-slide-in-right-bounce">
              <h1 className="text-sm lg:text-2xl font-black tracking-tighter text-white uppercase truncate max-w-[120px] lg:max-w-none">{prefs.assistantName}</h1>
              {/* Fix: use themeData.primary instead of undefined themeColor */}
              {!isMobile && <HardwareSensors data={sensorData} deviceType={device} themeColor={themeData.primary} />}
            </div>
          )}
        </div>
        <div className="flex items-center gap-2 md:gap-4">
           {transcriptions.length > 0 && !isWearable && (
             <button 
               onClick={clearAllTranscriptions} 
               className="w-10 h-10 lg:w-12 lg:h-12 rounded-xl bg-red-500/10 hover:bg-red-500/20 text-red-400 flex items-center justify-center transition-all active:scale-90"
               title="Clear All History"
             >
               <i className="fas fa-trash-sweep text-sm lg:text-lg"></i>
             </button>
           )}
           {!isWearable && <button onClick={() => setIsSettingsOpen(true)} className="w-10 h-10 lg:w-12 lg:h-12 rounded-xl bg-white/5 flex items-center justify-center hover:bg-white/10 transition-all active:scale-90"><i className="fas fa-cog text-sm lg:text-lg"></i></button>}
           {!isWearable && <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-10 h-10 lg:w-12 lg:h-12 rounded-xl flex items-center justify-center transition-all active:scale-90 ${isMemoryOpen ? 'bg-[var(--theme-primary)] text-white shadow-[0_0_30px_rgba(37,99,235,0.4)]' : 'bg-white/5 text-gray-400'}`}><i className="fas fa-brain text-sm lg:text-lg"></i></button>}
           <button onClick={handleLogout} className="w-10 h-10 lg:w-12 lg:h-12 flex items-center justify-center text-gray-600 hover:text-red-500 transition-colors active:scale-90"><i className="fas fa-power-off text-sm lg:text-lg"></i></button>
        </div>
      </header>

      <main className={`flex-1 flex ${isMobile || isWearable ? 'flex-col' : 'flex-row'} min-h-0 p-[var(--ui-gap)] gap-[var(--ui-gap)] overflow-hidden`}>
        <div className="flex-1 flex flex-col gap-[var(--ui-gap)] min-h-0">
          {(isVisionActive || isScreenSharing) && (
            <div className={`h-48 md:h-72 lg:h-[400px] w-full animate-pop flex-shrink-0 relative group`}>
              <div className={`absolute -inset-1 bg-gradient-to-r from-[var(--theme-primary)] to-[var(--theme-secondary)] rounded-[var(--ui-radius)] blur opacity-20 group-hover:opacity-40 transition-opacity`}></div>
              {isVisionActive && <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />}
              {isScreenSharing && screenStream && <ScreenShareMode isActive={isScreenSharing} stream={screenStream} onFrame={(b) => currentFrameRef.current = b} onStop={() => setIsScreenSharing(false)} />}
            </div>
          )}

          <div className="flex-1 flex flex-col glass rounded-[var(--ui-radius)] overflow-hidden relative min-h-0 group shadow-2xl">
            <div className={`absolute inset-0 bg-gradient-to-br from-[var(--theme-primary)]/5 via-transparent to-[var(--theme-secondary)]/5 pointer-events-none opacity-40`}></div>

            <div className={`flex-1 p-4 lg:p-8 space-y-4 lg:space-y-8 overflow-y-auto scrollbar-thin transcription-list`} ref={scrollRef}>
              {transcriptions.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center opacity-20 animate-float-3d">
                  <i className={`fas fa-comment-dots text-6xl lg:text-9xl mb-6 text-gray-600`}></i>
                  {!isWearable && <p className="text-xl lg:text-3xl font-black uppercase tracking-[0.5em] shimmer-text-fast">Chatty Core</p>}
                </div>
              )}

              {/* RENDER GROUPED TRANSCRIPTIONS BY DAY */}
              {Object.entries(groupedTranscriptions).map(([dateStr, items]) => (
                <React.Fragment key={dateStr}>
                  <div className="day-separator animate-fade-blur-in">
                    <div className="day-line"></div>
                    <div className="day-badge">{formatDateHeader(dateStr)}</div>
                    <div className="day-line"></div>
                  </div>

                  {items.map((e) => (
                    <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'} animate-slide-up-reveal group/item`}>
                      <div className={`
                        max-w-[90%] lg:max-w-[85%] 
                        px-4 py-3 lg:px-7 lg:py-5 
                        rounded-[1.5rem] lg:rounded-[2rem] 
                        shadow-xl transition-all hover:scale-[1.01] relative
                        ${e.sender === 'user' 
                          ? 'bg-gradient-to-br from-[var(--theme-primary)] to-indigo-600 text-white' 
                          : 'bg-white/[0.04] text-gray-200 border border-white/5 backdrop-blur-xl'
                        }
                      `}>
                        {/* Quick Delete Trigger */}
                        <button 
                          onClick={() => deleteTranscription(e.id)}
                          className={`absolute ${e.sender === 'user' ? '-left-8' : '-right-8'} top-1/2 -translate-y-1/2 opacity-0 group-hover/item:opacity-40 hover:!opacity-100 text-red-500 transition-all p-2 active:scale-90`}
                        >
                          <i className="fas fa-trash-alt text-xs lg:text-sm"></i>
                        </button>

                        <p className="text-sm lg:text-lg font-bold leading-relaxed whitespace-pre-wrap">{e.text}</p>
                        {!isWearable && e.sources && <GroundingSources sources={e.sources} themePrimary={themeData.primary} />}
                        <div className={`mt-2 text-[8px] opacity-40 uppercase font-black tracking-widest ${e.sender === 'user' ? 'text-right' : 'text-left'}`}>
                          {new Date(e.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </div>
                      </div>
                    </div>
                  ))}
                </React.Fragment>
              ))}

              {(streamingAssistantText || state === AssistantState.THINKING) && (
                <div className="items-start flex flex-col animate-pop">
                  <div className="max-w-[85%] px-5 py-3 rounded-[1.5rem] bg-white/[0.03] text-white/60 border border-white/5">
                    {streamingAssistantText ? <p className="font-mono text-xs lg:text-sm leading-relaxed">{streamingAssistantText}</p> : <div className="typing-indicator"><span></span><span></span><span></span></div>}
                  </div>
                </div>
              )}
            </div>

            <div className={`p-4 lg:p-8 border-t border-white/5 bg-black/50 backdrop-blur-2xl flex flex-col gap-3 lg:gap-6`}>
              {!isWearable && <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />}
              <div className={`flex ${isWearable ? 'flex-col gap-2' : 'gap-3'} items-center`}>
                  {!isWearable && (
                    <div className="flex gap-2">
                      <button onClick={handleToggleVision} title="Optic Link" className="w-10 h-10 lg:w-14 lg:h-14 rounded-xl glass flex items-center justify-center active:scale-90 transition-all"><i className="fas fa-camera text-sm lg:text-lg"></i></button>
                      <button onClick={handleToggleScreenShare} title="Desktop Uplink" className="w-10 h-10 lg:w-14 lg:h-14 rounded-xl glass flex items-center justify-center active:scale-90 transition-all"><i className="fas fa-desktop text-sm lg:text-lg"></i></button>
                    </div>
                  )}
                  {!isWearable && (
                    <input type="text" value={inputText} onChange={(e) => setInputText(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSendText()} placeholder="Directive..." className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-4 lg:px-6 py-3 lg:py-5 text-sm lg:text-lg focus:outline-none focus:border-[var(--theme-primary)]/50 text-white font-bold transition-all shadow-inner placeholder-gray-700" />
                  )}
                  <button 
                    onClick={inputText.trim() ? handleSendText : (state === AssistantState.IDLE ? () => startSession() : stopSession)} 
                    className={`${isWearable ? 'w-full h-12' : 'flex-1 md:flex-none md:w-48 lg:w-64 h-14 lg:h-20'} rounded-[1.5rem] lg:rounded-[2rem] flex items-center justify-center transition-all gap-2 lg:gap-4 neo-button shadow-2xl ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-600 text-white animate-pulse'}`}
                  >
                    <i className={`fas ${inputText.trim() ? 'fa-paper-plane' : (state === AssistantState.IDLE ? 'fa-microphone' : 'fa-square')} text-sm lg:text-lg`}></i>
                    <span className="font-black uppercase tracking-widest text-[8px] lg:text-[11px]">{inputText.trim() ? 'SEND' : (state === AssistantState.IDLE ? 'INITIALIZE' : 'STOP')}</span>
                  </button>
              </div>
            </div>
          </div>
        </div>

        {isMemoryOpen && !isMobile && !isWearable && (
          <div className="w-full md:w-[350px] lg:w-[420px] flex-shrink-0 h-full animate-slide-in-right-bounce">
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
          </div>
        )}
      </main>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} prefs={prefs} setPrefs={setPrefs} voices={dynamicVoices} personalities={PERSONALITIES} isTV={isTV} isWearable={isWearable} onPreviewVoice={handlePreviewVoice} previewingVoiceId={previewingVoiceId} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality } from '@google/genai';
import { AssistantState, DeviceType, SensorData, UserPreferences, GroundingSource, TranscriptionEntry } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';
import ScreenShareMode from './components/ScreenShareMode';
import HardwareSensors from './components/HardwareSensors';
import GroundingSources from './components/GroundingSources';
import SettingsModal from './components/SettingsModal';
import IntroSequence from './components/IntroSequence';

const THEMES = {
  cosmic: { primary: '#3b82f6', secondary: '#8b5cf6', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: '#10b981', secondary: '#064e3b', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: '#f43f5e', secondary: '#9f1239', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: '#94a3b8', secondary: '#1e293b', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool = {
  name: 'save_knowledge',
  parameters: {
    type: 'OBJECT',
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: 'STRING', description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: 'Charon',
  assistantName: 'Project Chatty',
  customPersonality: 'You are a highly capable AI assistant.',
  modality: 'masculine'
};

const App = () => {
  const [showIntro, setShowIntro] = useState(true);
  const [user, setUser] = useState<{username: string, preferences: UserPreferences} | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [device, setDevice] = useState<DeviceType>('desktop');
  const [isScanning, setIsScanning] = useState(true);
  const [sensorData, setSensorData] = useState<SensorData>({ online: navigator.onLine, platform: navigator.platform });
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [memories, setMemories] = useState<any[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [inputText, setInputText] = useState('');
  const [searchEnabled, setSearchEnabled] = useState(true);
  const [errorToast, setErrorToast] = useState<string | null>(null);
  const [previewingVoiceId, setPreviewingVoiceId] = useState<string | null>(null);

  const audioContextRef = useRef<{input: AudioContext, output: AudioContext} | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef(0);
  const activeSourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement | null>(null);

  const themeData = useMemo(() => THEMES[prefs.theme] || THEMES.cosmic, [prefs.theme]);

  useEffect(() => {
    document.documentElement.style.setProperty('--theme-primary', themeData.primary);
    document.documentElement.style.setProperty('--theme-secondary', themeData.secondary);
    document.documentElement.style.setProperty('--bg-base', themeData.bg);
    document.documentElement.style.setProperty('--theme-glow', themeData.glow);
  }, [themeData]);

  const dynamicVoices = useMemo(() => {
    const isFem = prefs.modality === 'feminine';
    return isFem ? [
      { id: 'Zephyr', name: 'Gabby', tone: 'Warm, Smooth, Melodic', gender: 'feminine' },
      { id: 'Kore', name: 'Paula', tone: 'Clear, Professional, Calm', gender: 'feminine' },
      { id: 'Aoede', name: 'Kai', tone: 'Poetic, Soulful, Expressive', gender: 'feminine' },
      { id: 'Leda', name: 'Jessie', tone: 'Bright, Airy, Gentle', gender: 'feminine' }
    ] : [
      { id: 'Charon', name: 'John', tone: 'Deep, Bass, Authoritative', gender: 'masculine' },
      { id: 'Puck', name: 'Caleb', tone: 'Energetic, Bright, Playful', gender: 'masculine' },
      { id: 'Fenrir', name: 'Able', tone: 'Vibrant, Sharp, Focused', gender: 'masculine' },
      { id: 'Jake', name: 'Jake', tone: 'Deep, Resonant, Command', gender: 'masculine' }
    ];
  }, [prefs.modality]);

  useEffect(() => {
    const isValid = dynamicVoices.some(v => v.id === prefs.voiceId);
    if (!isValid && dynamicVoices.length > 0) {
      setPrefs(p => ({ ...p, voiceId: dynamicVoices[0].id }));
    }
  }, [dynamicVoices, prefs.voiceId]);

  const detectHardware = useCallback(async (isMounted: boolean) => {
    try {
      const w = window.innerWidth;
      const h = window.innerHeight;
      const ua = navigator.userAgent.toLowerCase();

      let detectedDevice: DeviceType = 'desktop';
      if (w <= 300 || (ua.includes('watch') && !ua.includes('tv'))) detectedDevice = 'wear';
      else if (ua.includes('android') && w > h && w >= 800 && w <= 1280) detectedDevice = 'auto';
      else if (ua.includes('tv') || ua.includes('smarttv') || (w >= 1920 && h >= 1080)) detectedDevice = 'tv';
      else if (w < 768 || (w < 1024 && h > w)) detectedDevice = 'mobile';

      if (isMounted) {
        setDevice(detectedDevice);
        document.documentElement.setAttribute('data-device', detectedDevice);
      }

      const sensorPayload: SensorData = { online: navigator.onLine, platform: navigator.platform };
      if ('getBattery' in navigator) {
        try {
          const battery = await (navigator as any).getBattery();
          sensorPayload.battery = battery.level;
          sensorPayload.charging = battery.charging;
        } catch (e) {}
      }

      if (navigator.geolocation && ['auto', 'mobile', 'desktop'].includes(detectedDevice)) {
        navigator.geolocation.getCurrentPosition(
          (pos) => isMounted && setSensorData(prev => ({ ...prev, location: { lat: pos.coords.latitude, lng: pos.coords.longitude } })),
          undefined,
          { enableHighAccuracy: false, timeout: 5000 }
        );
      }
      if (isMounted) {
        setSensorData(prev => ({ ...prev, ...sensorPayload }));
        setTimeout(() => setIsScanning(false), 2000);
      }
    } catch (err) {
      console.error("Hardware probe failure", err);
    }
  }, []);

  useEffect(() => {
    let isMounted = true;
    detectHardware(isMounted);
    const handleResize = () => detectHardware(isMounted);
    window.addEventListener('resize', handleResize);
    return () => {
      isMounted = false;
      window.removeEventListener('resize', handleResize);
    };
  }, [detectHardware]);

  useEffect(() => {
    // Priority: Session (current tab) -> Persistent (localStorage)
    const sessionUser = sessionStorage.getItem('nova_session_user') || localStorage.getItem('nova_persistent_user');
    if (sessionUser) {
      try {
        const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
        setUser({ username: sessionUser, preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS });
      } catch (e) {
        setUser({ username: sessionUser, preferences: DEFAULT_PREFS });
      }
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      setMemories(JSON.parse(localStorage.getItem(`nova_${user.username}_memories`) || '[]'));
      setTranscriptions(JSON.parse(localStorage.getItem(`nova_${user.username}_logs`) || '[]'));
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
      localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
      localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  // CHAT BY DAY LOGIC
  const groupedTranscriptions = useMemo(() => {
    const groups: Record<string, TranscriptionEntry[]> = {};
    transcriptions.forEach(entry => {
      const date = new Date(entry.timestamp);
      const dateKey = date.toDateString();
      if (!groups[dateKey]) groups[dateKey] = [];
      groups[dateKey].push(entry);
    });
    return groups;
  }, [transcriptions]);

  const formatDateHeader = (dateStr: string) => {
    const date = new Date(dateStr);
    const today = new Date();
    const yesterday = new Date();
    yesterday.setDate(today.getDate() - 1);

    if (date.toDateString() === today.toDateString()) return "Today";
    if (date.toDateString() === yesterday.toDateString()) return "Yesterday";

    return date.toLocaleDateString(undefined, { 
      weekday: 'long', 
      year: 'numeric', 
      month: 'long', 
      day: 'numeric' 
    });
  };

  const isWearable = device === 'wear';
  const isAuto = device === 'auto';
  const isTV = device === 'tv';
  const isMobile = device === 'mobile';

  const addTranscription = useCallback((sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text?.trim()) return;
    setTranscriptions(prev => [
      ...prev, { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  }, []);

  const deleteTranscription = (id: string) => {
    setTranscriptions(prev => prev.filter(t => t.id !== id));
  };

  const clearAllTranscriptions = () => {
    if (window.confirm("Purge all chat records from this segment?")) {
      setTranscriptions([]);
    }
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
  }, [screenStream]);

  const handleLogout = useCallback(() => {
    stopSession();
    setUser(null);
    sessionStorage.removeItem('nova_session_user');
    localStorage.removeItem('nova_persistent_user');
  }, [stopSession]);

  const handleLogin = (username: string, initialPrefs: any) => {
    setUser({ username, preferences: { ...DEFAULT_PREFS, ...initialPrefs } });
  };

  const downsample = (buffer: Float32Array, fromRate: number, toRate: number) => {
    if (fromRate === toRate) return buffer;
    const ratio = fromRate / toRate;
    const result = new Float32Array(Math.round(buffer.length / ratio));
    for (let i = 0, offset = 0; i < result.length; i++, offset = Math.round(i * ratio)) {
      result[i] = buffer[offset];
    }
    return result;
  };

  const handlePreviewVoice = async (voiceId: string) => {
    if (previewingVoiceId) return;
    try {
      setPreviewingVoiceId(voiceId);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing.");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)(),
          output: new (window.AudioContext || (window as any).webkitAudioContext)()
        };
      }
      const outputCtx = audioContextRef.current.output;
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      const ai = new GoogleGenAI({ apiKey });
      const voice = dynamicVoices.find(v => v.id === voiceId);
      const prompt = `Say: Hello, I am ${voice?.name}. I am your chatty voice profile.`;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voiceId } } },
        },
      });

      const audioPart = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
      if (audioPart?.inlineData?.data) {
        const audioBuffer = await audioUtils.decodeAudioData(audioUtils.decode(audioPart.inlineData.data), outputCtx, 24000, 1);
        const source = outputCtx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(outputCtx.destination);
        source.onended = () => setPreviewingVoiceId(null);
        source.start(0);
      } else setPreviewingVoiceId(null);
    } catch (err) { setPreviewingVoiceId(null); }
  };

  const startSession = async (initialText?: string) => {
    try {
      setState(AssistantState.CONNECTING);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Authentication failure.");

      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)(),
          output: new (window.AudioContext || (window as any).webkitAudioContext)()
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      audioUtils.playLinkSound(outputCtx);

      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: { echoCancellation: true, noiseSuppression: true, sampleRate: 16000, channelCount: 1 } 
      });
      micStreamRef.current = stream;

      const source = inputCtx.createMediaStreamSource(stream);
      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;
      source.connect(analyser);

      const ai = new GoogleGenAI({ apiKey });
      const personalityPrompt = prefs.personality === 'custom' ? (prefs.customPersonality || 'Be helpful.') : PERSONALITIES[prefs.personality];

      const tools: any[] = [];
      if (sensorData.location) tools.push({ googleMaps: {} });
      if (searchEnabled) tools.push({ googleSearch: {} });
      if (!searchEnabled && !sensorData.location) tools.push({ functionDeclarations: [saveKnowledgeTool] });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools,
          toolConfig: sensorData.location ? {
            retrievalConfig: { latLng: { latitude: sensorData.location.lat, longitude: sensorData.location.lng } }
          } : undefined,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. Platform: ${device}. Personality: ${personalityPrompt}.`,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          thinkingConfig: { thinkingBudget: 24576 }
        } as any,
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const resampledData = downsample(inputData, inputCtx.sampleRate, 16000);
              const pcmBlob = audioUtils.createPcmBlob(resampledData);
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
              if (currentFrameRef.current) {
                const frame = currentFrameRef.current;
                currentFrameRef.current = null;
                sessionPromise.then(s => s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } }));
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
            if (initialText) sessionPromise.then(s => s.sendRealtimeInput({ text: initialText }));
          },
          onmessage: async (message: any) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const factStr = fc.args.fact;
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: factStr, timestamp: new Date() }]);
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Saved." } } }));
                }
              }
            }

            const turnParts = message.serverContent?.modelTurn?.parts || [];
            for (const part of turnParts) {
              if (part.inlineData?.data) {
                setState(AssistantState.SPEAKING);
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
                const buffer = await audioUtils.decodeAudioData(audioUtils.decode(part.inlineData.data), outputCtx, 24000, 1);
                const s = outputCtx.createBufferSource(); 
                s.buffer = buffer; 
                s.connect(outputCtx.destination);
                s.onended = () => { activeSourcesRef.current.delete(s); if (activeSourcesRef.current.size === 0) setState(AssistantState.LISTENING); };
                s.start(nextStartTimeRef.current); 
                nextStartTimeRef.current += buffer.duration; 
                activeSourcesRef.current.add(s);
              }
            }

            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent.inputTranscription.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent.outputTranscription.text);
            if (message.serverContent?.turnComplete) {
              const chunks = message.serverContent?.groundingMetadata?.groundingChunks || [];
              const sources = chunks.map((c: any) => {
                if (c.web) return { title: c.web.title, uri: c.web.uri };
                if (c.maps) return { title: c.maps.title, uri: c.maps.uri };
                return null;
              }).filter(Boolean);

              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) { addTranscription('assistant', a, sources); audioUtils.playSuccessSound(outputCtx); } return ''; });
            }
          },
          onerror: () => stopSession(),
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { 
      setErrorToast(err.message);
      setState(AssistantState.IDLE); 
      setTimeout(() => setErrorToast(null), 5000);
    }
  };

  const handleToggleScreenShare = async () => {
    if (isScreenSharing) {
      setIsScreenSharing(false);
      if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    } else {
      try {
        const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
        setScreenStream(stream);
        setIsVisionActive(false);
        setIsScreenSharing(true);
        if (state === AssistantState.IDLE) startSession();
        stream.getVideoTracks()[0].onended = () => { setIsScreenSharing(false); setScreenStream(null); };
      } catch (err: any) { setErrorToast(err.message); }
    }
  };

  const handleToggleVision = async () => {
    if (isVisionActive) setIsVisionActive(false);
    else {
      try {
        await navigator.mediaDevices.getUserMedia({ video: true });
        setIsScreenSharing(false);
        setIsVisionActive(true);
        if (state === AssistantState.IDLE) startSession();
      } catch (err) { setErrorToast("Optic access denied."); }
    }
  };

  const handleSendText = () => {
    if (!inputText.trim()) return;
    const msg = inputText.trim();
    setInputText('');
    addTranscription('user', msg);
    if (sessionRef.current) {
      setState(AssistantState.THINKING);
      sessionRef.current.sendRealtimeInput({ text: msg });
    } else startSession(msg);
  };

  if (showIntro) return <IntroSequence onComplete={() => setShowIntro(false)} />;
  if (!user) return <LoginPage onLogin={handleLogin} />;

  if (isScanning) {
    return (
      <div className="fixed inset-0 bg-[#02020a] flex flex-col items-center justify-center z-[200] animate-fade-blur-in overflow-hidden">
        <div className="absolute inset-0 animate-scan-v bg-gradient-to-b from-transparent via-[var(--theme-primary)]/20 to-transparent pointer-events-none opacity-40"></div>
        <div className="relative w-[30vw] h-[30vw] max-w-64 max-h-64 flex items-center justify-center animate-float-3d">
          <div className="absolute inset-0 border-4 border-t-[var(--theme-primary)] border-r-transparent border-b-transparent border-l-transparent rounded-full animate-spin"></div>
          <div className="absolute inset-4 border-2 border-b-[var(--theme-secondary)] border-t-transparent border-r-transparent border-l-transparent rounded-full animate-spin [animation-duration:3s]"></div>
          <i className="fas fa-atom text-6xl text-white animate-pulse"></i>
        </div>
        <h2 className="mt-12 text-2xl font-black tracking-[0.5em] uppercase text-white mb-2 text-center animate-slide-up-reveal px-6">Chatty Sync Active</h2>
        <p className="text-[11px] text-[var(--theme-primary)] font-black uppercase tracking-[0.3em] animate-pulse">Linking Bio-Core...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full w-full transition-all duration-1000 overflow-hidden">
      {errorToast && (
        <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[300] bg-red-600/90 backdrop-blur-xl text-white px-8 py-5 rounded-[2rem] font-black uppercase tracking-widest text-[10px] shadow-[0_20px_60px_rgba(220,38,38,0.4)] animate-pop flex items-center gap-4">
          <i className="fas fa-exclamation-triangle"></i>
          {errorToast}
          <button onClick={() => setErrorToast(null)} className="ml-4 opacity-50 hover:opacity-100"><i className="fas fa-times"></i></button>
        </div>
      )}

      <header className={`m-[var(--ui-gap)] p-4 lg:p-6 rounded-[var(--ui-radius)] flex items-center justify-between z-50 glass animate-fade-blur-in`}>
        <div className="flex items-center gap-3 lg:gap-6 group">
          <div className={`w-10 h-10 lg:w-14 lg:h-14 rounded-[1.5rem] overflow-hidden border border-white/10 relative transition-all duration-700 group-hover:scale-110 shadow-xl`}>
            {prefs.assistantProfilePic ? <img src={prefs.assistantProfilePic} className="w-full h-full object-cover" alt="AI" /> : <div className="w-full h-full bg-[var(--theme-primary)]/10 flex items-center justify-center"><i className="fas fa-atom text-white text-lg lg:text-xl"></i></div>}
          </div>
          {!isWearable && (
            <div className="animate-slide-in-right-bounce">
              <h1 className="text-sm lg:text-2xl font-black tracking-tighter text-white uppercase truncate max-w-[120px] lg:max-w-none">{prefs.assistantName}</h1>
              {/* Fix: use themeData.primary instead of undefined themeColor */}
              {!isMobile && <HardwareSensors data={sensorData} deviceType={device} themeColor={themeData.primary} />}
            </div>
          )}
        </div>
        <div className="flex items-center gap-2 md:gap-4">
           {transcriptions.length > 0 && !isWearable && (
             <button 
               onClick={clearAllTranscriptions} 
               className="w-10 h-10 lg:w-12 lg:h-12 rounded-xl bg-red-500/10 hover:bg-red-500/20 text-red-400 flex items-center justify-center transition-all active:scale-90"
               title="Clear All History"
             >
               <i className="fas fa-trash-sweep text-sm lg:text-lg"></i>
             </button>
           )}
           {!isWearable && <button onClick={() => setIsSettingsOpen(true)} className="w-10 h-10 lg:w-12 lg:h-12 rounded-xl bg-white/5 flex items-center justify-center hover:bg-white/10 transition-all active:scale-90"><i className="fas fa-cog text-sm lg:text-lg"></i></button>}
           {!isWearable && <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-10 h-10 lg:w-12 lg:h-12 rounded-xl flex items-center justify-center transition-all active:scale-90 ${isMemoryOpen ? 'bg-[var(--theme-primary)] text-white shadow-[0_0_30px_rgba(37,99,235,0.4)]' : 'bg-white/5 text-gray-400'}`}><i className="fas fa-brain text-sm lg:text-lg"></i></button>}
           <button onClick={handleLogout} className="w-10 h-10 lg:w-12 lg:h-12 flex items-center justify-center text-gray-600 hover:text-red-500 transition-colors active:scale-90"><i className="fas fa-power-off text-sm lg:text-lg"></i></button>
        </div>
      </header>

      <main className={`flex-1 flex ${isMobile || isWearable ? 'flex-col' : 'flex-row'} min-h-0 p-[var(--ui-gap)] gap-[var(--ui-gap)] overflow-hidden`}>
        <div className="flex-1 flex flex-col gap-[var(--ui-gap)] min-h-0">
          {(isVisionActive || isScreenSharing) && (
            <div className={`h-48 md:h-72 lg:h-[400px] w-full animate-pop flex-shrink-0 relative group`}>
              <div className={`absolute -inset-1 bg-gradient-to-r from-[var(--theme-primary)] to-[var(--theme-secondary)] rounded-[var(--ui-radius)] blur opacity-20 group-hover:opacity-40 transition-opacity`}></div>
              {isVisionActive && <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />}
              {isScreenSharing && screenStream && <ScreenShareMode isActive={isScreenSharing} stream={screenStream} onFrame={(b) => currentFrameRef.current = b} onStop={() => setIsScreenSharing(false)} />}
            </div>
          )}

          <div className="flex-1 flex flex-col glass rounded-[var(--ui-radius)] overflow-hidden relative min-h-0 group shadow-2xl">
            <div className={`absolute inset-0 bg-gradient-to-br from-[var(--theme-primary)]/5 via-transparent to-[var(--theme-secondary)]/5 pointer-events-none opacity-40`}></div>

            <div className={`flex-1 p-4 lg:p-8 space-y-4 lg:space-y-8 overflow-y-auto scrollbar-thin transcription-list`} ref={scrollRef}>
              {transcriptions.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center opacity-20 animate-float-3d">
                  <i className={`fas fa-comment-dots text-6xl lg:text-9xl mb-6 text-gray-600`}></i>
                  {!isWearable && <p className="text-xl lg:text-3xl font-black uppercase tracking-[0.5em] shimmer-text-fast">Chatty Core</p>}
                </div>
              )}

              {/* RENDER GROUPED TRANSCRIPTIONS BY DAY */}
              {Object.entries(groupedTranscriptions).map(([dateStr, items]) => (
                <React.Fragment key={dateStr}>
                  <div className="day-separator animate-fade-blur-in">
                    <div className="day-line"></div>
                    <div className="day-badge">{formatDateHeader(dateStr)}</div>
                    <div className="day-line"></div>
                  </div>

                  {items.map((e) => (
                    <div key={e.id} className={`flex flex-col ${e.sender === 'user' ? 'items-end' : 'items-start'} animate-slide-up-reveal group/item`}>
                      <div className={`
                        max-w-[90%] lg:max-w-[85%] 
                        px-4 py-3 lg:px-7 lg:py-5 
                        rounded-[1.5rem] lg:rounded-[2rem] 
                        shadow-xl transition-all hover:scale-[1.01] relative
                        ${e.sender === 'user' 
                          ? 'bg-gradient-to-br from-[var(--theme-primary)] to-indigo-600 text-white' 
                          : 'bg-white/[0.04] text-gray-200 border border-white/5 backdrop-blur-xl'
                        }
                      `}>
                        {/* Quick Delete Trigger */}
                        <button 
                          onClick={() => deleteTranscription(e.id)}
                          className={`absolute ${e.sender === 'user' ? '-left-8' : '-right-8'} top-1/2 -translate-y-1/2 opacity-0 group-hover/item:opacity-40 hover:!opacity-100 text-red-500 transition-all p-2 active:scale-90`}
                        >
                          <i className="fas fa-trash-alt text-xs lg:text-sm"></i>
                        </button>

                        <p className="text-sm lg:text-lg font-bold leading-relaxed whitespace-pre-wrap">{e.text}</p>
                        {!isWearable && e.sources && <GroundingSources sources={e.sources} themePrimary={themeData.primary} />}
                        <div className={`mt-2 text-[8px] opacity-40 uppercase font-black tracking-widest ${e.sender === 'user' ? 'text-right' : 'text-left'}`}>
                          {new Date(e.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </div>
                      </div>
                    </div>
                  ))}
                </React.Fragment>
              ))}

              {(streamingAssistantText || state === AssistantState.THINKING) && (
                <div className="items-start flex flex-col animate-pop">
                  <div className="max-w-[85%] px-5 py-3 rounded-[1.5rem] bg-white/[0.03] text-white/60 border border-white/5">
                    {streamingAssistantText ? <p className="font-mono text-xs lg:text-sm leading-relaxed">{streamingAssistantText}</p> : <div className="typing-indicator"><span></span><span></span><span></span></div>}
                  </div>
                </div>
              )}
            </div>

            <div className={`p-4 lg:p-8 border-t border-white/5 bg-black/50 backdrop-blur-2xl flex flex-col gap-3 lg:gap-6`}>
              {!isWearable && <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />}
              <div className={`flex ${isWearable ? 'flex-col gap-2' : 'gap-3'} items-center`}>
                  {!isWearable && (
                    <div className="flex gap-2">
                      <button onClick={handleToggleVision} title="Optic Link" className="w-10 h-10 lg:w-14 lg:h-14 rounded-xl glass flex items-center justify-center active:scale-90 transition-all"><i className="fas fa-camera text-sm lg:text-lg"></i></button>
                      <button onClick={handleToggleScreenShare} title="Desktop Uplink" className="w-10 h-10 lg:w-14 lg:h-14 rounded-xl glass flex items-center justify-center active:scale-90 transition-all"><i className="fas fa-desktop text-sm lg:text-lg"></i></button>
                    </div>
                  )}
                  {!isWearable && (
                    <input type="text" value={inputText} onChange={(e) => setInputText(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSendText()} placeholder="Directive..." className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-4 lg:px-6 py-3 lg:py-5 text-sm lg:text-lg focus:outline-none focus:border-[var(--theme-primary)]/50 text-white font-bold transition-all shadow-inner placeholder-gray-700" />
                  )}
                  <button 
                    onClick={inputText.trim() ? handleSendText : (state === AssistantState.IDLE ? () => startSession() : stopSession)} 
                    className={`${isWearable ? 'w-full h-12' : 'flex-1 md:flex-none md:w-48 lg:w-64 h-14 lg:h-20'} rounded-[1.5rem] lg:rounded-[2rem] flex items-center justify-center transition-all gap-2 lg:gap-4 neo-button shadow-2xl ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-600 text-white animate-pulse'}`}
                  >
                    <i className={`fas ${inputText.trim() ? 'fa-paper-plane' : (state === AssistantState.IDLE ? 'fa-microphone' : 'fa-square')} text-sm lg:text-lg`}></i>
                    <span className="font-black uppercase tracking-widest text-[8px] lg:text-[11px]">{inputText.trim() ? 'SEND' : (state === AssistantState.IDLE ? 'INITIALIZE' : 'STOP')}</span>
                  </button>
              </div>
            </div>
          </div>
        </div>

        {isMemoryOpen && !isMobile && !isWearable && (
          <div className="w-full md:w-[350px] lg:w-[420px] flex-shrink-0 h-full animate-slide-in-right-bounce">
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
          </div>
        )}
      </main>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} prefs={prefs} setPrefs={setPrefs} voices={dynamicVoices} personalities={PERSONALITIES} isTV={isTV} isWearable={isWearable} onPreviewVoice={handlePreviewVoice} previewingVoiceId={previewingVoiceId} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality } from '@google/genai';
import { AssistantState, DeviceType, SensorData, UserPreferences, GroundingSource, TranscriptionEntry } from './types';
import * as audioUtils from './services/audioUtils';
import VoiceVisualizer from './components/VoiceVisualizer';
import MemoryBank from './components/MemoryBank';
import LoginPage from './components/LoginPage';
import ObservationMode from './components/ObservationMode';
import ScreenShareMode from './components/ScreenShareMode';
import HardwareSensors from './components/HardwareSensors';
import GroundingSources from './components/GroundingSources';
import SettingsModal from './components/SettingsModal';
import IntroSequence from './components/IntroSequence';

const THEMES = {
  cosmic: { primary: '#3b82f6', secondary: '#8b5cf6', glow: 'rgba(59,130,246,0.5)', bg: '#02020a' },
  emerald: { primary: '#10b981', secondary: '#064e3b', glow: 'rgba(16,185,129,0.5)', bg: '#020a05' },
  ruby: { primary: '#f43f5e', secondary: '#9f1239', glow: 'rgba(244,63,94,0.5)', bg: '#0a0202' },
  obsidian: { primary: '#94a3b8', secondary: '#1e293b', glow: 'rgba(148,163,184,0.5)', bg: '#0a0a0a' }
};

const PERSONALITIES = {
  professional: 'Be highly professional, concise, and logical. Use technical terminology when appropriate.',
  friendly: 'Be warm, supportive, and enthusiastic. Use a casual but respectful tone.',
  witty: 'Be clever, slightly sarcastic, and humorous. Keep the user entertained while being helpful.',
  minimalist: 'Respond with the absolute minimum number of words necessary. No fluff.',
  alluring: 'Be mysterious, suggestive, and highly flirtatious. Push the boundaries of a typical assistant relationship with playful banter and charm while remaining helpful.',
  custom: ''
};

const saveKnowledgeTool = {
  name: 'save_knowledge',
  parameters: {
    type: 'OBJECT',
    description: 'Save a specific fact or preference for long-term memory.',
    properties: {
      fact: { type: 'STRING', description: 'The specific fact (e.g., "The user works as a pilot").' },
    },
    required: ['fact'],
  },
};

const DEFAULT_PREFS: UserPreferences = {
  theme: 'cosmic',
  personality: 'friendly',
  layout: 'right',
  voiceId: 'Charon',
  assistantName: 'Project Chatty',
  customPersonality: 'You are a highly capable AI assistant.',
  modality: 'masculine'
};

// COMPONENT OPTIMIZATION: Memoized Bubble
const TranscriptionBubble = React.memo(({ entry, deleteTranscription, themePrimary }: { entry: TranscriptionEntry, deleteTranscription: (id: string) => void, themePrimary: string }) => {
  return (
    <div className={`flex flex-col ${entry.sender === 'user' ? 'items-end' : 'items-start'} animate-slide-up-reveal group/item`}>
      <div className={`
        max-w-[90%] lg:max-w-[85%] 
        px-4 py-3 lg:px-7 lg:py-5 
        rounded-[1.5rem] lg:rounded-[2rem] 
        shadow-xl transition-all hover:scale-[1.01] relative
        ${entry.sender === 'user' 
          ? 'bg-gradient-to-br from-[var(--theme-primary)] to-indigo-600 text-white' 
          : 'bg-white/[0.04] text-gray-200 border border-white/5 backdrop-blur-xl'
        }
      `}>
        <button 
          onClick={() => deleteTranscription(entry.id)}
          className={`absolute ${entry.sender === 'user' ? '-left-8' : '-right-8'} top-1/2 -translate-y-1/2 opacity-0 group-hover/item:opacity-40 hover:!opacity-100 text-red-500 transition-all p-2 active:scale-90`}
        >
          <i className="fas fa-trash-alt text-xs lg:text-sm"></i>
        </button>
        <p className="text-sm lg:text-lg font-bold leading-relaxed whitespace-pre-wrap">{entry.text}</p>
        {entry.sources && <GroundingSources sources={entry.sources} themePrimary={themePrimary} />}
        <div className={`mt-2 text-[8px] opacity-40 uppercase font-black tracking-widest ${entry.sender === 'user' ? 'text-right' : 'text-left'}`}>
          {new Date(entry.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
        </div>
      </div>
    </div>
  );
});

// COMPONENT OPTIMIZATION: Memoized List
const TranscriptionList = React.memo(({ transcriptions, deleteTranscription, themePrimary }: { transcriptions: TranscriptionEntry[], deleteTranscription: (id: string) => void, themePrimary: string }) => {
  const grouped = useMemo(() => {
    const groups: Record<string, TranscriptionEntry[]> = {};
    transcriptions.forEach(entry => {
      const dateKey = new Date(entry.timestamp).toDateString();
      if (!groups[dateKey]) groups[dateKey] = [];
      groups[dateKey].push(entry);
    });
    return groups;
  }, [transcriptions]);

  const formatDateHeader = (dateStr: string) => {
    const date = new Date(dateStr);
    const today = new Date();
    const yesterday = new Date();
    yesterday.setDate(today.getDate() - 1);
    if (date.toDateString() === today.toDateString()) return "Today";
    if (date.toDateString() === yesterday.toDateString()) return "Yesterday";
    return date.toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
  };

  return (
    <>
      {Object.entries(grouped).map(([dateStr, items]) => (
        <React.Fragment key={dateStr}>
          <div className="day-separator animate-fade-blur-in">
            <div className="day-line"></div>
            <div className="day-badge">{formatDateHeader(dateStr)}</div>
            <div className="day-line"></div>
          </div>
          {items.map((e) => (
            <TranscriptionBubble key={e.id} entry={e} deleteTranscription={deleteTranscription} themePrimary={themePrimary} />
          ))}
        </React.Fragment>
      ))}
    </>
  );
});

const App = () => {
  const [showIntro, setShowIntro] = useState(true);
  const [user, setUser] = useState<{username: string, preferences: UserPreferences} | null>(null);
  const [prefs, setPrefs] = useState<UserPreferences>(DEFAULT_PREFS);
  const [state, setState] = useState<AssistantState>(AssistantState.IDLE);
  const [device, setDevice] = useState<DeviceType>('desktop');
  const [isScanning, setIsScanning] = useState(true);
  const [sensorData, setSensorData] = useState<SensorData>({ online: navigator.onLine, platform: navigator.platform });
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [streamingUserText, setStreamingUserText] = useState('');
  const [streamingAssistantText, setStreamingAssistantText] = useState('');
  const [memories, setMemories] = useState<any[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  const [inputText, setInputText] = useState('');
  const [searchEnabled, setSearchEnabled] = useState(true);
  const [errorToast, setErrorToast] = useState<string | null>(null);
  const [previewingVoiceId, setPreviewingVoiceId] = useState<string | null>(null);

  const audioContextRef = useRef<{input: AudioContext, output: AudioContext} | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef(0);
  const activeSourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const micStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const currentFrameRef = useRef<string | null>(null);
  const scrollRef = useRef<HTMLDivElement | null>(null);
  const saveTimeoutRef = useRef<number | null>(null);

  const themeData = useMemo(() => THEMES[prefs.theme] || THEMES.cosmic, [prefs.theme]);

  useEffect(() => {
    document.documentElement.style.setProperty('--theme-primary', themeData.primary);
    document.documentElement.style.setProperty('--theme-secondary', themeData.secondary);
    document.documentElement.style.setProperty('--bg-base', themeData.bg);
    document.documentElement.style.setProperty('--theme-glow', themeData.glow);
  }, [themeData]);

  const dynamicVoices = useMemo(() => {
    const isFem = prefs.modality === 'feminine';
    return isFem ? [
      { id: 'Zephyr', name: 'Gabby', tone: 'Warm, Smooth, Melodic', gender: 'feminine' },
      { id: 'Kore', name: 'Paula', tone: 'Clear, Professional, Calm', gender: 'feminine' },
      { id: 'Aoede', name: 'Kai', tone: 'Poetic, Soulful, Expressive', gender: 'feminine' },
      { id: 'Leda', name: 'Jessie', tone: 'Bright, Airy, Gentle', gender: 'feminine' }
    ] : [
      { id: 'Charon', name: 'John', tone: 'Deep, Bass, Authoritative', gender: 'masculine' },
      { id: 'Puck', name: 'Caleb', tone: 'Energetic, Bright, Playful', gender: 'masculine' },
      { id: 'Fenrir', name: 'Able', tone: 'Vibrant, Sharp, Focused', gender: 'masculine' },
      { id: 'Jake', name: 'Jake', tone: 'Deep, Resonant, Command', gender: 'masculine' }
    ];
  }, [prefs.modality]);

  useEffect(() => {
    const isValid = dynamicVoices.some(v => v.id === prefs.voiceId);
    if (!isValid && dynamicVoices.length > 0) {
      setPrefs(p => ({ ...p, voiceId: dynamicVoices[0].id }));
    }
  }, [dynamicVoices, prefs.voiceId]);

  const detectHardware = useCallback(async (isMounted: boolean) => {
    try {
      const w = window.innerWidth;
      const h = window.innerHeight;
      const ua = navigator.userAgent.toLowerCase();
      let detectedDevice: DeviceType = 'desktop';
      if (w <= 300 || (ua.includes('watch') && !ua.includes('tv'))) detectedDevice = 'wear';
      else if (ua.includes('android') && w > h && w >= 800 && w <= 1280) detectedDevice = 'auto';
      else if (ua.includes('tv') || ua.includes('smarttv') || (w >= 1920 && h >= 1080)) detectedDevice = 'tv';
      else if (w < 768 || (w < 1024 && h > w)) detectedDevice = 'mobile';

      if (isMounted) {
        setDevice(detectedDevice);
        document.documentElement.setAttribute('data-device', detectedDevice);
      }
      const sensorPayload: SensorData = { online: navigator.onLine, platform: navigator.platform };
      if ('getBattery' in navigator) {
        try {
          const battery = await (navigator as any).getBattery();
          sensorPayload.battery = battery.level;
          sensorPayload.charging = battery.charging;
        } catch (e) {}
      }
      if (navigator.geolocation && ['auto', 'mobile', 'desktop'].includes(detectedDevice)) {
        navigator.geolocation.getCurrentPosition(
          (pos) => isMounted && setSensorData(prev => ({ ...prev, location: { lat: pos.coords.latitude, lng: pos.coords.longitude } })),
          undefined, { enableHighAccuracy: false, timeout: 5000 }
        );
      }
      if (isMounted) {
        setSensorData(prev => ({ ...prev, ...sensorPayload }));
        setTimeout(() => setIsScanning(false), 2000);
      }
    } catch (err) { console.error("Hardware probe failure", err); }
  }, []);

  useEffect(() => {
    let isMounted = true;
    detectHardware(isMounted);
    let resizeTimer: number;
    const handleResize = () => {
      clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(() => detectHardware(isMounted), 250);
    };
    window.addEventListener('resize', handleResize);
    return () => { isMounted = false; window.removeEventListener('resize', handleResize); };
  }, [detectHardware]);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('nova_session_user') || localStorage.getItem('nova_persistent_user');
    if (sessionUser) {
      try {
        const savedPrefs = localStorage.getItem(`nova_${sessionUser}_prefs`);
        setUser({ username: sessionUser, preferences: savedPrefs ? JSON.parse(savedPrefs) : DEFAULT_PREFS });
      } catch (e) { setUser({ username: sessionUser, preferences: DEFAULT_PREFS }); }
    }
  }, []);

  useEffect(() => {
    if (user) {
      setPrefs(user.preferences);
      setMemories(JSON.parse(localStorage.getItem(`nova_${user.username}_memories`) || '[]'));
      setTranscriptions(JSON.parse(localStorage.getItem(`nova_${user.username}_logs`) || '[]'));
      sessionStorage.setItem('nova_session_user', user.username);
    }
  }, [user]);

  // PERSISTENCE OPTIMIZATION: Throttled saving to disk
  useEffect(() => {
    if (user) {
      if (saveTimeoutRef.current) window.clearTimeout(saveTimeoutRef.current);
      saveTimeoutRef.current = window.setTimeout(() => {
        localStorage.setItem(`nova_${user.username}_prefs`, JSON.stringify(prefs));
        localStorage.setItem(`nova_${user.username}_memories`, JSON.stringify(memories));
        localStorage.setItem(`nova_${user.username}_logs`, JSON.stringify(transcriptions));
      }, 1000);
    }
  }, [prefs, memories, transcriptions, user]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [transcriptions, streamingUserText, streamingAssistantText]);

  const isWearable = device === 'wear';
  const isAuto = device === 'auto';
  const isTV = device === 'tv';
  const isMobile = device === 'mobile';

  const addTranscription = useCallback((sender: 'user' | 'assistant', text: string, sources?: GroundingSource[]) => {
    if (!text?.trim()) return;
    setTranscriptions(prev => [
      ...prev, { id: Math.random().toString(36).substr(2, 9), sender, text, timestamp: new Date(), sources }
    ]);
  }, []);

  const deleteTranscription = useCallback((id: string) => {
    setTranscriptions(prev => prev.filter(t => t.id !== id));
  }, []);

  const clearAllTranscriptions = () => {
    if (window.confirm("Purge all chat records from this segment?")) setTranscriptions([]);
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
  }, [screenStream]);

  const handleLogout = useCallback(() => {
    stopSession();
    setUser(null);
    sessionStorage.removeItem('nova_session_user');
    localStorage.removeItem('nova_persistent_user');
  }, [stopSession]);

  const handleLogin = (username: string, initialPrefs: any) => {
    setUser({ username, preferences: { ...DEFAULT_PREFS, ...initialPrefs } });
  };

  const handlePreviewVoice = async (voiceId: string) => {
    if (previewingVoiceId) return;
    try {
      setPreviewingVoiceId(voiceId);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing.");
      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)(),
          output: new (window.AudioContext || (window as any).webkitAudioContext)()
        };
      }
      const outputCtx = audioContextRef.current.output;
      if (outputCtx.state === 'suspended') await outputCtx.resume();
      const ai = new GoogleGenAI({ apiKey });
      const voice = dynamicVoices.find(v => v.id === voiceId);
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Hello, I am ${voice?.name}. Profile link active.` }] }],
        config: { responseModalities: [Modality.AUDIO], speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voiceId } } } },
      });
      const audioPart = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
      if (audioPart?.inlineData?.data) {
        const audioBuffer = await audioUtils.decodeAudioData(audioUtils.decode(audioPart.inlineData.data), outputCtx, 24000, 1);
        const source = outputCtx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(outputCtx.destination);
        source.onended = () => setPreviewingVoiceId(null);
        source.start(0);
      } else setPreviewingVoiceId(null);
    } catch (err) { setPreviewingVoiceId(null); }
  };

  const startSession = async (initialText?: string) => {
    try {
      setState(AssistantState.CONNECTING);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Authentication failure.");
      if (!audioContextRef.current) {
        audioContextRef.current = {
          input: new (window.AudioContext || (window as any).webkitAudioContext)(),
          output: new (window.AudioContext || (window as any).webkitAudioContext)()
        };
      }
      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();
      audioUtils.playLinkSound(outputCtx);
      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: { echoCancellation: true, noiseSuppression: true, sampleRate: 16000, channelCount: 1 } 
      });
      micStreamRef.current = stream;
      const source = inputCtx.createMediaStreamSource(stream);
      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;
      source.connect(analyser);
      const ai = new GoogleGenAI({ apiKey });
      const personalityPrompt = prefs.personality === 'custom' ? (prefs.customPersonality || 'Be helpful.') : PERSONALITIES[prefs.personality];
      const tools: any[] = [];
      if (sensorData.location) tools.push({ googleMaps: {} });
      if (searchEnabled) tools.push({ googleSearch: {} });
      if (!searchEnabled && !sensorData.location) tools.push({ functionDeclarations: [saveKnowledgeTool] });
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools,
          toolConfig: sensorData.location ? { retrievalConfig: { latLng: { latitude: sensorData.location.lat, longitude: sensorData.location.lng } } } : undefined,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. Personality: ${personalityPrompt}.`,
          inputAudioTranscription: {}, outputAudioTranscription: {}, thinkingConfig: { thinkingBudget: 24576 }
        } as any,
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const l = inputData.length;
              const int16 = new Int16Array(l);
              for (let i = 0; i < l; i++) int16[i] = inputData[i] * 32768;
              const pcmBlob = { data: audioUtils.encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
              if (currentFrameRef.current) {
                const frame = currentFrameRef.current;
                currentFrameRef.current = null;
                sessionPromise.then(s => s.sendRealtimeInput({ media: { data: frame, mimeType: 'image/jpeg' } }));
              }
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
            if (initialText) sessionPromise.then(s => s.sendRealtimeInput({ text: initialText }));
          },
          onmessage: async (message: any) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact: fc.args.fact, timestamp: new Date() }]);
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Saved." } } }));
                }
              }
            }
            const turnParts = message.serverContent?.modelTurn?.parts || [];
            for (const part of turnParts) {
              if (part.inlineData?.data) {
                setState(AssistantState.SPEAKING);
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
                const buffer = await audioUtils.decodeAudioData(audioUtils.decode(part.inlineData.data), outputCtx, 24000, 1);
                const s = outputCtx.createBufferSource(); 
                s.buffer = buffer; s.connect(outputCtx.destination);
                s.onended = () => { activeSourcesRef.current.delete(s); if (activeSourcesRef.current.size === 0) setState(AssistantState.LISTENING); };
                s.start(nextStartTimeRef.current); 
                nextStartTimeRef.current += buffer.duration; 
                activeSourcesRef.current.add(s);
              }
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent.inputTranscription.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent.outputTranscription.text);
            if (message.serverContent?.turnComplete) {
              const chunks = message.serverContent?.groundingMetadata?.groundingChunks || [];
              const sources = chunks.map((c: any) => (c.web ? { title: c.web.title, uri: c.web.uri } : (c.maps ? { title: c.maps.title, uri: c.maps.uri } : null))).filter(Boolean);
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) { addTranscription('assistant', a, sources); audioUtils.playSuccessSound(outputCtx); } return ''; });
            }
          },
          onerror: () => stopSession(), onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setErrorToast(err.message); setState(AssistantState.IDLE); setTimeout(() => setErrorToast(null), 5000); }
  };

  const handleToggleScreenShare = async () => {
    if (isScreenSharing) {
      setIsScreenSharing(false);
      if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    } else {
      try {
        const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
        setScreenStream(stream); setIsVisionActive(false); setIsScreenSharing(true);
        if (state === AssistantState.IDLE) startSession();
        stream.getVideoTracks()[0].onended = () => { setIsScreenSharing(false); setScreenStream(null); };
      } catch (err: any) { setErrorToast(err.message); }
    }
  };

  const handleToggleVision = async () => {
    if (isVisionActive) setIsVisionActive(false);
    else {
      try { await navigator.mediaDevices.getUserMedia({ video: true }); setIsScreenSharing(false); setIsVisionActive(true); if (state === AssistantState.IDLE) startSession(); }
      catch (err) { setErrorToast("Optic access denied."); }
    }
  };

  const handleSendText = () => {
    if (!inputText.trim()) return;
    const msg = inputText.trim();
    setInputText('');
    addTranscription('user', msg);
    if (sessionRef.current) { setState(AssistantState.THINKING); sessionRef.current.sendRealtimeInput({ text: msg }); } else startSession(msg);
  };

  if (showIntro) return <IntroSequence onComplete={() => setShowIntro(false)} />;
  if (!user) return <LoginPage onLogin={handleLogin} />;
  if (isScanning) {
    return (
      <div className="fixed inset-0 bg-[#02020a] flex flex-col items-center justify-center z-[200] animate-fade-blur-in overflow-hidden">
        <div className="absolute inset-0 animate-scan-v bg-gradient-to-b from-transparent via-[var(--theme-primary)]/20 to-transparent pointer-events-none opacity-40"></div>
        <div className="relative w-[30vw] h-[30vw] max-w-64 max-h-64 flex items-center justify-center animate-float-3d">
          <div className="absolute inset-0 border-4 border-t-[var(--theme-primary)] border-r-transparent border-b-transparent border-l-transparent rounded-full animate-spin"></div>
          <div className="absolute inset-4 border-2 border-b-[var(--theme-secondary)] border-t-transparent border-r-transparent border-l-transparent rounded-full animate-spin [animation-duration:3s]"></div>
          <i className="fas fa-atom text-6xl text-white animate-pulse"></i>
        </div>
        <h2 className="mt-12 text-2xl font-black tracking-[0.5em] uppercase text-white mb-2 text-center">Chatty Sync Active</h2>
        <p className="text-[11px] text-[var(--theme-primary)] font-black uppercase tracking-[0.3em] animate-pulse">Linking Bio-Core...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full w-full transition-all duration-1000 overflow-hidden">
      {errorToast && (
        <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[300] bg-red-600/90 backdrop-blur-xl text-white px-8 py-5 rounded-[2rem] font-black uppercase tracking-widest text-[10px] shadow-[0_20px_60px_rgba(220,38,38,0.4)] animate-pop flex items-center gap-4">
          <i className="fas fa-exclamation-triangle"></i>
          {errorToast}
          <button onClick={() => setErrorToast(null)} className="ml-4 opacity-50 hover:opacity-100"><i className="fas fa-times"></i></button>
        </div>
      )}

      <header className="m-[var(--ui-gap)] p-4 lg:p-6 rounded-[var(--ui-radius)] flex items-center justify-between z-50 glass animate-fade-blur-in">
        <div className="flex items-center gap-3 lg:gap-6 group">
          <div className="w-10 h-10 lg:w-14 lg:h-14 rounded-[1.5rem] overflow-hidden border border-white/10 relative transition-all duration-700 group-hover:scale-110 shadow-xl">
            {prefs.assistantProfilePic ? <img src={prefs.assistantProfilePic} className="w-full h-full object-cover" alt="AI" /> : <div className="w-full h-full bg-[var(--theme-primary)]/10 flex items-center justify-center"><i className="fas fa-atom text-white text-lg lg:text-xl"></i></div>}
          </div>
          {!isWearable && (
            <div className="animate-slide-in-right-bounce">
              <h1 className="text-sm lg:text-2xl font-black tracking-tighter text-white uppercase truncate max-w-[120px] lg:max-w-none">{prefs.assistantName}</h1>
              {!isMobile && <HardwareSensors data={sensorData} deviceType={device} themeColor={themeData.primary} />}
            </div>
          )}
        </div>
        <div className="flex items-center gap-2 md:gap-4">
           {transcriptions.length > 0 && !isWearable && (
             <button onClick={clearAllTranscriptions} className="w-10 h-10 lg:w-12 lg:h-12 rounded-xl bg-red-500/10 hover:bg-red-500/20 text-red-400 flex items-center justify-center transition-all active:scale-90" title="Clear All History">
               <i className="fas fa-trash-sweep text-sm lg:text-lg"></i>
             </button>
           )}
           {!isWearable && <button onClick={() => setIsSettingsOpen(true)} className="w-10 h-10 lg:w-12 lg:h-12 rounded-xl bg-white/5 flex items-center justify-center hover:bg-white/10 transition-all active:scale-90"><i className="fas fa-cog text-sm lg:text-lg"></i></button>}
           {!isWearable && <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-10 h-10 lg:w-12 lg:h-12 rounded-xl flex items-center justify-center transition-all active:scale-90 ${isMemoryOpen ? 'bg-[var(--theme-primary)] text-white' : 'bg-white/5 text-gray-400'}`}><i className="fas fa-brain text-sm lg:text-lg"></i></button>}
           <button onClick={handleLogout} className="w-10 h-10 lg:w-12 lg:h-12 flex items-center justify-center text-gray-600 hover:text-red-500 transition-colors active:scale-90"><i className="fas fa-power-off text-sm lg:text-lg"></i></button>
        </div>
      </header>

      <main className={`flex-1 flex ${isMobile || isWearable ? 'flex-col' : 'flex-row'} min-h-0 p-[var(--ui-gap)] gap-[var(--ui-gap)] overflow-hidden`}>
        <div className="flex-1 flex flex-col gap-[var(--ui-gap)] min-h-0">
          {(isVisionActive || isScreenSharing) && (
            <div className="h-48 md:h-72 lg:h-[400px] w-full animate-pop flex-shrink-0 relative group">
              {isVisionActive && <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />}
              {isScreenSharing && screenStream && <ScreenShareMode isActive={isScreenSharing} stream={screenStream} onFrame={(b) => currentFrameRef.current = b} onStop={() => setIsScreenSharing(false)} />}
            </div>
          )}

          <div className="flex-1 flex flex-col glass rounded-[var(--ui-radius)] overflow-hidden relative min-h-0 group shadow-2xl">
            <div className={`flex-1 p-4 lg:p-8 space-y-4 lg:space-y-8 overflow-y-auto scrollbar-thin transcription-list`} ref={scrollRef}>
              {transcriptions.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center opacity-20 animate-float-3d">
                  <i className="fas fa-comment-dots text-6xl lg:text-9xl mb-6 text-gray-600"></i>
                  {!isWearable && <p className="text-xl lg:text-3xl font-black uppercase tracking-[0.5em] shimmer-text-fast">Chatty Core</p>}
                </div>
              )}

              {/* PERFORMANCE FIX: Use the optimized, memoized list component */}
              <TranscriptionList transcriptions={transcriptions} deleteTranscription={deleteTranscription} themePrimary={themeData.primary} />

              {/* PERFORMANCE FIX: Isolated streaming components to prevent full list re-renders */}
              {(streamingAssistantText || state === AssistantState.THINKING) && (
                <div className="items-start flex flex-col animate-pop">
                  <div className="max-w-[85%] px-5 py-3 rounded-[1.5rem] bg-white/[0.03] text-white/60 border border-white/5">
                    {streamingAssistantText ? <p className="font-mono text-xs lg:text-sm leading-relaxed">{streamingAssistantText}</p> : <div className="typing-indicator"><span></span><span></span><span></span></div>}
                  </div>
                </div>
              )}
              {streamingUserText && (
                <div className="items-end flex flex-col animate-pop">
                  <div className="max-w-[85%] px-5 py-3 rounded-[1.5rem] bg-gradient-to-br from-[var(--theme-primary)] to-indigo-600 text-white/80">
                    <p className="font-mono text-xs lg:text-sm">{streamingUserText}</p>
                  </div>
                </div>
              )}
            </div>

            <div className="p-4 lg:p-8 border-t border-white/5 bg-black/50 backdrop-blur-2xl flex flex-col gap-3 lg:gap-6">
              {!isWearable && <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />}
              <div className={`flex ${isWearable ? 'flex-col gap-2' : 'gap-3'} items-center`}>
                  {!isWearable && (
                    <div className="flex gap-2">
                      <button onClick={handleToggleVision} title="Optic Link" className="w-10 h-10 lg:w-14 lg:h-14 rounded-xl glass flex items-center justify-center active:scale-90"><i className="fas fa-camera text-sm lg:text-lg"></i></button>
                      <button onClick={handleToggleScreenShare} title="Desktop Uplink" className="w-10 h-10 lg:w-14 lg:h-14 rounded-xl glass flex items-center justify-center active:scale-90"><i className="fas fa-desktop text-sm lg:text-lg"></i></button>
                    </div>
                  )}
                  {!isWearable && (
                    <input type="text" value={inputText} onChange={(e) => setInputText(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSendText()} placeholder="Directive..." className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-4 lg:px-6 py-3 lg:py-5 text-sm lg:text-lg focus:outline-none focus:border-[var(--theme-primary)]/50 text-white font-bold placeholder-gray-700" />
                  )}
                  <button onClick={inputText.trim() ? handleSendText : (state === AssistantState.IDLE ? () => startSession() : stopSession)} className={`${isWearable ? 'w-full h-12' : 'flex-1 md:flex-none md:w-48 lg:w-64 h-14 lg:h-20'} rounded-[1.5rem] lg:rounded-[2rem] flex items-center justify-center transition-all gap-2 lg:gap-4 neo-button shadow-2xl ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-600 text-white animate-pulse'}`}>
                    <i className={`fas ${inputText.trim() ? 'fa-paper-plane' : (state === AssistantState.IDLE ? 'fa-microphone' : 'fa-square')} text-sm lg:text-lg`}></i>
                    <span className="font-black uppercase tracking-widest text-[8px] lg:text-[11px]">{inputText.trim() ? 'SEND' : (state === AssistantState.IDLE ? 'INITIALIZE' : 'STOP')}</span>
                  </button>
              </div>
            </div>
          </div>
        </div>

        {isMemoryOpen && !isMobile && !isWearable && (
          <div className="w-full md:w-[350px] lg:w-[420px] flex-shrink-0 h-full animate-slide-in-right-bounce">
            <MemoryBank memories={memories} onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} assistantName={prefs.assistantName} />
          </div>
        )}
      </main>
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} prefs={prefs} setPrefs={setPrefs} voices={dynamicVoices} personalities={PERSONALITIES} isTV={isTV} isWearable={isWearable} onPreviewVoice={handlePreviewVoice} previewingVoiceId={previewingVoiceId} />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';

const LoginPage = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [age, setAge] = useState('');
  const [genderPref, setGenderPref] = useState('masculine');
  const [mode, setMode] = useState('VAULT');
  const [selectedProfile, setSelectedProfile] = useState(null);
  const [error, setError] = useState(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [rememberMe, setRememberMe] = useState(true);
  const [identities, setIdentities] = useState([]);

  const getStoredUsers = () => {
    try {
      const stored = localStorage.getItem('nova_credentials');
      return stored ? JSON.parse(stored) : {};
    } catch (e) {
      return {};
    }
  };

  const getUserPrefs = (uname) => {
    try {
      const saved = localStorage.getItem(`nova_${uname}_prefs`);
      return saved ? JSON.parse(saved) : null;
    } catch (e) {
      return null;
    }
  };

  useEffect(() => {
    const storedIdentities = JSON.parse(localStorage.getItem('nova_identities') || '[]');
    setIdentities(storedIdentities);
    if (storedIdentities.length === 0) {
      setMode('SIGN_UP');
    }
  }, []);

  const handleProfileSelect = (name) => {
    setSelectedProfile(name);
    const prefs = getUserPrefs(name);
    if (prefs && prefs.modality) {
      setGenderPref(prefs.modality);
    }
    setMode('VERIFY');
    setError(null);
    setShowPassword(false);
  };

  const handleDeleteIdentity = (e, nameToDelete) => {
    e.stopPropagation(); // Prevent card selection
    if (window.confirm(`TERMINATE IDENTITY: ${nameToDelete}?\n\nThis will permanently purge all encrypted logs, memories, and access credentials. This action is irreversible.`)) {
      // 1. Remove from credentials
      const users = getStoredUsers();
      delete users[nameToDelete];
      localStorage.setItem('nova_credentials', JSON.stringify(users));

      // 2. Remove from identities list
      const updatedIdentities = identities.filter(id => id !== nameToDelete);
      localStorage.setItem('nova_identities', JSON.stringify(updatedIdentities));
      setIdentities(updatedIdentities);

      // 3. Purge data buckets
      localStorage.removeItem(`nova_${nameToDelete}_prefs`);
      localStorage.removeItem(`nova_${nameToDelete}_memories`);
      localStorage.removeItem(`nova_${nameToDelete}_logs`);

      // 4. Handle persistence
      if (localStorage.getItem('nova_persistent_user') === nameToDelete) {
        localStorage.removeItem('nova_persistent_user');
      }

      // If no identities left, go to sign up
      if (updatedIdentities.length === 0) {
        setMode('SIGN_UP');
      }
    }
  };

  const handleSignUpStart = (e) => {
    e.preventDefault();
    setError(null);
    const users = getStoredUsers();
    if (users[username]) {
      setError("Username already registered.");
      return;
    }
    setMode('SAFETY_GATE');
  };

  const handleAgeCheck = (e) => {
    e.preventDefault();
    if (age === '' || parseInt(age) < 13) {
      setError("Safety Protocol: 13+ only.");
      return;
    }
    setError(null);
    setMode('VOICE_SELECT');
  };

  const finalizeSignUp = () => {
    setIsSyncing(true);
    const users = getStoredUsers();
    setTimeout(() => {
      const updatedUsers = { ...users, [username]: password };
      localStorage.setItem('nova_credentials', JSON.stringify(updatedUsers));
      const updatedIdentities = [...new Set([username, ...identities])];
      localStorage.setItem('nova_identities', JSON.stringify(updatedIdentities));

      const defaultVoiceId = genderPref === 'masculine' ? 'Charon' : 'Zephyr';

      if (rememberMe) {
        localStorage.setItem('nova_persistent_user', username);
      } else {
        localStorage.removeItem('nova_persistent_user');
      }

      onLogin(username, { voiceId: defaultVoiceId, modality: genderPref });
    }, 1500);
  };

  const handleVerify = (e) => {
    e.preventDefault();
    setError(null);
    const users = getStoredUsers();
    if (selectedProfile && users[selectedProfile] === password) {
      setIsSyncing(true);

      const existingPrefs = getUserPrefs(selectedProfile) || {};
      const updatedPrefs = { 
        ...existingPrefs, 
        modality: genderPref,
        voiceId: (genderPref === 'feminine' && existingPrefs.modality === 'masculine') ? 'Zephyr' :
                 (genderPref === 'masculine' && existingPrefs.modality === 'feminine') ? 'Charon' :
                 existingPrefs.voiceId || (genderPref === 'masculine' ? 'Charon' : 'Zephyr')
      };
      localStorage.setItem(`nova_${selectedProfile}_prefs`, JSON.stringify(updatedPrefs));

      if (rememberMe) {
        localStorage.setItem('nova_persistent_user', selectedProfile);
      } else {
        localStorage.removeItem('nova_persistent_user');
      }

      setTimeout(() => onLogin(selectedProfile, updatedPrefs), 1200);
    } else {
      setError("Passcode mismatch.");
    }
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center p-4 lg:p-10 bg-[#02020a] relative overflow-hidden font-sans">
      <div className="w-full max-w-5xl z-10">
        {mode === 'VAULT' ? (
          <div className="space-y-8 lg:space-y-12 animate-fade-in text-center">
            <header className="space-y-4">
              <h1 className="text-4xl lg:text-7xl font-black tracking-tighter text-white">Chatty <span className="shimmer-text-fast">Link</span></h1>
              <p className="text-gray-500 uppercase tracking-widest text-[8px] lg:text-[10px] font-bold">Select biological segment</p>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 lg:gap-8">
              {identities.map((name) => (
                <div key={name} className="relative group">
                  <button
                    onClick={() => handleProfileSelect(name)}
                    className="w-full group relative glass rounded-[2rem] lg:rounded-[3rem] p-6 lg:p-10 transition-all hover:scale-[1.02] text-left overflow-hidden"
                  >
                    <div className="w-12 h-12 lg:w-16 lg:h-16 rounded-2xl lg:rounded-[2rem] bg-blue-600 flex items-center justify-center text-xl lg:text-2xl font-black text-white">{(name || 'U')[0].toUpperCase()}</div>
                    <div className="mt-6 lg:mt-10">
                      <p className="text-xl lg:text-2xl font-black text-white truncate">{name}</p>
                      <p className="text-[8px] lg:text-[10px] text-blue-400 font-black uppercase tracking-widest mt-1">Encrypted</p>
                    </div>
                  </button>
                  <button 
                    onClick={(e) => handleDeleteIdentity(e, name)}
                    className="absolute top-4 right-4 lg:top-8 lg:right-8 w-8 h-8 lg:w-10 lg:h-10 rounded-full bg-red-500/10 border border-red-500/20 text-red-500/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all hover:bg-red-500 hover:text-white shadow-lg hover:shadow-red-500/20 active:scale-90"
                    title="Terminate Identity"
                  >
                    <i className="fas fa-trash-alt text-[10px] lg:text-xs"></i>
                  </button>
                </div>
              ))}
              <button
                onClick={() => setMode('SIGN_UP')}
                className="flex flex-col items-center justify-center gap-4 glass border-dashed border-white/10 rounded-[2rem] lg:rounded-[3rem] p-6 lg:p-10 opacity-60 hover:opacity-100 transition-all"
              >
                <div className="w-10 h-10 lg:w-14 lg:h-14 rounded-full border-2 border-dashed border-white/20 flex items-center justify-center"><i className="fas fa-plus text-sm text-white"></i></div>
                <p className="font-black text-gray-500 uppercase tracking-widest text-[8px] lg:text-[10px]">New Identity</p>
              </button>
            </div>
          </div>
        ) : (
          <div className="max-w-md mx-auto animate-pop">
            <div className="glass rounded-[2rem] lg:rounded-[4rem] p-8 lg:p-12 shadow-2xl relative overflow-hidden">
              <div className="absolute top-0 left-0 w-full h-[2px] bg-cyan-400/30 animate-biometric"></div>

              <div className="relative z-10 space-y-6 lg:space-y-8">
                {error && (
                  <div className="p-3 bg-red-500/20 border border-red-500/50 rounded-xl text-red-400 text-[10px] font-bold uppercase tracking-wider text-center animate-shake">
                    {error}
                  </div>
                )}

                {mode === 'SIGN_UP' && (
                  <form onSubmit={handleSignUpStart} className="space-y-6 lg:space-y-8">
                    <div className="text-center">
                      <h2 className="text-2xl lg:text-3xl font-black text-white">Initialize</h2>
                    </div>
                    <div className="space-y-3 lg:space-y-4">
                      <input type="text" required placeholder="Username" className="w-full bg-white/5 border border-white/10 rounded-xl lg:rounded-2xl py-3 lg:py-5 px-6 lg:px-8 text-white font-bold outline-none focus:border-blue-500/50 transition-colors" value={username} onChange={(e) => setUsername(e.target.value)} />

                      <div className="relative group">
                        <input 
                          type={showPassword ? "text" : "password"} 
                          required 
                          placeholder="Passcode" 
                          className="w-full bg-white/5 border border-white/10 rounded-xl lg:rounded-2xl py-3 lg:py-5 px-6 lg:px-8 text-white font-bold outline-none focus:border-blue-500/50 transition-colors" 
                          value={password} 
                          onChange={(e) => setPassword(e.target.value)} 
                        />
                        <button 
                          type="button"
                          onClick={() => setShowPassword(!showPassword)}
                          className="absolute right-4 lg:right-6 top-1/2 -translate-y-1/2 text-gray-500 hover:text-white transition-colors"
                        >
                          <i className={`fas ${showPassword ? 'fa-eye-slash' : 'fa-eye'}`}></i>
                        </button>
                      </div>

                      <div className="flex items-center gap-3 px-2 pt-2">
                        <label className="flex items-center cursor-pointer group">
                          <div className="relative">
                            <input type="checkbox" className="sr-only" checked={rememberMe} onChange={() => setRememberMe(!rememberMe)} />
                            <div className={`w-10 h-5 rounded-full transition-colors ${rememberMe ? 'bg-blue-600' : 'bg-white/10'}`}></div>
                            <div className={`absolute left-1 top-1 w-3 h-3 bg-white rounded-full transition-transform ${rememberMe ? 'translate-x-5' : ''}`}></div>
                          </div>
                          <span className="ml-3 text-[9px] font-black uppercase tracking-widest text-gray-500 group-hover:text-gray-300 transition-colors">Persistent Link</span>
                        </label>
                      </div>
                    </div>
                    <button type="submit" className="w-full bg-white text-black font-black py-4 lg:py-5 rounded-xl lg:rounded-2xl uppercase tracking-widest text-[10px] lg:text-xs neo-button">Register</button>
                  </form>
                )}

                {mode === 'SAFETY_GATE' && (
                   <form onSubmit={handleAgeCheck} className="space-y-6 lg:space-y-8">
                      <div className="text-center">
                        <h2 className="text-2xl lg:text-3xl font-black text-white">Verification</h2>
                      </div>
                      <div className="space-y-3 lg:space-y-4">
                        <input type="number" required placeholder="Age" className="w-full bg-white/5 border border-white/10 rounded-xl lg:rounded-2xl py-3 lg:py-5 px-6 lg:px-8 text-white font-bold outline-none focus:border-blue-500/50 transition-colors" value={age} onChange={(e) => setAge(e.target.value)} />
                      </div>
                      <button type="submit" className="w-full bg-white text-black font-black py-4 lg:py-5 rounded-xl lg:rounded-2xl uppercase tracking-widest text-[10px] lg:text-xs neo-button">Validate</button>
                   </form>
                )}

                {mode === 'VOICE_SELECT' && (
                  <div className="space-y-6 lg:space-y-10">
                    <h2 className="text-2xl lg:text-3xl font-black text-center text-white">Modality</h2>
                    <div className="grid grid-cols-2 gap-3 lg:gap-4">
                      <button onClick={() => setGenderPref('masculine')} className={`p-6 lg:p-10 rounded-3xl border-2 transition-all flex flex-col items-center justify-center ${genderPref === 'masculine' ? 'bg-blue-500/10 border-blue-500' : 'bg-white/5 border-white/10'}`}>
                        <i className="fas fa-mars text-2xl lg:text-4xl text-blue-400"></i>
                        <p className="mt-2 text-[8px] font-bold uppercase tracking-widest text-white">Masculine</p>
                      </button>
                      <button onClick={() => setGenderPref('feminine')} className={`p-6 lg:p-10 rounded-3xl border-2 transition-all flex flex-col items-center justify-center ${genderPref === 'feminine' ? 'bg-emerald-500/10 border-emerald-500' : 'bg-white/5 border-white/10'}`}>
                        <i className="fas fa-venus text-2xl lg:text-4xl text-emerald-400"></i>
                        <p className="mt-2 text-[8px] font-bold uppercase tracking-widest text-white">Feminine</p>
                      </button>
                    </div>
                    <button onClick={finalizeSignUp} disabled={isSyncing} className="w-full bg-white text-black font-black py-4 lg:py-5 rounded-xl lg:rounded-2xl uppercase tracking-widest text-[10px] lg:text-xs">Finalize Link</button>
                  </div>
                )}

                {mode === 'VERIFY' && (
                  <form onSubmit={handleVerify} className="space-y-6 lg:space-y-8">
                    <div className="text-center">
                      <h2 className="text-2xl lg:text-3xl font-black text-white">Authorize</h2>
                      <p className="text-[10px] text-blue-400 font-bold uppercase tracking-[0.2em] mt-1">{selectedProfile}</p>
                    </div>

                    <div className="space-y-6">
                      <div className="space-y-2">
                        <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest block ml-2">Preferred Modality</label>
                        <div className="grid grid-cols-2 gap-2">
                          <button 
                            type="button"
                            onClick={() => setGenderPref('masculine')} 
                            className={`py-3 rounded-xl border transition-all flex items-center justify-center gap-2 ${genderPref === 'masculine' ? 'bg-blue-500/10 border-blue-500 text-blue-400' : 'bg-white/5 border-white/5 text-gray-600'}`}
                          >
                            <i className="fas fa-mars text-xs"></i>
                            <span className="text-[9px] font-black uppercase">MASC</span>
                          </button>
                          <button 
                            type="button"
                            onClick={() => setGenderPref('feminine')} 
                            className={`py-3 rounded-xl border transition-all flex items-center justify-center gap-2 ${genderPref === 'feminine' ? 'bg-emerald-500/10 border-emerald-500 text-emerald-400' : 'bg-white/5 border-white/5 text-gray-600'}`}
                          >
                            <i className="fas fa-venus text-xs"></i>
                            <span className="text-[9px] font-black uppercase">FEMI</span>
                          </button>
                        </div>
                      </div>

                      <div className="space-y-2">
                         <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest block ml-2">Passcode</label>
                         <div className="relative">
                            <input 
                              type={showPassword ? "text" : "password"} 
                              required 
                              autoFocus 
                              placeholder="••••••" 
                              className={`w-full bg-white/5 border border-white/10 rounded-xl lg:rounded-2xl py-4 lg:py-5 px-6 lg:px-8 text-white font-bold text-center transition-all focus:border-blue-500/50 outline-none ${showPassword ? 'tracking-normal' : 'tracking-[0.5em]'}`} 
                              value={password} 
                              onChange={(e) => setPassword(e.target.value)} 
                            />
                            <button 
                              type="button"
                              onClick={() => setShowPassword(!showPassword)}
                              className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-500 hover:text-white transition-colors p-2"
                            >
                              <i className={`fas ${showPassword ? 'fa-eye-slash' : 'fa-eye'}`}></i>
                            </button>
                         </div>
                      </div>

                      <div className="flex items-center gap-3 px-2">
                        <label className="flex items-center cursor-pointer group">
                          <div className="relative">
                            <input type="checkbox" className="sr-only" checked={rememberMe} onChange={() => setRememberMe(!rememberMe)} />
                            <div className={`w-10 h-5 rounded-full transition-colors ${rememberMe ? 'bg-blue-600' : 'bg-white/10'}`}></div>
                            <div className={`absolute left-1 top-1 w-3 h-3 bg-white rounded-full transition-transform ${rememberMe ? 'translate-x-5' : ''}`}></div>
                          </div>
                          <span className="ml-3 text-[9px] font-black uppercase tracking-widest text-gray-500 group-hover:text-gray-300 transition-colors">Persistent Link</span>
                        </label>
                      </div>
                    </div>

                    <button type="submit" disabled={isSyncing} className="w-full bg-white text-black font-black py-4 lg:py-5 rounded-xl lg:rounded-2xl uppercase tracking-widest text-[10px] lg:text-xs">
                      {isSyncing ? <i className="fas fa-circle-notch fa-spin"></i> : 'Uplink'}
                    </button>
                  </form>
                )}

                <button onClick={() => { setMode('VAULT'); setPassword(''); setShowPassword(false); }} className="w-full text-[8px] lg:text-[10px] text-gray-600 hover:text-white uppercase tracking-widest transition-colors py-2 flex items-center justify-center gap-2">
                  <i className="fas fa-chevron-left text-[6px]"></i> Return to Vault
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

