import React, { useRef, useEffect, useState } from 'react';

interface ScreenShareModeProps {
  isActive: boolean;
  stream: MediaStream;
  onFrame: (base64: string) => void;
  onStop: () => void;
}

const ScreenShareMode: React.FC<ScreenShareModeProps> = ({ isActive, stream, onFrame, onStop }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [bitrate, setBitrate] = useState('1.2');

  useEffect(() => {
    if (!isActive || !stream) return;
    if (videoRef.current) videoRef.current.srcObject = stream;

    const interval = window.setInterval(() => {
      if (videoRef.current && canvasRef.current) {
        const video = videoRef.current;
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        if (ctx && video.videoWidth > 0 && video.readyState >= 2) {
          canvas.width = video.videoWidth;
          canvas.height = video.videoHeight;
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          const base64 = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
          onFrame(base64);
        }
      }
    }, 1000);

    const bitInterval = window.setInterval(() => {
      setBitrate((Math.random() * (2.4 - 0.8) + 0.8).toFixed(1));
    }, 1500);

    return () => {
      clearInterval(interval);
      clearInterval(bitInterval);
    };
  }, [isActive, stream, onFrame]);

  if (!isActive) return null;

  return (
    <div className="relative h-full w-full rounded-[var(--ui-radius)] overflow-hidden border border-cyan-500/30 shadow-[0_0_50px_rgba(6,182,212,0.15)] bg-black animate-fade-in group">
      {/* Video Feed */}
      <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-contain bg-zinc-950" />

      <canvas ref={canvasRef} className="hidden" />

      {/* HUD Elements */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute inset-0 border-[30px] border-white/5 opacity-40"></div>
        <div className="absolute inset-0 border border-cyan-500/10"></div>

        {/* Animated Corner Brackets */}
        <div className="absolute top-8 left-8 w-10 h-10 border-t border-l border-cyan-500/50"></div>
        <div className="absolute top-8 right-8 w-10 h-10 border-t border-r border-cyan-500/50"></div>
        <div className="absolute bottom-8 left-8 w-10 h-10 border-b border-l border-cyan-500/50"></div>
        <div className="absolute bottom-8 right-8 w-10 h-10 border-b border-r border-cyan-500/50"></div>
      </div>

      {/* Indicators */}
      <div className="absolute top-6 left-6 flex flex-col gap-2">
        <div className="bg-cyan-600 px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-[0.2em] flex items-center gap-3 shadow-lg shadow-cyan-600/20 backdrop-blur-md border border-cyan-400/30">
          <div className="w-2 h-2 rounded-full bg-white animate-pulse"></div>
          UPLINK_SYNC_STREAM
        </div>
        <div className="bg-black/60 px-4 py-1.5 rounded-lg border border-cyan-500/20 text-[8px] font-mono text-cyan-400/80 uppercase tracking-widest backdrop-blur-sm">
            FLOW_RATE: {bitrate} GB/S
        </div>
      </div>

      {/* Simulated Data Readout */}
      <div className="absolute bottom-6 left-6 flex flex-col gap-2 max-w-[250px] opacity-60">
        <div className="w-full h-[2px] bg-white/5 rounded-full overflow-hidden">
            <div className="h-full bg-cyan-500 animate-[grid-drift_3s_linear_infinite]" style={{ width: `${parseFloat(bitrate) * 40}%` }}></div>
        </div>
        <div className="text-[8px] text-cyan-500/70 font-mono uppercase tracking-[0.3em] flex justify-between">
            <span>BITSTREAM_ENCRYPTED</span>
            <span>{Math.floor(parseFloat(bitrate) * 100)}%</span>
        </div>
      </div>

      <div className="absolute bottom-6 right-6 text-[10px] text-cyan-400/60 font-mono bg-black/60 px-5 py-2 rounded-2xl border border-cyan-500/20 backdrop-blur-md shadow-xl">
