import React, { useRef, useEffect, useState } from 'react';

interface ObservationModeProps {
  isActive: boolean;
  onFrame: (base64: string) => void;
}

const ObservationMode: React.FC<ObservationModeProps> = ({ isActive, onFrame }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isLowLight, setIsLowLight] = useState(false);
  const [biometricSync, setBiometricSync] = useState(0);
  const [isReady, setIsReady] = useState(false);

  useEffect(() => {
    let stream: MediaStream | null = null;
    let interval: number | null = null;
    let bioInterval: number | null = null;

    const startCamera = async () => {
      try {
        stream = await navigator.mediaDevices.getUserMedia({ 
          video: { 
            facingMode: 'user', 
            width: { ideal: 1280 }, 
            height: { ideal: 720 } 
          } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.onloadedmetadata = () => {
            setIsReady(true);
          };
        }

        // Dedicated capture loop
        interval = window.setInterval(() => {
          if (videoRef.current && canvasRef.current && isReady) {
            const video = videoRef.current;
            const canvas = canvasRef.current;
            const ctx = canvas.getContext('2d');

            if (ctx && video.readyState >= 2 && video.videoWidth > 0) {
              // Target a manageable resolution for the model (max 720p)
              const maxDim = 720;
              let width = video.videoWidth;
              let height = video.videoHeight;

              if (width > maxDim || height > maxDim) {
                const ratio = Math.min(maxDim / width, maxDim / height);
                width *= ratio;
                height *= ratio;
              }

              canvas.width = width;
              canvas.height = height;

              if (isLowLight) {
                ctx.filter = 'brightness(1.8) contrast(1.2) saturate(0.7)';
              } else {
                ctx.filter = 'none';
              }

              ctx.drawImage(video, 0, 0, width, height);
              ctx.filter = 'none';

              // Send the frame
              const base64 = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];
              onFrame(base64);
            }
          }
        }, 1000); // Send 1 frame per second for optimal multimodal context

        bioInterval = window.setInterval(() => {
          setBiometricSync(Math.floor(Math.random() * 100));
        }, 2000);
      } catch (err) { 
        console.error("Optic Link Error:", err); 
      }
    };

    if (isActive) {
      startCamera();
    }

    return () => {
      if (stream) stream.getTracks().forEach(t => t.stop());
      if (interval) clearInterval(interval);
      if (bioInterval) clearInterval(bioInterval);
      setIsReady(false);
    };
  }, [isActive, onFrame, isLowLight, isReady]);

  if (!isActive) return null;

  return (
    <div className="relative h-full w-full rounded-[var(--ui-radius)] overflow-hidden border border-red-500/20 shadow-2xl bg-black animate-fade-in group transition-all duration-500">
      {!isReady && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/80 z-50">
          <div className="flex flex-col items-center gap-4">
            <i className="fas fa-circle-notch fa-spin text-red-500 text-3xl"></i>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-red-500">Initializing_Optic</span>
          </div>
        </div>
      )}

      {/* HUD Scan Line */}
      <div className="absolute left-0 right-0 h-1 bg-red-500/40 shadow-[0_0_15px_red] z-20 animate-scanline-pass pointer-events-none"></div>

      {/* Video Feed */}
      <video 
        ref={videoRef} 
        autoPlay 
        playsInline 
        muted 
        className={`w-full h-full object-cover transition-all duration-700 ${isLowLight ? 'grayscale brightness-[1.4] contrast-[1.2] sepia-[.3] hue-rotate-[100deg]' : ''}`} 
      />

      <canvas ref={canvasRef} className="hidden" />

      {/* Scanning HUD Overlays */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_0%,rgba(0,0,0,0.6)_100%)]"></div>

        {/* Tactical Brackets */}
        <div className="absolute top-8 left-8 w-12 h-12 border-t-2 border-l-2 border-red-500 opacity-40 group-hover:opacity-100 transition-all duration-500"></div>
        <div className="absolute top-8 right-8 w-12 h-12 border-t-2 border-r-2 border-red-500 opacity-40 group-hover:opacity-100 transition-all duration-500"></div>
        <div className="absolute bottom-8 left-8 w-12 h-12 border-b-2 border-l-2 border-red-500 opacity-40 group-hover:opacity-100 transition-all duration-500"></div>
        <div className="absolute bottom-8 right-8 w-12 h-12 border-b-2 border-r-2 border-red-500 opacity-40 group-hover:opacity-100 transition-all duration-500"></div>

        {/* Reticle */}
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-24 h-24 border border-red-500/20 rounded-full flex items-center justify-center opacity-30">
            <div className="w-1 h-1 bg-red-500 rounded-full"></div>
            <div className="absolute w-12 h-[1px] bg-red-500"></div>
            <div className="absolute h-12 w-[1px] bg-red-500"></div>
        </div>
      </div>

      {/* Interface Elements */}
      <div className="absolute top-6 left-6 flex flex-col gap-2">
        <div className="bg-red-600 px-5 py-2 rounded-full text-[10px] font-black uppercase tracking-widest flex items-center gap-2 animate-pulse shadow-lg shadow-red-600/30 backdrop-blur-md border border-red-400/30">
          <div className="w-2 h-2 rounded-full bg-white"></div>
          OPTIC_ACTIVE_01
        </div>
        <div className="bg-black/60 px-4 py-1.5 rounded-lg border border-red-500/10 text-[8px] font-mono text-red-400 uppercase tracking-widest backdrop-blur-md">
           Biometric_Sync: {biometricSync}%
        </div>
      </div>

      <div className="absolute bottom-6 right-6 flex gap-2">
        <button 
          onClick={() => setIsLowLight(!isLowLight)}
          className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all duration-300 backdrop-blur-xl ${isLowLight ? 'bg-emerald-500 text-white shadow-lg' : 'bg-black/40 text-white/70 hover:bg-black/60 border border-white/10'}`}
          title={isLowLight ? "Disable High Lumen" : "Enable High Lumen"}
        >
          <i className={`fas ${isLowLight ? 'fa-eye' : 'fa-moon'} text-lg`}></i>
        </button>
      </div>

      <div className="absolute bottom-6 left-6 flex flex-col gap-2">
        <div className="flex items-center gap-3">
            <div className="w-1 h-16 bg-white/10 rounded-full overflow-hidden">
                <div className="w-full bg-red-500 animate-pulse" style={{ height: `${biometricSync}%` }}></div>
            </div>
            <div className="flex flex-col">
                <span className="text-[10px] text-white/40 font-black uppercase tracking-widest">Neural_Flow</span>
                <span className="text-[12px] text-white font-mono tracking-tighter">SEG_IDENTIFIED</span>
            </div>
        </div>
      </div>
    </div>
  );
};

