import React, { useRef, useEffect, useState } from 'react';

interface ScreenShareModeProps {
  isActive: boolean;
  stream: MediaStream;
  onFrame: (base64: string) => void;
  onStop: () => void;
}

const ScreenShareMode: React.FC<ScreenShareModeProps> = ({ isActive, stream, onFrame, onStop }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [bitrate, setBitrate] = useState('1.2');
  const [isReady, setIsReady] = useState(false);

  useEffect(() => {
    if (!isActive || !stream) return;

    const video = videoRef.current;
    if (video) {
      video.srcObject = stream;

      // If metadata is already there, set ready immediately
      if (video.readyState >= 1) {
        setIsReady(true);
      } else {
        video.onloadedmetadata = () => setIsReady(true);
      }
    }

    const interval = window.setInterval(() => {
      if (videoRef.current && canvasRef.current && isReady) {
        const video = videoRef.current;
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');

        if (ctx && video.videoWidth > 0 && video.readyState >= 2) {
          // Optimized resolution for screen sharing context
          // High enough to read text, but low enough for the model to process quickly
          const maxDim = 1280; 
          let width = video.videoWidth;
          let height = video.videoHeight;

          if (width > maxDim || height > maxDim) {
            const ratio = Math.min(maxDim / width, maxDim / height);
            width *= ratio;
            height *= ratio;
          }

          canvas.width = width;
          canvas.height = height;

          // Draw with high quality for text legibility
          ctx.imageSmoothingEnabled = true;
          ctx.imageSmoothingQuality = 'high';
          ctx.drawImage(video, 0, 0, width, height);

          // Using slightly higher quality (0.7) for screen shares as they often contain text
          const base64 = canvas.toDataURL('image/jpeg', 0.7).split(',')[1];
          onFrame(base64);
        }
      }
    }, 750); // Slightly faster capture for screen sharing (approx 1.3 FPS)

    const bitInterval = window.setInterval(() => {
      setBitrate((Math.random() * (4.8 - 0.8) + 0.8).toFixed(1));
    }, 1200);

    return () => {
      window.clearInterval(interval);
      window.clearInterval(bitInterval);
      if (video) {
        video.onloadedmetadata = null;
        video.srcObject = null;
      }
      setIsReady(false);
    };
  }, [isActive, stream, onFrame, isReady]);

  if (!isActive) return null;

  return (
    <div className="relative h-full w-full rounded-[var(--ui-radius)] overflow-hidden border border-cyan-500/30 shadow-[0_0_50px_rgba(6,182,212,0.15)] bg-black animate-fade-in group">
      {!isReady && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/80 z-50">
          <div className="flex flex-col items-center gap-4">
            <i className="fas fa-circle-notch fa-spin text-cyan-500 text-3xl"></i>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-cyan-500">Establishing_Uplink</span>
          </div>
        </div>
      )}

      {/* Video Feed */}
      <video 
        ref={videoRef} 
        autoPlay 
        playsInline 
        muted 
        className="w-full h-full object-contain bg-zinc-950" 
      />

      <canvas ref={canvasRef} className="hidden" />

      {/* HUD Elements */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute inset-0 border-[30px] border-white/5 opacity-40"></div>
        <div className="absolute inset-0 border border-cyan-500/10"></div>

        {/* Animated Corner Brackets */}
        <div className="absolute top-8 left-8 w-10 h-10 border-t border-l border-cyan-500/50"></div>
        <div className="absolute top-8 right-8 w-10 h-10 border-t border-r border-cyan-500/50"></div>
        <div className="absolute bottom-8 left-8 w-10 h-10 border-b border-l border-cyan-500/50"></div>
        <div className="absolute bottom-8 right-8 w-10 h-10 border-b border-r border-cyan-500/50"></div>
      </div>

      {/* Indicators */}
      <div className="absolute top-6 left-6 flex flex-col gap-2">
        <div className="bg-cyan-600 px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-[0.2em] flex items-center gap-3 shadow-lg shadow-cyan-600/20 backdrop-blur-md border border-cyan-400/30">
          <div className="w-2 h-2 rounded-full bg-white animate-pulse"></div>
          SCREEN_UPLINK_LIVE
        </div>
        <div className="bg-black/60 px-4 py-1.5 rounded-lg border border-cyan-500/20 text-[8px] font-mono text-cyan-400/80 uppercase tracking-widest backdrop-blur-sm">
            THROUGHPUT: {bitrate} MB/S
        </div>
      </div>

      {/* Simulated Data Readout */}
      <div className="absolute bottom-6 left-6 flex flex-col gap-2 max-w-[250px] opacity-60">
        <div className="w-full h-[2px] bg-white/5 rounded-full overflow-hidden">
            <div className="h-full bg-cyan-500 animate-[grid-drift_3s_linear_infinite]" style={{ width: `${(parseFloat(bitrate) / 5) * 100}%` }}></div>
        </div>
        <div className="text-[8px] text-cyan-500/70 font-mono uppercase tracking-[0.3em] flex justify-between">
            <span>PACKET_FLOW_SYNC</span>
            <span>{Math.floor((parseFloat(bitrate) / 5) * 100)}%</span>
        </div>
      </div>

      <div className="absolute bottom-6 right-6 text-[10px] text-cyan-400/60 font-mono bg-black/60 px-5 py-2 rounded-2xl border border-cyan-500/20 backdrop-blur-md shadow-xl uppercase tracking-widest">
        Neural_Uplink // 0xAF_77
      </div>
    </div>
  );
};

