        ? `Long-Term Memory Data: ${memories.map(m => m.fact).join(' | ')}.`
        : "Long-Term Memory is currently empty.";

      const visionContext = isScreenSharing ? "Viewing SCREEN." : "Viewing USER CAMERA.";

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools,
          toolConfig: sensorData.location ? { retrievalConfig: { latLng: { latitude: sensorData.location.lat, longitude: sensorData.location.lng } } } : undefined,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. Persona: ${personalityPrompt}. Greeting: ${prefs.greeting}. ${memoryPrompt}. ${visionContext} Use visuals for context.`,
          inputAudioTranscription: {}, outputAudioTranscription: {}, thinkingConfig: { thinkingBudget: 24576 }
        } as any,
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);

            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const pcmBlob = { data: audioUtils.encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);

            frameIntervalRef.current = window.setInterval(() => {
              if (currentFrameRef.current) {
                const frameData = currentFrameRef.current;
                currentFrameRef.current = null;
                sessionPromise.then(s => s.sendRealtimeInput({ 
                  media: { data: frameData, mimeType: 'image/jpeg' } 
                }));
              }
            }, 800); 

            const initialMsg = initialText || prefs.greeting;
            sessionPromise.then(s => s.sendRealtimeInput({ text: initialMsg }));
            if (initialText) addTranscription('user', initialText);
          },
          onmessage: async (message: any) => {
            // Handle Interruptions
            if (message.serverContent?.interrupted) {
              activeSourcesRef.current.forEach(s => { try { s.stop(); } catch(e){} });
              activeSourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setState(AssistantState.LISTENING);
            }

            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const newMemory = { id: Math.random().toString(36).substr(2, 9), fact: fc.args.fact, timestamp: new Date() };
                  setMemories(p => [...p, newMemory]);
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Learned." } } }));
                }
              }
            }
            const turnParts = message.serverContent?.modelTurn?.parts || [];
            for (const part of turnParts) {
              if (part.inlineData?.data) {
                setState(AssistantState.SPEAKING);
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
                const buffer = await audioUtils.decodeAudioData(audioUtils.decode(part.inlineData.data), outputCtx, 24000, 1);
                const s = outputCtx.createBufferSource(); 
                s.buffer = buffer; 
                s.playbackRate.value = prefs.speechSpeed;
                s.detune.value = (prefs.speechPitch - 1.0) * 1200; 
                s.connect(outputCtx.destination);
                s.onended = () => { 
                  activeSourcesRef.current.delete(s); 
                  if (activeSourcesRef.current.size === 0) setState(AssistantState.LISTENING); 
                };
                s.start(nextStartTimeRef.current); 
                nextStartTimeRef.current += (buffer.duration / prefs.speechSpeed); 
                activeSourcesRef.current.add(s);
              }
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent.inputTranscription.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent.outputTranscription.text);
            if (message.serverContent?.turnComplete) {
              const chunks = message.serverContent?.groundingMetadata?.groundingChunks || [];
              const sources = chunks.map((c: any) => (c.web ? { title: c.web.title, uri: c.web.uri } : (c.maps ? { title: c.maps.title, uri: c.maps.uri } : null))).filter(Boolean);
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) { addTranscription('assistant', a, sources); audioUtils.playSuccessSound(outputCtx); } return ''; });
            }
          },
          onerror: async (err: any) => {
            console.error("Session Error:", err);
            if (err?.message?.includes("Requested entity was not found") && window.aistudio) {
              await window.aistudio.openSelectKey();
            }
            stopSession();
          }, 
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { 
      if (err?.message?.includes("Requested entity was not found") && window.aistudio) {
          await window.aistudio.openSelectKey();
      }
      setErrorToast(err.message); 
      setState(AssistantState.IDLE); 
      setTimeout(() => setErrorToast(null), 5000); 
    }
  };

  const handleSendText = useCallback(() => {
    if (!inputText.trim()) return;
    const text = inputText.trim();
    setInputText('');
    if (state === AssistantState.IDLE) {
      startSession(text);
    } else if (sessionRef.current) {
      sessionRef.current.sendRealtimeInput({ text });
      addTranscription('user', text);
    }
  }, [inputText, state, addTranscription]);

  const handleToggleVision = async () => {
    if (isVisionActive) {
      setIsVisionActive(false);
    } else {
      try {
        await navigator.mediaDevices.getUserMedia({ video: true });
        setIsScreenSharing(false);
        setIsVisionActive(true);
        if (state === AssistantState.IDLE) startSession();
        else if (sessionRef.current) {
           stopSession();
           setTimeout(() => { setIsVisionActive(true); startSession(); }, 500);
        }
      } catch (err) { setErrorToast("Hardware access failed."); }
    }
  };

  const handleToggleScreenShare = async () => {
    if (isScreenSharing) {
      setIsScreenSharing(false);
      if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    } else {
      try {
        const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
        setScreenStream(stream);
        setIsVisionActive(false);
        setIsScreenSharing(true);
        if (state === AssistantState.IDLE) startSession();
        else if (sessionRef.current) {
           stopSession();
           setTimeout(() => { 
             setScreenStream(stream);
             setIsScreenSharing(true); 
             startSession(); 
           }, 500);
        }
        stream.getVideoTracks()[0].onended = () => { setIsScreenSharing(false); setScreenStream(null); };
      } catch (err) { setErrorToast("Uplink negotiation aborted."); }
    }
  };

  const handleLogin = (username: string, preferences: UserPreferences) => {
    setUser({ username, preferences });
  };

  const handlePreviewVoice = async (voiceId: string) => {
    if (previewingVoiceId) return;
    setPreviewingVoiceId(voiceId);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Neural link check.` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voiceId } } },
        },
      });

      const outputCtx = audioContextRef.current?.output || new (window.AudioContext || (window as any).webkitAudioContext)();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const audioBuffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
        const source = outputCtx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(outputCtx.destination);
        source.onended = () => setPreviewingVoiceId(null);
        source.start();
      } else { setPreviewingVoiceId(null); }
    } catch (err) {
      setPreviewingVoiceId(null);
    }
  };

  if (showIntro) return <IntroSequence onComplete={() => setShowIntro(false)} />;
  if (!user) return <LoginPage onLogin={handleLogin} />;

  return (
    <div className="flex flex-col h-full w-full transition-all duration-1000 overflow-hidden">
      <header className="m-[var(--ui-gap)] p-4 lg:p-6 rounded-[var(--ui-radius)] flex items-center justify-between z-50 glass animate-fade-blur-in">
        <div className="flex items-center gap-3 lg:gap-6 group">
          <div className="w-10 h-10 lg:w-14 lg:h-14 rounded-[var(--bubble-radius)] overflow-hidden border border-white/10 relative transition-all duration-700 group-hover:scale-110 shadow-xl">
            {prefs.assistantProfilePic ? <img src={prefs.assistantProfilePic} className="w-full h-full object-cover" alt="AI" /> : <div className="w-full h-full bg-[var(--theme-primary)]/10 flex items-center justify-center"><i className="fas fa-atom text-white text-lg lg:text-xl"></i></div>}
          </div>
          <div className="animate-slide-in-right-bounce">
            <h1 className="text-sm lg:text-2xl font-black tracking-tighter text-white uppercase truncate max-w-[120px] lg:max-w-none">{prefs.assistantName}</h1>
            <HardwareSensors data={sensorData} deviceType={device} themeColor={themeData.primary} />
          </div>
        </div>
        <div className="flex items-center gap-2 md:gap-4">
           <button onClick={() => setIsSettingsOpen(true)} className="w-10 h-10 lg:w-12 lg:h-12 rounded-xl bg-white/5 flex items-center justify-center hover:bg-white/10 transition-all active:scale-90"><i className="fas fa-sliders-h text-sm lg:text-lg"></i></button>
           <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-10 h-10 lg:w-12 lg:h-12 rounded-xl flex items-center justify-center transition-all active:scale-90 ${isMemoryOpen ? 'bg-[var(--theme-primary)] text-white shadow-[0_0_20px_var(--theme-glow)]' : 'bg-white/5 text-gray-400'}`}><i className="fas fa-brain text-sm lg:text-lg"></i></button>
           <button onClick={() => { stopSession(); setUser(null); }} className="w-10 h-10 lg:w-12 lg:h-12 flex items-center justify-center text-gray-600 hover:text-red-500 transition-colors active:scale-90"><i className="fas fa-power-off text-sm lg:text-lg"></i></button>
        </div>
      </header>

      <main className={`flex-1 flex p-[var(--ui-gap)] gap-[var(--ui-gap)] overflow-hidden`}>
        <div className="flex-1 flex flex-col gap-[var(--ui-gap)] min-h-0">

          {(isVisionActive || isScreenSharing) && (
            <div className="h-48 md:h-72 lg:h-[400px] w-full animate-pop flex-shrink-0 relative group">
              {isVisionActive && <ObservationMode isActive={isVisionActive} onFrame={(b) => currentFrameRef.current = b} />}
              {isScreenSharing && screenStream && <ScreenShareMode isActive={isScreenSharing} stream={screenStream} onFrame={(b) => currentFrameRef.current = b} onStop={() => setIsScreenSharing(false)} />}
            </div>
          )}

          <div className="flex-1 flex flex-col glass rounded-[var(--ui-radius)] overflow-hidden relative shadow-2xl min-h-0">
            <div className={`flex-1 p-4 lg:p-8 space-y-4 lg:space-y-8 overflow-y-auto scrollbar-thin transcription-list`} ref={scrollRef}>
              <TranscriptionList transcriptions={transcriptions} deleteTranscription={deleteTranscription} themePrimary={themeData.primary} />
              {(streamingAssistantText || state === AssistantState.THINKING) && (
                <div className="items-start flex flex-col animate-pop">
                  <div className="max-w-[85%] px-5 py-3 rounded-[var(--bubble-radius)] bg-white/[0.03] text-white/60 border border-white/5">
                    {streamingAssistantText ? <p className="font-mono text-xs lg:text-sm leading-relaxed">{streamingAssistantText}</p> : <div className="typing-indicator"><span></span><span></span><span></span></div>}
                  </div>
                </div>
              )}
            </div>
            <div className="p-4 lg:p-8 border-t border-white/5 bg-black/50 backdrop-blur-2xl flex flex-col gap-3 lg:gap-6">
              <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
              <div className="flex gap-3 items-center">
                  <div className="flex gap-2">
                    <button onClick={handleToggleVision} className={`w-10 h-10 lg:w-14 lg:h-14 rounded-xl flex items-center justify-center transition-all active:scale-90 ${isVisionActive ? 'bg-red-500 text-white animate-pulse shadow-lg shadow-red-500/20' : 'bg-white/5 text-gray-400 hover:text-white'}`} title="Optic Link"><i className="fas fa-camera text-sm lg:text-lg"></i></button>
                    <button onClick={handleToggleScreenShare} className={`w-10 h-10 lg:w-14 lg:h-14 rounded-xl flex items-center justify-center transition-all active:scale-90 ${isScreenSharing ? 'bg-cyan-500 text-white animate-pulse shadow-lg shadow-cyan-500/20' : 'bg-white/5 text-gray-400 hover:text-white'}`} title="Screen Uplink"><i className="fas fa-desktop text-sm lg:text-lg"></i></button>
                  </div>
                  <input type="text" value={inputText} onChange={(e) => setInputText(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSendText()} placeholder="Directive..." className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-4 lg:px-6 py-3 lg:py-5 text-sm lg:text-lg focus:outline-none focus:border-[var(--theme-primary)]/50 text-white font-bold" />
                  <button onClick={inputText.trim() ? handleSendText : (state === AssistantState.IDLE ? () => startSession() : stopSession)} className={`flex-1 md:flex-none md:w-48 lg:w-64 h-14 lg:h-20 rounded-[var(--ui-radius)] flex items-center justify-center transition-all gap-2 lg:gap-4 neo-button shadow-2xl ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-600 text-white animate-pulse'}`}>
                    <i className={`fas ${inputText.trim() ? 'fa-paper-plane' : (state === AssistantState.IDLE ? 'fa-bolt' : 'fa-square')} text-sm lg:text-lg`}></i>
                    <span className="font-black uppercase tracking-widest text-[8px] lg:text-[11px]">{inputText.trim() ? 'SEND' : (state === AssistantState.IDLE ? 'IGNITE' : 'HALT')}</span>
                  </button>
              </div>
            </div>
          </div>
        </div>

        {isMemoryOpen && (
          <div className="w-full md:w-[380px] lg:w-[420px] h-full flex-shrink-0 animate-slide-in-right-bounce z-[60]">
            <MemoryBank 
              memories={memories} 
              onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} 
              onAdd={(fact) => setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact, timestamp: new Date() }])}
              onPurge={() => { if(window.confirm("Purge memory?")) setMemories([]); }}
              assistantName={prefs.assistantName} 
            />
          </div>
        )}
      </main>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} prefs={prefs} setPrefs={setPrefs} voices={dynamicVoices} personalities={PERSONALITIES} isTV={false} isWearable={false} onPreviewVoice={handlePreviewVoice} previewingVoiceId={previewingVoiceId} />

      {errorToast && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-red-600 text-white px-8 py-4 rounded-2xl font-black uppercase tracking-widest text-[10px] shadow-2xl animate-shake z-[200]">
          <i className="fas fa-exclamation-triangle mr-3"></i> {errorToast}
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useState } from 'react';

interface ScreenShareModeProps {
  isActive: boolean;
  stream: MediaStream;
  onFrame: (base64: string) => void;
  onStop: () => void;
}

const ScreenShareMode: React.FC<ScreenShareModeProps> = ({ isActive, stream, onFrame, onStop }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [throughput, setThroughput] = useState('0.0');
  const [isReady, setIsReady] = useState(false);

  useEffect(() => {
    if (!isActive || !stream) return;

    const video = videoRef.current;
    if (video) {
      video.srcObject = stream;

      const handleMetadata = () => {
        setIsReady(true);
        video.play().catch(console.error);
      };

      if (video.readyState >= 1) {
        handleMetadata();
      } else {
        video.onloadedmetadata = handleMetadata;
      }
    }

    // High-performance capture loop optimized for Screen Text
    const interval = window.setInterval(() => {
      if (videoRef.current && canvasRef.current && isReady) {
        const video = videoRef.current;
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d', { alpha: false }); // Disable alpha for perf

        if (ctx && video.videoWidth > 0 && video.readyState >= 2) {
          // Gemini Vision works best at balanced resolutions
          // 1280px width is the 'Sweet Spot' for reading screen text
          const targetWidth = 1280; 
          const scale = targetWidth / video.videoWidth;
          const targetHeight = video.videoHeight * scale;

          if (canvas.width !== targetWidth || canvas.height !== targetHeight) {
            canvas.width = targetWidth;
            canvas.height = targetHeight;
          }

          ctx.imageSmoothingEnabled = true;
          ctx.imageSmoothingQuality = 'high';

          // Background fill to prevent transparent artifacts
          ctx.fillStyle = '#000';
          ctx.fillRect(0, 0, targetWidth, targetHeight);

          ctx.drawImage(video, 0, 0, targetWidth, targetHeight);

          // 0.6 quality is optimal for Gemini Live (balance of speed and detail)
          const base64 = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];
          onFrame(base64);
        }
      }
    }, 500); // 2 FPS - Standard for Multimodal Screen Share

    const throughputInterval = window.setInterval(() => {
      setThroughput((Math.random() * (8.2 - 2.1) + 2.1).toFixed(1));
    }, 2000);

    return () => {
      window.clearInterval(interval);
      window.clearInterval(throughputInterval);
      if (video) {
        video.onloadedmetadata = null;
        video.srcObject = null;
      }
      setIsReady(false);
    };
  }, [isActive, stream, onFrame, isReady]);

  if (!isActive) return null;

  return (
    <div className="relative h-full w-full rounded-[var(--ui-radius)] overflow-hidden border border-cyan-500/30 shadow-[0_0_50px_rgba(6,182,212,0.2)] bg-black animate-fade-in group">
      {!isReady && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/90 z-50">
          <div className="flex flex-col items-center gap-6">
            <div className="relative w-16 h-16">
                <i className="fas fa-circle-notch fa-spin text-cyan-500 text-4xl absolute inset-0"></i>
                <i className="fas fa-desktop text-cyan-500/40 text-xl absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2"></i>
            </div>
            <span className="text-[10px] font-black uppercase tracking-[0.4em] text-cyan-400 animate-pulse">Establishing_Uplink</span>
          </div>
        </div>
      )}

      {/* Video Feed */}
      <video 
        ref={videoRef} 
        autoPlay 
        playsInline 
        muted 
        className="w-full h-full object-contain bg-zinc-950" 
      />

      <canvas ref={canvasRef} className="hidden" />

      {/* HUD Elements */}
      <div className="absolute inset-0 pointer-events-none">
        {/* Sync Pulse Effect */}
        <div className="absolute inset-0 border border-cyan-500/20 animate-pulse"></div>
        <div className="absolute inset-0 bg-[linear-gradient(rgba(6,182,212,0.03)_1px,transparent_1px)] bg-[length:100%_4px] pointer-events-none"></div>

        {/* Corner Brackets */}
        <div className="absolute top-6 left-6 w-8 h-8 border-t-2 border-l-2 border-cyan-500/40"></div>
        <div className="absolute top-6 right-6 w-8 h-8 border-t-2 border-r-2 border-cyan-500/40"></div>
        <div className="absolute bottom-6 left-6 w-8 h-8 border-b-2 border-l-2 border-cyan-500/40"></div>
        <div className="absolute bottom-6 right-6 w-8 h-8 border-b-2 border-r-2 border-cyan-500/40"></div>
      </div>

      {/* Real-time Indicators */}
      <div className="absolute top-6 left-6 flex flex-col gap-2">
        <div className="bg-cyan-600 px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest flex items-center gap-3 shadow-xl backdrop-blur-xl border border-cyan-400/30">
          <div className="w-2 h-2 rounded-full bg-white animate-ping"></div>
          UPLINK_SYNC_ACTIVE
        </div>
        <div className="flex gap-2">
            <div className="bg-black/60 px-3 py-1 rounded-lg border border-cyan-500/20 text-[8px] font-mono text-cyan-400 uppercase tracking-widest backdrop-blur-md">
                FLOW: {throughput} MB/S
            </div>
            <div className="bg-black/60 px-3 py-1 rounded-lg border border-cyan-500/20 text-[8px] font-mono text-cyan-400 uppercase tracking-widest backdrop-blur-md">
                LATENCY: 24MS
            </div>
        </div>
      </div>

      <div className="absolute bottom-6 right-6 flex items-center gap-4 bg-black/60 px-5 py-2 rounded-2xl border border-cyan-500/20 backdrop-blur-xl shadow-2xl">
        <div className="flex flex-col items-end">
            <span className="text-[7px] text-cyan-400/40 font-black uppercase tracking-widest">Protocol</span>
            <span className="text-[10px] text-cyan-400 font-mono tracking-widest">GEMINI_OPTIC_v2</span>
        </div>
        <div className="w-[1px] h-6 bg-cyan-500/20"></div>
        <button 
          onClick={(e) => { e.stopPropagation(); onStop(); }}
          className="text-red-500 hover:text-red-400 transition-colors pointer-events-auto p-1"
        >
          <i className="fas fa-stop-circle text-lg"></i>
        </button>
      </div>
    </div>
  );
};

