  const stopSession = useCallback(() => {
    if (sessionRef.current) { try { sessionRef.current.close?.(); } catch(e){} sessionRef.current = null; }
    if (micStreamRef.current) { micStreamRef.current.getTracks().forEach(t => t.stop()); micStreamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (audioContextRef.current) {
        audioContextRef.current.input.close().catch(() => {});
        audioContextRef.current.output.close().catch(() => {});
        audioContextRef.current = null;
    }
    if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    if (frameIntervalRef.current) { window.clearInterval(frameIntervalRef.current); frameIntervalRef.current = null; }
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    activeSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setState(AssistantState.IDLE);
    setIsVisionActive(false);
    setIsScreenSharing(false);
    setStreamingUserText('');
    setStreamingAssistantText('');
  }, [screenStream]);

  const startSession = async (initialText?: string) => {
    try {
      setState(AssistantState.CONNECTING);
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Authentication failure.");

      const ai = new GoogleGenAI({ apiKey });

      /**
       * STABILIZATION FIX: 
       * We MUST initialize the Input context with NATIVE sample rate to prevent 
       * "Connecting nodes from different sample-rate" browser error.
       * Output context remains 24000Hz as it doesn't connect to the mic.
       */
      audioContextRef.current = {
        input: new (window.AudioContext || (window as any).webkitAudioContext)(),
        output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
      };

      const { input: inputCtx, output: outputCtx } = audioContextRef.current;
      if (inputCtx.state === 'suspended') await inputCtx.resume();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      audioUtils.playLinkSound(outputCtx);

      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: { 
          echoCancellation: true, 
          noiseSuppression: true, 
          autoGainControl: true,
          channelCount: 1 
        } 
      });
      micStreamRef.current = stream;

      const source = inputCtx.createMediaStreamSource(stream);
      const analyser = inputCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;
      source.connect(analyser);

      const personalityPrompt = prefs.personality === 'custom' ? (prefs.customPersonality || 'Be helpful.') : PERSONALITIES[prefs.personality];

      const tools: any[] = [{ functionDeclarations: [saveKnowledgeTool] }];
      if (sensorData.location) tools.push({ googleMaps: {} });
      if (searchEnabled) tools.push({ googleSearch: {} });

      const memoryPrompt = memories.length > 0 
        ? `Knowledge Bank: ${memories.map(m => m.fact).join(' | ')}.`
        : "Knowledge Bank is empty.";

      const visionContext = isScreenSharing ? "OPTIC_UPLINK: SCREEN_SHARE." : "OPTIC_UPLINK: USER_CAMERA.";

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools,
          toolConfig: sensorData.location ? { retrievalConfig: { latLng: { latitude: sensorData.location.lat, longitude: sensorData.location.lng } } } : undefined,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: prefs.voiceId } } },
          systemInstruction: `Identity: ${prefs.assistantName}. Persona: ${personalityPrompt}. ${memoryPrompt}. ${visionContext} VISUAL_MODE: ACTIVE. Use frames for context. HEARING_MODE: ACTIVE. Respond naturally.`,
          inputAudioTranscription: {}, outputAudioTranscription: {}, thinkingConfig: { thinkingBudget: 24576 }
        } as any,
        callbacks: {
          onopen: () => {
            setState(AssistantState.LISTENING);

            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              // Manual Resampling happens here inside createPcmBlob
              const pcmBlob = audioUtils.createPcmBlob(inputData, inputCtx.sampleRate);
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);

            frameIntervalRef.current = window.setInterval(() => {
              if (currentFrameRef.current) {
                const frameData = currentFrameRef.current;
                currentFrameRef.current = null;
                sessionPromise.then(s => s.sendRealtimeInput({ 
                  media: { data: frameData, mimeType: 'image/jpeg' } 
                }));
              }
            }, 500); 

            const initialMsg = initialText || prefs.greeting;
            sessionPromise.then(s => s.sendRealtimeInput({ text: initialMsg }));
            if (initialText) addTranscription('user', initialText);
          },
          onmessage: async (message: any) => {
            if (message.serverContent?.interrupted) {
              activeSourcesRef.current.forEach(s => { try { s.stop(); } catch(e){} });
              activeSourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setState(AssistantState.LISTENING);
            }

            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'save_knowledge') {
                  const newMemory = { id: Math.random().toString(36).substr(2, 9), fact: fc.args.fact, timestamp: new Date() };
                  setMemories(p => [...p, newMemory]);
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "Memory archived." } } }));
                }
              }
            }
            const turnParts = message.serverContent?.modelTurn?.parts || [];
            for (const part of turnParts) {
              if (part.inlineData?.data) {
                setState(AssistantState.SPEAKING);
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
                const buffer = await audioUtils.decodeAudioData(audioUtils.decode(part.inlineData.data), outputCtx, 24000, 1);
                const s = outputCtx.createBufferSource(); 
                s.buffer = buffer; 
                s.playbackRate.value = prefs.speechSpeed;
                s.detune.value = (prefs.speechPitch - 1.0) * 1200; 
                s.connect(outputCtx.destination);
                s.onended = () => { 
                  activeSourcesRef.current.delete(s); 
                  if (activeSourcesRef.current.size === 0) setState(AssistantState.LISTENING); 
                };
                s.start(nextStartTimeRef.current); 
                nextStartTimeRef.current += (buffer.duration / prefs.speechSpeed); 
                activeSourcesRef.current.add(s);
              }
            }
            if (message.serverContent?.inputTranscription) setStreamingUserText(prev => prev + message.serverContent.inputTranscription.text);
            if (message.serverContent?.outputTranscription) setStreamingAssistantText(prev => prev + message.serverContent.outputTranscription.text);
            if (message.serverContent?.turnComplete) {
              const chunks = message.serverContent?.groundingMetadata?.groundingChunks || [];
              const sources = chunks.map((c: any) => (c.web ? { title: c.web.title, uri: c.web.uri } : (c.maps ? { title: c.maps.title, uri: c.maps.uri } : null))).filter(Boolean);
              setStreamingUserText(u => { if (u) addTranscription('user', u); return ''; });
              setStreamingAssistantText(a => { if (a) { addTranscription('assistant', a, sources); audioUtils.playSuccessSound(outputCtx); } return ''; });
            }
          },
          onerror: async (err: any) => {
            console.error("Session Critical:", err);
            if (err?.message?.includes("Requested entity was not found") && window.aistudio) {
              await window.aistudio.openSelectKey();
            }
            stopSession();
          }, 
          onclose: () => stopSession()
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { 
      if (err?.message?.includes("Requested entity was not found") && window.aistudio) {
          await window.aistudio.openSelectKey();
      }
      setErrorToast(err.message); 
      setState(AssistantState.IDLE); 
      setTimeout(() => setErrorToast(null), 5000); 
    }
  };

  const handleSendText = useCallback(() => {
    if (!inputText.trim()) return;
    const text = inputText.trim();
    setInputText('');
    if (state === AssistantState.IDLE) {
      startSession(text);
    } else if (sessionRef.current) {
      sessionRef.current.sendRealtimeInput({ text });
      addTranscription('user', text);
    }
  }, [inputText, state, addTranscription]);

  const handleToggleVision = async () => {
    if (isVisionActive) {
      setIsVisionActive(false);
    } else {
      try {
        await navigator.mediaDevices.getUserMedia({ video: true });
        setIsScreenSharing(false);
        setIsVisionActive(true);
        if (state === AssistantState.IDLE) startSession();
        else {
           stopSession();
           setTimeout(() => { setIsVisionActive(true); startSession(); }, 600);
        }
      } catch (err) { setErrorToast("Optic hardware link failed."); }
    }
  };

  const handleToggleScreenShare = async () => {
    if (isScreenSharing) {
      setIsScreenSharing(false);
      if (screenStream) { screenStream.getTracks().forEach(t => t.stop()); setScreenStream(null); }
    } else {
      try {
        const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
        setScreenStream(stream);
        setIsVisionActive(false);
        setIsScreenSharing(true);
        if (state === AssistantState.IDLE) startSession();
        else {
           stopSession();
           setTimeout(() => { 
             setScreenStream(stream);
             setIsScreenSharing(true); 
             startSession(); 
           }, 600);
        }
        stream.getVideoTracks()[0].onended = () => { setIsScreenSharing(false); setScreenStream(null); };
      } catch (err) { setErrorToast("Uplink negotiation aborted."); }
    }
  };

  const handleLogin = (username: string, preferences: UserPreferences) => {
    setUser({ username, preferences });
  };

  const handlePreviewVoice = async (voiceId: string) => {
    if (previewingVoiceId) return;
    setPreviewingVoiceId(voiceId);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Link nominal.` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voiceId } } },
        },
      });

      const outputCtx = audioContextRef.current?.output || new (window.AudioContext || (window as any).webkitAudioContext)();
      if (outputCtx.state === 'suspended') await outputCtx.resume();

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const audioBuffer = await audioUtils.decodeAudioData(audioUtils.decode(base64Audio), outputCtx, 24000, 1);
        const source = outputCtx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(outputCtx.destination);
        source.onended = () => setPreviewingVoiceId(null);
        source.start();
      } else { setPreviewingVoiceId(null); }
    } catch (err) {
      setPreviewingVoiceId(null);
    }
  };

  if (showIntro) return <IntroSequence onComplete={() => setShowIntro(false)} />;
  if (!user) return <LoginPage onLogin={handleLogin} />;

  return (
    <div className="flex flex-col h-full w-full transition-all duration-1000 overflow-hidden">
      <header className="m-[var(--ui-gap)] p-4 lg:p-6 rounded-[var(--ui-radius)] flex items-center justify-between z-50 glass animate-fade-blur-in">
        <div className="flex items-center gap-3 lg:gap-6 group">
          <div className="w-10 h-10 lg:w-14 lg:h-14 rounded-[var(--bubble-radius)] overflow-hidden border border-white/10 relative transition-all duration-700 group-hover:scale-110 shadow-xl">
            {prefs.assistantProfilePic ? <img src={prefs.assistantProfilePic} className="w-full h-full object-cover" alt="AI" /> : <div className="w-full h-full bg-[var(--theme-primary)]/10 flex items-center justify-center"><i className="fas fa-atom text-white text-lg lg:text-xl"></i></div>}
          </div>
          <div className="animate-slide-in-right-bounce">
            <h1 className="text-sm lg:text-2xl font-black tracking-tighter text-white uppercase truncate max-w-[120px] lg:max-w-none">{prefs.assistantName}</h1>
            <HardwareSensors data={sensorData} deviceType={device} themeColor={themeData.primary} />
          </div>
        </div>
        <div className="flex items-center gap-2 md:gap-4">
           <button onClick={() => setIsSettingsOpen(true)} className="w-10 h-10 lg:w-12 lg:h-12 rounded-xl bg-white/5 flex items-center justify-center hover:bg-white/10 transition-all active:scale-90"><i className="fas fa-sliders-h text-sm lg:text-lg"></i></button>
           <button onClick={() => setIsMemoryOpen(!isMemoryOpen)} className={`w-10 h-10 lg:w-12 lg:h-12 rounded-xl flex items-center justify-center transition-all active:scale-90 ${isMemoryOpen ? 'bg-[var(--theme-primary)] text-white shadow-[0_0_20px_var(--theme-glow)]' : 'bg-white/5 text-gray-400'}`}><i className="fas fa-brain text-sm lg:text-lg"></i></button>
           <button onClick={() => { stopSession(); setUser(null); }} className="w-10 h-10 lg:w-12 lg:h-12 flex items-center justify-center text-gray-600 hover:text-red-500 transition-colors active:scale-90"><i className="fas fa-power-off text-sm lg:text-lg"></i></button>
        </div>
      </header>

      <main className={`flex-1 flex p-[var(--ui-gap)] gap-[var(--ui-gap)] overflow-hidden`}>
        <div className="flex-1 flex flex-col gap-[var(--ui-gap)] min-h-0">

          {(isVisionActive || isScreenSharing) && (
            <div className="h-48 md:h-72 lg:h-[400px] w-full animate-pop flex-shrink-0 relative group">
              {isVisionActive && <ObservationMode isActive={isVisionActive} onFrame={handleIncomingFrame} />}
              {isScreenSharing && screenStream && <ScreenShareMode isActive={isScreenSharing} stream={screenStream} onFrame={handleIncomingFrame} onStop={() => setIsScreenSharing(false)} />}
            </div>
          )}

          <div className="flex-1 flex flex-col glass rounded-[var(--ui-radius)] overflow-hidden relative shadow-2xl min-h-0">
            <div className={`flex-1 p-4 lg:p-8 space-y-4 lg:space-y-8 overflow-y-auto scrollbar-thin transcription-list`} ref={scrollRef}>
              <TranscriptionList transcriptions={transcriptions} deleteTranscription={deleteTranscription} themePrimary={themeData.primary} />
              {(streamingAssistantText || streamingUserText || state === AssistantState.THINKING) && (
                <div className="items-start flex flex-col animate-pop">
                  <div className="max-w-[85%] px-5 py-3 rounded-[var(--bubble-radius)] bg-white/[0.03] text-white/60 border border-white/5">
                    {streamingUserText && <p className="text-[10px] text-blue-400 font-black uppercase mb-1 opacity-50">Transcribing User...</p>}
                    {streamingUserText && <p className="mb-3 text-sm italic">"{streamingUserText}"</p>}
                    {streamingAssistantText ? <p className="font-mono text-xs lg:text-sm leading-relaxed">{streamingAssistantText}</p> : <div className="typing-indicator"><span></span><span></span><span></span></div>}
                  </div>
                </div>
              )}
            </div>
            <div className="p-4 lg:p-8 border-t border-white/5 bg-black/50 backdrop-blur-2xl flex flex-col gap-3 lg:gap-6">
              <VoiceVisualizer state={state} analyser={analyserRef.current || undefined} />
              <div className="flex gap-3 items-center">
                  <div className="flex gap-2">
                    <button onClick={handleToggleVision} className={`w-10 h-10 lg:w-14 lg:h-14 rounded-xl flex items-center justify-center transition-all active:scale-90 ${isVisionActive ? 'bg-red-500 text-white animate-pulse shadow-lg shadow-red-500/20' : 'bg-white/5 text-gray-400 hover:text-white'}`} title="Optic Link"><i className="fas fa-camera text-sm lg:text-lg"></i></button>
                    <button onClick={handleToggleScreenShare} className={`w-10 h-10 lg:w-14 lg:h-14 rounded-xl flex items-center justify-center transition-all active:scale-90 ${isScreenSharing ? 'bg-cyan-500 text-white animate-pulse shadow-lg shadow-cyan-500/20' : 'bg-white/5 text-gray-400 hover:text-white'}`} title="Screen Uplink"><i className="fas fa-desktop text-sm lg:text-lg"></i></button>
                  </div>
                  <input type="text" value={inputText} onChange={(e) => setInputText(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSendText()} placeholder="Directive..." className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-4 lg:px-6 py-3 lg:py-5 text-sm lg:text-lg focus:outline-none focus:border-[var(--theme-primary)]/50 text-white font-bold" />
                  <button onClick={inputText.trim() ? handleSendText : (state === AssistantState.IDLE ? () => startSession() : stopSession)} className={`flex-1 md:flex-none md:w-48 lg:w-64 h-14 lg:h-20 rounded-[var(--ui-radius)] flex items-center justify-center transition-all gap-2 lg:gap-4 neo-button shadow-2xl ${state === AssistantState.IDLE ? 'bg-white text-black' : 'bg-red-600 text-white animate-pulse'}`}>
                    <i className={`fas ${inputText.trim() ? 'fa-paper-plane' : (state === AssistantState.IDLE ? 'fa-bolt' : 'fa-square')} text-sm lg:text-lg`}></i>
                    <span className="font-black uppercase tracking-widest text-[8px] lg:text-[11px]">{inputText.trim() ? 'SEND' : (state === AssistantState.IDLE ? 'IGNITE' : 'HALT')}</span>
                  </button>
              </div>
            </div>
          </div>
        </div>

        {isMemoryOpen && (
          <div className="w-full md:w-[380px] lg:w-[420px] h-full flex-shrink-0 animate-slide-in-right-bounce z-[60]">
            <MemoryBank 
              memories={memories} 
              onRemove={(id) => setMemories(p => p.filter(m => m.id !== id))} 
              onAdd={(fact) => setMemories(p => [...p, { id: Math.random().toString(36).substr(2, 9), fact, timestamp: new Date() }])}
              onPurge={() => { if(window.confirm("Purge memory?")) setMemories([]); }}
              assistantName={prefs.assistantName} 
            />
          </div>
        )}
      </main>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} prefs={prefs} setPrefs={setPrefs} voices={dynamicVoices} personalities={PERSONALITIES} isTV={false} isWearable={false} onPreviewVoice={handlePreviewVoice} previewingVoiceId={previewingVoiceId} />

      {errorToast && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-red-600 text-white px-8 py-4 rounded-2xl font-black uppercase tracking-widest text-[10px] shadow-2xl animate-shake z-[200]">
          <i className="fas fa-exclamation-triangle mr-3"></i> {errorToast}
        </div>
      )}
    </div>
  );
};

export default App;

export enum AssistantState {
  IDLE = 'IDLE',
  CONNECTING = 'CONNECTING',
  LISTENING = 'LISTENING',
  SPEAKING = 'SPEAKING',
  THINKING = 'THINKING',
  OBSERVING = 'OBSERVING',
  ERROR = 'ERROR'
}

export type DeviceType = 'wear' | 'mobile' | 'desktop' | 'tv' | 'auto';

export type UITheme = 'cosmic' | 'emerald' | 'ruby' | 'obsidian' | 'custom';
export type PersonalityType = 'professional' | 'friendly' | 'witty' | 'minimalist' | 'alluring' | 'custom';
export type BackgroundStyle = 'grid' | 'aurora' | 'noise' | 'solid';

export interface GroundingSource {
  title: string;
  uri: string;
}

export interface SensorData {
  battery?: number;
  charging?: boolean;
  online: boolean;
  platform: string;
  location?: { lat: number; lng: number };
}

export interface TranscriptionEntry {
  id: string;
  sender: 'user' | 'assistant';
  text: string;
  timestamp: Date;
  isThinking?: boolean;
  isStreaming?: boolean;
  sources?: GroundingSource[];
}

export interface MemoryEntry {
  id: string;
  fact: string;
  timestamp: Date;
}

export interface AvatarConfig {
  hairStyle: string;
  hairColor: string;
  eyeColor: string;
  skinTone: string;
  clothingStyle: string;
  vibe: string;
  traits: string[];
}

export interface UserPreferences {
  theme: UITheme;
  personality: PersonalityType;
  customPersonality?: string;
  layout: 'left' | 'right';
  voiceId: string;
  assistantName: string;
  assistantProfilePic?: string;
  modality: 'masculine' | 'feminine';

  // Customization Extensions
  primaryColor: string;
  secondaryColor: string;
  borderRadius: string; 
  fontFamily: 'Inter' | 'Roboto Mono' | 'Outfit' | 'Bebas Neue';
  bgStyle: BackgroundStyle;
  speechSpeed: number; 
  speechPitch: number; 
  greeting: string;

  // Avatar Builder Integration
  avatarConfig?: AvatarConfig;
}

export interface AuthUser {
  username: string;
  preferences: UserPreferences;
}

import React, { useState } from 'react';
import { GoogleGenAI } from '@google/genai';
import { AvatarConfig, UserPreferences } from '../types';

interface AvatarBuilderProps {
  onClose: () => void;
  onSave: (picUrl: string, config: AvatarConfig, traits: string) => void;
  currentPrefs: UserPreferences;
}

const CATEGORIES = [
  { id: 'PHYSICAL', icon: 'fa-user-astronaut', label: 'Body' },
  { id: 'HAIR', icon: 'fa-cut', label: 'Hair' },
  { id: 'OUTFIT', icon: 'fa-tshirt', label: 'Wardrobe' },
  { id: 'MIND', icon: 'fa-brain', label: 'Traits' }
];

const OPTIONS = {
  skinTone: ['Fair', 'Warm', 'Tan', 'Deep', 'Obsidian', 'Nebula Blue', 'Chrome'],
  hairStyle: ['Short Crop', 'Long Waves', 'Slicked Back', 'Messy Spikes', 'Bob Cut', 'Braid', 'Bald'],
  hairColor: ['Midnight', 'Platinum', 'Rose Gold', 'Neon Green', 'Crimson', 'Azure', 'Golden'],
  eyeColor: ['Sapphire', 'Emerald', 'Amber', 'Violet', 'Silver', 'Black'],
  clothingStyle: ['Cyberpunk Techwear', 'Minimalist Suit', 'Ethereal Robes', 'Casual Streetwear', 'Victorian Gothic', 'Space Suit'],
  vibe: ['Realistic Digital Portrait', 'Stylized Anime', '3D Render', 'Oil Painting', 'Neon Hologram'],
  traits: ['Genius', 'Sarcastic', 'Empathetic', 'Stoic', 'Cheerful', 'Mysterious', 'Loyal', 'Witty']
};

const AvatarBuilder: React.FC<AvatarBuilderProps> = ({ onClose, onSave, currentPrefs }) => {
  const [activeTab, setActiveTab] = useState('PHYSICAL');
  const [isGenerating, setIsGenerating] = useState(false);
  const [previewUrl, setPreviewUrl] = useState(currentPrefs.assistantProfilePic || '');
  const [status, setStatus] = useState('');

  const [config, setConfig] = useState<AvatarConfig>(currentPrefs.avatarConfig || {
    hairStyle: 'Short Crop',
    hairColor: 'Midnight',
    eyeColor: 'Sapphire',
    skinTone: 'Warm',
    clothingStyle: 'Minimalist Suit',
    vibe: 'Realistic Digital Portrait',
    traits: ['Friendly']
  });

  const toggleTrait = (trait: string) => {
    setConfig(prev => ({
      ...prev,
      traits: prev.traits.includes(trait) 
        ? prev.traits.filter(t => t !== trait)
        : [...prev.traits, trait].slice(-3) // Max 3 traits
    }));
  };

  const handleGenerate = async () => {
    setIsGenerating(true);
    setStatus('Analyzing genetic markers...');

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `A highly detailed ${config.vibe} of an AI assistant character. 
        Physical features: ${config.skinTone} skin, ${config.hairStyle} hair in ${config.hairColor}, striking ${config.eyeColor} eyes. 
        Wearing: ${config.clothingStyle}. 
        Personality traits visible: ${config.traits.join(', ')}. 
        Background: Cinematic lighting, soft bokeh, high quality digital art, centered composition.`;

      setStatus('Synthesizing neural portrait...');
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: { parts: [{ text: prompt }] },
        config: { imageConfig: { aspectRatio: "1:1" } }
      });

      let imageUrl = null;
      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            imageUrl = `data:image/png;base64,${part.inlineData.data}`;
            break;
          }
        }
      }

      if (imageUrl) {
        setPreviewUrl(imageUrl);
        setStatus('Synthesis successful.');
      } else {
        throw new Error("No visual data returned.");
      }
    } catch (err: any) {
      console.error(err);
      setStatus(`Link Failure: ${err.message}`);
    } finally {
      setIsGenerating(false);
    }
  };

  const handleFinalize = () => {
    const traitInstruction = `You are an AI with the following traits: ${config.traits.join(', ')}. Let these traits influence your tone and behavior.`;
    onSave(previewUrl, config, traitInstruction);
  };

  return (
    <div className="fixed inset-0 z-[300] bg-black/95 backdrop-blur-3xl flex items-center justify-center p-4 lg:p-10 animate-fade-in font-sans">
      <div className="w-full max-w-6xl h-[90vh] glass rounded-[4rem] border border-white/10 flex overflow-hidden shadow-2xl">

        {/* CAS Sidebar */}
        <div className="w-24 lg:w-32 bg-black/40 border-r border-white/5 flex flex-col items-center py-10 gap-8 flex-shrink-0">
          {CATEGORIES.map(cat => (
            <button 
              key={cat.id}
              onClick={() => setActiveTab(cat.id)}
              className={`w-14 h-14 lg:w-16 lg:h-16 rounded-2xl flex flex-col items-center justify-center gap-1 transition-all group ${activeTab === cat.id ? 'bg-white text-black scale-110 shadow-lg' : 'text-gray-500 hover:text-white hover:bg-white/5'}`}
            >
              <i className={`fas ${cat.icon} text-lg lg:text-xl`}></i>
              <span className="text-[7px] font-black uppercase tracking-tighter opacity-0 group-hover:opacity-100 transition-opacity">{cat.label}</span>
            </button>
          ))}
          <div className="mt-auto">
             <button onClick={onClose} className="text-gray-600 hover:text-red-500 transition-colors p-4"><i className="fas fa-times text-xl"></i></button>
          </div>
        </div>

        {/* Customization Panel */}
        <div className="flex-1 flex flex-col lg:flex-row overflow-hidden">

          <div className="flex-1 p-8 lg:p-12 space-y-10 overflow-y-auto scrollbar-thin">
            <header>
              <h2 className="text-3xl lg:text-5xl font-black text-white uppercase tracking-tighter">Neural <span className="text-[var(--theme-primary)]">Synthesis</span></h2>
              <p className="text-[10px] text-gray-500 font-black uppercase tracking-[0.3em] mt-2">Adjusting Bio-Matrix Segments</p>
            </header>

            <div className="space-y-12 animate-slide-up-reveal">
              {activeTab === 'PHYSICAL' && (
                <div className="space-y-8">
                  <div className="space-y-4">
                    <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Skin Tone Matrix</label>
                    <div className="flex flex-wrap gap-2">
                      {OPTIONS.skinTone.map(opt => (
                        <button key={opt} onClick={() => setConfig(p => ({...p, skinTone: opt}))} className={`px-5 py-3 rounded-xl border-2 text-[9px] font-black uppercase transition-all ${config.skinTone === opt ? 'border-[var(--theme-primary)] bg-[var(--theme-primary)]/10 text-white' : 'border-white/5 bg-white/5 text-gray-600 hover:border-white/10'}`}>{opt}</button>
                      ))}
                    </div>
                  </div>
                  <div className="space-y-4">
                    <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Optic Pigmentation</label>
                    <div className="flex flex-wrap gap-2">
                      {OPTIONS.eyeColor.map(opt => (
                        <button key={opt} onClick={() => setConfig(p => ({...p, eyeColor: opt}))} className={`px-5 py-3 rounded-xl border-2 text-[9px] font-black uppercase transition-all ${config.eyeColor === opt ? 'border-[var(--theme-primary)] bg-[var(--theme-primary)]/10 text-white' : 'border-white/5 bg-white/5 text-gray-600 hover:border-white/10'}`}>{opt}</button>
                      ))}
                    </div>
                  </div>
                </div>
              )}

              {activeTab === 'HAIR' && (
                <div className="space-y-8">
                  <div className="space-y-4">
                    <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Follicle Structure</label>
                    <div className="flex flex-wrap gap-2">
                      {OPTIONS.hairStyle.map(opt => (
                        <button key={opt} onClick={() => setConfig(p => ({...p, hairStyle: opt}))} className={`px-5 py-3 rounded-xl border-2 text-[9px] font-black uppercase transition-all ${config.hairStyle === opt ? 'border-[var(--theme-primary)] bg-[var(--theme-primary)]/10 text-white' : 'border-white/5 bg-white/5 text-gray-600 hover:border-white/10'}`}>{opt}</button>
                      ))}
                    </div>
                  </div>
                  <div className="space-y-4">
                    <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Chroma Wash</label>
