    root.style.setProperty('--bg-base', themeData.bg);
    root.style.setProperty('--theme-glow', themeData.glow);
    root.style.setProperty('--ui-radius', prefs.borderRadius);

    const fontMap = {
      'Inter': "'Inter', sans-serif",
      'Outfit': "'Outfit', sans-serif",
